INSERT INTO temp_seed_reviews_2000 VALUES
('54500700-0000-4000-9000-000000000501', '54500700-0000-4000-8000-000000000065', 'p-tourapi-3510320', '주식회사라온문화창작소', '평일 연차 쓰고 혼자 주식회사라온문화창작소 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.646704, 128.848714, '2026-10-16T07:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000502', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2746352', '청와대 세트장', '청와대 세트장 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 35.548276, 128.072858, '2026-10-16T13:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000503', '54500700-0000-4000-8000-000000000130', 'p-tourapi-1615878', '철종외가', '오랜만에 여유 찾으러 철종외가 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉"]'::jsonb, 37.704921, 126.477121, '2026-10-16T05:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000504', '54500700-0000-4000-8000-000000000195', 'p-tourapi-2604344', '락희원', '근처 여행 코스로 락희원 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "산책로", "힐링", "온마루"]'::jsonb, 35.837174, 129.212206, '2026-10-16T14:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000505', '54500700-0000-4000-8000-000000000196', 'p-tourapi-795829', '청송 후송당 고택', '평일 연차 쓰고 혼자 청송 후송당 고택 다녀옴. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "산책로", "힐링", "온마루"]'::jsonb, 36.289734, 129.010008, '2026-10-16T10:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000506', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2575836', '북촌 게스트하우스', '주말에 친구들이랑 북촌 게스트하우스 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 37.578322, 126.985712, '2026-10-16T11:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000507', '54500700-0000-4000-8000-000000000140', 'p-tourapi-3102111', '옥천풍경', '근처 여행 코스로 옥천풍경 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 34.952740, 127.482105, '2026-10-16T08:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000508', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2604833', '해로당', '근처 여행 코스로 해로당 넣길 정말 잘했어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링", "고즈넉", "온마루"]'::jsonb, 34.739549, 126.717571, '2026-10-16T10:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000509', '54500700-0000-4000-8000-000000000126', 'p-tourapi-127896', '양주 도자기나라', '근처 여행 코스로 양주 도자기나라 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "사색"]'::jsonb, 37.713544, 126.954228, '2026-10-16T06:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000510', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2638521', '영천 목재문화체험장', '해 질 무렵에 영천 목재문화체험장 방문했는데 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 36.142195, 128.977932, '2026-10-16T14:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000511', '54500700-0000-4000-8000-000000000204', 'p-tourapi-1883087', '연우하우스', '조용히 사색하고 싶어서 찾은 연우하우스. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 37.582315, 126.985044, '2026-10-16T05:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000512', '54500700-0000-4000-8000-000000000149', 'p-tourapi-3072219', '북촌빈관 by 락고재', '비 오는 날 운치 찾아 북촌빈관 by 락고재 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["데이트", "주말나들이"]'::jsonb, 37.582523, 126.984235, '2026-10-16T07:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000513', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2603996', '매죽헌2(매죽헌한옥민박)', '예전부터 가보고 싶었던 매죽헌2(매죽헌한옥민박) 드디어 방문! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.068941, 127.401645, '2026-10-16T13:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000514', '54500700-0000-4000-8000-000000000072', 'p-tourapi-798830', '영동 김참판댁', 'SNS에서 사진 보고 찾아간 영동 김참판댁, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "방문팁", "주말나들이"]'::jsonb, 36.152908, 127.755276, '2026-10-16T13:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000515', '54500700-0000-4000-8000-000000000189', 'p-tourapi-1997639', '찰방공종택', '해 질 무렵에 찰방공종택 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 36.437475, 129.026443, '2026-10-16T03:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000516', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2514834', '죽정분교(구,죽정초등학교)', '비 오는 날 운치 찾아 죽정분교(구,죽정초등학교) 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "주말나들이", "사진맛집"]'::jsonb, 38.470499, 128.420026, '2026-10-16T12:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000517', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2602750', '쥬라기랜드', '해 질 무렵에 쥬라기랜드 방문했는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 37.435259, 127.023882, '2026-10-16T08:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000518', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2569824', '흥해배씨 임연재종택', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링", "풍경맛집", "온마루"]'::jsonb, 36.549940, 128.791592, '2026-10-16T04:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000519', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3432447', '2025 서울 카페&베이커리페어', '근처 여행 코스로 2025 서울 카페&베이커리페어 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 37.496288, 127.070528, '2026-10-16T04:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000520', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3533129', '감성보다 양평서종점', '날씨가 너무 맑아서 감성보다 양평서종점 한 바퀴 돌고 왔네요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "풍경맛집", "혼자여행"]'::jsonb, 37.616232, 127.443446, '2026-10-16T04:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000521', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2787267', '오봉정사', '해 질 무렵에 오봉정사 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "데이트", "온마루"]'::jsonb, 35.184181, 127.524347, '2026-10-16T12:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000522', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2990185', '금곡영화마을', '기대 이상으로 너무 좋았던 금곡영화마을! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 35.395360, 126.734372, '2026-10-16T12:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000523', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2531497', '추우재', '기대 이상으로 너무 좋았던 추우재! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "데이트", "주말나들이", "온마루"]'::jsonb, 35.668773, 128.227541, '2026-10-16T04:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000524', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2821554', '꽃이 머무는 자리', '평일 연차 쓰고 혼자 꽃이 머무는 자리 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉", "산책로"]'::jsonb, 36.393820, 126.857360, '2026-10-16T12:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000525', '54500700-0000-4000-8000-000000000108', 'p-tourapi-1964622', '스카이로드', '드라이브 겸 나들이로 스카이로드 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "주말나들이", "데이트"]'::jsonb, 36.329086, 127.427655, '2026-10-16T04:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000526', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2822187', '꽃동네제빵소(꽃구움)', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행", "데이트"]'::jsonb, 36.890593, 127.566443, '2026-10-16T03:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000527', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3533007', '종로 성혜헌', '날씨가 너무 맑아서 종로 성혜헌 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 37.573159, 127.016994, '2026-10-16T14:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000528', '54500700-0000-4000-8000-000000000176', 'p-tourapi-802358', '아산 대통령마을(농촌전통테마)', '기대 이상으로 너무 좋았던 아산 대통령마을(농촌전통테마)! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 36.834145, 127.022877, '2026-10-16T07:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000529', '54500700-0000-4000-8000-000000000070', 'p-tourapi-1590793', '노동환가옥', '예전부터 가보고 싶었던 노동환가옥 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 35.484041, 127.266328, '2026-10-16T13:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000530', '54500700-0000-4000-8000-000000000115', 'p-tourapi-736751', '화성 정시영 고택', '예전부터 가보고 싶었던 화성 정시영 고택 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 37.132888, 126.701051, '2026-10-16T08:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000531', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2717600', '이플아토', '이플아토 다녀왔어요! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 36.451822, 126.803973, '2026-10-16T05:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000532', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2604573', '산들바다애(산들바다애 한옥민박)', '날씨가 너무 맑아서 산들바다애(산들바다애 한옥민박) 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링"]'::jsonb, 34.438406, 126.632902, '2026-10-16T12:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000533', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2891349', '미술관아래협동조합', '해 질 무렵에 미술관아래협동조합 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "데이트", "인생샷"]'::jsonb, 34.775244, 126.646574, '2026-10-16T06:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000534', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2531496', '하동댁', '부모님 모시고 하동댁 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.667025, 128.227705, '2026-10-16T07:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000535', '54500700-0000-4000-8000-000000000058', 'p-tourapi-3438496', '소우주', '해 질 무렵에 소우주 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "힐링"]'::jsonb, 37.640859, 126.938550, '2026-10-16T08:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000536', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2615342', '비비정예술열차', '날씨가 너무 맑아서 비비정예술열차 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 35.899023, 127.067567, '2026-10-16T03:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000537', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2939639', '유현문화관광지', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이", "가족여행"]'::jsonb, 37.530744, 127.820121, '2026-10-16T05:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000538', '54500700-0000-4000-8000-000000000203', 'p-tourapi-3108226', '사단법인 푸른차문화연구원', '주말에 친구들이랑 사단법인 푸른차문화연구원 들렀는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "가족여행", "온마루"]'::jsonb, 35.834723, 128.677240, '2026-10-16T02:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000539', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2046299', '한옥이야기', '천천히 골목 걷다가 마주친 한옥이야기. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "사진맛집", "가족여행", "온마루"]'::jsonb, 35.812308, 127.153711, '2026-10-16T10:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000540', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2930839', '경리단길', '드라이브 겸 나들이로 경리단길 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 37.538514, 126.987682, '2026-10-16T07:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000541', '54500700-0000-4000-8000-000000000089', 'p-tourapi-1627236', '신경섭 전통가옥', '비 오는 날 운치 찾아 신경섭 전통가옥 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 36.420898, 126.668264, '2026-10-16T11:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000542', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2707438', '하은재', '하은재 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "가족여행", "주말나들이"]'::jsonb, 37.581989, 126.971328, '2026-10-16T04:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000543', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2600265', '섬계고택', '주말에 친구들이랑 섬계고택 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["데이트", "가족여행", "온마루"]'::jsonb, 36.734849, 128.618750, '2026-10-16T08:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000544', '54500700-0000-4000-8000-000000000121', 'p-tourapi-264466', '김하인 아트홀 국화꽃향기', '김하인 아트홀 국화꽃향기 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 38.307390, 128.541322, '2026-10-16T05:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000545', '54500700-0000-4000-8000-000000000146', 'p-tourapi-3510444', '농업회사법인주식회사꿀벌인', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 36.014295, 128.421522, '2026-10-16T03:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000546', '54500700-0000-4000-8000-000000000142', 'p-tourapi-802420', '천안 두아람마을 [농촌전통테마]', '기대 이상으로 너무 좋았던 천안 두아람마을 [농촌전통테마]! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 36.691544, 127.076067, '2026-10-16T09:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000547', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2820733', '생생마을여행사', '조용히 사색하고 싶어서 찾은 생생마을여행사. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로", "혼자여행"]'::jsonb, 37.027378, 127.630604, '2026-10-16T11:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000548', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3510987', '주식회사감천아울', '해 질 무렵에 주식회사감천아울 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 35.093671, 129.008844, '2026-10-16T06:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000549', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2599272', '모지고택', '평일 연차 쓰고 혼자 모지고택 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.540446, 128.518400, '2026-10-16T10:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000550', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2939639', '유현문화관광지', '예전부터 가보고 싶었던 유현문화관광지 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "방문팁", "가족여행"]'::jsonb, 37.530591, 127.819469, '2026-10-16T12:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000551', '54500700-0000-4000-8000-000000000101', 'p-tourapi-3532970', '한옥스테이 유유자적', '천천히 골목 걷다가 마주친 한옥스테이 유유자적. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 35.826858, 129.207033, '2026-10-14T19:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000552', '54500700-0000-4000-8000-000000000134', 'p-tourapi-3009051', '도깨비 양조장', '기대 이상으로 너무 좋았던 도깨비 양조장! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 37.026747, 128.384589, '2026-10-16T00:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000553', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3421909', '그런고로', '그런고로 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 35.157364, 129.064432, '2026-10-14T22:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000554', '54500700-0000-4000-8000-000000000097', 'p-tourapi-1614564', '달성 삼가헌 고택', '조용히 사색하고 싶어서 찾은 달성 삼가헌 고택. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 35.906604, 128.412356, '2026-10-13T21:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000555', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2599504', '수졸당', '오랜만에 여유 찾으러 수졸당 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 36.733693, 128.859249, '2026-10-15T18:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000556', '54500700-0000-4000-8000-000000000181', 'p-tourapi-3533007', '종로 성혜헌', '드라이브 겸 나들이로 종로 성혜헌 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 37.573050, 127.017405, '2026-10-14T20:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000557', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2615320', '봄의 왈츠 드라마 촬영지', '날씨가 너무 맑아서 봄의 왈츠 드라마 촬영지 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "혼자여행", "고즈넉", "온마루"]'::jsonb, 34.170476, 126.862543, '2026-10-13T19:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000558', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2657501', '한옥카페 갤러리 도솔', '평일 연차 쓰고 혼자 한옥카페 갤러리 도솔 다녀옴. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "고즈넉", "산책로"]'::jsonb, 37.642179, 126.506436, '2026-10-14T04:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000559', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3442142', '서울숲 곤충식물원', '주말에 친구들이랑 서울숲 곤충식물원 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링"]'::jsonb, 37.543332, 127.042218, '2026-10-14T06:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000560', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2047715', '소강고택', '부모님 모시고 소강고택 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 36.893892, 128.712383, '2026-10-15T10:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000561', '54500700-0000-4000-8000-000000000126', 'p-tourapi-1594746', '장현식고택', '부모님 모시고 장현식고택 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.812159, 127.156890, '2026-10-15T16:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000562', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2695730', '효자스테이', '평일 연차 쓰고 혼자 효자스테이 다녀옴. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 37.579032, 126.973784, '2026-10-14T05:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000563', '54500700-0000-4000-8000-000000000115', 'p-tourapi-1882371', '학인당', '드라이브 겸 나들이로 학인당 선택했는데 대만족! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "고즈넉"]'::jsonb, 35.811887, 127.151989, '2026-10-15T02:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000564', '54500700-0000-4000-8000-000000000180', 'p-tourapi-3533114', '스테이여유담', '천천히 골목 걷다가 마주친 스테이여유담. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "산책로", "풍경맛집"]'::jsonb, 35.051559, 126.863919, '2026-10-15T04:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000565', '54500700-0000-4000-8000-000000000197', 'p-tourapi-3427162', '타임빌라스 수원', '평일 연차 쓰고 혼자 타임빌라스 수원 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "사색", "혼자여행", "온마루"]'::jsonb, 37.264300, 126.997518, '2026-10-14T09:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000566', '54500700-0000-4000-8000-000000000060', 'p-tourapi-252602', '영천 만취당 고택', 'SNS에서 사진 보고 찾아간 영천 만취당 고택, 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 35.906503, 128.890508, '2026-10-15T13:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000567', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2707440', '누와', '오랜만에 여유 찾으러 누와 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 37.579737, 126.968230, '2026-10-15T17:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000568', '54500700-0000-4000-8000-000000000180', 'p-tourapi-3582693', '한복남 북촌점', '부모님 모시고 한복남 북촌점 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁", "가족여행", "온마루"]'::jsonb, 37.580147, 126.984774, '2026-10-15T11:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000569', '54500700-0000-4000-8000-000000000109', 'p-tourapi-1566740', '양평 맑은숲캠프', '산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["가족여행", "주말나들이"]'::jsonb, 37.562134, 127.733986, '2026-10-13T17:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000570', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2767753', '후암거실', '해 질 무렵에 후암거실 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "사진맛집", "온마루"]'::jsonb, 37.548557, 126.976467, '2026-10-15T11:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000571', '54500700-0000-4000-8000-000000000119', 'p-tourapi-4104618', '함계정사', '예전부터 가보고 싶었던 함계정사 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "데이트", "주말나들이"]'::jsonb, 36.047454, 128.978035, '2026-10-15T14:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000572', '54500700-0000-4000-8000-000000000142', 'p-tourapi-3438420', '성북 은은한가', '예전부터 가보고 싶었던 성북 은은한가 드디어 방문! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "가족여행", "방문팁"]'::jsonb, 37.590591, 127.009424, '2026-10-14T09:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000573', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2679990', '신라불교초전지', '날씨가 너무 맑아서 신라불교초전지 한 바퀴 돌고 왔네요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 36.291058, 128.363322, '2026-10-16T00:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000574', '54500700-0000-4000-8000-000000000060', 'p-tourapi-130903', '북촌문화센터', '근처 여행 코스로 북촌문화센터 넣길 정말 잘했어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 37.579351, 126.986496, '2026-10-13T20:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000575', '54500700-0000-4000-8000-000000000186', 'p-tourapi-3438572', '스테이 노아', '근처 여행 코스로 스테이 노아 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "주말나들이", "인생샷", "온마루"]'::jsonb, 36.099216, 127.450126, '2026-10-13T22:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000576', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2574186', '김포아트빌리지 전통한옥숙박체험관', '평일 연차 쓰고 혼자 김포아트빌리지 전통한옥숙박체험관 다녀옴. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "산책로", "고즈넉"]'::jsonb, 37.646413, 126.696048, '2026-10-15T06:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000577', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2850614', '스탈릿성수', '드라이브 겸 나들이로 스탈릿성수 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.544752, 127.055588, '2026-10-14T08:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000578', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2603884', '연당', '주말에 친구들이랑 연당 들렀는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 37.582321, 126.986891, '2026-10-15T00:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000579', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2380834', '마복산 목재문화체험장', '비 오는 날 운치 찾아 마복산 목재문화체험장 다녀왔어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 34.550365, 127.375822, '2026-10-14T14:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000580', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2713396', '함정균가옥', '근처 여행 코스로 함정균가옥 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 38.341113, 128.498241, '2026-10-15T13:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000581', '54500700-0000-4000-8000-000000000119', 'p-tourapi-4070357', '한옥온온', '평일 연차 쓰고 혼자 한옥온온 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 36.735146, 127.404799, '2026-10-15T03:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000582', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2572817', '옥산정사 독락당', '오랜만에 여유 찾으러 옥산정사 독락당 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링", "혼자여행", "온마루"]'::jsonb, 36.016876, 129.160079, '2026-10-13T21:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000583', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2638479', '장생포 모노레일', '주말에 친구들이랑 장생포 모노레일 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 35.502818, 129.381374, '2026-10-13T22:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000584', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2595847', '달의 정원', '날씨가 너무 맑아서 달의 정원 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 35.790223, 128.087208, '2026-10-14T07:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000585', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2611472', '보리수 자수 숙박', '해 질 무렵에 보리수 자수 숙박 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "방문팁", "온마루"]'::jsonb, 35.811918, 127.153212, '2026-10-14T07:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000586', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2870141', '한옥마을 박씨네추어탕', '부모님 모시고 한옥마을 박씨네추어탕 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 37.648113, 126.701684, '2026-10-15T18:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000587', '54500700-0000-4000-8000-000000000192', 'p-tourapi-1971917', '청공한옥', '예전부터 가보고 싶었던 청공한옥 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["사진맛집", "인생샷"]'::jsonb, 35.781938, 129.303033, '2026-10-15T06:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000588', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2708329', '학림재', 'SNS에서 사진 보고 찾아간 학림재, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["사진맛집", "가족여행", "데이트"]'::jsonb, 36.551422, 127.189785, '2026-10-13T21:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000589', '54500700-0000-4000-8000-000000000113', 'p-tourapi-2701396', '서남산한옥', '드라이브 겸 나들이로 서남산한옥 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.780685, 129.204963, '2026-10-14T22:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000590', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2592885', '엘크레', '날씨가 너무 맑아서 엘크레 한 바퀴 돌고 왔네요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "산책로"]'::jsonb, 37.521178, 127.023614, '2026-10-14T21:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000591', '54500700-0000-4000-8000-000000000200', 'p-tourapi-2850614', '스탈릿성수', '드라이브 겸 나들이로 스탈릿성수 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "사진맛집", "가족여행"]'::jsonb, 37.544490, 127.055278, '2026-10-14T23:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000592', '54500700-0000-4000-8000-000000000126', 'p-tourapi-3102033', '풍경의 아침', '날씨가 너무 맑아서 풍경의 아침 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "방문팁", "인생샷"]'::jsonb, 35.387952, 126.884965, '2026-10-15T10:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000593', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3114431', '모주체험 여', '근처 여행 코스로 모주체험 여 넣길 정말 잘했어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "데이트", "주말나들이"]'::jsonb, 35.815702, 127.152154, '2026-10-15T15:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000594', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3438588', '유유가', '기대 이상으로 너무 좋았던 유유가! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 34.955714, 127.483187, '2026-10-14T17:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000595', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2606207', '목포 해상케이블카', '조용히 사색하고 싶어서 찾은 목포 해상케이블카. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "사색", "혼자여행"]'::jsonb, 34.799160, 126.370004, '2026-10-14T02:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000596', '54500700-0000-4000-8000-000000000065', 'p-tourapi-3438241', '한가로움', '부모님 모시고 한가로움 산책 겸 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 37.586710, 126.981328, '2026-10-14T02:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000597', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2610062', '태양의 후예 촬영지', '오랜만에 여유 찾으러 태양의 후예 촬영지 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링", "풍경맛집", "온마루"]'::jsonb, 37.160806, 129.042943, '2026-10-13T15:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000598', '54500700-0000-4000-8000-000000000174', 'p-tourapi-2569581', '춘하원(죽헌고택)', '천천히 골목 걷다가 마주친 춘하원(죽헌고택). 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁", "온마루"]'::jsonb, 36.647502, 128.663266, '2026-10-16T00:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000599', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2638566', '주문진읍 BTS 앨범사진 촬영지 (버스정류장)', '평일 연차 쓰고 혼자 주문진읍 BTS 앨범사진 촬영지 (버스정류장) 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.912781, 128.817229, '2026-10-14T04:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000600', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2593271', '가은채', '예전부터 가보고 싶었던 가은채 드디어 방문! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "인생샷", "방문팁"]'::jsonb, 35.816800, 127.153472, '2026-10-15T13:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000601', '54500700-0000-4000-8000-000000000135', 'p-tourapi-127060', '이장우가옥', '천천히 골목 걷다가 마주친 이장우가옥. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["사진맛집", "주말나들이"]'::jsonb, 35.140393, 126.914135, '2026-10-16T01:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000602', '54500700-0000-4000-8000-000000000057', 'p-tourapi-3040204', '함파우소리체험관', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집", "산책로", "온마루"]'::jsonb, 35.397969, 127.384259, '2026-10-14T11:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000603', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2725010', '휴식 레스토랑', '주말에 친구들이랑 휴식 레스토랑 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 36.451322, 126.813156, '2026-10-13T20:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000604', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3072197', '오롯이, 한옥', '기대 이상으로 너무 좋았던 오롯이, 한옥! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "풍경맛집", "힐링"]'::jsonb, 37.580176, 126.968054, '2026-10-14T02:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000605', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2629570', '새마을 시대촌', '드라이브 겸 나들이로 새마을 시대촌 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "사진맛집", "가족여행"]'::jsonb, 35.599793, 128.761586, '2026-10-15T17:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000606', '54500700-0000-4000-8000-000000000161', 'p-tourapi-1626699', '아산 외암마을 참판댁', '날씨가 너무 맑아서 아산 외암마을 참판댁 한 바퀴 돌고 왔네요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 36.730419, 127.018288, '2026-10-14T04:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000607', '54500700-0000-4000-8000-000000000122', 'p-tourapi-1624846', '창원정씨종가', 'SNS에서 사진 보고 찾아간 창원정씨종가, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "풍경맛집"]'::jsonb, 35.565367, 127.395419, '2026-10-13T17:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000608', '54500700-0000-4000-8000-000000000105', 'p-tourapi-129433', '영주 괴헌고택', '영주 괴헌고택 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 36.734064, 128.681262, '2026-10-14T23:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000609', '54500700-0000-4000-8000-000000000110', 'p-tourapi-2458168', '일락당사랑채', '일락당사랑채 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "주말나들이", "방문팁"]'::jsonb, 35.815999, 127.152982, '2026-10-15T17:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000610', '54500700-0000-4000-8000-000000000201', 'p-tourapi-3438189', '한옥 북클럽 하우스', '한옥 북클럽 하우스 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "사진맛집", "인생샷"]'::jsonb, 37.591012, 127.005181, '2026-10-14T09:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000611', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2583187', '전통문화체험장', '천천히 골목 걷다가 마주친 전통문화체험장. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 35.989470, 127.260999, '2026-10-14T06:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000612', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2570339', '달빛한옥민박 별유풍경', '드라이브 겸 나들이로 달빛한옥민박 별유풍경 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 34.740343, 126.719249, '2026-10-15T01:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000613', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3438433', '호우재 한옥', '부모님 모시고 호우재 한옥 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["가족여행", "데이트", "온마루"]'::jsonb, 37.595492, 126.999451, '2026-10-13T17:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000614', '54500700-0000-4000-8000-000000000133', 'p-tourapi-1395270', '최순우 옛집', '오랜만에 여유 찾으러 최순우 옛집 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 37.592846, 127.000360, '2026-10-15T23:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000615', '54500700-0000-4000-8000-000000000104', 'p-tourapi-1623828', '안동권씨유회당종가일원', '드라이브 겸 나들이로 안동권씨유회당종가일원 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "풍경맛집", "온마루"]'::jsonb, 36.277819, 127.404621, '2026-10-15T23:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000616', '54500700-0000-4000-8000-000000000085', 'p-tourapi-264353', '인사동', '오랜만에 여유 찾으러 인사동 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "풍경맛집", "사색", "온마루"]'::jsonb, 37.575530, 126.983859, '2026-10-14T01:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000617', '54500700-0000-4000-8000-000000000107', 'p-tourapi-3056595', '전주한옥마을역사관', '날씨가 너무 맑아서 전주한옥마을역사관 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 35.815643, 127.152761, '2026-10-15T18:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000618', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2995167', '달달구리(주식회사달달구리)', 'SNS에서 사진 보고 찾아간 달달구리(주식회사달달구리), 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["주말나들이", "인생샷", "방문팁", "온마루"]'::jsonb, 35.938513, 127.166917, '2026-10-14T09:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000619', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2804328', '만죽재고택', '만죽재고택 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁", "온마루"]'::jsonb, 36.731550, 128.621131, '2026-10-14T10:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000620', '54500700-0000-4000-8000-000000000170', 'p-tourapi-3102079', '한옥에서 하루를', 'SNS에서 사진 보고 찾아간 한옥에서 하루를, 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 37.840013, 126.754367, '2026-10-13T20:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000621', '54500700-0000-4000-8000-000000000172', 'p-tourapi-971122', '강화 아르미애월드', '천천히 골목 걷다가 마주친 강화 아르미애월드. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["가족여행", "데이트", "인생샷"]'::jsonb, 37.703169, 126.434475, '2026-10-14T07:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000622', '54500700-0000-4000-8000-000000000172', 'p-tourapi-4006383', '고요별서', '고요별서 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 34.821986, 128.043420, '2026-10-15T17:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000623', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3582643', '한복남 창덕궁점', '평일 연차 쓰고 혼자 한복남 창덕궁점 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 37.575888, 126.991004, '2026-10-14T14:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000624', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3577428', '고창 전통예술체험마을', '날씨가 너무 맑아서 고창 전통예술체험마을 한 바퀴 돌고 왔네요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "사색", "힐링", "온마루"]'::jsonb, 35.430404, 126.701144, '2026-10-14T07:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000625', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2350029', '도래미하우스', '천천히 골목 걷다가 마주친 도래미하우스. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "사색", "혼자여행", "온마루"]'::jsonb, 34.997602, 126.824443, '2026-10-15T18:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000626', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2793068', '밀양 퇴로리 이씨고가', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 35.551093, 128.700748, '2026-10-14T07:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000627', '54500700-0000-4000-8000-000000000203', 'p-tourapi-3102087', '한옥더원', '날씨가 너무 맑아서 한옥더원 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "가족여행", "사진맛집"]'::jsonb, 37.471221, 127.506004, '2026-10-14T10:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000628', '54500700-0000-4000-8000-000000000131', 'p-tourapi-3101961', '자미재', 'SNS에서 사진 보고 찾아간 자미재, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "가족여행", "방문팁", "온마루"]'::jsonb, 34.911711, 126.648264, '2026-10-14T05:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000629', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2531357', '경주한옥1번가', '조용히 사색하고 싶어서 찾은 경주한옥1번가. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 35.825925, 129.212738, '2026-10-15T00:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000630', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2708657', '초정행궁', '근처 여행 코스로 초정행궁 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 36.721269, 127.601181, '2026-10-15T17:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000631', '54500700-0000-4000-8000-000000000172', 'p-tourapi-3072271', '청담', '기대 이상으로 너무 좋았던 청담! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행", "인생샷", "온마루"]'::jsonb, 36.456019, 127.120350, '2026-10-14T11:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000632', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2992823', 'K-컬처 스크린(대한민국역사박물관)', '해 질 무렵에 K-컬처 스크린(대한민국역사박물관) 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "혼자여행"]'::jsonb, 37.574054, 126.977317, '2026-10-15T18:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000633', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3532605', '조각집', '해 질 무렵에 조각집 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["인생샷", "데이트"]'::jsonb, 35.846855, 129.210578, '2026-10-14T07:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000634', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2932921', '한울', '주말에 친구들이랑 한울 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.236862, 127.265678, '2026-10-14T19:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000635', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2638488', '거제 관광모노레일', '예전부터 가보고 싶었던 거제 관광모노레일 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "데이트", "인생샷"]'::jsonb, 34.876179, 128.625107, '2026-10-14T07:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000636', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3438621', '희게', '평일 연차 쓰고 혼자 희게 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "힐링", "풍경맛집", "온마루"]'::jsonb, 36.554034, 128.923350, '2026-10-15T09:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000637', '54500700-0000-4000-8000-000000000094', 'p-tourapi-264402', '화성어차', '천천히 골목 걷다가 마주친 화성어차. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 37.288061, 127.023810, '2026-10-13T18:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000638', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2607706', '곡전재', '근처 여행 코스로 곡전재 넣길 정말 잘했어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.203464, 127.513742, '2026-10-14T02:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000639', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2717594', '바늘꽃피우다', '예전부터 가보고 싶었던 바늘꽃피우다 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "산책로", "힐링", "온마루"]'::jsonb, 36.782007, 126.452687, '2026-10-14T04:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000640', '54500700-0000-4000-8000-000000000167', 'p-tourapi-1600719', '정종수 고택', '정종수 고택 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "풍경맛집"]'::jsonb, 35.773540, 126.858734, '2026-10-14T09:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000641', '54500700-0000-4000-8000-000000000125', 'p-tourapi-3428354', '스타필드 시티 부천', '해 질 무렵에 스타필드 시티 부천 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "인생샷", "주말나들이"]'::jsonb, 37.461371, 126.814396, '2026-10-14T05:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000642', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2663054', '경주 춘추관', '경주 춘추관 다녀왔어요! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.822774, 129.186212, '2026-10-15T03:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000643', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2820706', '폴링 인 진주', '평일 연차 쓰고 혼자 폴링 인 진주 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.183431, 128.085833, '2026-10-15T18:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000644', '54500700-0000-4000-8000-000000000200', 'p-tourapi-3510944', '주식회사영리캐롤', '부모님 모시고 주식회사영리캐롤 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 36.008488, 128.359462, '2026-10-15T07:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000645', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2576540', '풍정(풍정게스트하우스)', '예전부터 가보고 싶었던 풍정(풍정게스트하우스) 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.840749, 129.231264, '2026-10-15T22:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000646', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2775017', '주식회사 하늘', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "혼자여행", "고즈넉", "온마루"]'::jsonb, 35.304857, 126.546468, '2026-10-14T00:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000647', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2717337', '소백산꽃차이야기', '해 질 무렵에 소백산꽃차이야기 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집", "방문팁", "온마루"]'::jsonb, 36.883026, 128.563485, '2026-10-14T09:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000648', '54500700-0000-4000-8000-000000000124', 'p-tourapi-125925', '아산 맹씨 행단(맹사성 고택)', '근처 여행 코스로 아산 맹씨 행단(맹사성 고택) 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 36.747201, 127.041517, '2026-10-14T23:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000649', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2792804', '금시당', '비 오는 날 운치 찾아 금시당 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 35.486994, 128.784230, '2026-10-15T03:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000650', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3511656', '하얀민들레마을(주식회사미진)', 'SNS에서 사진 보고 찾아간 하얀민들레마을(주식회사미진), 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "인생샷", "주말나들이"]'::jsonb, 36.493571, 127.611177, '2026-10-15T01:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000651', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3453929', '경상북도교육청 발명체험교육관', 'SNS에서 사진 보고 찾아간 경상북도교육청 발명체험교육관, 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 35.833309, 129.212972, '2026-10-10T23:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000652', '54500700-0000-4000-8000-000000000134', 'p-tourapi-231909', '안동 예안이씨 충효당', '툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.574382, 128.580084, '2026-10-12T02:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000653', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2587214', '제이한옥(JAY Hanok)', '근처 여행 코스로 제이한옥(JAY Hanok) 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.582669, 126.987471, '2026-10-11T22:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000654', '54500700-0000-4000-8000-000000000089', 'p-tourapi-128653', '거창 동계종택', '거창 동계종택 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행", "힐링"]'::jsonb, 35.755534, 127.828504, '2026-10-12T11:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000655', '54500700-0000-4000-8000-000000000112', 'p-tourapi-3353909', '소잉(에이핸즈협동조합)', '날씨가 너무 맑아서 소잉(에이핸즈협동조합) 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.207770, 126.865167, '2026-10-11T04:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000656', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3447048', '사우당 종택', '예전부터 가보고 싶었던 사우당 종택 드디어 방문! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 35.828572, 128.215169, '2026-10-09T09:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000657', '54500700-0000-4000-8000-000000000057', 'p-tourapi-3102212', '한옥마을숙박 가인당', '예전부터 가보고 싶었던 한옥마을숙박 가인당 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "힐링", "산책로", "온마루"]'::jsonb, 35.812502, 127.151771, '2026-10-09T22:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000658', '54500700-0000-4000-8000-000000000065', 'p-tourapi-3511603', '수달궁(문화살롱주식회사)', '예전부터 가보고 싶었던 수달궁(문화살롱주식회사) 드디어 방문! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "데이트", "사진맛집"]'::jsonb, 35.864289, 127.123557, '2026-10-11T11:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000659', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2611575', '양천생활안전체험교육관', '비 오는 날 운치 찾아 양천생활안전체험교육관 다녀왔어요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 37.516743, 126.863684, '2026-10-10T16:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000660', '54500700-0000-4000-8000-000000000128', 'p-tourapi-231932', '탁청정종가', '기대 이상으로 너무 좋았던 탁청정종가! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집", "산책로"]'::jsonb, 36.673230, 128.801390, '2026-10-11T08:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000661', '54500700-0000-4000-8000-000000000074', 'p-tourapi-2792804', '금시당', '비 오는 날 운치 찾아 금시당 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 35.487224, 128.783923, '2026-10-12T04:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000662', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2996825', '애플트리 힐링팜', '비 오는 날 운치 찾아 애플트리 힐링팜 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 35.557014, 127.099097, '2026-10-09T09:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000663', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2623585', '별궁', 'SNS에서 사진 보고 찾아간 별궁, 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 36.940691, 126.301430, '2026-10-09T00:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000664', '54500700-0000-4000-8000-000000000131', 'p-tourapi-1626349', '팔공산 케이블카', '예전부터 가보고 싶었던 팔공산 케이블카 드디어 방문! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 35.990998, 128.694651, '2026-10-12T00:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000665', '54500700-0000-4000-8000-000000000111', 'p-tourapi-3532948', '하녹명당', '대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 35.836930, 129.211556, '2026-10-10T20:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000666', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2706484', '3917마중', '주말에 친구들이랑 3917마중 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "풍경맛집"]'::jsonb, 35.033291, 126.710780, '2026-10-11T20:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000667', '54500700-0000-4000-8000-000000000111', 'p-tourapi-129030', '전주유씨 무실종택', '근처 여행 코스로 전주유씨 무실종택 넣길 정말 잘했어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 36.553434, 128.923251, '2026-10-10T16:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000668', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2777043', '김택준가옥', '천천히 골목 걷다가 마주친 김택준가옥. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "데이트"]'::jsonb, 37.971815, 128.759066, '2026-10-11T18:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000669', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2715382', '여송정', '오랜만에 여유 찾으러 여송정 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 37.477533, 128.724499, '2026-10-09T14:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000670', '54500700-0000-4000-8000-000000000149', 'p-tourapi-3438567', '스테이 자하', '주말에 친구들이랑 스테이 자하 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "인생샷", "사진맛집"]'::jsonb, 37.891940, 127.724602, '2026-10-11T10:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000671', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2819607', '드로잉라이프', '날씨가 너무 맑아서 드로잉라이프 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "데이트", "가족여행", "온마루"]'::jsonb, 34.951042, 127.483418, '2026-10-10T03:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000672', '54500700-0000-4000-8000-000000000087', 'p-tourapi-3533130', '대전별서', '오랜만에 여유 찾으러 대전별서 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 36.286370, 127.448311, '2026-10-09T09:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000673', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3353949', '㈜ 희품씨', '부모님 모시고 ㈜ 희품씨 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["가족여행", "데이트"]'::jsonb, 35.567146, 129.112188, '2026-10-10T23:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000674', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3438295', '함한옥스테이', '오랜만에 여유 찾으러 함한옥스테이 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["산책로", "사색"]'::jsonb, 37.582167, 126.987167, '2026-10-09T18:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000675', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2819644', '적정온도(순향가)', '천천히 골목 걷다가 마주친 적정온도(순향가). 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "가족여행", "방문팁"]'::jsonb, 34.872667, 127.528121, '2026-10-10T13:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000676', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2587355', '소이한옥', '예전부터 가보고 싶었던 소이한옥 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 35.834614, 129.211789, '2026-10-12T13:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000677', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2594862', '향우당', '예전부터 가보고 싶었던 향우당 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "가족여행", "데이트"]'::jsonb, 35.602792, 128.907287, '2026-10-10T21:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000678', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2783558', '필운동 홍건익 가옥', '근처 여행 코스로 필운동 홍건익 가옥 넣길 정말 잘했어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행", "데이트"]'::jsonb, 37.577570, 126.969047, '2026-10-10T19:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000679', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2570188', '청풍헌(시랑골한옥스테이)', '아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.979712, 127.233324, '2026-10-11T00:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000680', '54500700-0000-4000-8000-000000000105', 'p-tourapi-129046', '서벽고택', '비 오는 날 운치 찾아 서벽고택 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "사진맛집", "데이트", "온마루"]'::jsonb, 36.458840, 129.022451, '2026-10-09T19:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000681', '54500700-0000-4000-8000-000000000148', 'p-tourapi-3072197', '오롯이, 한옥', '근처 여행 코스로 오롯이, 한옥 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 37.580099, 126.967905, '2026-10-08T21:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000682', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3056873', '영암 집영재', '오랜만에 여유 찾으러 영암 집영재 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "혼자여행", "힐링"]'::jsonb, 34.762847, 126.533752, '2026-10-12T10:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000683', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2647026', '석가헌', '평일 연차 쓰고 혼자 석가헌 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집", "혼자여행"]'::jsonb, 37.718956, 128.904566, '2026-10-10T01:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000684', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2598597', '덕여재', '예전부터 가보고 싶었던 덕여재 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행", "데이트"]'::jsonb, 36.540863, 128.516875, '2026-10-09T07:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000685', '54500700-0000-4000-8000-000000000132', 'p-tourapi-635593', '갈중이(천연염색체험)', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "풍경맛집"]'::jsonb, 33.234792, 126.313664, '2026-10-11T14:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000686', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2699326', '월출산 청풍명월', 'SNS에서 사진 보고 찾아간 월출산 청풍명월, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉", "온마루"]'::jsonb, 34.770031, 126.654803, '2026-10-12T06:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000687', '54500700-0000-4000-8000-000000000174', 'p-tourapi-319577', '경주 독락당', '근처 여행 코스로 경주 독락당 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "가족여행", "주말나들이"]'::jsonb, 36.016647, 129.160439, '2026-10-11T22:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000688', '54500700-0000-4000-8000-000000000080', 'p-tourapi-3452786', '시흥시청소년수련관', '예전부터 가보고 싶었던 시흥시청소년수련관 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "풍경맛집", "고즈넉"]'::jsonb, 37.446469, 126.797505, '2026-10-10T10:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000689', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2606219', '영천전투메모리얼파크', '드라이브 겸 나들이로 영천전투메모리얼파크 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 35.973691, 128.927279, '2026-10-12T01:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000690', '54500700-0000-4000-8000-000000000089', 'p-tourapi-3102073', '오원 스테이', '오원 스테이 다녀왔어요! 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁", "가족여행", "온마루"]'::jsonb, 35.836364, 129.209313, '2026-10-10T13:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000691', '54500700-0000-4000-8000-000000000092', 'p-tourapi-2621282', '사슴이랑배랑농원', '비 오는 날 운치 찾아 사슴이랑배랑농원 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["방문팁", "사진맛집", "주말나들이", "온마루"]'::jsonb, 35.187811, 126.591384, '2026-10-09T01:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000692', '54500700-0000-4000-8000-000000000187', 'p-tourapi-130854', '해미 청소년 문화의집', '주말에 친구들이랑 해미 청소년 문화의집 들렀는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉"]'::jsonb, 36.710119, 126.542894, '2026-10-11T19:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000693', '54500700-0000-4000-8000-000000000145', 'p-tourapi-2000725', '안동 수애당', '안동 수애당 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["가족여행", "인생샷", "주말나들이"]'::jsonb, 36.553581, 128.923408, '2026-10-12T10:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000694', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2702581', '강릉 오금집', '날씨가 너무 맑아서 강릉 오금집 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 37.756132, 128.894162, '2026-10-09T02:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000695', '54500700-0000-4000-8000-000000000083', 'p-tourapi-126419', '다산초당', '예전부터 가보고 싶었던 다산초당 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 34.580705, 126.745151, '2026-10-10T11:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000696', '54500700-0000-4000-8000-000000000148', 'p-tourapi-129030', '전주유씨 무실종택', '오랜만에 여유 찾으러 전주유씨 무실종택 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "고즈넉", "풍경맛집", "온마루"]'::jsonb, 36.553247, 128.923607, '2026-10-09T16:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000697', '54500700-0000-4000-8000-000000000130', 'p-tourapi-2768086', '한양 한옥마을점', '기대 이상으로 너무 좋았던 한양 한옥마을점! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 37.390668, 126.638868, '2026-10-08T17:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000698', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2594216', '전주한옥마당', '부모님 모시고 전주한옥마당 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 35.811601, 127.152115, '2026-10-11T04:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000699', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2624013', '별동산달빛아래', '기대 이상으로 너무 좋았던 별동산달빛아래! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행", "사색"]'::jsonb, 36.439102, 129.026879, '2026-10-08T23:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000700', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2595021', '동락원', '해 질 무렵에 동락원 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 35.816889, 127.152712, '2026-10-11T22:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000701', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3531662', '최선평 가옥', '근처 여행 코스로 최선평 가옥 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.878021, 128.795982, '2026-10-09T08:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000702', '54500700-0000-4000-8000-000000000122', 'p-tourapi-1621161', '제주 성읍마을 고창환 고택', '드라이브 겸 나들이로 제주 성읍마을 고창환 고택 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 33.387501, 126.800187, '2026-10-10T02:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000703', '54500700-0000-4000-8000-000000000198', 'p-tourapi-3577428', '고창 전통예술체험마을', '오랜만에 여유 찾으러 고창 전통예술체험마을 다녀왔습니다. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "사색", "혼자여행"]'::jsonb, 35.430268, 126.701425, '2026-10-11T19:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000704', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2821565', '룰루낭만협동조합', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "주말나들이", "방문팁"]'::jsonb, 35.235532, 128.881308, '2026-10-10T05:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000705', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3547622', '허균 허난설헌 기념공원 초희전통차체험관', 'SNS에서 사진 보고 찾아간 허균 허난설헌 기념공원 초희전통차체험관, 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "사진맛집", "방문팁", "온마루"]'::jsonb, 37.790992, 128.910239, '2026-10-10T01:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000706', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3533008', '청택고택', '오랜만에 여유 찾으러 청택고택 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "사색", "힐링", "온마루"]'::jsonb, 37.591630, 127.015795, '2026-10-10T13:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000707', '54500700-0000-4000-8000-000000000187', 'p-tourapi-1992038', '귀애고택', '기대 이상으로 너무 좋았던 귀애고택! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "주말나들이", "방문팁", "온마루"]'::jsonb, 36.057096, 128.874494, '2026-10-11T23:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000708', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2458168', '일락당사랑채', '드라이브 겸 나들이로 일락당사랑채 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "사진맛집"]'::jsonb, 35.816193, 127.152857, '2026-10-11T05:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000709', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2820370', '버들국수 (농업법인 주식회사 유화 ㈜)', '평일 연차 쓰고 혼자 버들국수 (농업법인 주식회사 유화 ㈜) 다녀옴. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 35.575959, 128.439036, '2026-10-10T12:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000710', '54500700-0000-4000-8000-000000000132', 'p-tourapi-3438629', '아늑', '드라이브 겸 나들이로 아늑 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "주말나들이", "인생샷"]'::jsonb, 36.554341, 128.757143, '2026-10-10T20:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000711', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2699354', '은혜당', '해 질 무렵에 은혜당 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 36.507635, 129.400360, '2026-10-11T07:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000712', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3532956', '경주황리단길숙소 한옥스테이 목화', '기대 이상으로 너무 좋았던 경주황리단길숙소 한옥스테이 목화! 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.836632, 129.211079, '2026-10-10T05:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000713', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2795007', '화성 정수영 고택', '조용히 사색하고 싶어서 찾은 화성 정수영 고택. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "사색"]'::jsonb, 37.132613, 126.701106, '2026-10-09T01:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000714', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2715383', '수고당', '근처 여행 코스로 수고당 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 37.485097, 128.848604, '2026-10-09T14:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000715', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2699328', '혜간헌', '기대 이상으로 너무 좋았던 혜간헌! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.462608, 127.116084, '2026-10-11T22:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000716', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2593235', '거목장민박', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 34.508296, 126.606811, '2026-10-08T14:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000717', '54500700-0000-4000-8000-000000000092', 'p-tourapi-129514', '정읍 전봉준 유적', '예전부터 가보고 싶었던 정읍 전봉준 유적 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "주말나들이", "온마루"]'::jsonb, 35.670833, 126.814297, '2026-10-12T04:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000718', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2638441', '제주탐나라공화국', 'SNS에서 사진 보고 찾아간 제주탐나라공화국, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 33.334394, 126.325517, '2026-10-11T06:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000719', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2804370', '화담재', '부모님 모시고 화담재 산책 겸 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 34.739227, 126.717122, '2026-10-11T05:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000720', '54500700-0000-4000-8000-000000000168', 'p-tourapi-128594', '창녕 석리 성씨고가', '드라이브 겸 나들이로 창녕 석리 성씨고가 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.556933, 128.459372, '2026-10-08T22:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000721', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2358186', '쌍산재', '예전부터 가보고 싶었던 쌍산재 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 35.215527, 127.497836, '2026-10-12T13:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000722', '54500700-0000-4000-8000-000000000090', 'p-tourapi-1081744', '한국전통음식문화체험관(정강원)', '한국전통음식문화체험관(정강원) 다녀왔어요! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 37.571059, 128.407987, '2026-10-10T18:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000723', '54500700-0000-4000-8000-000000000171', 'p-tourapi-1871270', '맥산댁', '근처 여행 코스로 맥산댁 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "고즈넉"]'::jsonb, 35.667381, 128.228522, '2026-10-11T01:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000724', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3006699', '어린이농장학농원', '어린이농장학농원 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 37.104298, 127.110540, '2026-10-11T13:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000725', '54500700-0000-4000-8000-000000000094', 'p-tourapi-130938', '광나루안전체험관', '평일 연차 쓰고 혼자 광나루안전체험관 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.551291, 127.077055, '2026-10-08T17:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000726', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2717604', '어슬티굿밤', '오랜만에 여유 찾으러 어슬티굿밤 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "산책로", "풍경맛집"]'::jsonb, 36.487874, 126.822776, '2026-10-09T14:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000727', '54500700-0000-4000-8000-000000000093', 'p-tourapi-3453166', '원주교육문화관 독도체험관', '원주교육문화관 독도체험관 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 37.351856, 127.934754, '2026-10-09T12:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000728', '54500700-0000-4000-8000-000000000157', 'p-tourapi-3483083', '간송옛집', '날씨가 너무 맑아서 간송옛집 한 바퀴 돌고 왔네요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 37.665265, 127.028177, '2026-10-10T07:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000729', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2676000', '응정헌', '해 질 무렵에 응정헌 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["인생샷", "주말나들이", "사진맛집"]'::jsonb, 37.640179, 126.939925, '2026-10-10T09:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000730', '54500700-0000-4000-8000-000000000175', 'p-tourapi-3438287', '사적인', '평일 연차 쓰고 혼자 사적인 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "사색", "풍경맛집"]'::jsonb, 37.574773, 126.982400, '2026-10-09T05:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000731', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2600498', '주실고택', '해 질 무렵에 주실고택 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 36.735328, 128.619088, '2026-10-10T20:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000732', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2621282', '사슴이랑배랑농원', '날씨가 너무 맑아서 사슴이랑배랑농원 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "데이트", "주말나들이", "온마루"]'::jsonb, 35.187654, 126.591150, '2026-10-09T13:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000733', '54500700-0000-4000-8000-000000000180', 'p-tourapi-3533116', '덕만재', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "인생샷", "가족여행", "온마루"]'::jsonb, 35.821625, 129.243802, '2026-10-10T15:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000734', '54500700-0000-4000-8000-000000000205', 'p-tourapi-1596067', '김정회고가', '김정회고가 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.439790, 126.659605, '2026-10-10T14:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000735', '54500700-0000-4000-8000-000000000156', 'p-tourapi-3442142', '서울숲 곤충식물원', '부모님 모시고 서울숲 곤충식물원 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "가족여행", "사진맛집", "온마루"]'::jsonb, 37.542949, 127.042249, '2026-10-11T18:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000736', '54500700-0000-4000-8000-000000000201', 'p-tourapi-3532773', '덕용재4.9', '날씨가 너무 맑아서 덕용재4.9 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 36.691835, 128.409507, '2026-10-09T06:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000737', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2638488', '거제 관광모노레일', '거제 관광모노레일 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링", "고즈넉", "온마루"]'::jsonb, 34.876729, 128.625134, '2026-10-08T14:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000738', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2633954', '산속등대 복합문화공간', '부모님 모시고 산속등대 복합문화공간 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "가족여행", "방문팁", "온마루"]'::jsonb, 35.869272, 127.251905, '2026-10-09T03:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000739', '54500700-0000-4000-8000-000000000079', 'p-tourapi-1579747', '거창 동호리 이씨고가', '드라이브 겸 나들이로 거창 동호리 이씨고가 선택했는데 대만족! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.799121, 127.927225, '2026-10-12T05:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000740', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2996749', '송금체험마을영농조합법인', '오랜만에 여유 찾으러 송금체험마을영농조합법인 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로", "혼자여행", "온마루"]'::jsonb, 35.713177, 128.720553, '2026-10-11T21:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000741', '54500700-0000-4000-8000-000000000186', 'p-tourapi-1884057', '태백산 한옥펜션', '기대 이상으로 너무 좋았던 태백산 한옥펜션! 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "풍경맛집", "고즈넉"]'::jsonb, 37.134352, 128.952190, '2026-10-12T10:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000742', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2674014', '비체올린', '주말에 친구들이랑 비체올린 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "데이트", "가족여행", "온마루"]'::jsonb, 33.349529, 126.218229, '2026-10-11T08:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000743', '54500700-0000-4000-8000-000000000122', 'p-tourapi-1579747', '거창 동호리 이씨고가', '부모님 모시고 거창 동호리 이씨고가 산책 겸 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "데이트"]'::jsonb, 35.798691, 127.927389, '2026-10-08T16:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000744', '54500700-0000-4000-8000-000000000148', 'p-tourapi-3072242', '이화당', '조용히 사색하고 싶어서 찾은 이화당. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 35.040235, 126.774336, '2026-10-11T16:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000745', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2598297', '목재고택', '비 오는 날 운치 찾아 목재고택 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "힐링", "풍경맛집"]'::jsonb, 36.742874, 128.863742, '2026-10-12T08:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000746', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2774723', '니지모리 스튜디오', '니지모리 스튜디오 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행", "방문팁", "온마루"]'::jsonb, 37.879423, 127.092270, '2026-10-09T00:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000747', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2725025', '소찬 협동조합', '주말에 친구들이랑 소찬 협동조합 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "사진맛집", "주말나들이"]'::jsonb, 36.513125, 126.814743, '2026-10-09T21:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000748', '54500700-0000-4000-8000-000000000177', 'p-tourapi-1621410', '김용학가옥', '부모님 모시고 김용학가옥 산책 겸 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 35.190410, 126.888374, '2026-10-09T03:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000749', '54500700-0000-4000-8000-000000000142', 'p-tourapi-3425093', '서울 인디스페이스', '천천히 골목 걷다가 마주친 서울 인디스페이스. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "가족여행", "데이트"]'::jsonb, 37.557284, 126.924827, '2026-10-10T19:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000750', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2651450', '한옥혜윰', '예전부터 가보고 싶었던 한옥혜윰 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "가족여행", "인생샷", "온마루"]'::jsonb, 35.811245, 127.152428, '2026-10-12T14:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000751', '54500700-0000-4000-8000-000000000096', 'p-tourapi-1883996', '취옹예술관', '주말에 친구들이랑 취옹예술관 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 37.752637, 127.359441, '2026-10-10T23:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000752', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2604371', '노을한옥', '해 질 무렵에 노을한옥 방문했는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 34.851504, 127.523184, '2026-10-08T23:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000753', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2650230', '문래예술공장', '주말에 친구들이랑 문래예술공장 들렀는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 37.512962, 126.900164, '2026-10-09T16:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000754', '54500700-0000-4000-8000-000000000081', 'p-tourapi-3448778', '양평 생활문화센터', '근처 여행 코스로 양평 생활문화센터 넣길 정말 잘했어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "방문팁"]'::jsonb, 37.499447, 127.477290, '2026-10-12T06:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000755', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2820838', '평창캠프닉', '평일 연차 쓰고 혼자 평창캠프닉 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "산책로"]'::jsonb, 37.578542, 128.331972, '2026-10-09T07:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000756', '54500700-0000-4000-8000-000000000160', 'p-tourapi-1619375', '조병수 가옥', '천천히 골목 걷다가 마주친 조병수 가옥. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "주말나들이"]'::jsonb, 37.451197, 126.404188, '2026-10-12T04:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000757', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2595672', '하회 양진당', '주말에 친구들이랑 하회 양진당 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 36.538896, 128.516241, '2026-10-10T01:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000758', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2994636', '다담한옥', '드라이브 겸 나들이로 다담한옥 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.588143, 129.059499, '2026-10-10T21:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000759', '54500700-0000-4000-8000-000000000144', 'p-tourapi-1997202', '여수 해상케이블카', '조용히 사색하고 싶어서 찾은 여수 해상케이블카. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 34.730920, 127.739425, '2026-10-10T22:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000760', '54500700-0000-4000-8000-000000000197', 'p-tourapi-127371', '수내동가옥(이택구가옥)', '오랜만에 여유 찾으러 수내동가옥(이택구가옥) 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 37.380659, 127.121516, '2026-10-09T15:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000761', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2603996', '매죽헌2(매죽헌한옥민박)', '해 질 무렵에 매죽헌2(매죽헌한옥민박) 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "가족여행"]'::jsonb, 35.069200, 127.401175, '2026-10-12T00:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000762', '54500700-0000-4000-8000-000000000204', 'p-tourapi-1972014', '삼락헌', '비 오는 날 운치 찾아 삼락헌 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 35.815729, 127.152986, '2026-10-11T11:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000763', '54500700-0000-4000-8000-000000000148', 'p-tourapi-1882853', '풍남헌', '부모님 모시고 풍남헌 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 35.816751, 127.152233, '2026-10-09T08:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000764', '54500700-0000-4000-8000-000000000159', 'p-tourapi-1621155', '제주 성읍마을 고평오 고택', '조용히 사색하고 싶어서 찾은 제주 성읍마을 고평오 고택. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집", "산책로"]'::jsonb, 33.385780, 126.801885, '2026-10-10T22:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000765', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2790490', '비손농장(포항체험잇다)', '부모님 모시고 비손농장(포항체험잇다) 산책 겸 다녀왔습니다. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 36.197750, 129.317587, '2026-10-11T18:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000766', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3021290', '자작자작협동조합', '주말에 친구들이랑 자작자작협동조합 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "방문팁", "데이트", "온마루"]'::jsonb, 36.969286, 127.932849, '2026-10-11T09:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000767', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2738663', '김환기고택', '오랜만에 여유 찾으러 김환기고택 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 34.752629, 126.121498, '2026-10-12T01:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000768', '54500700-0000-4000-8000-000000000142', 'p-tourapi-264284', '전북 전주 한옥마을 [슬로시티]', '조용히 사색하고 싶어서 찾은 전북 전주 한옥마을 [슬로시티]. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.818533, 127.153814, '2026-10-09T09:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000769', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2662467', '만천하 알파인코스터', '비 오는 날 운치 찾아 만천하 알파인코스터 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "가족여행", "사진맛집"]'::jsonb, 36.977587, 128.336670, '2026-10-11T20:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000770', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3511613', '전라감영양조장(전라감영주식회사)', '부모님 모시고 전라감영양조장(전라감영주식회사) 산책 겸 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["주말나들이", "방문팁", "온마루"]'::jsonb, 35.817313, 127.145828, '2026-10-08T21:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000771', '54500700-0000-4000-8000-000000000192', 'p-tourapi-2000648', '하회 북촌댁', '하회 북촌댁 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["사진맛집", "주말나들이", "가족여행"]'::jsonb, 36.539535, 128.518277, '2026-10-11T22:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000772', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2615320', '봄의 왈츠 드라마 촬영지', '봄의 왈츠 드라마 촬영지 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "풍경맛집", "산책로"]'::jsonb, 34.170227, 126.862469, '2026-10-10T10:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000773', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2612909', '해남 공재고택', '기대 이상으로 너무 좋았던 해남 공재고택! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "고즈넉", "산책로", "온마루"]'::jsonb, 34.440569, 126.518559, '2026-10-12T04:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000774', '54500700-0000-4000-8000-000000000152', 'p-tourapi-3536364', '속리산 테마파크', '주말에 친구들이랑 속리산 테마파크 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.497971, 127.792274, '2026-10-09T11:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000775', '54500700-0000-4000-8000-000000000160', 'p-tourapi-3438379', '더 모먼트', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "주말나들이"]'::jsonb, 37.577543, 126.970323, '2026-10-12T06:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000776', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2814147', '순천만숲', '기대 이상으로 너무 좋았던 순천만숲! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 34.896900, 127.506353, '2026-10-10T21:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000777', '54500700-0000-4000-8000-000000000066', 'p-tourapi-879633', '물드리네', '천천히 골목 걷다가 마주친 물드리네. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 33.322685, 126.226798, '2026-10-09T06:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000778', '54500700-0000-4000-8000-000000000145', 'p-tourapi-1623646', '권희문가옥', '날씨가 너무 맑아서 권희문가옥 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 35.587616, 127.386557, '2026-10-12T09:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000779', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2613459', '공주 중학동 구 선교사 가옥', '날씨가 너무 맑아서 공주 중학동 구 선교사 가옥 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색", "혼자여행", "온마루"]'::jsonb, 36.449321, 127.126305, '2026-10-10T04:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000780', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2605443', '사나래한옥', '근처 여행 코스로 사나래한옥 넣길 정말 잘했어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "힐링"]'::jsonb, 34.837177, 126.902684, '2026-10-09T02:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000781', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3426935', '구리문화재단', '구리문화재단 다녀왔어요! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 37.595735, 127.129462, '2026-10-10T02:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000782', '54500700-0000-4000-8000-000000000058', 'p-tourapi-4012448', '검무한옥 호운당', '부모님 모시고 검무한옥 호운당 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.575151, 128.511154, '2026-10-10T08:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000783', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2781621', '숫골', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 36.829802, 128.625224, '2026-10-09T10:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000784', '54500700-0000-4000-8000-000000000099', 'p-tourapi-1685586', '청풍 황석리 고가', '날씨가 너무 맑아서 청풍 황석리 고가 한 바퀴 돌고 왔네요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 37.005640, 128.170158, '2026-10-12T10:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000785', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2700309', '경주읍성한옥', '해 질 무렵에 경주읍성한옥 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "주말나들이", "데이트", "온마루"]'::jsonb, 35.849932, 129.211678, '2026-10-08T17:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000786', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2996133', '(주)손으로만드는수공예', '기대 이상으로 너무 좋았던 (주)손으로만드는수공예! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "사진맛집", "인생샷", "온마루"]'::jsonb, 36.099006, 127.492997, '2026-10-08T21:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000787', '54500700-0000-4000-8000-000000000141', 'p-tourapi-803988', '순천 용오름마을 [농촌전통테마마을]', '평일 연차 쓰고 혼자 순천 용오름마을 [농촌전통테마마을] 다녀옴. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 35.092283, 127.202308, '2026-10-11T08:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000788', '54500700-0000-4000-8000-000000000080', 'p-tourapi-635593', '갈중이(천연염색체험)', '갈중이(천연염색체험) 다녀왔어요! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "고즈넉"]'::jsonb, 33.235158, 126.313457, '2026-10-10T12:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000789', '54500700-0000-4000-8000-000000000074', 'p-tourapi-1433369', '괴산 김항묵 고택', '천천히 골목 걷다가 마주친 괴산 김항묵 고택. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 36.781838, 127.859604, '2026-10-09T03:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000790', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438329', '안유재', '천천히 골목 걷다가 마주친 안유재. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "풍경맛집", "산책로"]'::jsonb, 37.583323, 126.987605, '2026-10-10T02:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000791', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2939588', '행주커뮤니티센터', '행주커뮤니티센터 다녀왔어요! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.602680, 126.823058, '2026-10-12T00:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000792', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2357469', '훈몽재 유지', '평일 연차 쓰고 혼자 훈몽재 유지 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 35.472710, 126.968727, '2026-10-08T22:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000793', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2725025', '소찬 협동조합', '주말에 친구들이랑 소찬 협동조합 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "힐링", "온마루"]'::jsonb, 36.513356, 126.814850, '2026-10-09T19:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000794', '54500700-0000-4000-8000-000000000188', 'p-tourapi-3006699', '어린이농장학농원', '근처 여행 코스로 어린이농장학농원 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "가족여행", "온마루"]'::jsonb, 37.104621, 127.110799, '2026-10-10T17:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000795', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2600221', '박정우가옥', '툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 36.734709, 128.619708, '2026-10-09T04:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000796', '54500700-0000-4000-8000-000000000066', 'p-tourapi-4072014', '스테이 화녹', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.801419, 129.196828, '2026-10-11T07:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000797', '54500700-0000-4000-8000-000000000140', 'p-tourapi-319577', '경주 독락당', '조용히 사색하고 싶어서 찾은 경주 독락당. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.016426, 129.160120, '2026-10-11T21:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000798', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2996115', '야미야미팜(야미야미팜농업회사법인(주))', '주말에 친구들이랑 야미야미팜(야미야미팜농업회사법인(주)) 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 34.704876, 126.614056, '2026-10-11T09:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000799', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2701356', '달빛한옥 수류화개', '근처 여행 코스로 달빛한옥 수류화개 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "혼자여행", "온마루"]'::jsonb, 34.739528, 126.716949, '2026-10-09T17:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000800', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2603889', '문행당', '평일 연차 쓰고 혼자 문행당 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 36.913123, 128.740912, '2026-10-10T04:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000801', '54500700-0000-4000-8000-000000000067', 'p-tourapi-1872077', '석정댁', '날씨가 너무 맑아서 석정댁 한 바퀴 돌고 왔네요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.666962, 128.229067, '2026-10-02T05:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000802', '54500700-0000-4000-8000-000000000205', 'p-tourapi-4079535', '우구정가옥', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로", "고즈넉", "온마루"]'::jsonb, 37.205148, 128.377852, '2026-10-04T17:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000803', '54500700-0000-4000-8000-000000000174', 'p-tourapi-1883367', '축구꿈나무집', '드라이브 겸 나들이로 축구꿈나무집 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 35.667347, 128.229038, '2026-10-01T20:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000804', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2721915', '밀양 월연정', '비 오는 날 운치 찾아 밀양 월연정 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "사색", "온마루"]'::jsonb, 35.498592, 128.779986, '2026-10-08T09:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000805', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2595871', '나들한옥', '주말에 친구들이랑 나들한옥 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집", "산책로", "온마루"]'::jsonb, 35.836194, 129.218568, '2026-10-05T04:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000806', '54500700-0000-4000-8000-000000000115', 'p-tourapi-127664', '최참판댁', '평일 연차 쓰고 혼자 최참판댁 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.155473, 127.688346, '2026-10-08T03:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000807', '54500700-0000-4000-8000-000000000140', 'p-tourapi-1870849', '덕동댁', '오랜만에 여유 찾으러 덕동댁 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "산책로", "풍경맛집"]'::jsonb, 35.666819, 128.228243, '2026-10-01T15:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000808', '54500700-0000-4000-8000-000000000132', 'p-tourapi-1583137', '이배원 가옥', '오랜만에 여유 찾으러 이배원 가옥 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.060379, 126.910186, '2026-10-07T02:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000809', '54500700-0000-4000-8000-000000000177', 'p-tourapi-3532999', '한옥,만월 프리미엄스테이', '비 오는 날 운치 찾아 한옥,만월 프리미엄스테이 다녀왔어요. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "사진맛집", "방문팁"]'::jsonb, 35.862301, 128.598125, '2026-10-04T16:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000810', '54500700-0000-4000-8000-000000000198', 'p-tourapi-3536364', '속리산 테마파크', 'SNS에서 사진 보고 찾아간 속리산 테마파크, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["데이트", "가족여행", "온마루"]'::jsonb, 36.498062, 127.791863, '2026-10-05T00:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000811', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2855009', '한옥 생고기', '드라이브 겸 나들이로 한옥 생고기 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 37.949154, 127.189290, '2026-10-05T20:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000812', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3454381', '디즈니스토어 현대프리미엄아울렛 대전점', '조용히 사색하고 싶어서 찾은 디즈니스토어 현대프리미엄아울렛 대전점. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "혼자여행", "고즈넉", "온마루"]'::jsonb, 36.423556, 127.398704, '2026-10-04T17:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000813', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1865597', '가람초연재', '주말에 친구들이랑 가람초연재 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.538920, 128.516107, '2026-10-05T05:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000814', '54500700-0000-4000-8000-000000000073', 'p-tourapi-4065036', '스테이로이', '천천히 골목 걷다가 마주친 스테이로이. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "인생샷", "사진맛집", "온마루"]'::jsonb, 36.102843, 127.486562, '2026-10-04T22:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000815', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2657838', '마차리폐광촌', '날씨가 너무 맑아서 마차리폐광촌 한 바퀴 돌고 왔네요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "힐링", "혼자여행", "온마루"]'::jsonb, 37.255140, 128.456053, '2026-10-08T10:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000816', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3511602', '주식회사조아지구', '드라이브 겸 나들이로 주식회사조아지구 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 35.944269, 127.164066, '2026-10-05T02:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000817', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2822187', '꽃동네제빵소(꽃구움)', '예전부터 가보고 싶었던 꽃동네제빵소(꽃구움) 드디어 방문! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "힐링"]'::jsonb, 36.890607, 127.566815, '2026-10-08T01:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000818', '54500700-0000-4000-8000-000000000096', 'p-tourapi-4012463', '검무한옥 휴복당', '해 질 무렵에 검무한옥 휴복당 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 36.575779, 128.511911, '2026-10-04T21:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000819', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2668524', '이천백사 산수유영농조합법인(이천산수유마을)', '드라이브 겸 나들이로 이천백사 산수유영농조합법인(이천산수유마을) 선택했는데 대만족! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 37.340711, 127.462535, '2026-10-02T16:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000820', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2707439', '스테이 데이 오프', '날씨가 너무 맑아서 스테이 데이 오프 한 바퀴 돌고 왔네요. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 37.577209, 126.970833, '2026-10-08T12:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000821', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2623585', '별궁', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "가족여행", "온마루"]'::jsonb, 36.940757, 126.301228, '2026-10-03T02:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000822', '54500700-0000-4000-8000-000000000125', 'p-tourapi-3007507', '호수양조장', '천천히 골목 걷다가 마주친 호수양조장. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 37.872060, 127.731092, '2026-10-03T12:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000823', '54500700-0000-4000-8000-000000000082', 'p-tourapi-1390248', '장흥 오헌고택', '조용히 사색하고 싶어서 찾은 장흥 오헌고택. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 34.549021, 126.939803, '2026-10-07T02:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000824', '54500700-0000-4000-8000-000000000163', 'p-tourapi-1937772', '계룡 사계고택', '계룡 사계고택 다녀왔어요! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 36.265876, 127.271512, '2026-10-01T17:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000825', '54500700-0000-4000-8000-000000000187', 'p-tourapi-129514', '정읍 전봉준 유적', '드라이브 겸 나들이로 정읍 전봉준 유적 선택했는데 대만족! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.670877, 126.814611, '2026-10-08T07:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000826', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3447048', '사우당 종택', '조용히 사색하고 싶어서 찾은 사우당 종택. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 35.828516, 128.215043, '2026-10-02T06:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000827', '54500700-0000-4000-8000-000000000111', 'p-tourapi-3438599', '이사빛1968 한옥스테이', '기대 이상으로 너무 좋았던 이사빛1968 한옥스테이! 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["방문팁", "주말나들이"]'::jsonb, 36.564887, 128.737359, '2026-10-01T20:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000828', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3065503', '전주 대사습청', '조용히 사색하고 싶어서 찾은 전주 대사습청. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.817558, 127.153416, '2026-10-02T23:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000829', '54500700-0000-4000-8000-000000000205', 'p-tourapi-1436162', '괴산 이창훈 고가', '조용히 사색하고 싶어서 찾은 괴산 이창훈 고가. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.840854, 127.858835, '2026-10-08T05:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000830', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2606387', '예천군체육회활체험센터', '주말에 친구들이랑 예천군체육회활체험센터 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "사진맛집", "방문팁"]'::jsonb, 36.634918, 128.468750, '2026-10-03T23:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000831', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2600265', '섬계고택', '주말에 친구들이랑 섬계고택 들렀는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 36.734436, 128.618478, '2026-10-06T21:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000832', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3080477', '수원전통문화관', '비 오는 날 운치 찾아 수원전통문화관 다녀왔어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "사진맛집", "주말나들이"]'::jsonb, 37.287642, 127.014900, '2026-10-08T08:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000833', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3469883', '서동선화한옥', '평일 연차 쓰고 혼자 서동선화한옥 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 36.291909, 126.927813, '2026-10-03T00:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000834', '54500700-0000-4000-8000-000000000164', 'p-tourapi-3438412', '중림재', '비 오는 날 운치 찾아 중림재 다녀왔어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행", "온마루"]'::jsonb, 37.558137, 126.967751, '2026-10-06T02:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000835', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2705419', '피크닉댕댕', '기대 이상으로 너무 좋았던 피크닉댕댕! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "가족여행", "인생샷"]'::jsonb, 37.866788, 127.108597, '2026-10-07T06:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000836', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2715385', '난포정(蘭浦亭)', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "사진맛집", "온마루"]'::jsonb, 37.482328, 128.849754, '2026-10-03T14:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000837', '54500700-0000-4000-8000-000000000162', 'p-tourapi-1992038', '귀애고택', '조용히 사색하고 싶어서 찾은 귀애고택. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "고즈넉"]'::jsonb, 36.057214, 128.874546, '2026-10-08T11:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000838', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3351567', '충남안전체험관', '해 질 무렵에 충남안전체험관 방문했는데 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "사진맛집", "데이트"]'::jsonb, 36.821958, 127.191763, '2026-10-03T07:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000839', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2576865', '한옥산에산에', '한옥산에산에 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.198297, 128.558382, '2026-10-03T09:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000840', '54500700-0000-4000-8000-000000000154', 'p-tourapi-893974', '개평한옥마을', '조용히 사색하고 싶어서 찾은 개평한옥마을. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 35.565594, 127.767314, '2026-10-05T16:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000841', '54500700-0000-4000-8000-000000000153', 'p-tourapi-126537', '북촌한옥마을', '오랜만에 여유 찾으러 북촌한옥마을 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "사색", "풍경맛집"]'::jsonb, 37.579076, 126.986758, '2026-10-04T16:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000842', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2620413', '병암고택', '병암고택 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색", "혼자여행", "온마루"]'::jsonb, 36.557953, 129.128142, '2026-10-06T08:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000843', '54500700-0000-4000-8000-000000000184', 'p-tourapi-4039810', '스테이꼬리', '부모님 모시고 스테이꼬리 산책 겸 다녀왔습니다. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.812812, 129.212701, '2026-10-07T05:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000844', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2717549', '순솝', '예전부터 가보고 싶었던 순솝 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 34.947689, 127.503938, '2026-10-04T07:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000845', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2544638', '바운스 트램폴린파크 동대구신세계백화점센터', '주말에 친구들이랑 바운스 트램폴린파크 동대구신세계백화점센터 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.879945, 128.633147, '2026-10-08T02:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000846', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2604344', '락희원', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "풍경맛집", "산책로"]'::jsonb, 35.837541, 129.212094, '2026-10-05T17:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000847', '54500700-0000-4000-8000-000000000147', 'p-tourapi-3454469', '아동청소년친화공간 꿈이랑', '부모님 모시고 아동청소년친화공간 꿈이랑 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 38.199577, 128.580611, '2026-10-04T05:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000848', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2613456', '금강아트센터', '마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["사진맛집", "가족여행", "방문팁"]'::jsonb, 36.428770, 127.201988, '2026-10-03T03:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000849', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2610526', '안정궁 관광 한옥 펜션', '평일 연차 쓰고 혼자 안정궁 관광 한옥 펜션 다녀옴. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 34.945729, 128.397848, '2026-10-06T16:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000850', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2747760', '그라운드플래닛', '근처 여행 코스로 그라운드플래닛 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "혼자여행", "고즈넉"]'::jsonb, 37.433914, 127.011013, '2026-10-04T07:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000851', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2804370', '화담재', '기대 이상으로 너무 좋았던 화담재! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "가족여행", "인생샷"]'::jsonb, 34.738892, 126.716457, '2026-10-02T22:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000852', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3438182', '여느날', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "가족여행", "온마루"]'::jsonb, 37.576396, 126.969287, '2026-10-02T14:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000853', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3442142', '서울숲 곤충식물원', '비 오는 날 운치 찾아 서울숲 곤충식물원 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 37.543232, 127.041635, '2026-10-03T11:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000854', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2668091', '구림전통한옥민박', '구림전통한옥민박 다녀왔어요! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행", "주말나들이"]'::jsonb, 34.763271, 126.621323, '2026-10-02T10:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000855', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3452786', '시흥시청소년수련관', '시흥시청소년수련관 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "데이트", "주말나들이", "온마루"]'::jsonb, 37.446577, 126.797048, '2026-10-06T09:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000856', '54500700-0000-4000-8000-000000000064', 'p-tourapi-129448', '두륜산케이블카', '드라이브 겸 나들이로 두륜산케이블카 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "인생샷", "데이트", "온마루"]'::jsonb, 34.496896, 126.625164, '2026-10-05T12:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000857', '54500700-0000-4000-8000-000000000109', 'p-tourapi-1872077', '석정댁', '비 오는 날 운치 찾아 석정댁 다녀왔어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.667403, 128.229049, '2026-10-01T16:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000858', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2663054', '경주 춘추관', '드라이브 겸 나들이로 경주 춘추관 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "주말나들이", "가족여행", "온마루"]'::jsonb, 35.822977, 129.186006, '2026-10-06T15:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000859', '54500700-0000-4000-8000-000000000138', 'p-tourapi-3469883', '서동선화한옥', '주말에 친구들이랑 서동선화한옥 들렀는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 36.291895, 126.927809, '2026-10-05T04:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000860', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3421909', '그런고로', '그런고로 다녀왔어요! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.157388, 129.064281, '2026-10-07T13:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000861', '54500700-0000-4000-8000-000000000069', 'p-tourapi-1971844', '필봉문화촌 취락원', '드라이브 겸 나들이로 필봉문화촌 취락원 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "고즈넉", "산책로", "온마루"]'::jsonb, 35.537534, 127.154928, '2026-10-05T04:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000862', '54500700-0000-4000-8000-000000000152', 'p-tourapi-1624505', '해남 민정기 가옥', '평일 연차 쓰고 혼자 해남 민정기 가옥 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "고즈넉", "산책로", "온마루"]'::jsonb, 34.542468, 126.568407, '2026-10-07T23:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000863', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3533116', '덕만재', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.822144, 129.244146, '2026-10-03T01:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000864', '54500700-0000-4000-8000-000000000072', 'p-tourapi-3013272', '무계원', '예전부터 가보고 싶었던 무계원 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "풍경맛집"]'::jsonb, 37.591849, 126.963527, '2026-10-06T16:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000865', '54500700-0000-4000-8000-000000000102', 'p-tourapi-801918', '무안 감풀마을 [농촌전통테마]', '무안 감풀마을 [농촌전통테마] 다녀왔어요! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 35.060902, 126.406024, '2026-10-06T13:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000866', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2996647', '정촌유기농원', '예전부터 가보고 싶었던 정촌유기농원 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "주말나들이", "데이트", "온마루"]'::jsonb, 36.425705, 126.672074, '2026-10-04T16:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000867', '54500700-0000-4000-8000-000000000146', 'p-tourapi-3072218', '오히', '날씨가 너무 맑아서 오히 한 바퀴 돌고 왔네요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.824126, 129.212896, '2026-10-03T21:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000868', '54500700-0000-4000-8000-000000000164', 'p-tourapi-1372956', '이상화 고택', '평일 연차 쓰고 혼자 이상화 고택 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.867470, 128.588347, '2026-10-05T17:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000869', '54500700-0000-4000-8000-000000000108', 'p-tourapi-126537', '북촌한옥마을', '평일 연차 쓰고 혼자 북촌한옥마을 다녀옴. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 37.579098, 126.986588, '2026-10-02T22:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000870', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2724392', '은평한옥마을', '기대 이상으로 너무 좋았던 은평한옥마을! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 37.641215, 126.939490, '2026-10-05T12:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000871', '54500700-0000-4000-8000-000000000141', 'p-tourapi-128645', '춘천최재근가옥', '해 질 무렵에 춘천최재근가옥 방문했는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "데이트", "사진맛집"]'::jsonb, 37.843023, 127.727864, '2026-10-08T09:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000872', '54500700-0000-4000-8000-000000000181', 'p-tourapi-894145', '명품옻골 1616 협동조합', 'SNS에서 사진 보고 찾아간 명품옻골 1616 협동조합, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 35.907753, 128.686634, '2026-10-02T02:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000873', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3511018', '주식회사어반힐링', '조용히 사색하고 싶어서 찾은 주식회사어반힐링. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 35.111815, 128.964977, '2026-10-03T10:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000874', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2603913', '후연지한옥펜션', 'SNS에서 사진 보고 찾아간 후연지한옥펜션, 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "혼자여행", "힐링"]'::jsonb, 35.780610, 129.204041, '2026-10-06T00:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000875', '54500700-0000-4000-8000-000000000189', 'p-tourapi-3101971', '나모:온', '비 오는 날 운치 찾아 나모:온 다녀왔어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁", "주말나들이"]'::jsonb, 34.951407, 127.481347, '2026-10-08T09:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000876', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2718257', '서울웨이브아트센터', '전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.518531, 127.007307, '2026-10-02T20:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000877', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2744514', '합천목재문화체험장', '합천목재문화체험장 다녀왔어요! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 35.548606, 128.073149, '2026-10-02T21:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000878', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2722936', '아모레 성수', 'SNS에서 사진 보고 찾아간 아모레 성수, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "가족여행", "인생샷"]'::jsonb, 37.544561, 127.059255, '2026-10-02T11:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000879', '54500700-0000-4000-8000-000000000110', 'p-tourapi-127337', '당진 필경사', '당진 필경사 다녀왔어요! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["데이트", "주말나들이"]'::jsonb, 36.951878, 126.772017, '2026-10-08T03:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000880', '54500700-0000-4000-8000-000000000146', 'p-tourapi-128542', '안성 정무공 오정방 고택', '부모님 모시고 안성 정무공 오정방 고택 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 37.045459, 127.186113, '2026-10-07T22:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000881', '54500700-0000-4000-8000-000000000180', 'p-tourapi-1867806', '공주한옥마을', '공주한옥마을 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "방문팁", "주말나들이"]'::jsonb, 36.464642, 127.108688, '2026-10-06T20:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000882', '54500700-0000-4000-8000-000000000168', 'p-tourapi-3510971', '컬러브릿지협동조합', '근처 여행 코스로 컬러브릿지협동조합 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 35.141391, 126.916685, '2026-10-07T02:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000883', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2604833', '해로당', '날씨가 너무 맑아서 해로당 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "인생샷", "가족여행"]'::jsonb, 34.739724, 126.717482, '2026-10-02T02:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000884', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2696528', '토박이숙박', '부모님 모시고 토박이숙박 산책 겸 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 35.813633, 127.151687, '2026-10-02T04:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000885', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3540259', '한옥스테이 파인앤프렌즈', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 37.776400, 128.932748, '2026-10-07T07:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000886', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2586166', '황토한옥고마', '기대 이상으로 너무 좋았던 황토한옥고마! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 36.461481, 127.122704, '2026-10-06T20:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000887', '54500700-0000-4000-8000-000000000089', 'p-tourapi-3438041', '유선재', '주말에 친구들이랑 유선재 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.490446, 127.709520, '2026-10-08T13:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000888', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3102068', '경주 황리단길 한옥 독채 풀빌라 무와', '드라이브 겸 나들이로 경주 황리단길 한옥 독채 풀빌라 무와 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 35.835902, 129.208209, '2026-10-06T02:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000889', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2569980', '온고을', '주말에 친구들이랑 온고을 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "가족여행", "사진맛집"]'::jsonb, 35.812380, 127.152590, '2026-10-05T23:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000890', '54500700-0000-4000-8000-000000000059', 'p-tourapi-4074857', '미옥스테이', '근처 여행 코스로 미옥스테이 넣길 정말 잘했어요. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로", "사색", "온마루"]'::jsonb, 35.866977, 128.611949, '2026-10-06T08:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000891', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2717492', '비녀랑 한복이랑', '부모님 모시고 비녀랑 한복이랑 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "방문팁", "가족여행", "온마루"]'::jsonb, 36.630061, 127.287381, '2026-10-05T08:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000892', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3452166', '커넥트현대', '해 질 무렵에 커넥트현대 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "사진맛집", "데이트", "온마루"]'::jsonb, 35.141440, 129.058141, '2026-10-04T21:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000893', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2717600', '이플아토', '해 질 무렵에 이플아토 방문했는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 36.451802, 126.803568, '2026-10-04T22:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000894', '54500700-0000-4000-8000-000000000075', 'p-tourapi-126387', '전주 풍패지관 (전주객사)', '천천히 골목 걷다가 마주친 전주 풍패지관 (전주객사). 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행", "인생샷", "온마루"]'::jsonb, 35.818758, 127.145418, '2026-10-06T20:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000895', '54500700-0000-4000-8000-000000000187', 'p-tourapi-1991992', '고택 한옥에서', '천천히 골목 걷다가 마주친 고택 한옥에서. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "가족여행", "사진맛집", "온마루"]'::jsonb, 35.237562, 127.020450, '2026-10-07T21:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000896', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3438082', '안길사가', '해 질 무렵에 안길사가 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 37.577307, 126.984747, '2026-10-03T03:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000897', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2822187', '꽃동네제빵소(꽃구움)', '해 질 무렵에 꽃동네제빵소(꽃구움) 방문했는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉", "산책로"]'::jsonb, 36.890689, 127.566310, '2026-10-06T15:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000898', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3438545', '예맥당 한옥스테이', '부모님 모시고 예맥당 한옥스테이 산책 겸 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "힐링"]'::jsonb, 37.640686, 126.938786, '2026-10-07T04:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000899', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2993194', '위라이드 서울전차', '천천히 골목 걷다가 마주친 위라이드 서울전차. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행", "고즈넉"]'::jsonb, 37.571032, 126.980354, '2026-10-05T08:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000900', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2650230', '문래예술공장', '예전부터 가보고 싶었던 문래예술공장 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "주말나들이", "온마루"]'::jsonb, 37.513394, 126.900069, '2026-10-07T12:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000901', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3438735', '소월담', '근처 여행 코스로 소월담 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.579141, 126.985724, '2026-10-02T13:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000902', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2514834', '죽정분교(구,죽정초등학교)', '평일 연차 쓰고 혼자 죽정분교(구,죽정초등학교) 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 38.470562, 128.420134, '2026-10-02T03:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000903', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3072242', '이화당', '천천히 골목 걷다가 마주친 이화당. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 35.040196, 126.773935, '2026-10-02T21:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000904', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3532759', '스테이 희와', '오랜만에 여유 찾으러 스테이 희와 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 37.589297, 126.998389, '2026-10-05T10:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000905', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2576343', '뜰안채', '부모님 모시고 뜰안채 산책 겸 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "사진맛집", "방문팁", "온마루"]'::jsonb, 35.817047, 127.149390, '2026-10-08T13:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000906', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2587355', '소이한옥', '예전부터 가보고 싶었던 소이한옥 드디어 방문! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색", "풍경맛집"]'::jsonb, 35.834832, 129.211895, '2026-10-05T23:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000907', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2820629', '부여북포한옥마을', '부여북포한옥마을 다녀왔어요! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 36.292845, 126.924476, '2026-10-02T22:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000908', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3425093', '서울 인디스페이스', '평일 연차 쓰고 혼자 서울 인디스페이스 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "풍경맛집", "혼자여행"]'::jsonb, 37.557119, 126.925374, '2026-10-03T01:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000909', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3337799', '레이홉', '기대 이상으로 너무 좋았던 레이홉! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 35.542531, 129.307037, '2026-10-04T22:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000910', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2795956', '양평 창대리 고가', '평일 연차 쓰고 혼자 양평 창대리 고가 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "산책로"]'::jsonb, 37.470863, 127.506276, '2026-10-07T11:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000911', '54500700-0000-4000-8000-000000000091', 'p-tourapi-4079535', '우구정가옥', '오랜만에 여유 찾으러 우구정가옥 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 37.205367, 128.377729, '2026-10-07T15:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000912', '54500700-0000-4000-8000-000000000164', 'p-tourapi-3532989', '예선재', '주말에 친구들이랑 예선재 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.962075, 127.938253, '2026-10-08T10:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000913', '54500700-0000-4000-8000-000000000059', 'p-tourapi-1606009', '삼청동오위장김춘영가옥', '기대 이상으로 너무 좋았던 삼청동오위장김춘영가옥! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "방문팁", "가족여행"]'::jsonb, 37.558883, 126.994955, '2026-10-02T16:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000914', '54500700-0000-4000-8000-000000000064', 'p-tourapi-3532883', '소풍한옥풀빌라', '예전부터 가보고 싶었던 소풍한옥풀빌라 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "사색"]'::jsonb, 35.855969, 129.266964, '2026-10-04T04:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000915', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2789827', '제천 김세균 고가', '조용히 사색하고 싶어서 찾은 제천 김세균 고가. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 36.881691, 128.080206, '2026-10-05T08:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000916', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2992824', '락고재 컬쳐 라운지 애가헌', '천천히 골목 걷다가 마주친 락고재 컬쳐 라운지 애가헌. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 37.582275, 126.983726, '2026-10-08T11:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000917', '54500700-0000-4000-8000-000000000141', 'p-tourapi-3438379', '더 모먼트', '비 오는 날 운치 찾아 더 모먼트 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 37.577629, 126.970598, '2026-10-03T13:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000918', '54500700-0000-4000-8000-000000000200', 'p-tourapi-2603918', '(사)영남선비문화수련원(구암서원)', '주말에 친구들이랑 (사)영남선비문화수련원(구암서원) 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.901507, 128.596962, '2026-10-08T02:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000919', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3543415', '주문진문화교육센터', '드라이브 겸 나들이로 주문진문화교육센터 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 37.882099, 128.822645, '2026-10-04T11:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000920', '54500700-0000-4000-8000-000000000153', 'p-tourapi-3438485', '다락재', '주말에 친구들이랑 다락재 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "풍경맛집", "힐링"]'::jsonb, 37.641212, 126.939723, '2026-10-01T17:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000921', '54500700-0000-4000-8000-000000000184', 'p-tourapi-2996115', '야미야미팜(야미야미팜농업회사법인(주))', '드라이브 겸 나들이로 야미야미팜(야미야미팜농업회사법인(주)) 선택했는데 대만족! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트", "인생샷", "온마루"]'::jsonb, 34.704491, 126.613915, '2026-10-03T19:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000922', '54500700-0000-4000-8000-000000000183', 'p-tourapi-3337799', '레이홉', '레이홉 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "사진맛집"]'::jsonb, 35.542347, 129.307367, '2026-10-07T05:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000923', '54500700-0000-4000-8000-000000000146', 'p-tourapi-1626780', '예산 오추리 고택(정동호 가옥)', '평일 연차 쓰고 혼자 예산 오추리 고택(정동호 가옥) 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "혼자여행", "풍경맛집"]'::jsonb, 36.763913, 126.719995, '2026-10-04T17:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000924', '54500700-0000-4000-8000-000000000201', 'p-tourapi-4074856', '연림스테이', '바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "혼자여행", "온마루"]'::jsonb, 35.972039, 128.698633, '2026-10-01T19:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000925', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2602196', '의양리 권진사댁', '해 질 무렵에 의양리 권진사댁 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 36.944706, 128.912658, '2026-10-04T14:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000926', '54500700-0000-4000-8000-000000000096', 'p-tourapi-3459013', '월영광장', '조용히 사색하고 싶어서 찾은 월영광장. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "고즈넉", "사색"]'::jsonb, 35.180491, 128.558068, '2026-10-02T20:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000927', '54500700-0000-4000-8000-000000000102', 'p-tourapi-1883070', '정재종택', '부모님 모시고 정재종택 산책 겸 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "사색", "온마루"]'::jsonb, 36.559316, 128.915427, '2026-10-05T19:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000928', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2764323', '은평역사한옥박물관', '해 질 무렵에 은평역사한옥박물관 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["방문팁", "인생샷", "온마루"]'::jsonb, 37.640501, 126.937919, '2026-10-07T18:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000929', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2732271', '수작코리아', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "방문팁", "인생샷", "온마루"]'::jsonb, 37.717693, 126.877187, '2026-10-08T06:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000930', '54500700-0000-4000-8000-000000000171', 'p-tourapi-3080013', '에덴파크 단양', '날씨가 너무 맑아서 에덴파크 단양 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "가족여행"]'::jsonb, 36.929687, 128.334115, '2026-10-06T09:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000931', '54500700-0000-4000-8000-000000000177', 'p-tourapi-1992543', '송정고택', '예전부터 가보고 싶었던 송정고택 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["사진맛집", "주말나들이", "인생샷", "온마루"]'::jsonb, 36.435881, 129.026141, '2026-10-02T20:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000932', '54500700-0000-4000-8000-000000000137', 'p-tourapi-3438653', '호호재', '근처 여행 코스로 호호재 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["방문팁", "데이트", "온마루"]'::jsonb, 36.560539, 128.710428, '2026-10-03T14:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000933', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2613254', '도봉서당', '부모님 모시고 도봉서당 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 35.827740, 129.184760, '2026-10-07T07:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000934', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2706047', '한옥 게스트하우스 동촌재', '오랜만에 여유 찾으러 한옥 게스트하우스 동촌재 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "혼자여행", "산책로"]'::jsonb, 37.580133, 126.969561, '2026-10-05T21:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000935', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2932871', '한복입고 유유자적 (주식회사고영)', '천천히 골목 걷다가 마주친 한복입고 유유자적 (주식회사고영). 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행", "방문팁"]'::jsonb, 34.760309, 126.623540, '2026-10-02T18:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000936', '54500700-0000-4000-8000-000000000078', 'p-tourapi-1606014', '순정효황후윤씨친가', '평일 연차 쓰고 혼자 순정효황후윤씨친가 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "산책로", "고즈넉"]'::jsonb, 37.558664, 126.994061, '2026-10-03T19:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000937', '54500700-0000-4000-8000-000000000163', 'p-tourapi-3421909', '그런고로', '비 오는 날 운치 찾아 그런고로 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "가족여행", "데이트"]'::jsonb, 35.157299, 129.064491, '2026-10-01T17:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000938', '54500700-0000-4000-8000-000000000151', 'p-tourapi-252606', '영암 삼성당 고택', '비 오는 날 운치 찾아 영암 삼성당 고택 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "힐링", "온마루"]'::jsonb, 34.829694, 126.733014, '2026-10-05T13:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000939', '54500700-0000-4000-8000-000000000188', 'p-tourapi-3438735', '소월담', '드라이브 겸 나들이로 소월담 선택했는데 대만족! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 37.578883, 126.985864, '2026-10-03T01:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000940', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2747760', '그라운드플래닛', '조용히 사색하고 싶어서 찾은 그라운드플래닛. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "혼자여행", "온마루"]'::jsonb, 37.433834, 127.011115, '2026-10-03T10:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000941', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2561208', '디키디키', '해 질 무렵에 디키디키 방문했는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 37.568182, 127.010245, '2026-10-01T20:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000942', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2574064', '백미응서재', '조용히 사색하고 싶어서 찾은 백미응서재. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 37.141619, 126.691052, '2026-10-07T05:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000943', '54500700-0000-4000-8000-000000000152', 'p-tourapi-3101956', '죽록정사', '해 질 무렵에 죽록정사 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "주말나들이"]'::jsonb, 35.226732, 127.486187, '2026-10-07T23:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000944', '54500700-0000-4000-8000-000000000128', 'p-tourapi-2574250', '라온한옥꿀잠', '예전부터 가보고 싶었던 라온한옥꿀잠 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 35.815681, 127.154121, '2026-10-08T01:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000945', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2576546', '홍시(전주한옥마을 숙박 홍시)', '기대 이상으로 너무 좋았던 홍시(전주한옥마을 숙박 홍시)! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "풍경맛집", "사색", "온마루"]'::jsonb, 35.815473, 127.152748, '2026-10-06T17:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000946', '54500700-0000-4000-8000-000000000086', 'p-tourapi-128644', '춘천김정은가옥', '드라이브 겸 나들이로 춘천김정은가옥 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.845027, 127.729010, '2026-10-08T08:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000947', '54500700-0000-4000-8000-000000000187', 'p-tourapi-1373030', '서상돈 고택', '근처 여행 코스로 서상돈 고택 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "인생샷", "온마루"]'::jsonb, 35.867024, 128.587833, '2026-10-02T16:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000948', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3532883', '소풍한옥풀빌라', '오랜만에 여유 찾으러 소풍한옥풀빌라 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "사색", "풍경맛집", "온마루"]'::jsonb, 35.856166, 129.267320, '2026-10-01T16:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000949', '54500700-0000-4000-8000-000000000135', 'p-tourapi-1018702', '국제시장 먹자골목', '날씨가 너무 맑아서 국제시장 먹자골목 한 바퀴 돌고 왔네요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로", "사색"]'::jsonb, 35.101188, 129.028292, '2026-10-04T11:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000950', '54500700-0000-4000-8000-000000000146', 'p-tourapi-1245865', '심산기념문화센터', 'SNS에서 사진 보고 찾아간 심산기념문화센터, 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 37.498878, 126.990591, '2026-10-05T18:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000951', '54500700-0000-4000-8000-000000000191', 'p-tourapi-800528', '춘천 강언덕마을 [농촌전통테마]', 'SNS에서 사진 보고 찾아간 춘천 강언덕마을 [농촌전통테마], 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "가족여행", "방문팁", "온마루"]'::jsonb, 37.678626, 127.613804, '2026-10-03T03:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000952', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2613318', '이가한옥', '이가한옥 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "주말나들이", "사진맛집", "온마루"]'::jsonb, 35.816533, 127.155540, '2026-10-04T08:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000953', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3421909', '그런고로', '기대 이상으로 너무 좋았던 그런고로! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "사진맛집"]'::jsonb, 35.157699, 129.064416, '2026-10-05T13:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000954', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2699607', '모꼬지', '드라이브 겸 나들이로 모꼬지 선택했는데 대만족! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.811815, 127.156678, '2026-10-01T20:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000955', '54500700-0000-4000-8000-000000000159', 'p-tourapi-1883593', '월인당', '주말에 친구들이랑 월인당 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 34.777748, 126.612188, '2026-10-04T15:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000956', '54500700-0000-4000-8000-000000000158', 'p-tourapi-3469953', '하녹집', '드라이브 겸 나들이로 하녹집 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "산책로"]'::jsonb, 36.564735, 128.736604, '2026-10-08T03:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000957', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2996855', '버금상점', '부모님 모시고 버금상점 산책 겸 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 34.972913, 128.323982, '2026-10-04T13:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000958', '54500700-0000-4000-8000-000000000067', 'p-tourapi-129030', '전주유씨 무실종택', '부모님 모시고 전주유씨 무실종택 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "인생샷", "주말나들이"]'::jsonb, 36.553447, 128.923249, '2026-10-08T10:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000959', '54500700-0000-4000-8000-000000000161', 'p-tourapi-1872077', '석정댁', '천천히 골목 걷다가 마주친 석정댁. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "데이트", "가족여행", "온마루"]'::jsonb, 35.667061, 128.228977, '2026-10-02T23:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000960', '54500700-0000-4000-8000-000000000077', 'p-tourapi-1872145', '설아다원', 'SNS에서 사진 보고 찾아간 설아다원, 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 34.468132, 126.660159, '2026-10-05T13:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000961', '54500700-0000-4000-8000-000000000154', 'p-tourapi-3101960', '한옥스테이 연', '날씨가 너무 맑아서 한옥스테이 연 한 바퀴 돌고 왔네요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "데이트", "인생샷"]'::jsonb, 36.734341, 127.405375, '2026-10-08T10:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000962', '54500700-0000-4000-8000-000000000171', 'p-tourapi-250372', '의성김씨 학봉종택', '날씨가 너무 맑아서 의성김씨 학봉종택 한 바퀴 돌고 왔네요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "힐링", "사색"]'::jsonb, 36.609746, 128.669135, '2026-10-03T18:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000963', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2572817', '옥산정사 독락당', '비 오는 날 운치 찾아 옥산정사 독락당 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "주말나들이", "데이트", "온마루"]'::jsonb, 36.016999, 129.160183, '2026-10-07T21:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000964', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2620236', '예다움', '기대 이상으로 너무 좋았던 예다움! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 35.273759, 127.936903, '2026-10-05T08:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000965', '54500700-0000-4000-8000-000000000126', 'p-tourapi-3532767', '도동유교문화관', '산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.701663, 128.371342, '2026-10-07T11:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000966', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2663065', '휴휴당', '평일 연차 쓰고 혼자 휴휴당 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.835620, 129.212519, '2026-10-01T16:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000967', '54500700-0000-4000-8000-000000000108', 'p-tourapi-4012448', '검무한옥 호운당', 'SNS에서 사진 보고 찾아간 검무한옥 호운당, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 36.575346, 128.511333, '2026-10-05T16:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000968', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2569824', '흥해배씨 임연재종택', '예전부터 가보고 싶었던 흥해배씨 임연재종택 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 36.550184, 128.792082, '2026-10-08T09:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000969', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2662883', '경주 오릉 한옥', 'SNS에서 사진 보고 찾아간 경주 오릉 한옥, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 35.825789, 129.207076, '2026-10-07T19:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000970', '54500700-0000-4000-8000-000000000190', 'p-tourapi-3511230', '김씨네마카롱공장(주식회사필링)', '예전부터 가보고 싶었던 김씨네마카롱공장(주식회사필링) 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁", "가족여행"]'::jsonb, 35.490472, 129.435782, '2026-10-05T17:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000971', '54500700-0000-4000-8000-000000000146', 'p-tourapi-129514', '정읍 전봉준 유적', '드라이브 겸 나들이로 정읍 전봉준 유적 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["사진맛집", "가족여행", "방문팁", "온마루"]'::jsonb, 35.670663, 126.814907, '2026-10-05T07:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000972', '54500700-0000-4000-8000-000000000063', 'p-tourapi-129035', '안동 묵계서원 및 보백당 종택', '비 오는 날 운치 찾아 안동 묵계서원 및 보백당 종택 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 36.417692, 128.915237, '2026-10-05T17:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000973', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2638441', '제주탐나라공화국', '해 질 무렵에 제주탐나라공화국 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "풍경맛집"]'::jsonb, 33.334453, 126.325677, '2026-10-06T05:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000974', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2611575', '양천생활안전체험교육관', '부모님 모시고 양천생활안전체험교육관 산책 겸 다녀왔습니다. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "고즈넉", "산책로"]'::jsonb, 37.516493, 126.863691, '2026-10-03T10:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000975', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3532757', '곰곰하우스', '예전부터 가보고 싶었던 곰곰하우스 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.581375, 126.986549, '2026-10-01T20:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000976', '54500700-0000-4000-8000-000000000166', 'p-tourapi-3081677', '운림공원', '운림공원 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["사진맛집", "가족여행", "온마루"]'::jsonb, 34.465324, 126.292751, '2026-10-03T08:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000977', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2850614', '스탈릿성수', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉"]'::jsonb, 37.544395, 127.055526, '2026-10-05T19:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000978', '54500700-0000-4000-8000-000000000138', 'p-tourapi-126375', '진도 운림산방', '근처 여행 코스로 진도 운림산방 넣길 정말 잘했어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 34.466241, 126.308570, '2026-10-03T18:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000979', '54500700-0000-4000-8000-000000000167', 'p-tourapi-1972381', '서로', '근처 여행 코스로 서로 넣길 정말 잘했어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "가족여행", "방문팁"]'::jsonb, 35.816144, 127.153682, '2026-10-05T00:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000980', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2600248', '수춘제(김태길) 고택', '평일 연차 쓰고 혼자 수춘제(김태길) 고택 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 36.734775, 128.619066, '2026-10-03T20:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000981', '54500700-0000-4000-8000-000000000156', 'p-tourapi-4071289', '함평 이재혁 가옥', '근처 여행 코스로 함평 이재혁 가옥 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["사진맛집", "방문팁", "주말나들이", "온마루"]'::jsonb, 35.066529, 126.511932, '2026-10-03T11:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000982', '54500700-0000-4000-8000-000000000200', 'p-tourapi-3056595', '전주한옥마을역사관', '전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.816081, 127.152866, '2026-10-03T15:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000983', '54500700-0000-4000-8000-000000000095', 'p-tourapi-3532595', '오브헤리티지', '오랜만에 여유 찾으러 오브헤리티지 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링", "고즈넉", "온마루"]'::jsonb, 34.546699, 127.137204, '2026-10-06T18:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000984', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2715382', '여송정', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 37.477449, 128.724968, '2026-10-07T06:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000985', '54500700-0000-4000-8000-000000000168', 'p-tourapi-3089931', '모영재', '부모님 모시고 모영재 산책 겸 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 35.934217, 128.719277, '2026-10-04T08:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000986', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2595489', '동해한옥 동안재', '통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "고즈넉", "혼자여행"]'::jsonb, 37.528353, 129.108746, '2026-10-05T10:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000987', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3067572', '점핑고', '오랜만에 여유 찾으러 점핑고 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색", "힐링"]'::jsonb, 36.787751, 127.121530, '2026-10-03T00:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000988', '54500700-0000-4000-8000-000000000184', 'p-tourapi-1991992', '고택 한옥에서', '날씨가 너무 맑아서 고택 한옥에서 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 35.237480, 127.020254, '2026-10-03T10:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000989', '54500700-0000-4000-8000-000000000156', 'p-tourapi-3438588', '유유가', '예전부터 가보고 싶었던 유유가 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "방문팁", "데이트", "온마루"]'::jsonb, 34.955805, 127.483000, '2026-10-07T15:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000990', '54500700-0000-4000-8000-000000000183', 'p-tourapi-3541047', '주문진 관광안내센터', '마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.889930, 128.828518, '2026-10-05T00:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000991', '54500700-0000-4000-8000-000000000085', 'p-tourapi-4093690', '삼호정', '평일 연차 쓰고 혼자 삼호정 다녀옴. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 35.464285, 126.624673, '2026-10-05T02:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000992', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2572908', '별바라기집', '해 질 무렵에 별바라기집 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 34.740919, 126.717722, '2026-10-07T12:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000993', '54500700-0000-4000-8000-000000000080', 'p-tourapi-250436', '아산 용궁댁', '주말에 친구들이랑 아산 용궁댁 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.740648, 126.892370, '2026-10-02T18:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000994', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2509920', '울산중구생활문화센터', '직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 35.556545, 129.322075, '2026-10-05T12:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000995', '54500700-0000-4000-8000-000000000132', 'p-tourapi-3065503', '전주 대사습청', '부모님 모시고 전주 대사습청 산책 겸 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링", "사색"]'::jsonb, 35.817807, 127.153390, '2026-10-06T01:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000996', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2769810', '오창 미래지 한옥마을', '오랜만에 여유 찾으러 오창 미래지 한옥마을 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "산책로", "고즈넉"]'::jsonb, 36.735483, 127.404691, '2026-10-07T20:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000997', '54500700-0000-4000-8000-000000000063', 'p-tourapi-127289', '괴산 홍범식 고가(벽초 홍명희 생가)', '주말에 친구들이랑 괴산 홍범식 고가(벽초 홍명희 생가) 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 36.814114, 127.794635, '2026-10-03T03:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000998', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2679044', '청향재', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 37.641995, 126.939886, '2026-10-03T15:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000000999', '54500700-0000-4000-8000-000000000178', 'p-tourapi-1081744', '한국전통음식문화체험관(정강원)', '근처 여행 코스로 한국전통음식문화체험관(정강원) 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 37.571256, 128.408157, '2026-10-06T07:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001000', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2622784', '소양고택 한옥스테이', '조용히 사색하고 싶어서 찾은 소양고택 한옥스테이. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "혼자여행", "산책로"]'::jsonb, 35.903862, 127.243288, '2026-10-04T16:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001001', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2992061', '씨파크', 'SNS에서 사진 보고 찾아간 씨파크, 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 35.544668, 128.053545, '2026-10-01T07:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001002', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2792819', '박시춘옛집', '주말에 친구들이랑 박시춘옛집 들렀는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 35.491907, 128.755577, '2026-09-26T05:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001003', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3438160', '통인 1939', '근처 여행 코스로 통인 1939 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.578835, 126.971286, '2026-09-24T22:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001004', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2997257', '청담1942', '오랜만에 여유 찾으러 청담1942 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 35.899675, 128.229717, '2026-09-28T13:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001005', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2775304', '아올', '평일 연차 쓰고 혼자 아올 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 35.276474, 126.509528, '2026-09-19T14:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001006', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2576343', '뜰안채', '천천히 골목 걷다가 마주친 뜰안채. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.817024, 127.149222, '2026-09-22T12:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001007', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3438586', '휴휴가', '조용히 사색하고 싶어서 찾은 휴휴가. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 34.955138, 127.480714, '2026-09-29T17:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001008', '54500700-0000-4000-8000-000000000062', 'p-tourapi-1626349', '팔공산 케이블카', '드라이브 겸 나들이로 팔공산 케이블카 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 35.990819, 128.694491, '2026-09-18T00:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001009', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3072227', '아담한옥', '조용히 사색하고 싶어서 찾은 아담한옥. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "산책로", "사색", "온마루"]'::jsonb, 37.580418, 126.970184, '2026-09-18T23:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001010', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2050197', '어련당', '해 질 무렵에 어련당 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "주말나들이", "데이트", "온마루"]'::jsonb, 35.574107, 129.349937, '2026-09-23T03:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001011', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2620380', '풍송재', '오랜만에 여유 찾으러 풍송재 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "혼자여행", "산책로", "온마루"]'::jsonb, 36.573984, 128.514250, '2026-10-01T00:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001012', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2706568', '왕의지밀', '기대 이상으로 너무 좋았던 왕의지밀! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["사진맛집", "데이트", "인생샷", "온마루"]'::jsonb, 35.799829, 127.178734, '2026-09-23T05:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001013', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3392012', '한강시원지체험관', '근처 여행 코스로 한강시원지체험관 넣길 정말 잘했어요. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 37.720292, 128.602465, '2026-09-21T13:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001014', '54500700-0000-4000-8000-000000000122', 'p-tourapi-1870849', '덕동댁', '덕동댁 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 35.666857, 128.228034, '2026-09-17T11:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001015', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2744514', '합천목재문화체험장', 'SNS에서 사진 보고 찾아간 합천목재문화체험장, 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "사진맛집", "가족여행"]'::jsonb, 35.548234, 128.073399, '2026-09-20T04:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001016', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2613097', '월암재', '월암재 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 35.815345, 129.216186, '2026-09-20T21:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001017', '54500700-0000-4000-8000-000000000204', 'p-tourapi-800528', '춘천 강언덕마을 [농촌전통테마]', 'SNS에서 사진 보고 찾아간 춘천 강언덕마을 [농촌전통테마], 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 37.678388, 127.613317, '2026-09-23T20:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001018', '54500700-0000-4000-8000-000000000163', 'p-tourapi-736754', '홍승인고가', '부모님 모시고 홍승인고가 산책 겸 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 37.152141, 126.959313, '2026-09-17T04:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001019', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3532883', '소풍한옥풀빌라', '비 오는 날 운치 찾아 소풍한옥풀빌라 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.855682, 129.267022, '2026-09-18T03:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001020', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2990185', '금곡영화마을', '아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "산책로", "풍경맛집"]'::jsonb, 35.395376, 126.734415, '2026-09-24T00:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001021', '54500700-0000-4000-8000-000000000122', 'p-tourapi-2544734', '한채당 한옥체험관', '오랜만에 여유 찾으러 한채당 한옥체험관 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "산책로", "힐링"]'::jsonb, 36.830152, 126.161491, '2026-09-25T08:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001022', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2733074', '오산 드라마세트장', '주말에 친구들이랑 오산 드라마세트장 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 37.180129, 127.062761, '2026-09-19T01:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001023', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2789002', '조규승가옥', '오랜만에 여유 찾으러 조규승가옥 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.943960, 128.765390, '2026-09-19T23:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001024', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3427223', '충무로영상센터 오재미동', '오랜만에 여유 찾으러 충무로영상센터 오재미동 다녀왔습니다. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.561301, 126.994189, '2026-09-29T09:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001025', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2390314', '한복남 경복궁점', '드라이브 겸 나들이로 한복남 경복궁점 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 37.575966, 126.973098, '2026-09-29T20:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001026', '54500700-0000-4000-8000-000000000165', 'p-tourapi-3013816', '궁집', '드라이브 겸 나들이로 궁집 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "주말나들이", "온마루"]'::jsonb, 37.644110, 127.230504, '2026-09-21T11:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001027', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2621282', '사슴이랑배랑농원', '천천히 골목 걷다가 마주친 사슴이랑배랑농원. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["주말나들이", "사진맛집", "인생샷"]'::jsonb, 35.187454, 126.591339, '2026-09-27T11:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001028', '54500700-0000-4000-8000-000000000099', 'p-tourapi-3444479', '성주 예산리 배리댁', '주말에 친구들이랑 성주 예산리 배리댁 들렀는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "사색", "힐링", "온마루"]'::jsonb, 35.923482, 128.284858, '2026-09-17T15:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001029', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2769769', 'SK하이닉스 문화센터', '부모님 모시고 SK하이닉스 문화센터 산책 겸 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["가족여행", "사진맛집", "인생샷"]'::jsonb, 36.649263, 127.424454, '2026-09-28T02:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001030', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2777931', '생산소', '예전부터 가보고 싶었던 생산소 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 36.243801, 126.887347, '2026-09-30T01:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001031', '54500700-0000-4000-8000-000000000137', 'p-tourapi-3511181', '주식회사도시나무', '주말에 친구들이랑 주식회사도시나무 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "방문팁", "가족여행"]'::jsonb, 35.489546, 129.419109, '2026-09-16T08:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001032', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2717486', '엘오알오', '날씨가 너무 맑아서 엘오알오 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 36.733455, 128.108809, '2026-09-22T19:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001033', '54500700-0000-4000-8000-000000000145', 'p-tourapi-2674014', '비체올린', '예전부터 가보고 싶었던 비체올린 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "혼자여행", "산책로"]'::jsonb, 33.349388, 126.218516, '2026-09-18T19:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001034', '54500700-0000-4000-8000-000000000112', 'p-tourapi-231940', '안동 소호헌', '오랜만에 여유 찾으러 안동 소호헌 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.463667, 128.663361, '2026-09-17T04:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001035', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2706484', '3917마중', '3917마중 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["사진맛집", "주말나들이", "가족여행", "온마루"]'::jsonb, 35.032997, 126.711026, '2026-09-21T01:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001036', '54500700-0000-4000-8000-000000000122', 'p-tourapi-129210', '무안 유교리 고택', '주말에 친구들이랑 무안 유교리 고택 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 34.847696, 126.438536, '2026-09-25T21:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001037', '54500700-0000-4000-8000-000000000140', 'p-tourapi-4074857', '미옥스테이', '근처 여행 코스로 미옥스테이 넣길 정말 잘했어요. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "가족여행", "주말나들이"]'::jsonb, 35.866688, 128.612314, '2026-09-28T18:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001038', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3438582', '여가', '조용히 사색하고 싶어서 찾은 여가. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.815575, 127.152972, '2026-09-24T14:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001039', '54500700-0000-4000-8000-000000000190', 'p-tourapi-3102211', '자하연', '조용히 사색하고 싶어서 찾은 자하연. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "고즈넉", "힐링"]'::jsonb, 35.812336, 127.154652, '2026-09-24T13:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001040', '54500700-0000-4000-8000-000000000152', 'p-tourapi-3438584', '건축의 선율', '조용히 사색하고 싶어서 찾은 건축의 선율. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "풍경맛집", "산책로"]'::jsonb, 35.815926, 127.153361, '2026-09-18T14:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001041', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2717423', '힐데루시 자연치유 협동조합', '부모님 모시고 힐데루시 자연치유 협동조합 산책 겸 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "데이트", "사진맛집", "온마루"]'::jsonb, 37.958456, 127.157704, '2026-09-17T08:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001042', '54500700-0000-4000-8000-000000000176', 'p-tourapi-2568571', '1928 쉼마루', '조용히 사색하고 싶어서 찾은 1928 쉼마루. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "사색", "혼자여행", "온마루"]'::jsonb, 35.811802, 127.152045, '2026-09-24T02:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001043', '54500700-0000-4000-8000-000000000151', 'p-tourapi-1884345', '행복드림한옥', '부모님 모시고 행복드림한옥 산책 겸 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "가족여행"]'::jsonb, 35.905532, 127.209448, '2026-09-27T18:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001044', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2647026', '석가헌', '예전부터 가보고 싶었던 석가헌 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.719040, 128.904429, '2026-09-15T21:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001045', '54500700-0000-4000-8000-000000000071', 'p-tourapi-128644', '춘천김정은가옥', '바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 37.844981, 127.728628, '2026-09-18T14:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001046', '54500700-0000-4000-8000-000000000181', 'p-tourapi-126391', '고창신재효고택', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 35.432166, 126.702829, '2026-09-17T16:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001047', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3510444', '농업회사법인주식회사꿀벌인', '부모님 모시고 농업회사법인주식회사꿀벌인 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "방문팁", "온마루"]'::jsonb, 36.013718, 128.422096, '2026-09-16T09:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001048', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2820838', '평창캠프닉', '부모님 모시고 평창캠프닉 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["주말나들이", "가족여행", "방문팁"]'::jsonb, 37.578894, 128.332036, '2026-09-26T10:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001049', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2770587', '연암서당골', '해 질 무렵에 연암서당골 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 35.900653, 128.596774, '2026-09-16T14:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001050', '54500700-0000-4000-8000-000000000073', 'p-tourapi-1201060', '이천보고가', '오랜만에 여유 찾으러 이천보고가 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 37.798890, 127.348223, '2026-09-29T19:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001051', '54500700-0000-4000-8000-000000000199', 'p-tourapi-705411', '군위 남천고택', '비 오는 날 운치 찾아 군위 남천고택 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 36.058528, 128.653850, '2026-09-17T19:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001052', '54500700-0000-4000-8000-000000000159', 'p-tourapi-128542', '안성 정무공 오정방 고택', '해 질 무렵에 안성 정무공 오정방 고택 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 37.045681, 127.185851, '2026-09-22T20:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001053', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2592885', '엘크레', '해 질 무렵에 엘크레 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "방문팁", "사진맛집"]'::jsonb, 37.521138, 127.023554, '2026-09-25T11:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001054', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2633954', '산속등대 복합문화공간', '산속등대 복합문화공간 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "방문팁", "가족여행", "온마루"]'::jsonb, 35.869377, 127.251779, '2026-09-28T07:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001055', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2500771', '타오르는 강 문학관', '오랜만에 여유 찾으러 타오르는 강 문학관 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "힐링"]'::jsonb, 34.999143, 126.712966, '2026-09-22T16:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001056', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2657848', '한국트로트가요센터', '해 질 무렵에 한국트로트가요센터 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 34.791550, 126.685008, '2026-09-19T23:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001057', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3438261', '이도한옥', '날씨가 너무 맑아서 이도한옥 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 37.580691, 126.987089, '2026-09-25T14:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001058', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2795229', '한지생각이닥', '한지생각이닥 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "혼자여행", "산책로", "온마루"]'::jsonb, 37.470569, 126.626160, '2026-09-23T06:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001059', '54500700-0000-4000-8000-000000000063', 'p-tourapi-4041219', '지후헌', '은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 37.589516, 127.003127, '2026-09-26T15:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001060', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2531222', '강릉오죽한옥마을', '기대 이상으로 너무 좋았던 강릉오죽한옥마을! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 37.777598, 128.878001, '2026-09-23T08:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001061', '54500700-0000-4000-8000-000000000137', 'p-tourapi-3337188', '세종전통문화체험관', '예전부터 가보고 싶었던 세종전통문화체험관 드디어 방문! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "데이트"]'::jsonb, 36.506529, 127.291855, '2026-09-30T12:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001062', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2819644', '적정온도(순향가)', '예전부터 가보고 싶었던 적정온도(순향가) 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 34.873015, 127.528267, '2026-10-01T05:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001063', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2697287', '하서원(외암민속마을)', '평일 연차 쓰고 혼자 하서원(외암민속마을) 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 36.731803, 127.014461, '2026-09-26T04:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001064', '54500700-0000-4000-8000-000000000099', 'p-tourapi-231909', '안동 예안이씨 충효당', '안동 예안이씨 충효당 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.574409, 128.580428, '2026-09-27T05:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001065', '54500700-0000-4000-8000-000000000127', 'p-tourapi-129518', '경주 양동마을 송첨종택', '근처 여행 코스로 경주 양동마을 송첨종택 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "방문팁", "가족여행", "온마루"]'::jsonb, 36.003619, 129.253496, '2026-09-17T06:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001066', '54500700-0000-4000-8000-000000000145', 'p-tourapi-127430', '신석정 고택', '천천히 골목 걷다가 마주친 신석정 고택. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["인생샷", "주말나들이", "방문팁"]'::jsonb, 35.739985, 126.733871, '2026-09-18T03:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001067', '54500700-0000-4000-8000-000000000109', 'p-tourapi-252546', '영덕 무안박씨 무의공파 종택', '드라이브 겸 나들이로 영덕 무안박씨 무의공파 종택 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.510039, 129.409533, '2026-09-30T11:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001068', '54500700-0000-4000-8000-000000000091', 'p-tourapi-3038851', '치헌', '드라이브 겸 나들이로 치헌 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 36.534636, 128.861183, '2026-10-01T09:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001069', '54500700-0000-4000-8000-000000000081', 'p-tourapi-3354209', '오로시예술공방(주식회사오로시프로젝트)', '예전부터 가보고 싶었던 오로시예술공방(주식회사오로시프로젝트) 드디어 방문! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 34.982520, 126.959578, '2026-09-16T20:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001070', '54500700-0000-4000-8000-000000000177', 'p-tourapi-3056873', '영암 집영재', '해 질 무렵에 영암 집영재 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "인생샷", "방문팁"]'::jsonb, 34.762826, 126.534036, '2026-09-22T20:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001071', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3428354', '스타필드 시티 부천', '날씨가 너무 맑아서 스타필드 시티 부천 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색"]'::jsonb, 37.461736, 126.814251, '2026-09-30T12:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001072', '54500700-0000-4000-8000-000000000144', 'p-tourapi-3582643', '한복남 창덕궁점', '조용히 사색하고 싶어서 찾은 한복남 창덕궁점. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 37.575857, 126.990844, '2026-09-29T09:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001073', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2037306', '완도 청해포구촬영장', 'SNS에서 사진 보고 찾아간 완도 청해포구촬영장, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "인생샷", "데이트"]'::jsonb, 34.323577, 126.670622, '2026-09-16T16:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001074', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3411229', '천지인 전통사상체험관', '드라이브 겸 나들이로 천지인 전통사상체험관 선택했는데 대만족! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 36.730558, 128.614542, '2026-09-19T23:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001075', '54500700-0000-4000-8000-000000000112', 'p-tourapi-894145', '명품옻골 1616 협동조합', '예전부터 가보고 싶었던 명품옻골 1616 협동조합 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 35.907789, 128.686978, '2026-09-24T10:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001076', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2638479', '장생포 모노레일', '드라이브 겸 나들이로 장생포 모노레일 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 35.502626, 129.381567, '2026-09-16T13:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001077', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3422587', '더맑음', '부모님 모시고 더맑음 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.540432, 129.338591, '2026-10-01T09:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001078', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2020734', '영동국악체험촌', '영동국악체험촌 다녀왔어요! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "온마루"]'::jsonb, 36.210959, 127.702403, '2026-09-27T18:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001079', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2602750', '쥬라기랜드', '드라이브 겸 나들이로 쥬라기랜드 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "데이트", "사진맛집", "온마루"]'::jsonb, 37.435425, 127.023821, '2026-09-20T16:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001080', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2775017', '주식회사 하늘', '주말에 친구들이랑 주식회사 하늘 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "사진맛집", "방문팁", "온마루"]'::jsonb, 35.305252, 126.546645, '2026-09-20T17:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001081', '54500700-0000-4000-8000-000000000124', 'p-tourapi-3438674', '나들방', '오랜만에 여유 찾으러 나들방 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "고즈넉", "산책로", "온마루"]'::jsonb, 35.816124, 127.151643, '2026-09-29T20:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001082', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3426935', '구리문화재단', '근처 여행 코스로 구리문화재단 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "힐링"]'::jsonb, 37.595762, 127.129916, '2026-09-17T13:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001083', '54500700-0000-4000-8000-000000000081', 'p-tourapi-129051', '청송 송소 고택', '조용히 사색하고 싶어서 찾은 청송 송소 고택. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 36.436410, 129.026676, '2026-09-22T15:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001084', '54500700-0000-4000-8000-000000000166', 'p-tourapi-3444479', '성주 예산리 배리댁', '날씨가 너무 맑아서 성주 예산리 배리댁 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.923309, 128.285576, '2026-09-16T07:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001085', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2570532', '한옥미담(전주한옥마을 한옥미담)', '해 질 무렵에 한옥미담(전주한옥마을 한옥미담) 방문했는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 35.819458, 127.150766, '2026-09-25T13:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001086', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2465890', '시은재', '드라이브 겸 나들이로 시은재 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 37.573574, 126.987552, '2026-09-16T20:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001087', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2932871', '한복입고 유유자적 (주식회사고영)', '한복입고 유유자적 (주식회사고영) 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "방문팁", "온마루"]'::jsonb, 34.760141, 126.623310, '2026-09-25T17:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001088', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2668524', '이천백사 산수유영농조합법인(이천산수유마을)', '평일 연차 쓰고 혼자 이천백사 산수유영농조합법인(이천산수유마을) 다녀옴. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 37.341111, 127.462381, '2026-09-22T04:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001089', '54500700-0000-4000-8000-000000000205', 'p-tourapi-3438586', '휴휴가', 'SNS에서 사진 보고 찾아간 휴휴가, 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로"]'::jsonb, 34.954961, 127.480984, '2026-09-24T01:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001090', '54500700-0000-4000-8000-000000000087', 'p-tourapi-3510971', '컬러브릿지협동조합', '조용히 사색하고 싶어서 찾은 컬러브릿지협동조합. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "풍경맛집", "혼자여행"]'::jsonb, 35.141070, 126.917352, '2026-09-20T08:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001091', '54500700-0000-4000-8000-000000000148', 'p-tourapi-1621481', '화기리인동장씨종택', '부모님 모시고 화기리인동장씨종택 산책 겸 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "데이트", "주말나들이"]'::jsonb, 36.769422, 128.575600, '2026-09-22T00:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001092', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3438590', '중정별채', '드라이브 겸 나들이로 중정별채 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.076739, 126.685527, '2026-09-18T01:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001093', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2612877', '장욱진 고택', '평일 연차 쓰고 혼자 장욱진 고택 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "힐링", "풍경맛집"]'::jsonb, 37.301577, 127.120638, '2026-09-15T17:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001094', '54500700-0000-4000-8000-000000000155', 'p-tourapi-231907', '정읍 김명관 고택', '날씨가 너무 맑아서 정읍 김명관 고택 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 35.616281, 127.019878, '2026-09-25T04:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001095', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2000964', '향단', '천천히 골목 걷다가 마주친 향단. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["데이트", "주말나들이"]'::jsonb, 36.000096, 129.252879, '2026-09-21T09:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001096', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2668037', '월암종택(김호장군고택)', '주말에 친구들이랑 월암종택(김호장군고택) 들렀는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집", "방문팁"]'::jsonb, 35.819898, 129.218648, '2026-09-27T15:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001097', '54500700-0000-4000-8000-000000000062', 'p-tourapi-128145', '나주 목사내아', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["가족여행", "데이트"]'::jsonb, 35.031969, 126.715439, '2026-09-17T00:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001098', '54500700-0000-4000-8000-000000000123', 'p-tourapi-128759', '강릉 수리골 고택', '부모님 모시고 강릉 수리골 고택 산책 겸 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 37.785869, 128.891204, '2026-09-28T04:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001099', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2570576', '금농헌', '해 질 무렵에 금농헌 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "사색", "산책로"]'::jsonb, 35.820366, 127.157628, '2026-09-27T10:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001100', '54500700-0000-4000-8000-000000000150', 'p-tourapi-3532694', '어보이', 'SNS에서 사진 보고 찾아간 어보이, 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "사색"]'::jsonb, 35.811704, 127.153122, '2026-09-16T17:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001101', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438575', '일상이상', '오랜만에 여유 찾으러 일상이상 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.824583, 127.154118, '2026-09-26T20:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001102', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2598628', '별아래한옥', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "가족여행", "데이트"]'::jsonb, 36.536834, 128.821424, '2026-09-15T18:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001103', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2686588', '오성한옥마을', '조용히 사색하고 싶어서 찾은 오성한옥마을. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.903295, 127.243544, '2026-09-22T18:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001104', '54500700-0000-4000-8000-000000000106', 'p-tourapi-1395270', '최순우 옛집', '최순우 옛집 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 37.593027, 127.000449, '2026-09-30T02:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001105', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2603889', '문행당', '해 질 무렵에 문행당 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.913139, 128.740738, '2026-09-24T05:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001106', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2696256', '낙안재', '천천히 골목 걷다가 마주친 낙안재. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.836031, 129.208596, '2026-09-29T10:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001107', '54500700-0000-4000-8000-000000000118', 'p-tourapi-792208', '괴산 한지체험박물관', '다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.785614, 128.015059, '2026-09-28T00:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001108', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2606192', '선샤인랜드', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "혼자여행", "힐링"]'::jsonb, 36.101743, 127.105780, '2026-09-17T14:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001109', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3438736', '전주한옥마을 독채덕수궁', '예전부터 가보고 싶었던 전주한옥마을 독채덕수궁 드디어 방문! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이", "인생샷", "온마루"]'::jsonb, 35.816795, 127.151543, '2026-09-21T18:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001110', '54500700-0000-4000-8000-000000000102', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '거창 갈계리 임씨고가 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 35.779933, 127.818619, '2026-09-28T00:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001111', '54500700-0000-4000-8000-000000000102', 'p-tourapi-3438653', '호호재', '부모님 모시고 호호재 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "산책로", "혼자여행", "온마루"]'::jsonb, 36.560441, 128.711060, '2026-09-21T19:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001112', '54500700-0000-4000-8000-000000000096', 'p-tourapi-129046', '서벽고택', '날씨가 너무 맑아서 서벽고택 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 36.458615, 129.022511, '2026-09-17T15:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001113', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2594864', '남호구택', '근처 여행 코스로 남호구택 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "가족여행", "방문팁"]'::jsonb, 36.894191, 128.712564, '2026-09-18T13:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001114', '54500700-0000-4000-8000-000000000160', 'p-tourapi-3455504', '용인특례시 가상현실스포츠체험센터', 'SNS에서 사진 보고 찾아간 용인특례시 가상현실스포츠체험센터, 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 37.238523, 127.180757, '2026-09-23T04:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001115', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2737307', '경기광주 한옥마을', '드라이브 겸 나들이로 경기광주 한옥마을 선택했는데 대만족! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 37.438444, 127.230178, '2026-09-23T11:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001116', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2609894', '경기전 연가', '산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행", "힐링", "온마루"]'::jsonb, 35.817400, 127.150254, '2026-09-19T13:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001117', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2593272', '가은채2', '천천히 골목 걷다가 마주친 가은채2. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 35.815293, 127.153387, '2026-09-26T20:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001118', '54500700-0000-4000-8000-000000000168', 'p-tourapi-3547622', '허균 허난설헌 기념공원 초희전통차체험관', '비 오는 날 운치 찾아 허균 허난설헌 기념공원 초희전통차체험관 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 37.790911, 128.909753, '2026-09-27T11:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001119', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2606296', '청풍호반케이블카', '천천히 골목 걷다가 마주친 청풍호반케이블카. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 37.001625, 128.166859, '2026-09-23T06:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001120', '54500700-0000-4000-8000-000000000086', 'p-tourapi-3427223', '충무로영상센터 오재미동', '기대 이상으로 너무 좋았던 충무로영상센터 오재미동! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 37.561540, 126.994274, '2026-09-20T14:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001121', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3432447', '2025 서울 카페&베이커리페어', '드라이브 겸 나들이로 2025 서울 카페&베이커리페어 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 37.496278, 127.070422, '2026-09-27T21:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001122', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2717590', '김성래 가옥', '천천히 골목 걷다가 마주친 김성래 가옥. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 37.987335, 128.739432, '2026-09-16T23:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001123', '54500700-0000-4000-8000-000000000140', 'p-tourapi-1433369', '괴산 김항묵 고택', '평일 연차 쓰고 혼자 괴산 김항묵 고택 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "혼자여행", "고즈넉"]'::jsonb, 36.781858, 127.859481, '2026-09-22T14:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001124', '54500700-0000-4000-8000-000000000113', 'p-tourapi-3438630', '서우재', '기대 이상으로 너무 좋았던 서우재! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 36.559780, 128.708672, '2026-09-19T15:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001125', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2701396', '서남산한옥', '오랜만에 여유 찾으러 서남산한옥 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 35.780883, 129.204753, '2026-09-29T03:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001126', '54500700-0000-4000-8000-000000000109', 'p-tourapi-3442142', '서울숲 곤충식물원', '오랜만에 여유 찾으러 서울숲 곤충식물원 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 37.543507, 127.041891, '2026-09-17T10:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001127', '54500700-0000-4000-8000-000000000109', 'p-tourapi-895327', '남도한옥민박마을', '조용히 사색하고 싶어서 찾은 남도한옥민박마을. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 34.509119, 126.605623, '2026-09-28T12:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001128', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2707444', '가영당', '부모님 모시고 가영당 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "가족여행", "데이트", "온마루"]'::jsonb, 36.734905, 127.405527, '2026-09-28T22:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001129', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2007983', '경북전통음식체험관 모심정', '경북전통음식체험관 모심정 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 36.661985, 128.119465, '2026-09-29T00:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001130', '54500700-0000-4000-8000-000000000077', 'p-tourapi-3533156', '라라몽몽', '조용히 사색하고 싶어서 찾은 라라몽몽. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "힐링", "산책로", "온마루"]'::jsonb, 35.821632, 127.138537, '2026-10-01T10:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001131', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2663065', '휴휴당', '주말에 친구들이랑 휴휴당 들렀는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 35.835887, 129.212174, '2026-09-18T09:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001132', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2657716', '치유의숲 무장애길', '부모님 모시고 치유의숲 무장애길 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "가족여행", "주말나들이"]'::jsonb, 35.736610, 128.040933, '2026-10-01T14:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001133', '54500700-0000-4000-8000-000000000092', 'p-tourapi-1883135', '안동고택 이상루', '기대 이상으로 너무 좋았던 안동고택 이상루! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 36.635054, 128.678819, '2026-09-24T12:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001134', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2647939', '고스락', '기대 이상으로 너무 좋았던 고스락! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 36.045717, 126.960941, '2026-09-23T10:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001135', '54500700-0000-4000-8000-000000000080', 'p-tourapi-3101965', '스테이서문', '현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "주말나들이", "온마루"]'::jsonb, 35.033646, 126.712558, '2026-09-27T07:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001136', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2708322', '이화고택', '오랜만에 여유 찾으러 이화고택 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "힐링"]'::jsonb, 35.816089, 127.153569, '2026-09-22T03:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001137', '54500700-0000-4000-8000-000000000189', 'p-tourapi-1621481', '화기리인동장씨종택', '해 질 무렵에 화기리인동장씨종택 방문했는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 36.769585, 128.575124, '2026-09-18T18:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001138', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2717486', '엘오알오', '주말에 친구들이랑 엘오알오 들렀는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 36.733782, 128.108389, '2026-09-20T08:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001139', '54500700-0000-4000-8000-000000000159', 'p-tourapi-1594746', '장현식고택', '천천히 골목 걷다가 마주친 장현식고택. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "고즈넉"]'::jsonb, 35.812096, 127.156608, '2026-09-21T03:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001140', '54500700-0000-4000-8000-000000000180', 'p-tourapi-1883070', '정재종택', '천천히 골목 걷다가 마주친 정재종택. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "혼자여행"]'::jsonb, 36.559514, 128.915146, '2026-09-27T11:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001141', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2638566', '주문진읍 BTS 앨범사진 촬영지 (버스정류장)', '오랜만에 여유 찾으러 주문진읍 BTS 앨범사진 촬영지 (버스정류장) 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "산책로", "고즈넉"]'::jsonb, 37.912930, 128.817048, '2026-09-26T01:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001142', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2608154', '조약도 한옥체험', '근처 여행 코스로 조약도 한옥체험 넣길 정말 잘했어요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색"]'::jsonb, 34.373451, 126.888085, '2026-09-26T19:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001143', '54500700-0000-4000-8000-000000000192', 'p-tourapi-2657848', '한국트로트가요센터', 'SNS에서 사진 보고 찾아간 한국트로트가요센터, 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 34.791819, 126.685272, '2026-09-23T16:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001144', '54500700-0000-4000-8000-000000000164', 'p-tourapi-3056624', '한복남 전주한옥마을점', '날씨가 너무 맑아서 한복남 전주한옥마을점 한 바퀴 돌고 왔네요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "방문팁", "가족여행", "온마루"]'::jsonb, 35.814405, 127.152308, '2026-09-22T14:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001145', '54500700-0000-4000-8000-000000000135', 'p-tourapi-2855009', '한옥 생고기', '평일 연차 쓰고 혼자 한옥 생고기 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.948780, 127.189571, '2026-09-24T01:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001146', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3438587', '빌라오', 'SNS에서 사진 보고 찾아간 빌라오, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["방문팁", "주말나들이"]'::jsonb, 34.953221, 127.479968, '2026-09-27T08:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001147', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3438684', '물길스테이', '물길스테이 다녀왔어요! 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "데이트", "가족여행"]'::jsonb, 36.505596, 128.852255, '2026-09-17T10:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001148', '54500700-0000-4000-8000-000000000143', 'p-tourapi-127329', '목포시사', '주말에 친구들이랑 목포시사 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "인생샷", "데이트"]'::jsonb, 34.790009, 126.377204, '2026-09-23T22:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001149', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2680781', '소리터', '고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 34.762178, 126.622791, '2026-09-22T14:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001150', '54500700-0000-4000-8000-000000000186', 'p-tourapi-125800', '강릉 선교장', '기대 이상으로 너무 좋았던 강릉 선교장! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트", "온마루"]'::jsonb, 37.786484, 128.885303, '2026-09-16T07:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001151', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2782688', '와글아이', '조용히 사색하고 싶어서 찾은 와글아이. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 37.654121, 126.775440, '2026-09-28T07:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001152', '54500700-0000-4000-8000-000000000163', 'p-tourapi-3469883', '서동선화한옥', '주말에 친구들이랑 서동선화한옥 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "방문팁"]'::jsonb, 36.291800, 126.927591, '2026-10-01T08:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001153', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2624231', '장충영각', '오랜만에 여유 찾으러 장충영각 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "풍경맛집", "산책로", "온마루"]'::jsonb, 36.572390, 126.612415, '2026-09-24T06:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001154', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3532694', '어보이', '날씨가 너무 맑아서 어보이 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "데이트", "사진맛집", "온마루"]'::jsonb, 35.811803, 127.153141, '2026-09-24T03:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001155', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3353800', '뜻모아센터', '조용히 사색하고 싶어서 찾은 뜻모아센터. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 35.189472, 126.907391, '2026-09-16T03:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001156', '54500700-0000-4000-8000-000000000096', 'p-tourapi-3337761', '마마스홈퀴진', '드라이브 겸 나들이로 마마스홈퀴진 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 35.561594, 129.117034, '2026-09-26T02:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001157', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2613254', '도봉서당', '조용히 사색하고 싶어서 찾은 도봉서당. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "사색", "혼자여행", "온마루"]'::jsonb, 35.827642, 129.184290, '2026-09-19T10:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001158', '54500700-0000-4000-8000-000000000131', 'p-tourapi-1433369', '괴산 김항묵 고택', '평일 연차 쓰고 혼자 괴산 김항묵 고택 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 36.781474, 127.859282, '2026-09-23T14:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001159', '54500700-0000-4000-8000-000000000112', 'p-tourapi-1566740', '양평 맑은숲캠프', '비 오는 날 운치 찾아 양평 맑은숲캠프 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "힐링"]'::jsonb, 37.562286, 127.734397, '2026-09-16T00:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001160', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3533116', '덕만재', '예전부터 가보고 싶었던 덕만재 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색", "산책로"]'::jsonb, 35.822098, 129.243867, '2026-09-23T01:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001161', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2665817', '부여안방마님', 'SNS에서 사진 보고 찾아간 부여안방마님, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 36.265615, 126.848319, '2026-09-15T21:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001162', '54500700-0000-4000-8000-000000000114', 'p-tourapi-3438379', '더 모먼트', 'SNS에서 사진 보고 찾아간 더 모먼트, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["가족여행", "주말나들이", "사진맛집"]'::jsonb, 37.577682, 126.970550, '2026-09-16T23:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001163', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2707233', '한옥人(한옥인)', '천천히 골목 걷다가 마주친 한옥人(한옥인). 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "고즈넉"]'::jsonb, 35.835106, 129.211345, '2026-09-28T15:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001164', '54500700-0000-4000-8000-000000000063', 'p-tourapi-3019714', '같이삽시도', '달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.346265, 126.353076, '2026-09-22T04:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001165', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2663054', '경주 춘추관', '드라이브 겸 나들이로 경주 춘추관 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 35.822780, 129.186215, '2026-09-17T15:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001166', '54500700-0000-4000-8000-000000000101', 'p-tourapi-3448778', '양평 생활문화센터', '예전부터 가보고 싶었던 양평 생활문화센터 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 37.499820, 127.477218, '2026-09-19T01:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001167', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3438581', '교동94', '부모님 모시고 교동94 산책 겸 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "사진맛집", "인생샷", "온마루"]'::jsonb, 35.812418, 127.152137, '2026-09-25T07:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001168', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2820629', '부여북포한옥마을', '천천히 골목 걷다가 마주친 부여북포한옥마을. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 36.292520, 126.924428, '2026-09-28T09:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001169', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2751455', '시흥 ABC행복학습타운', '조용히 사색하고 싶어서 찾은 시흥 ABC행복학습타운. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링", "산책로"]'::jsonb, 37.448834, 126.785515, '2026-09-16T09:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001170', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2817792', '밀알영농조합', 'SNS에서 사진 보고 찾아간 밀알영농조합, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["주말나들이", "인생샷"]'::jsonb, 35.081652, 128.185773, '2026-09-17T14:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001171', '54500700-0000-4000-8000-000000000086', 'p-tourapi-3427800', '더헤븐 리조트', '오랜만에 여유 찾으러 더헤븐 리조트 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 37.229745, 126.562724, '2026-09-26T18:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001172', '54500700-0000-4000-8000-000000000196', 'p-tourapi-3511181', '주식회사도시나무', '천천히 골목 걷다가 마주친 주식회사도시나무. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 35.489275, 129.419089, '2026-09-16T07:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001173', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2768086', '한양 한옥마을점', '부모님 모시고 한양 한옥마을점 산책 겸 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "풍경맛집", "혼자여행"]'::jsonb, 37.390862, 126.638783, '2026-09-25T05:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001174', '54500700-0000-4000-8000-000000000130', 'p-tourapi-2570611', '잊음', '기대 이상으로 너무 좋았던 잊음! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "가족여행", "데이트"]'::jsonb, 34.846577, 128.418419, '2026-09-21T22:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001175', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2594218', '정가한옥', '주말에 친구들이랑 정가한옥 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "가족여행"]'::jsonb, 35.816179, 127.155294, '2026-10-01T13:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001176', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2544095', '전통리조트 구름에', '기대 이상으로 너무 좋았던 전통리조트 구름에! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 36.573165, 128.768113, '2026-09-26T06:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001177', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2610549', '예원당(한옥체험 예원당)', '날씨가 너무 맑아서 예원당(한옥체험 예원당) 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "사진맛집"]'::jsonb, 35.817560, 127.152378, '2026-10-01T07:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001178', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2572886', '삼연재', '비 오는 날 운치 찾아 삼연재 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 36.676023, 128.490751, '2026-09-17T17:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001179', '54500700-0000-4000-8000-000000000135', 'p-tourapi-1627167', '추사 김정희 선생 고택', '날씨가 너무 맑아서 추사 김정희 선생 고택 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 36.746617, 126.798667, '2026-09-24T23:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001180', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2820707', '프로스트맥주협동조합 (망경동 에일맥주. 진주유등축제 흑맥주. 촉석루라거맥주. 진주석류에일맥주)', '주말에 친구들이랑 프로스트맥주협동조합 (망경동 에일맥주. 진주유등축제 흑맥주. 촉석루라거맥주. 진주석류에일맥주) 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 35.236016, 128.030591, '2026-09-16T12:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001181', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2629010', '영남알프스 얼음골케이블카', '조용히 사색하고 싶어서 찾은 영남알프스 얼음골케이블카. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "풍경맛집", "혼자여행"]'::jsonb, 35.582888, 128.987407, '2026-09-25T12:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001182', '54500700-0000-4000-8000-000000000188', 'p-tourapi-1937772', '계룡 사계고택', '주말에 친구들이랑 계룡 사계고택 들렀는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 36.265335, 127.271534, '2026-09-29T07:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001183', '54500700-0000-4000-8000-000000000092', 'p-tourapi-2574225', '도원', '주말에 친구들이랑 도원 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 35.807847, 127.150530, '2026-10-01T10:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001184', '54500700-0000-4000-8000-000000000100', 'p-tourapi-1883087', '연우하우스', '천천히 골목 걷다가 마주친 연우하우스. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 37.582251, 126.985106, '2026-09-25T18:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001185', '54500700-0000-4000-8000-000000000062', 'p-tourapi-250460', '남원몽심재', '평일 연차 쓰고 혼자 남원몽심재 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "힐링", "풍경맛집"]'::jsonb, 35.337748, 127.374938, '2026-09-21T13:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001186', '54500700-0000-4000-8000-000000000192', 'p-tourapi-2602750', '쥬라기랜드', '예전부터 가보고 싶었던 쥬라기랜드 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 37.435602, 127.023414, '2026-09-30T20:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001187', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2932894', '주월재', '주말에 친구들이랑 주월재 들렀는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "혼자여행", "사색"]'::jsonb, 34.779217, 127.167029, '2026-09-18T23:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001188', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2717286', '마린데크(커피마린협동조합)', '천천히 골목 걷다가 마주친 마린데크(커피마린협동조합). 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "방문팁", "가족여행"]'::jsonb, 37.456533, 129.186412, '2026-09-26T02:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001189', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1623646', '권희문가옥', '기대 이상으로 너무 좋았던 권희문가옥! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.587490, 127.386380, '2026-09-20T08:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001190', '54500700-0000-4000-8000-000000000171', 'p-tourapi-3038830', '백하구려', '조용히 사색하고 싶어서 찾은 백하구려. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "산책로", "풍경맛집", "온마루"]'::jsonb, 36.534525, 128.859384, '2026-09-24T20:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001191', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2609894', '경기전 연가', '기대 이상으로 너무 좋았던 경기전 연가! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "주말나들이", "데이트", "온마루"]'::jsonb, 35.817319, 127.150138, '2026-09-18T13:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001192', '54500700-0000-4000-8000-000000000096', 'p-tourapi-3438189', '한옥 북클럽 하우스', '조용히 사색하고 싶어서 찾은 한옥 북클럽 하우스. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링", "혼자여행"]'::jsonb, 37.591404, 127.004924, '2026-09-26T05:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001193', '54500700-0000-4000-8000-000000000158', 'p-tourapi-798830', '영동 김참판댁', '날씨가 너무 맑아서 영동 김참판댁 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "가족여행"]'::jsonb, 36.153369, 127.755044, '2026-09-29T17:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001194', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2531417', '전주 한옥숙박체험관', '주말에 친구들이랑 전주 한옥숙박체험관 들렀는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "방문팁", "주말나들이", "온마루"]'::jsonb, 35.814647, 127.151939, '2026-09-29T03:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001195', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2029564', '오미요리연구소', '드라이브 겸 나들이로 오미요리연구소 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 37.582967, 127.041001, '2026-09-18T09:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001196', '54500700-0000-4000-8000-000000000127', 'p-tourapi-128645', '춘천최재근가옥', '비 오는 날 운치 찾아 춘천최재근가옥 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "풍경맛집", "힐링"]'::jsonb, 37.843235, 127.727516, '2026-09-16T02:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001197', '54500700-0000-4000-8000-000000000148', 'p-tourapi-803988', '순천 용오름마을 [농촌전통테마마을]', '천천히 골목 걷다가 마주친 순천 용오름마을 [농촌전통테마마을]. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["방문팁", "주말나들이", "가족여행"]'::jsonb, 35.092054, 127.202137, '2026-09-29T03:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001198', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2787267', '오봉정사', '근처 여행 코스로 오봉정사 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "사진맛집", "방문팁"]'::jsonb, 35.183914, 127.524578, '2026-09-16T14:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001199', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2409490', '만회고택', 'SNS에서 사진 보고 찾아간 만회고택, 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "고즈넉", "혼자여행", "온마루"]'::jsonb, 36.897257, 128.715376, '2026-09-26T13:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001200', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2050197', '어련당', '기대 이상으로 너무 좋았던 어련당! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "사진맛집", "가족여행"]'::jsonb, 35.574357, 129.350323, '2026-09-26T19:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001201', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2575836', '북촌 게스트하우스', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "방문팁", "데이트"]'::jsonb, 37.578340, 126.985557, '2026-09-21T10:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001202', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2609838', '다래헌', '해 질 무렵에 다래헌 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.815629, 127.152807, '2026-09-28T13:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001203', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2621263', '자연스토리', '예전부터 가보고 싶었던 자연스토리 드디어 방문! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 34.509266, 126.605404, '2026-09-30T14:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001204', '54500700-0000-4000-8000-000000000074', 'p-tourapi-2604100', '예직한옥체험마을(용인예직한옥체험 마을)', '근처 여행 코스로 예직한옥체험마을(용인예직한옥체험 마을) 넣길 정말 잘했어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉", "산책로", "온마루"]'::jsonb, 37.192096, 127.255777, '2026-09-27T07:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001205', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3030491', '선성현문화단지 한옥체험관', '평일 연차 쓰고 혼자 선성현문화단지 한옥체험관 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 36.698418, 128.814664, '2026-09-24T22:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001206', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2435103', '중앙탑의상실', '오랜만에 여유 찾으러 중앙탑의상실 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.018328, 127.865963, '2026-09-29T09:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001207', '54500700-0000-4000-8000-000000000203', 'p-tourapi-1105980', '양천구어린이교통안전교육장', '부모님 모시고 양천구어린이교통안전교육장 산책 겸 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 37.509817, 126.870315, '2026-09-21T19:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001208', '54500700-0000-4000-8000-000000000165', 'p-tourapi-1590793', '노동환가옥', '해 질 무렵에 노동환가옥 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 35.484330, 127.266423, '2026-09-26T12:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001209', '54500700-0000-4000-8000-000000000071', 'p-tourapi-753850', '키즈오토파크', '기대 이상으로 너무 좋았던 키즈오토파크! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 37.549615, 127.076209, '2026-09-19T15:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001210', '54500700-0000-4000-8000-000000000201', 'p-tourapi-2409490', '만회고택', '해 질 무렵에 만회고택 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "데이트", "방문팁"]'::jsonb, 36.897205, 128.715149, '2026-09-20T20:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001211', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2767851', '송도 한옥마을', 'SNS에서 사진 보고 찾아간 송도 한옥마을, 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "방문팁", "주말나들이", "온마루"]'::jsonb, 37.390337, 126.638350, '2026-09-19T01:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001212', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2939639', '유현문화관광지', '근처 여행 코스로 유현문화관광지 넣길 정말 잘했어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.530828, 127.820130, '2026-09-25T11:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001213', '54500700-0000-4000-8000-000000000142', 'p-tourapi-1972012', '산에는 꽃이피네', '산에는 꽃이피네 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["인생샷", "방문팁", "데이트"]'::jsonb, 34.998878, 126.823709, '2026-09-16T01:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001214', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2531222', '강릉오죽한옥마을', 'SNS에서 사진 보고 찾아간 강릉오죽한옥마을, 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "방문팁", "데이트"]'::jsonb, 37.777069, 128.877603, '2026-09-17T23:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001215', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2598978', '온계종택(삼백당)', '오랜만에 여유 찾으러 온계종택(삼백당) 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 36.752847, 128.827501, '2026-09-20T15:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001216', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2717337', '소백산꽃차이야기', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.882855, 128.563964, '2026-09-20T17:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001217', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3038851', '치헌', '드라이브 겸 나들이로 치헌 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "사색"]'::jsonb, 36.534851, 128.860649, '2026-09-23T16:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001218', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2037306', '완도 청해포구촬영장', '바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["인생샷", "주말나들이", "가족여행", "온마루"]'::jsonb, 34.323663, 126.670256, '2026-09-16T00:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001219', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '천천히 골목 걷다가 마주친 미담 한옥 게스트 하우스. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "사색"]'::jsonb, 37.580789, 126.986356, '2026-09-29T23:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001220', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2777931', '생산소', '통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "산책로", "힐링"]'::jsonb, 36.243688, 126.887692, '2026-09-24T19:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001221', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3451224', '은계2어울림센터', '오랜만에 여유 찾으러 은계2어울림센터 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 37.435857, 126.797565, '2026-09-22T14:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001222', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2583699', '소소하우스', '천천히 골목 걷다가 마주친 소소하우스. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 37.580294, 126.967988, '2026-09-28T06:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001223', '54500700-0000-4000-8000-000000000172', 'p-tourapi-3438722', '전주 한옥마을 중심 독채', '오랜만에 여유 찾으러 전주 한옥마을 중심 독채 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 35.815224, 127.151566, '2026-09-16T03:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001224', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2707041', '경극고택', '경극고택 다녀왔어요! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로"]'::jsonb, 35.907482, 128.686476, '2026-09-29T18:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001225', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3438052', '중정독채', '주말에 친구들이랑 중정독채 들렀는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 35.034637, 126.715124, '2026-09-25T16:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001226', '54500700-0000-4000-8000-000000000147', 'p-tourapi-3469889', '석주재', '평일 연차 쓰고 혼자 석주재 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 35.510817, 128.837885, '2026-09-18T16:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001227', '54500700-0000-4000-8000-000000000109', 'p-tourapi-1627280', '단양 조덕수 고택', '천천히 골목 걷다가 마주친 단양 조덕수 고택. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 37.003466, 128.383906, '2026-09-30T06:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001228', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2867659', '곤지암반디숲', '드라이브 겸 나들이로 곤지암반디숲 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "사진맛집", "방문팁"]'::jsonb, 37.363530, 127.331025, '2026-09-30T08:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001229', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2574064', '백미응서재', 'SNS에서 사진 보고 찾아간 백미응서재, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "인생샷", "온마루"]'::jsonb, 37.141586, 126.691090, '2026-09-30T17:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001230', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2633895', '예천목재문화체험장', '조용히 사색하고 싶어서 찾은 예천목재문화체험장. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "풍경맛집"]'::jsonb, 36.799617, 128.376172, '2026-09-19T11:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001231', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2638521', '영천 목재문화체험장', '조용히 사색하고 싶어서 찾은 영천 목재문화체험장. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "힐링", "산책로"]'::jsonb, 36.142330, 128.978168, '2026-09-21T15:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001232', '54500700-0000-4000-8000-000000000133', 'p-tourapi-3105334', '133파티룸 한옥스테이점', 'SNS에서 사진 보고 찾아간 133파티룸 한옥스테이점, 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 37.279515, 127.016213, '2026-10-01T05:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001233', '54500700-0000-4000-8000-000000000141', 'p-tourapi-3438585', '스테이 구도', '날씨가 너무 맑아서 스테이 구도 한 바퀴 돌고 왔네요. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집", "힐링"]'::jsonb, 34.792064, 126.380207, '2026-09-15T21:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001234', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3533116', '덕만재', '부모님 모시고 덕만재 산책 겸 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 35.822239, 129.243874, '2026-09-22T00:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001235', '54500700-0000-4000-8000-000000000080', 'p-tourapi-228892', '담양 명옥헌 원림', 'SNS에서 사진 보고 찾아간 담양 명옥헌 원림, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색", "혼자여행"]'::jsonb, 35.219387, 126.996460, '2026-09-22T12:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001236', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2657501', '한옥카페 갤러리 도솔', '날씨가 너무 맑아서 한옥카페 갤러리 도솔 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["데이트", "인생샷", "온마루"]'::jsonb, 37.642155, 126.506300, '2026-09-28T15:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001237', '54500700-0000-4000-8000-000000000198', 'p-tourapi-4074856', '연림스테이', '해 질 무렵에 연림스테이 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링", "산책로", "온마루"]'::jsonb, 35.972221, 128.698593, '2026-09-19T14:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001238', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2775014', '나무키움(전의양묘영농조합법인)', '나무키움(전의양묘영농조합법인) 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 36.676726, 127.197794, '2026-09-25T06:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001239', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2650825', '일몰이아름다운한옥', '천천히 골목 걷다가 마주친 일몰이아름다운한옥. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "데이트", "인생샷"]'::jsonb, 34.847512, 127.528001, '2026-09-30T05:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001240', '54500700-0000-4000-8000-000000000176', 'p-tourapi-801918', '무안 감풀마을 [농촌전통테마]', '예전부터 가보고 싶었던 무안 감풀마을 [농촌전통테마] 드디어 방문! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.061343, 126.405558, '2026-09-19T03:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001241', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2820794', '별내리마을', '아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["주말나들이", "가족여행"]'::jsonb, 35.455171, 126.843111, '2026-09-21T03:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001242', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3072072', '한옥에세이 서촌', '드라이브 겸 나들이로 한옥에세이 서촌 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링", "풍경맛집"]'::jsonb, 37.578604, 126.968442, '2026-09-24T16:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001243', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2995168', '유한회사복합문화공간 서리울', '주말에 친구들이랑 유한회사복합문화공간 서리울 들렀는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 36.015236, 127.145313, '2026-09-20T23:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001244', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2574250', '라온한옥꿀잠', '조용히 사색하고 싶어서 찾은 라온한옥꿀잠. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉", "온마루"]'::jsonb, 35.815843, 127.153950, '2026-09-17T09:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001245', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2603889', '문행당', '부모님 모시고 문행당 산책 겸 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "혼자여행", "사색"]'::jsonb, 36.913239, 128.741161, '2026-09-28T08:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001246', '54500700-0000-4000-8000-000000000109', 'p-tourapi-3577428', '고창 전통예술체험마을', '예전부터 가보고 싶었던 고창 전통예술체험마을 드디어 방문! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "가족여행"]'::jsonb, 35.430361, 126.701637, '2026-09-30T16:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001247', '54500700-0000-4000-8000-000000000109', 'p-tourapi-3438735', '소월담', '기대 이상으로 너무 좋았던 소월담! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 37.578808, 126.985830, '2026-09-16T04:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001248', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2568571', '1928 쉼마루', '부모님 모시고 1928 쉼마루 산책 겸 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집"]'::jsonb, 35.812068, 127.152684, '2026-09-28T23:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001249', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2574250', '라온한옥꿀잠', '조용히 사색하고 싶어서 찾은 라온한옥꿀잠. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "사색", "산책로"]'::jsonb, 35.816029, 127.154329, '2026-09-17T08:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001250', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3068424', '가리왕산케이블카', '가리왕산케이블카 다녀왔어요! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "주말나들이", "데이트"]'::jsonb, 37.474167, 128.609742, '2026-09-30T06:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001251', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3102073', '오원 스테이', '천천히 골목 걷다가 마주친 오원 스테이. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "사진맛집", "인생샷"]'::jsonb, 35.836525, 129.208911, '2026-09-29T08:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001252', '54500700-0000-4000-8000-000000000101', 'p-tourapi-1883086', '연경당', '조용히 사색하고 싶어서 찾은 연경당. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "산책로", "혼자여행", "온마루"]'::jsonb, 35.015734, 127.586043, '2026-09-16T15:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001253', '54500700-0000-4000-8000-000000000089', 'p-tourapi-3011053', '더 히로 플레이 그라운드', '더 히로 플레이 그라운드 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "산책로", "사색"]'::jsonb, 37.866558, 127.277174, '2026-09-28T01:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001254', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2795007', '화성 정수영 고택', '평일 연차 쓰고 혼자 화성 정수영 고택 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "힐링"]'::jsonb, 37.132409, 126.700606, '2026-09-27T11:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001255', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2602750', '쥬라기랜드', 'SNS에서 사진 보고 찾아간 쥬라기랜드, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["주말나들이", "데이트", "온마루"]'::jsonb, 37.435628, 127.023929, '2026-09-30T07:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001256', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2426995', '전주한옥레일바이크', 'SNS에서 사진 보고 찾아간 전주한옥레일바이크, 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "방문팁", "사진맛집", "온마루"]'::jsonb, 35.829545, 127.175991, '2026-09-27T03:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001257', '54500700-0000-4000-8000-000000000110', 'p-tourapi-2708327', '사단법인 한국천연염색 숨', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 34.904979, 127.120400, '2026-09-29T10:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001258', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2592489', '복합한옥공간 곳', '평일 연차 쓰고 혼자 복합한옥공간 곳 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색", "힐링"]'::jsonb, 37.579891, 126.987183, '2026-09-18T12:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001259', '54500700-0000-4000-8000-000000000157', 'p-tourapi-3469883', '서동선화한옥', '날씨가 너무 맑아서 서동선화한옥 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "풍경맛집"]'::jsonb, 36.292050, 126.928020, '2026-09-17T17:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001260', '54500700-0000-4000-8000-000000000189', 'p-tourapi-128560', '안동 임청각', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 36.564993, 128.745142, '2026-09-26T18:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001261', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3447048', '사우당 종택', '드라이브 겸 나들이로 사우당 종택 선택했는데 대만족! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "풍경맛집", "온마루"]'::jsonb, 35.828178, 128.214958, '2026-09-26T23:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001262', '54500700-0000-4000-8000-000000000143', 'p-tourapi-1584115', '익산 김병순 고택', '평일 연차 쓰고 혼자 익산 김병순 고택 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "산책로", "힐링", "온마루"]'::jsonb, 36.060926, 126.909581, '2026-09-21T07:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001263', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3438582', '여가', '기대 이상으로 너무 좋았던 여가! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.815496, 127.153052, '2026-09-22T07:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001264', '54500700-0000-4000-8000-000000000197', 'p-tourapi-3422587', '더맑음', '날씨가 너무 맑아서 더맑음 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "인생샷", "주말나들이"]'::jsonb, 35.540245, 129.338602, '2026-09-21T08:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001265', '54500700-0000-4000-8000-000000000118', 'p-tourapi-1171915', '조선왕가', '드라이브 겸 나들이로 조선왕가 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "데이트", "사진맛집", "온마루"]'::jsonb, 38.063280, 127.101322, '2026-09-22T23:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001266', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2725123', '운기석9020(운기석9020협동조합)', '기대 이상으로 너무 좋았던 운기석9020(운기석9020협동조합)! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 37.380494, 128.662789, '2026-09-21T11:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001267', '54500700-0000-4000-8000-000000000069', 'p-tourapi-3544074', '대한노인회 강릉시지회', '평일 연차 쓰고 혼자 대한노인회 강릉시지회 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "고즈넉", "혼자여행", "온마루"]'::jsonb, 37.747653, 128.883867, '2026-09-30T14:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001268', '54500700-0000-4000-8000-000000000126', 'p-tourapi-1883758', '창실고택', '오랜만에 여유 찾으러 창실고택 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "사색", "힐링", "온마루"]'::jsonb, 36.438427, 129.026668, '2026-09-21T07:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001269', '54500700-0000-4000-8000-000000000108', 'p-tourapi-1971844', '필봉문화촌 취락원', '필봉문화촌 취락원 다녀왔어요! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "산책로", "온마루"]'::jsonb, 35.537519, 127.154869, '2026-09-18T07:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001270', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3353949', '㈜ 희품씨', '해 질 무렵에 ㈜ 희품씨 방문했는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로", "풍경맛집"]'::jsonb, 35.567144, 129.112339, '2026-09-24T10:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001271', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2652952', '김해한옥체험관', '근처 여행 코스로 김해한옥체험관 넣길 정말 잘했어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "주말나들이", "가족여행", "온마루"]'::jsonb, 35.233839, 128.877578, '2026-09-16T00:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001272', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1883590', '옥연정사', '고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.543413, 128.518239, '2026-09-19T08:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001273', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2531496', '하동댁', '해 질 무렵에 하동댁 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.667261, 128.227513, '2026-09-30T16:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001274', '54500700-0000-4000-8000-000000000072', 'p-tourapi-4065036', '스테이로이', '천천히 골목 걷다가 마주친 스테이로이. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 36.102659, 127.486791, '2026-09-17T01:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001275', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2820707', '프로스트맥주협동조합 (망경동 에일맥주. 진주유등축제 흑맥주. 촉석루라거맥주. 진주석류에일맥주)', 'SNS에서 사진 보고 찾아간 프로스트맥주협동조합 (망경동 에일맥주. 진주유등축제 흑맥주. 촉석루라거맥주. 진주석류에일맥주), 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 35.235910, 128.030122, '2026-09-25T13:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001276', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3353949', '㈜ 희품씨', '예전부터 가보고 싶었던 ㈜ 희품씨 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 35.567300, 129.112248, '2026-09-22T09:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001277', '54500700-0000-4000-8000-000000000103', 'p-tourapi-3468318', '청재한옥', '기대 이상으로 너무 좋았던 청재한옥! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.784215, 129.311404, '2026-09-26T05:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001278', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2610850', '강원숲체험장', '비 오는 날 운치 찾아 강원숲체험장 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 37.962749, 127.639585, '2026-09-25T21:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001279', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2743393', '강선대', '예전부터 가보고 싶었던 강선대 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "가족여행", "사진맛집"]'::jsonb, 36.135106, 127.695757, '2026-09-30T02:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001280', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2743740', '육영재단 어린이회관', 'SNS에서 사진 보고 찾아간 육영재단 어린이회관, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 37.547342, 127.078354, '2026-09-25T18:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001281', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2775344', '지구마을산책', '근처 여행 코스로 지구마을산책 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "방문팁", "데이트"]'::jsonb, 35.875630, 128.892216, '2026-09-16T18:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001282', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3582693', '한복남 북촌점', '기대 이상으로 너무 좋았던 한복남 북촌점! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["사진맛집", "주말나들이"]'::jsonb, 37.579570, 126.985057, '2026-09-22T11:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001283', '54500700-0000-4000-8000-000000000132', 'p-tourapi-129057', '청송 평산신씨 판사공파 종택과 분가 고택', 'SNS에서 사진 보고 찾아간 청송 평산신씨 판사공파 종택과 분가 고택, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 36.458496, 129.022993, '2026-09-26T17:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001284', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2782485', '종학당', '비 오는 날 운치 찾아 종학당 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "인생샷", "데이트", "온마루"]'::jsonb, 36.291444, 127.097552, '2026-09-30T07:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001285', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2597551', '고성이씨 탑동종택', 'SNS에서 사진 보고 찾아간 고성이씨 탑동종택, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 36.569497, 128.744171, '2026-09-19T22:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001286', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2854436', '옥천전통문화체험관', '평일 연차 쓰고 혼자 옥천전통문화체험관 다녀옴. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 36.316576, 127.585254, '2026-09-23T13:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001287', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2600248', '수춘제(김태길) 고택', '수춘제(김태길) 고택 다녀왔어요! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "풍경맛집", "온마루"]'::jsonb, 36.734759, 128.618809, '2026-09-29T22:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001288', '54500700-0000-4000-8000-000000000180', 'p-tourapi-1682936', '제천 중전리 고가', '주말에 친구들이랑 제천 중전리 고가 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 37.062615, 128.191146, '2026-09-16T14:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001289', '54500700-0000-4000-8000-000000000106', 'p-tourapi-843726', '한옥집김치찜', '조용히 사색하고 싶어서 찾은 한옥집김치찜. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.869325, 128.593995, '2026-09-25T01:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001290', '54500700-0000-4000-8000-000000000094', 'p-tourapi-3081792', '화순 고인돌선사체험장', '기대 이상으로 너무 좋았던 화순 고인돌선사체험장! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 34.987300, 126.916508, '2026-09-30T05:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001291', '54500700-0000-4000-8000-000000000175', 'p-tourapi-3113740', '고결', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "가족여행", "데이트"]'::jsonb, 36.642962, 128.064464, '2026-09-22T20:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001292', '54500700-0000-4000-8000-000000000140', 'p-tourapi-129518', '경주 양동마을 송첨종택', '드라이브 겸 나들이로 경주 양동마을 송첨종택 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.003965, 129.253594, '2026-09-23T04:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001293', '54500700-0000-4000-8000-000000000159', 'p-tourapi-125925', '아산 맹씨 행단(맹사성 고택)', '주말에 친구들이랑 아산 맹씨 행단(맹사성 고택) 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "힐링", "산책로"]'::jsonb, 36.747415, 127.041664, '2026-09-24T07:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001294', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2725101', '주티스트', 'SNS에서 사진 보고 찾아간 주티스트, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉", "힐링", "온마루"]'::jsonb, 36.843157, 128.550802, '2026-09-15T17:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001295', '54500700-0000-4000-8000-000000000070', 'p-tourapi-127588', '애은당고택·사우정고택·용계정', '기대 이상으로 너무 좋았던 애은당고택·사우정고택·용계정! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 36.167247, 129.185810, '2026-09-23T22:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001296', '54500700-0000-4000-8000-000000000157', 'p-tourapi-3438589', '윤은재', '날씨가 너무 맑아서 윤은재 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.033492, 126.712177, '2026-09-19T12:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001297', '54500700-0000-4000-8000-000000000058', 'p-tourapi-1089992', '대전교통문화연수원', '기대 이상으로 너무 좋았던 대전교통문화연수원! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 36.376940, 127.386733, '2026-09-30T10:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001298', '54500700-0000-4000-8000-000000000147', 'p-tourapi-264570', '강남', '평일 연차 쓰고 혼자 강남 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 37.527017, 127.027475, '2026-09-29T19:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001299', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2592489', '복합한옥공간 곳', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "가족여행", "온마루"]'::jsonb, 37.579667, 126.987230, '2026-09-16T18:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001300', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2698680', '4.16희망목공소(4.16희망목공협동조합)', '조용히 사색하고 싶어서 찾은 4.16희망목공소(4.16희망목공협동조합). 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "사색", "산책로", "온마루"]'::jsonb, 37.343796, 126.834525, '2026-09-19T00:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001301', '54500700-0000-4000-8000-000000000135', 'p-tourapi-3102081', '동파랑', '드라이브 겸 나들이로 동파랑 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 35.844224, 129.224833, '2026-09-08T10:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001302', '54500700-0000-4000-8000-000000000074', 'p-tourapi-1201060', '이천보고가', '드라이브 겸 나들이로 이천보고가 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "사진맛집", "가족여행"]'::jsonb, 37.798685, 127.348150, '2026-09-01T23:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001303', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2695742', '대성 정담한옥', '평일 연차 쓰고 혼자 대성 정담한옥 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.796832, 127.178465, '2026-08-20T15:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001304', '54500700-0000-4000-8000-000000000139', 'p-tourapi-128788', '설악산 케이블카', '기대 이상으로 너무 좋았던 설악산 케이블카! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 38.173192, 128.489225, '2026-08-15T04:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001305', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2717493', '삼버들협동조합', '달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 36.527841, 127.370213, '2026-07-25T19:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001306', '54500700-0000-4000-8000-000000000184', 'p-tourapi-3532595', '오브헤리티지', '날씨가 너무 맑아서 오브헤리티지 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 34.546297, 127.136884, '2026-07-31T13:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001307', '54500700-0000-4000-8000-000000000130', 'p-tourapi-231940', '안동 소호헌', '천천히 골목 걷다가 마주친 안동 소호헌. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "방문팁"]'::jsonb, 36.463644, 128.663608, '2026-07-18T19:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001308', '54500700-0000-4000-8000-000000000113', 'p-tourapi-231933', '경주 양동 무첨당', '천천히 골목 걷다가 마주친 경주 양동 무첨당. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 36.002043, 129.252812, '2026-08-30T14:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001309', '54500700-0000-4000-8000-000000000171', 'p-tourapi-1972397', '주식회사 황남관', '조용히 사색하고 싶어서 찾은 주식회사 황남관. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 35.833784, 129.209233, '2026-07-21T14:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001310', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2621825', '어울림', '날씨가 너무 맑아서 어울림 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 35.813335, 127.153162, '2026-09-03T21:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001311', '54500700-0000-4000-8000-000000000076', 'p-tourapi-129051', '청송 송소 고택', '드라이브 겸 나들이로 청송 송소 고택 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 36.436297, 129.026356, '2026-08-27T17:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001312', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3533165', '청량안채', '예전부터 가보고 싶었던 청량안채 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.574958, 127.048339, '2026-07-23T14:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001313', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2531675', '진도한옥펜션', '예전부터 가보고 싶었던 진도한옥펜션 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "사진맛집", "데이트"]'::jsonb, 34.398283, 126.277645, '2026-08-29T12:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001314', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2570229', '결성향교', '날씨가 너무 맑아서 결성향교 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 36.528895, 126.543593, '2026-09-04T21:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001315', '54500700-0000-4000-8000-000000000145', 'p-tourapi-2996818', '반줄', '드라이브 겸 나들이로 반줄 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 35.945744, 127.101722, '2026-08-15T19:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001316', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2721915', '밀양 월연정', '은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색", "힐링"]'::jsonb, 35.498634, 128.779999, '2026-09-13T00:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001317', '54500700-0000-4000-8000-000000000151', 'p-tourapi-3102210', '선음재', '드라이브 겸 나들이로 선음재 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "사진맛집"]'::jsonb, 37.585003, 126.985635, '2026-08-11T11:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001318', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2821865', '향온', '드라이브 겸 나들이로 향온 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색", "혼자여행", "온마루"]'::jsonb, 36.403810, 126.845838, '2026-07-23T11:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001319', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2603550', '무척산관광예술원', '해 질 무렵에 무척산관광예술원 방문했는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이", "가족여행", "온마루"]'::jsonb, 35.383927, 128.839504, '2026-08-26T15:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001320', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3438368', '해아원', '예전부터 가보고 싶었던 해아원 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 37.583047, 126.983740, '2026-08-30T04:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001321', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3438621', '희게', '평일 연차 쓰고 혼자 희게 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 36.554138, 128.923525, '2026-07-21T16:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001322', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2715385', '난포정(蘭浦亭)', '조용히 사색하고 싶어서 찾은 난포정(蘭浦亭). 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "사색", "산책로"]'::jsonb, 37.482148, 128.849370, '2026-09-07T12:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001323', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3438579', '스테이 한울', '부모님 모시고 스테이 한울 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["사진맛집", "가족여행", "온마루"]'::jsonb, 35.812405, 127.152036, '2026-08-04T19:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001324', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2990185', '금곡영화마을', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 35.395265, 126.733775, '2026-07-21T06:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001325', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2604100', '예직한옥체험마을(용인예직한옥체험 마을)', '날씨가 너무 맑아서 예직한옥체험마을(용인예직한옥체험 마을) 한 바퀴 돌고 왔네요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "인생샷", "데이트"]'::jsonb, 37.191716, 127.255465, '2026-08-19T20:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001326', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2606296', '청풍호반케이블카', '기대 이상으로 너무 좋았던 청풍호반케이블카! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "주말나들이", "온마루"]'::jsonb, 37.001413, 128.166511, '2026-08-29T16:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001327', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2782667', '김대기가옥', '부모님 모시고 김대기가옥 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 36.692868, 128.410174, '2026-07-31T11:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001328', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2717549', '순솝', '순솝 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 34.947742, 127.503841, '2026-08-18T10:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001329', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2587214', '제이한옥(JAY Hanok)', '기대 이상으로 너무 좋았던 제이한옥(JAY Hanok)! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링", "산책로", "온마루"]'::jsonb, 37.582577, 126.987218, '2026-08-24T07:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001330', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3453929', '경상북도교육청 발명체험교육관', '직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.833715, 129.213158, '2026-09-05T12:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001331', '54500700-0000-4000-8000-000000000173', 'p-tourapi-2481866', '백인제가옥', '오랜만에 여유 찾으러 백인제가옥 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 37.580147, 126.984066, '2026-07-28T14:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001332', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2770621', '향사례 대구시민단', '오랜만에 여유 찾으러 향사례 대구시민단 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "풍경맛집", "사색", "온마루"]'::jsonb, 35.898113, 128.601154, '2026-08-31T23:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001333', '54500700-0000-4000-8000-000000000180', 'p-tourapi-129182', '오색약수골전통장', '비 오는 날 운치 찾아 오색약수골전통장 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 38.079801, 128.506201, '2026-08-13T05:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001334', '54500700-0000-4000-8000-000000000188', 'p-tourapi-3582744', '한복남 한국민속촌점', '조용히 사색하고 싶어서 찾은 한복남 한국민속촌점. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 37.256572, 127.113729, '2026-08-30T16:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001335', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2932828', '우리술과힐링(주식회사우리술과힐링)', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["방문팁", "주말나들이", "데이트"]'::jsonb, 34.800726, 126.698044, '2026-09-14T23:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001336', '54500700-0000-4000-8000-000000000164', 'p-tourapi-129514', '정읍 전봉준 유적', '해 질 무렵에 정읍 전봉준 유적 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "혼자여행", "산책로"]'::jsonb, 35.670883, 126.814584, '2026-07-21T07:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001337', '54500700-0000-4000-8000-000000000176', 'p-tourapi-2606387', '예천군체육회활체험센터', '비 오는 날 운치 찾아 예천군체육회활체험센터 다녀왔어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 36.634864, 128.468479, '2026-07-20T10:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001338', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2409490', '만회고택', '기대 이상으로 너무 좋았던 만회고택! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 36.897361, 128.715228, '2026-09-02T03:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001339', '54500700-0000-4000-8000-000000000160', 'p-tourapi-126387', '전주 풍패지관 (전주객사)', '해 질 무렵에 전주 풍패지관 (전주객사) 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 35.818586, 127.145000, '2026-08-07T11:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001340', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3438569', '아담', '비 오는 날 운치 찾아 아담 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 36.450572, 127.122019, '2026-07-21T04:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001341', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2714563', '서편제 촬영지', '서편제 촬영지 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "힐링", "온마루"]'::jsonb, 34.172264, 126.862166, '2026-09-08T18:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001342', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3102164', '황남별곡', '비 오는 날 운치 찾아 황남별곡 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "가족여행"]'::jsonb, 35.837620, 129.210386, '2026-08-04T00:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001343', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3438684', '물길스테이', 'SNS에서 사진 보고 찾아간 물길스테이, 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["인생샷", "사진맛집", "방문팁"]'::jsonb, 36.505612, 128.852769, '2026-09-15T09:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001344', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2775344', '지구마을산책', '부모님 모시고 지구마을산책 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "인생샷"]'::jsonb, 35.875548, 128.892250, '2026-09-05T05:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001345', '54500700-0000-4000-8000-000000000191', 'p-tourapi-3438422', '한옥 스테이 미경', '드라이브 겸 나들이로 한옥 스테이 미경 선택했는데 대만족! 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.586528, 127.007796, '2026-07-24T00:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001346', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2725025', '소찬 협동조합', '조용히 사색하고 싶어서 찾은 소찬 협동조합. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 36.512905, 126.814803, '2026-09-07T13:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001347', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2574307', '목양산방', '디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 34.889793, 127.507424, '2026-07-21T06:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001348', '54500700-0000-4000-8000-000000000186', 'p-tourapi-1005548', '충주 최응성 고가', '평일 연차 쓰고 혼자 충주 최응성 고가 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 36.896102, 127.980317, '2026-08-24T21:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001349', '54500700-0000-4000-8000-000000000181', 'p-tourapi-3438591', '구례 문 한옥 게스트 하우스', '근처 여행 코스로 구례 문 한옥 게스트 하우스 넣길 정말 잘했어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.244276, 127.453794, '2026-09-11T00:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001350', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2717286', '마린데크(커피마린협동조합)', '예전부터 가보고 싶었던 마린데크(커피마린협동조합) 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 37.456785, 129.185872, '2026-07-31T14:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001351', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2708657', '초정행궁', '평일 연차 쓰고 혼자 초정행궁 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.721625, 127.601371, '2026-09-11T17:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001352', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2820820', '위인더랜드', '드라이브 겸 나들이로 위인더랜드 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "풍경맛집", "힐링", "온마루"]'::jsonb, 35.301462, 126.780426, '2026-07-25T10:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001353', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2775344', '지구마을산책', '전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "방문팁", "사진맛집", "온마루"]'::jsonb, 35.875965, 128.892388, '2026-08-16T13:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001354', '54500700-0000-4000-8000-000000000068', 'p-tourapi-128046', '여주 황포돛배', '해 질 무렵에 여주 황포돛배 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 37.293134, 127.667232, '2026-09-06T02:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001355', '54500700-0000-4000-8000-000000000094', 'p-tourapi-3102031', '소산당', '해 질 무렵에 소산당 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷", "데이트"]'::jsonb, 35.206906, 127.511967, '2026-08-10T16:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001356', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2606296', '청풍호반케이블카', '기대 이상으로 너무 좋았던 청풍호반케이블카! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로", "힐링", "온마루"]'::jsonb, 37.001358, 128.166856, '2026-09-12T05:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001357', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2820659', '부여 선샤인', '부모님 모시고 부여 선샤인 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "인생샷", "데이트"]'::jsonb, 36.274209, 126.887181, '2026-07-18T07:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001358', '54500700-0000-4000-8000-000000000104', 'p-tourapi-3354017', '술작가 양조장', '평일 연차 쓰고 혼자 술작가 양조장 다녀옴. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 37.473225, 126.641103, '2026-08-27T15:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001359', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2932973', '다올재', '오랜만에 여유 찾으러 다올재 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "사색"]'::jsonb, 34.955039, 127.480832, '2026-07-22T22:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001360', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2819158', '매원마을', '평일 연차 쓰고 혼자 매원마을 다녀옴. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "혼자여행", "힐링", "온마루"]'::jsonb, 35.994204, 128.430867, '2026-07-29T02:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001361', '54500700-0000-4000-8000-000000000103', 'p-tourapi-3438674', '나들방', '비 오는 날 운치 찾아 나들방 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.815758, 127.151503, '2026-07-18T15:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001362', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2706568', '왕의지밀', '해 질 무렵에 왕의지밀 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 35.799909, 127.178211, '2026-08-10T16:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001363', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2775365', '바다공룡 워케이션', '근처 여행 코스로 바다공룡 워케이션 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "가족여행", "방문팁"]'::jsonb, 35.016845, 128.298441, '2026-08-28T07:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001364', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2743393', '강선대', '해 질 무렵에 강선대 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 36.135167, 127.695446, '2026-07-31T19:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001365', '54500700-0000-4000-8000-000000000087', 'p-tourapi-1997639', '찰방공종택', '주말에 친구들이랑 찰방공종택 들렀는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 36.437174, 129.026426, '2026-09-07T02:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001366', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2782981', '존재고택', '주말에 친구들이랑 존재고택 들렀는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 34.549660, 126.949894, '2026-08-14T00:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001367', '54500700-0000-4000-8000-000000000058', 'p-tourapi-1600719', '정종수 고택', '정종수 고택 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 35.774022, 126.858279, '2026-07-28T01:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001368', '54500700-0000-4000-8000-000000000190', 'p-tourapi-264311', '명동', '비 오는 날 운치 찾아 명동 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "방문팁", "사진맛집"]'::jsonb, 37.562119, 126.984875, '2026-07-19T00:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001369', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3438470', '한옥 카키', 'SNS에서 사진 보고 찾아간 한옥 카키, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["가족여행", "주말나들이", "온마루"]'::jsonb, 37.642323, 126.939561, '2026-09-07T22:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001370', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2669992', '산청 이사재', '비 오는 날 운치 찾아 산청 이사재 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 35.276792, 127.935418, '2026-08-20T08:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001371', '54500700-0000-4000-8000-000000000111', 'p-tourapi-736754', '홍승인고가', '근처 여행 코스로 홍승인고가 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁", "가족여행"]'::jsonb, 37.152455, 126.959661, '2026-08-01T14:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001372', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2695757', '한옥게스트하우스 ''安(Ahn)''', '주말에 친구들이랑 한옥게스트하우스 ''安(Ahn)'' 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "데이트", "주말나들이"]'::jsonb, 35.873089, 128.611052, '2026-07-26T15:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001373', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2509933', '울산 큰애기집', '울산 큰애기집 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["가족여행", "데이트", "온마루"]'::jsonb, 35.556981, 129.321794, '2026-08-08T11:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001374', '54500700-0000-4000-8000-000000000095', 'p-tourapi-3056624', '한복남 전주한옥마을점', '천천히 골목 걷다가 마주친 한복남 전주한옥마을점. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 35.814342, 127.152289, '2026-08-24T12:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001375', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2707445', '일독일박', '부모님 모시고 일독일박 산책 겸 다녀왔습니다. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 37.578791, 126.968645, '2026-07-24T06:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001376', '54500700-0000-4000-8000-000000000117', 'p-tourapi-3533128', '달에게 빌려온 하루', '오랜만에 여유 찾으러 달에게 빌려온 하루 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 37.681161, 126.412340, '2026-07-21T16:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001377', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2604806', '목임당', '기대 이상으로 너무 좋았던 목임당! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "고즈넉", "풍경맛집", "온마루"]'::jsonb, 34.951622, 127.201527, '2026-08-22T23:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001378', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3511602', '주식회사조아지구', 'SNS에서 사진 보고 찾아간 주식회사조아지구, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "주말나들이", "인생샷"]'::jsonb, 35.944307, 127.164754, '2026-08-01T00:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001379', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3337761', '마마스홈퀴진', '기대 이상으로 너무 좋았던 마마스홈퀴진! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색", "혼자여행", "온마루"]'::jsonb, 35.561342, 129.116907, '2026-08-13T05:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001380', '54500700-0000-4000-8000-000000000154', 'p-tourapi-1627167', '추사 김정희 선생 고택', '비 오는 날 운치 찾아 추사 김정희 선생 고택 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "방문팁", "인생샷"]'::jsonb, 36.746821, 126.798763, '2026-07-21T08:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001381', '54500700-0000-4000-8000-000000000113', 'p-tourapi-3438573', '자단', '근처 여행 코스로 자단 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.823880, 127.153446, '2026-08-10T23:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001382', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2996127', '기범이네국수', '천천히 골목 걷다가 마주친 기범이네국수. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 36.104577, 127.487892, '2026-08-03T17:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001383', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2701396', '서남산한옥', '서남산한옥 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집", "인생샷"]'::jsonb, 35.780704, 129.204496, '2026-08-09T19:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001384', '54500700-0000-4000-8000-000000000093', 'p-tourapi-3511602', '주식회사조아지구', 'SNS에서 사진 보고 찾아간 주식회사조아지구, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "혼자여행"]'::jsonb, 35.944212, 127.164405, '2026-08-24T01:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001385', '54500700-0000-4000-8000-000000000059', 'p-tourapi-780778', '이상한나라의 앨리스', '근처 여행 코스로 이상한나라의 앨리스 넣길 정말 잘했어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 33.289010, 126.321675, '2026-08-20T21:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001386', '54500700-0000-4000-8000-000000000135', 'p-tourapi-2775014', '나무키움(전의양묘영농조합법인)', '해 질 무렵에 나무키움(전의양묘영농조합법인) 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "인생샷", "온마루"]'::jsonb, 36.676665, 127.197697, '2026-08-03T22:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001387', '54500700-0000-4000-8000-000000000155', 'p-tourapi-231899', '용흥궁', '주말에 친구들이랑 용흥궁 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 37.747621, 126.486331, '2026-08-25T14:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001388', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2820370', '버들국수 (농업법인 주식회사 유화 ㈜)', '해 질 무렵에 버들국수 (농업법인 주식회사 유화 ㈜) 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 35.576391, 128.439364, '2026-08-20T08:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001389', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2569165', '수곡고택', '천천히 골목 걷다가 마주친 수곡고택. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 36.574062, 128.526565, '2026-07-19T23:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001390', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3080477', '수원전통문화관', '천천히 골목 걷다가 마주친 수원전통문화관. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "산책로", "온마루"]'::jsonb, 37.287414, 127.014187, '2026-08-11T11:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001391', '54500700-0000-4000-8000-000000000177', 'p-tourapi-1626791', '영동 성장환 고택', '조용히 사색하고 싶어서 찾은 영동 성장환 고택. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.121535, 127.710433, '2026-08-12T17:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001392', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2613382', '수곡당', '날씨가 너무 맑아서 수곡당 한 바퀴 돌고 왔네요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.405034, 127.382241, '2026-09-05T08:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001393', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2593571', '부경당', '평일 연차 쓰고 혼자 부경당 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.815989, 127.154131, '2026-09-05T14:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001394', '54500700-0000-4000-8000-000000000116', 'p-tourapi-250436', '아산 용궁댁', '드라이브 겸 나들이로 아산 용궁댁 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "사진맛집", "인생샷", "온마루"]'::jsonb, 36.740523, 126.892802, '2026-09-10T17:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001395', '54500700-0000-4000-8000-000000000068', 'p-tourapi-1606001', '해풍부원군윤택영댁재실', '예전부터 가보고 싶었던 해풍부원군윤택영댁재실 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "사색"]'::jsonb, 37.558508, 126.994397, '2026-07-25T11:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001396', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3451976', '길음역롯데캐슬트윈골드상가', '날씨가 너무 맑아서 길음역롯데캐슬트윈골드상가 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "힐링"]'::jsonb, 37.604052, 127.023341, '2026-07-29T23:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001397', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2605489', '군위 상매댁(군위남천고택)', '군위 상매댁(군위남천고택) 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "풍경맛집", "힐링", "온마루"]'::jsonb, 36.058344, 128.654240, '2026-09-03T06:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001398', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2569581', '춘하원(죽헌고택)', '드라이브 겸 나들이로 춘하원(죽헌고택) 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "풍경맛집"]'::jsonb, 36.647250, 128.663413, '2026-08-12T06:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001399', '54500700-0000-4000-8000-000000000195', 'p-tourapi-2795007', '화성 정수영 고택', '드라이브 겸 나들이로 화성 정수영 고택 선택했는데 대만족! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "사진맛집", "데이트"]'::jsonb, 37.132278, 126.700859, '2026-08-08T20:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001400', '54500700-0000-4000-8000-000000000086', 'p-tourapi-1871262', '락고재 하회한옥호텔 초가별관', '천천히 골목 걷다가 마주친 락고재 하회한옥호텔 초가별관. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행", "풍경맛집"]'::jsonb, 36.540466, 128.517511, '2026-09-15T02:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001401', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2696271', '공주공산성게스트 하우스', '예전부터 가보고 싶었던 공주공산성게스트 하우스 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 36.464855, 127.122665, '2026-08-04T03:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001402', '54500700-0000-4000-8000-000000000170', 'p-tourapi-1883758', '창실고택', '부모님 모시고 창실고택 산책 겸 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 36.438531, 129.027418, '2026-07-28T09:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001403', '54500700-0000-4000-8000-000000000201', 'p-tourapi-2605489', '군위 상매댁(군위남천고택)', '조용히 사색하고 싶어서 찾은 군위 상매댁(군위남천고택). 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "혼자여행", "사색"]'::jsonb, 36.058757, 128.653958, '2026-07-22T14:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001404', '54500700-0000-4000-8000-000000000140', 'p-tourapi-791531', '의성 소계당', '주말에 친구들이랑 의성 소계당 들렀는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "사색"]'::jsonb, 36.400706, 128.773930, '2026-08-27T18:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001405', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2594216', '전주한옥마당', '평일 연차 쓰고 혼자 전주한옥마당 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "산책로", "혼자여행"]'::jsonb, 35.811578, 127.152322, '2026-07-29T12:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001406', '54500700-0000-4000-8000-000000000101', 'p-tourapi-127588', '애은당고택·사우정고택·용계정', '비 오는 날 운치 찾아 애은당고택·사우정고택·용계정 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 36.167044, 129.186136, '2026-08-07T00:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001407', '54500700-0000-4000-8000-000000000072', 'p-tourapi-129584', '강릉 해운정', '천천히 골목 걷다가 마주친 강릉 해운정. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 37.786335, 128.890729, '2026-08-13T22:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001408', '54500700-0000-4000-8000-000000000089', 'p-tourapi-1584115', '익산 김병순 고택', '드라이브 겸 나들이로 익산 김병순 고택 선택했는데 대만족! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 36.060700, 126.909293, '2026-08-13T14:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001409', '54500700-0000-4000-8000-000000000116', 'p-tourapi-1998565', '학봉종택', 'SNS에서 사진 보고 찾아간 학봉종택, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 36.609623, 128.669272, '2026-08-22T01:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001410', '54500700-0000-4000-8000-000000000201', 'p-tourapi-2612804', '스카이큐브', '스카이큐브 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "가족여행"]'::jsonb, 34.926491, 127.502123, '2026-08-29T06:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001411', '54500700-0000-4000-8000-000000000156', 'p-tourapi-4074857', '미옥스테이', '날씨가 너무 맑아서 미옥스테이 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.866728, 128.612207, '2026-07-29T19:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001412', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2743393', '강선대', '부모님 모시고 강선대 산책 겸 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "주말나들이", "가족여행"]'::jsonb, 36.135002, 127.696118, '2026-07-17T23:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001413', '54500700-0000-4000-8000-000000000098', 'p-tourapi-126795', '고성 어명기 고택', '예전부터 가보고 싶었던 고성 어명기 고택 드디어 방문! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "산책로"]'::jsonb, 38.314844, 128.517720, '2026-08-03T03:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001414', '54500700-0000-4000-8000-000000000185', 'p-tourapi-893974', '개평한옥마을', '부모님 모시고 개평한옥마을 산책 겸 다녀왔습니다. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "가족여행", "데이트"]'::jsonb, 35.565824, 127.767046, '2026-08-11T04:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001415', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2638566', '주문진읍 BTS 앨범사진 촬영지 (버스정류장)', '비 오는 날 운치 찾아 주문진읍 BTS 앨범사진 촬영지 (버스정류장) 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.912328, 128.817080, '2026-09-11T10:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001416', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3428354', '스타필드 시티 부천', '드라이브 겸 나들이로 스타필드 시티 부천 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.461645, 126.814047, '2026-08-27T12:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001417', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2000964', '향단', '부모님 모시고 향단 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.999575, 129.253074, '2026-08-13T11:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001418', '54500700-0000-4000-8000-000000000137', 'p-tourapi-3353949', '㈜ 희품씨', '㈜ 희품씨 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 35.566981, 129.112387, '2026-08-24T09:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001419', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2850614', '스탈릿성수', '근처 여행 코스로 스탈릿성수 넣길 정말 잘했어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 37.544562, 127.055572, '2026-07-28T03:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001420', '54500700-0000-4000-8000-000000000140', 'p-tourapi-3105217', '오늘스테이 동대문점', '기대 이상으로 너무 좋았던 오늘스테이 동대문점! 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이", "방문팁", "온마루"]'::jsonb, 37.576996, 127.037507, '2026-07-22T09:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001421', '54500700-0000-4000-8000-000000000142', 'p-tourapi-3102032', '무아기와', '해 질 무렵에 무아기와 방문했는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "풍경맛집", "산책로", "온마루"]'::jsonb, 37.575314, 127.048330, '2026-09-07T05:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001422', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2575836', '북촌 게스트하우스', '북촌 게스트하우스 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.578813, 126.985457, '2026-08-22T18:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001423', '54500700-0000-4000-8000-000000000074', 'p-tourapi-2604533', '고집불통송가네', '근처 여행 코스로 고집불통송가네 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "힐링", "온마루"]'::jsonb, 34.441407, 126.631232, '2026-08-24T23:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001424', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2993587', '대구 신천물놀이장', '예전부터 가보고 싶었던 대구 신천물놀이장 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 35.854366, 128.607526, '2026-08-06T16:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001425', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2621370', '태양아래월출산', '천천히 골목 걷다가 마주친 태양아래월출산. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["인생샷", "사진맛집", "방문팁", "온마루"]'::jsonb, 34.739771, 126.718563, '2026-08-13T14:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001426', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2502595', '술샘', '날씨가 너무 맑아서 술샘 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 37.233700, 127.298356, '2026-09-11T10:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001427', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2996133', '(주)손으로만드는수공예', '오랜만에 여유 찾으러 (주)손으로만드는수공예 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 36.099017, 127.492826, '2026-08-29T23:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001428', '54500700-0000-4000-8000-000000000144', 'p-tourapi-2769810', '오창 미래지 한옥마을', '오창 미래지 한옥마을 다녀왔어요! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.735089, 127.405001, '2026-09-04T03:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001429', '54500700-0000-4000-8000-000000000148', 'p-tourapi-1882371', '학인당', '해 질 무렵에 학인당 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["가족여행", "인생샷"]'::jsonb, 35.811980, 127.151906, '2026-08-13T16:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001430', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1594500', '전주목판서화체험관', '비 오는 날 운치 찾아 전주목판서화체험관 다녀왔어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.811489, 127.155573, '2026-08-04T23:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001431', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2613176', '현부자네 집', '날씨가 너무 맑아서 현부자네 집 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 34.849946, 127.353492, '2026-09-05T20:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001432', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2746709', '파주팜랜드', '부모님 모시고 파주팜랜드 산책 겸 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.809926, 126.692808, '2026-08-11T10:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001433', '54500700-0000-4000-8000-000000000149', 'p-tourapi-1877477', '노송정종택(퇴계생가)', '비 오는 날 운치 찾아 노송정종택(퇴계생가) 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 36.749409, 128.828367, '2026-08-04T23:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001434', '54500700-0000-4000-8000-000000000097', 'p-tourapi-1684863', '제천 지곡리 고가', '오랜만에 여유 찾으러 제천 지곡리 고가 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집", "혼자여행"]'::jsonb, 37.004341, 128.170756, '2026-07-31T11:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001435', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2594862', '향우당', '천천히 골목 걷다가 마주친 향우당. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 35.602975, 128.907062, '2026-07-19T19:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001436', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2706613', '송계헌', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 36.542751, 128.556934, '2026-08-03T11:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001437', '54500700-0000-4000-8000-000000000069', 'p-tourapi-3438684', '물길스테이', '날씨가 너무 맑아서 물길스테이 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "데이트", "방문팁", "온마루"]'::jsonb, 36.505806, 128.852443, '2026-09-01T15:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001438', '54500700-0000-4000-8000-000000000187', 'p-tourapi-802358', '아산 대통령마을(농촌전통테마)', 'SNS에서 사진 보고 찾아간 아산 대통령마을(농촌전통테마), 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 36.834570, 127.023034, '2026-08-27T06:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001439', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2569165', '수곡고택', '드라이브 겸 나들이로 수곡고택 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "주말나들이"]'::jsonb, 36.573900, 128.525998, '2026-07-22T12:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001440', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2795007', '화성 정수영 고택', 'SNS에서 사진 보고 찾아간 화성 정수영 고택, 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 37.132532, 126.700588, '2026-07-29T22:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001441', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2700309', '경주읍성한옥', '기대 이상으로 너무 좋았던 경주읍성한옥! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "주말나들이", "방문팁", "온마루"]'::jsonb, 35.849798, 129.211779, '2026-09-11T18:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001442', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2007983', '경북전통음식체험관 모심정', '부모님 모시고 경북전통음식체험관 모심정 산책 겸 다녀왔습니다. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "힐링", "고즈넉", "온마루"]'::jsonb, 36.662007, 128.119181, '2026-07-27T14:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001443', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3529694', '서울아리', '근처 여행 코스로 서울아리 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "인생샷"]'::jsonb, 37.576505, 126.991458, '2026-08-03T14:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001444', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3511613', '전라감영양조장(전라감영주식회사)', '날씨가 너무 맑아서 전라감영양조장(전라감영주식회사) 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "주말나들이", "사진맛집"]'::jsonb, 35.817251, 127.146214, '2026-08-16T17:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001445', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2046122', '정강원 관광농원', '근처 여행 코스로 정강원 관광농원 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "주말나들이", "데이트"]'::jsonb, 37.570183, 128.408020, '2026-09-07T03:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001446', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2047895', '대승한지마을 한옥전통문화체험관', '근처 여행 코스로 대승한지마을 한옥전통문화체험관 넣길 정말 잘했어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 35.854325, 127.294322, '2026-08-23T15:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001447', '54500700-0000-4000-8000-000000000056', 'p-tourapi-3102084', '산온 리트릿', 'SNS에서 사진 보고 찾아간 산온 리트릿, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "힐링"]'::jsonb, 36.574030, 128.578383, '2026-09-08T10:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001448', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2620182', '송담 고택', '드라이브 겸 나들이로 송담 고택 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "사진맛집", "온마루"]'::jsonb, 37.106612, 127.191996, '2026-09-10T14:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001449', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2605927', '초원사진관', '기대 이상으로 너무 좋았던 초원사진관! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "사진맛집", "인생샷"]'::jsonb, 35.987999, 126.708575, '2026-09-11T23:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001450', '54500700-0000-4000-8000-000000000165', 'p-tourapi-1620863', '양금석가옥', '양금석가옥 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["가족여행", "방문팁", "온마루"]'::jsonb, 33.291066, 126.628279, '2026-07-22T08:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001451', '54500700-0000-4000-8000-000000000057', 'p-tourapi-1621161', '제주 성읍마을 고창환 고택', '비 오는 날 운치 찾아 제주 성읍마을 고창환 고택 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 33.387323, 126.799839, '2026-07-20T02:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001452', '54500700-0000-4000-8000-000000000171', 'p-tourapi-264402', '화성어차', '기대 이상으로 너무 좋았던 화성어차! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 37.287997, 127.023548, '2026-07-28T03:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001453', '54500700-0000-4000-8000-000000000119', 'p-tourapi-1939620', '보은 하얀민들레한옥마을', '해 질 무렵에 보은 하얀민들레한옥마을 방문했는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "방문팁", "사진맛집", "온마루"]'::jsonb, 36.492075, 127.609560, '2026-08-11T12:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001454', '54500700-0000-4000-8000-000000000087', 'p-tourapi-792208', '괴산 한지체험박물관', '주말에 친구들이랑 괴산 한지체험박물관 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링", "고즈넉"]'::jsonb, 36.785336, 128.014887, '2026-08-29T12:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001455', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3438166', '뉠스테이', '뉠스테이 다녀왔어요! 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "인생샷", "방문팁"]'::jsonb, 37.579408, 126.967781, '2026-09-09T03:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001456', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2696256', '낙안재', '기대 이상으로 너무 좋았던 낙안재! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "힐링", "사색", "온마루"]'::jsonb, 35.836369, 129.208273, '2026-09-12T05:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001457', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2570638', '강령전', '날씨가 너무 맑아서 강령전 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 35.814909, 127.152163, '2026-08-23T20:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001458', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2702475', '고진하 가옥', '기대 이상으로 너무 좋았던 고진하 가옥! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 37.174205, 128.387326, '2026-09-02T16:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001459', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2603884', '연당', '예전부터 가보고 싶었던 연당 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "산책로"]'::jsonb, 37.582607, 126.987158, '2026-09-10T03:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001460', '54500700-0000-4000-8000-000000000091', 'p-tourapi-3105334', '133파티룸 한옥스테이점', '조용히 사색하고 싶어서 찾은 133파티룸 한옥스테이점. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "산책로", "고즈넉"]'::jsonb, 37.279258, 127.016096, '2026-07-27T11:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001461', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2651358', '홍휘관', '해 질 무렵에 홍휘관 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "힐링", "고즈넉"]'::jsonb, 36.465868, 127.122616, '2026-08-09T15:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001462', '54500700-0000-4000-8000-000000000202', 'p-tourapi-1626780', '예산 오추리 고택(정동호 가옥)', '예산 오추리 고택(정동호 가옥) 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 36.763690, 126.719655, '2026-08-14T12:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001463', '54500700-0000-4000-8000-000000000183', 'p-tourapi-742022', '한터농원(한터조랑말농장)', '날씨가 너무 맑아서 한터농원(한터조랑말농장) 한 바퀴 돌고 왔네요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.271121, 127.265467, '2026-07-30T05:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001464', '54500700-0000-4000-8000-000000000081', 'p-tourapi-3066467', '우리 놀이터 마루달', '근처 여행 코스로 우리 놀이터 마루달 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 35.816849, 127.152271, '2026-08-19T09:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001465', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3030491', '선성현문화단지 한옥체험관', '부모님 모시고 선성현문화단지 한옥체험관 산책 겸 다녀왔습니다. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 36.698249, 128.814689, '2026-08-18T17:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001466', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3072240', '온유헌 바이 버틀러리', '예전부터 가보고 싶었던 온유헌 바이 버틀러리 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "가족여행", "온마루"]'::jsonb, 37.581560, 126.987559, '2026-07-17T20:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001467', '54500700-0000-4000-8000-000000000202', 'p-tourapi-971122', '강화 아르미애월드', '천천히 골목 걷다가 마주친 강화 아르미애월드. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "주말나들이"]'::jsonb, 37.703204, 126.434824, '2026-08-09T04:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001468', '54500700-0000-4000-8000-000000000074', 'p-tourapi-2595871', '나들한옥', '조용히 사색하고 싶어서 찾은 나들한옥. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 35.836322, 129.218239, '2026-07-21T03:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001469', '54500700-0000-4000-8000-000000000202', 'p-tourapi-1627280', '단양 조덕수 고택', '천천히 골목 걷다가 마주친 단양 조덕수 고택. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["사진맛집", "방문팁", "온마루"]'::jsonb, 37.003312, 128.383600, '2026-09-13T01:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001470', '54500700-0000-4000-8000-000000000102', 'p-tourapi-3531662', '최선평 가옥', '날씨가 너무 맑아서 최선평 가옥 한 바퀴 돌고 왔네요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "풍경맛집", "힐링"]'::jsonb, 37.878371, 128.795644, '2026-08-14T16:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001471', '54500700-0000-4000-8000-000000000164', 'p-tourapi-987720', '신사동 가로수길', '근처 여행 코스로 신사동 가로수길 넣길 정말 잘했어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉", "사색", "온마루"]'::jsonb, 37.519777, 127.022695, '2026-08-24T06:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001472', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2995167', '달달구리(주식회사달달구리)', '기대 이상으로 너무 좋았던 달달구리(주식회사달달구리)! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 35.938547, 127.167109, '2026-07-19T16:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001473', '54500700-0000-4000-8000-000000000152', 'p-tourapi-1972487', '시원 한옥체험관', 'SNS에서 사진 보고 찾아간 시원 한옥체험관, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색", "고즈넉"]'::jsonb, 35.812757, 127.153508, '2026-07-18T00:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001474', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2725051', '다올재 협동조합', '비 오는 날 운치 찾아 다올재 협동조합 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 34.955224, 127.480477, '2026-09-06T12:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001475', '54500700-0000-4000-8000-000000000082', 'p-tourapi-3438588', '유유가', '근처 여행 코스로 유유가 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 34.955668, 127.483011, '2026-08-12T10:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001476', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2996749', '송금체험마을영농조합법인', '해 질 무렵에 송금체험마을영농조합법인 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.713558, 128.720097, '2026-08-20T23:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001477', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2568571', '1928 쉼마루', '평일 연차 쓰고 혼자 1928 쉼마루 다녀옴. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 35.811865, 127.152322, '2026-07-28T15:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001478', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3533167', '황남채', '기대 이상으로 너무 좋았던 황남채! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.837255, 129.210490, '2026-09-13T06:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001479', '54500700-0000-4000-8000-000000000141', 'p-tourapi-127329', '목포시사', '목포시사 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "힐링", "온마루"]'::jsonb, 34.790174, 126.377335, '2026-08-07T11:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001480', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2009156', '고택문화체험관', '오랜만에 여유 찾으러 고택문화체험관 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "혼자여행", "산책로"]'::jsonb, 35.616830, 127.020479, '2026-07-17T15:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001481', '54500700-0000-4000-8000-000000000122', 'p-tourapi-129057', '청송 평산신씨 판사공파 종택과 분가 고택', '주말에 친구들이랑 청송 평산신씨 판사공파 종택과 분가 고택 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 36.458769, 129.023068, '2026-08-29T01:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001482', '54500700-0000-4000-8000-000000000113', 'p-tourapi-3337188', '세종전통문화체험관', '드라이브 겸 나들이로 세종전통문화체험관 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 36.506753, 127.291417, '2026-08-11T18:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001483', '54500700-0000-4000-8000-000000000204', 'p-tourapi-3449335', '고양드론앵커센터', '조용히 사색하고 싶어서 찾은 고양드론앵커센터. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "혼자여행", "사색"]'::jsonb, 37.604403, 126.867469, '2026-07-22T12:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001484', '54500700-0000-4000-8000-000000000136', 'p-tourapi-129043', '청송 사남고택', '주말에 친구들이랑 청송 사남고택 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 36.458238, 129.021428, '2026-08-30T15:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001485', '54500700-0000-4000-8000-000000000145', 'p-tourapi-893974', '개평한옥마을', '부모님 모시고 개평한옥마을 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.565650, 127.767481, '2026-07-27T20:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001486', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2683997', '카포레', '근처 여행 코스로 카포레 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "방문팁", "온마루"]'::jsonb, 37.505681, 127.435724, '2026-09-13T19:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001487', '54500700-0000-4000-8000-000000000090', 'p-tourapi-1685627', '청풍 후산리 고가', '해 질 무렵에 청풍 후산리 고가 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 37.003969, 128.172902, '2026-08-20T13:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001488', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2575760', '연우당', '오랜만에 여유 찾으러 연우당 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "산책로", "고즈넉"]'::jsonb, 35.815616, 127.153330, '2026-07-27T04:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001489', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2900858', '제천비행장', '제천비행장 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "방문팁", "인생샷"]'::jsonb, 37.163132, 128.213748, '2026-09-04T01:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001490', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2777043', '김택준가옥', '드라이브 겸 나들이로 김택준가옥 선택했는데 대만족! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["방문팁", "데이트", "온마루"]'::jsonb, 37.971924, 128.759398, '2026-09-04T11:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001491', '54500700-0000-4000-8000-000000000171', 'p-tourapi-1623646', '권희문가옥', '기대 이상으로 너무 좋았던 권희문가옥! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "혼자여행", "힐링"]'::jsonb, 35.587709, 127.386293, '2026-08-07T12:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001492', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2604602', '경주 교동한옥집', '부모님 모시고 경주 교동한옥집 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["사진맛집", "방문팁", "주말나들이", "온마루"]'::jsonb, 35.828701, 129.211791, '2026-08-08T22:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001493', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3438450', '평안채', '날씨가 너무 맑아서 평안채 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "사색"]'::jsonb, 37.640945, 126.938866, '2026-08-01T00:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001494', '54500700-0000-4000-8000-000000000164', 'p-tourapi-1578365', '거창 무릉리 정씨고가', '근처 여행 코스로 거창 무릉리 정씨고가 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "데이트", "가족여행", "온마루"]'::jsonb, 35.664400, 127.945534, '2026-08-23T16:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001495', '54500700-0000-4000-8000-000000000192', 'p-tourapi-2725123', '운기석9020(운기석9020협동조합)', '천천히 골목 걷다가 마주친 운기석9020(운기석9020협동조합). 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["가족여행", "인생샷", "온마루"]'::jsonb, 37.380507, 128.662827, '2026-08-10T15:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001496', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2706514', '여수한옥체험관', 'SNS에서 사진 보고 찾아간 여수한옥체험관, 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "방문팁", "주말나들이", "온마루"]'::jsonb, 34.748545, 127.630178, '2026-08-17T03:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001497', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3102068', '경주 황리단길 한옥 독채 풀빌라 무와', '근처 여행 코스로 경주 황리단길 한옥 독채 풀빌라 무와 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 35.835605, 129.208140, '2026-08-06T14:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001498', '54500700-0000-4000-8000-000000000157', 'p-tourapi-1395466', '만해 한용운 심우장', '비 오는 날 운치 찾아 만해 한용운 심우장 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 37.593551, 126.991550, '2026-09-05T11:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001499', '54500700-0000-4000-8000-000000000194', 'p-tourapi-1615878', '철종외가', '평일 연차 쓰고 혼자 철종외가 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 37.704994, 126.476955, '2026-09-03T13:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001500', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2569105', '너와 나의 둥지', '근처 여행 코스로 너와 나의 둥지 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["사진맛집", "방문팁", "주말나들이"]'::jsonb, 34.740971, 126.718380, '2026-08-01T02:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001501', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2623228', '권정생동화나라', 'SNS에서 사진 보고 찾아간 권정생동화나라, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "방문팁", "데이트", "온마루"]'::jsonb, 36.460553, 128.665035, '2026-08-12T07:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001502', '54500700-0000-4000-8000-000000000072', 'p-tourapi-128145', '나주 목사내아', '날씨가 너무 맑아서 나주 목사내아 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "주말나들이", "사진맛집", "온마루"]'::jsonb, 35.032114, 126.715106, '2026-08-16T22:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001503', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2609850', '마당예쁜집(전주한옥마을 마당예쁜집)', '기대 이상으로 너무 좋았던 마당예쁜집(전주한옥마을 마당예쁜집)! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.812251, 127.154143, '2026-08-02T09:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001504', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2695757', '한옥게스트하우스 ''安(Ahn)''', '근처 여행 코스로 한옥게스트하우스 ''安(Ahn)'' 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "가족여행", "인생샷", "온마루"]'::jsonb, 35.872934, 128.611189, '2026-07-20T07:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001505', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2820027', '바른스포츠월드', '비 오는 날 운치 찾아 바른스포츠월드 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["사진맛집", "데이트", "인생샷"]'::jsonb, 36.598963, 127.423073, '2026-08-10T08:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001506', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2784682', '진해루', '날씨가 너무 맑아서 진해루 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["인생샷", "방문팁", "온마루"]'::jsonb, 35.146963, 128.685379, '2026-09-15T14:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001507', '54500700-0000-4000-8000-000000000167', 'p-tourapi-1951619', '비암사 도깨비도로', '부모님 모시고 비암사 도깨비도로 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["방문팁", "데이트", "사진맛집", "온마루"]'::jsonb, 36.610962, 127.191664, '2026-09-10T05:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001508', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3438724', '소월정', '비 오는 날 운치 찾아 소월정 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "고즈넉"]'::jsonb, 37.583085, 126.986623, '2026-07-29T12:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001509', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2699326', '월출산 청풍명월', '근처 여행 코스로 월출산 청풍명월 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "고즈넉", "산책로", "온마루"]'::jsonb, 34.769592, 126.654795, '2026-07-31T14:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001510', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2608154', '조약도 한옥체험', '조약도 한옥체험 다녀왔어요! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "사진맛집", "가족여행", "온마루"]'::jsonb, 34.373385, 126.887854, '2026-08-02T13:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001511', '54500700-0000-4000-8000-000000000155', 'p-tourapi-4070358', '호메오', '해 질 무렵에 호메오 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집", "고즈넉"]'::jsonb, 35.815215, 127.142152, '2026-08-01T07:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001512', '54500700-0000-4000-8000-000000000138', 'p-tourapi-3116447', '웰컴미스테익스', '조용히 사색하고 싶어서 찾은 웰컴미스테익스. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "산책로", "풍경맛집", "온마루"]'::jsonb, 37.591780, 126.963465, '2026-08-11T08:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001513', '54500700-0000-4000-8000-000000000197', 'p-tourapi-3438126', '스테이 어플로트', '근처 여행 코스로 스테이 어플로트 넣길 정말 잘했어요. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "혼자여행", "산책로"]'::jsonb, 37.578533, 126.972696, '2026-08-13T07:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001514', '54500700-0000-4000-8000-000000000200', 'p-tourapi-1992717', '의성 소우당', '부모님 모시고 의성 소우당 산책 겸 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.245722, 128.701370, '2026-08-09T01:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001515', '54500700-0000-4000-8000-000000000201', 'p-tourapi-3532720', '메모리스테이 효자', '천천히 골목 걷다가 마주친 메모리스테이 효자. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 37.582351, 126.971158, '2026-07-20T15:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001516', '54500700-0000-4000-8000-000000000189', 'p-tourapi-4039810', '스테이꼬리', '예전부터 가보고 싶었던 스테이꼬리 드디어 방문! 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 35.813081, 129.212728, '2026-09-11T00:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001517', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2995169', '농업회사법인 주식회사 공동체공간 수작', '근처 여행 코스로 농업회사법인 주식회사 공동체공간 수작 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 35.942144, 127.263261, '2026-07-25T18:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001518', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2569824', '흥해배씨 임연재종택', '근처 여행 코스로 흥해배씨 임연재종택 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "주말나들이", "사진맛집"]'::jsonb, 36.550312, 128.791350, '2026-07-25T15:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001519', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2575841', '지우당', '해 질 무렵에 지우당 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "사색", "산책로"]'::jsonb, 35.812660, 127.154049, '2026-07-24T13:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001520', '54500700-0000-4000-8000-000000000056', 'p-tourapi-705411', '군위 남천고택', '근처 여행 코스로 군위 남천고택 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["방문팁", "사진맛집", "온마루"]'::jsonb, 36.058475, 128.654295, '2026-08-21T06:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001521', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2586166', '황토한옥고마', '천천히 골목 걷다가 마주친 황토한옥고마. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["인생샷", "주말나들이", "방문팁"]'::jsonb, 36.461517, 127.121998, '2026-08-07T03:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001522', '54500700-0000-4000-8000-000000000057', 'p-tourapi-971122', '강화 아르미애월드', '평일 연차 쓰고 혼자 강화 아르미애월드 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "혼자여행", "힐링", "온마루"]'::jsonb, 37.702555, 126.434628, '2026-08-20T12:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001523', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2778518', '주포지구한옥전원마을', '주포지구한옥전원마을 다녀왔어요! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉", "풍경맛집", "온마루"]'::jsonb, 35.091845, 126.461227, '2026-08-23T14:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001524', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2697287', '하서원(외암민속마을)', '평일 연차 쓰고 혼자 하서원(외암민속마을) 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 36.731758, 127.014740, '2026-07-25T00:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001525', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2679044', '청향재', '천천히 골목 걷다가 마주친 청향재. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉", "산책로"]'::jsonb, 37.642049, 126.940460, '2026-08-29T15:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001526', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3072315', '담담', '오랜만에 여유 찾으러 담담 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "풍경맛집", "혼자여행"]'::jsonb, 36.453343, 127.122133, '2026-08-10T20:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001527', '54500700-0000-4000-8000-000000000089', 'p-tourapi-3454074', '영화의전당 라이브러리 자료실', '해 질 무렵에 영화의전당 라이브러리 자료실 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 35.171378, 129.127003, '2026-07-26T15:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001528', '54500700-0000-4000-8000-000000000107', 'p-tourapi-1877477', '노송정종택(퇴계생가)', '오랜만에 여유 찾으러 노송정종택(퇴계생가) 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 36.749532, 128.828152, '2026-09-06T02:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001529', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2819644', '적정온도(순향가)', '예전부터 가보고 싶었던 적정온도(순향가) 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["데이트", "가족여행", "인생샷", "온마루"]'::jsonb, 34.872637, 127.528224, '2026-07-19T10:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001530', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2707445', '일독일박', '기대 이상으로 너무 좋았던 일독일박! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 37.578448, 126.968682, '2026-07-17T21:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001531', '54500700-0000-4000-8000-000000000101', 'p-tourapi-3541047', '주문진 관광안내센터', '드라이브 겸 나들이로 주문진 관광안내센터 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "고즈넉", "온마루"]'::jsonb, 37.889948, 128.828830, '2026-09-11T23:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001532', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3438182', '여느날', 'SNS에서 사진 보고 찾아간 여느날, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 37.576450, 126.969867, '2026-09-14T19:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001533', '54500700-0000-4000-8000-000000000139', 'p-tourapi-127371', '수내동가옥(이택구가옥)', '부모님 모시고 수내동가옥(이택구가옥) 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 37.379957, 127.121312, '2026-09-01T11:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001534', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2350029', '도래미하우스', '부모님 모시고 도래미하우스 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "데이트", "주말나들이", "온마루"]'::jsonb, 34.997330, 126.825039, '2026-08-02T09:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001535', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2683997', '카포레', '드라이브 겸 나들이로 카포레 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["사진맛집", "방문팁"]'::jsonb, 37.505813, 127.435198, '2026-09-03T23:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001536', '54500700-0000-4000-8000-000000000200', 'p-tourapi-3102068', '경주 황리단길 한옥 독채 풀빌라 무와', '주말에 친구들이랑 경주 황리단길 한옥 독채 풀빌라 무와 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 35.836065, 129.207896, '2026-09-01T14:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001537', '54500700-0000-4000-8000-000000000122', 'p-tourapi-127060', '이장우가옥', '천천히 골목 걷다가 마주친 이장우가옥. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 35.140541, 126.914070, '2026-08-01T07:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001538', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2663065', '휴휴당', 'SNS에서 사진 보고 찾아간 휴휴당, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 35.835778, 129.212214, '2026-08-21T04:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001539', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3072218', '오히', '부모님 모시고 오히 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "사진맛집"]'::jsonb, 35.824148, 129.212665, '2026-08-02T05:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001540', '54500700-0000-4000-8000-000000000080', 'p-tourapi-1883593', '월인당', '비 오는 날 운치 찾아 월인당 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 34.777581, 126.612274, '2026-07-29T06:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001541', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2795956', '양평 창대리 고가', 'SNS에서 사진 보고 찾아간 양평 창대리 고가, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "방문팁", "사진맛집"]'::jsonb, 37.471426, 127.505652, '2026-08-20T20:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001542', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2598628', '별아래한옥', '평일 연차 쓰고 혼자 별아래한옥 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "힐링", "혼자여행"]'::jsonb, 36.537482, 128.821272, '2026-08-01T17:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001543', '54500700-0000-4000-8000-000000000105', 'p-tourapi-800812', '장성 자라뫼마을 [농촌전통테마]', '오랜만에 여유 찾으러 장성 자라뫼마을 [농촌전통테마] 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 35.420135, 126.822345, '2026-08-17T01:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001544', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2707444', '가영당', '가영당 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "인생샷"]'::jsonb, 36.735271, 127.405963, '2026-08-26T06:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001545', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2786859', '읍청정(산청)', '해 질 무렵에 읍청정(산청) 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 35.308808, 127.965650, '2026-09-06T06:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001546', '54500700-0000-4000-8000-000000000080', 'p-tourapi-3012678', '사기막골 도예촌', '사기막골 도예촌 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 37.293637, 127.411769, '2026-09-13T03:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001547', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2696271', '공주공산성게스트 하우스', '기대 이상으로 너무 좋았던 공주공산성게스트 하우스! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 36.465095, 127.123226, '2026-09-01T10:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001548', '54500700-0000-4000-8000-000000000141', 'p-tourapi-1947036', '스미스가 좋아하는 한옥', '드라이브 겸 나들이로 스미스가 좋아하는 한옥 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이", "인생샷", "온마루"]'::jsonb, 37.577909, 126.980426, '2026-08-08T15:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001549', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2599272', '모지고택', '주말에 친구들이랑 모지고택 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 36.540666, 128.518286, '2026-08-23T22:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001550', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3510444', '농업회사법인주식회사꿀벌인', '근처 여행 코스로 농업회사법인주식회사꿀벌인 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "방문팁", "사진맛집", "온마루"]'::jsonb, 36.014054, 128.421781, '2026-08-18T16:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001551', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2742194', '울산시립어린이테마파크', 'SNS에서 사진 보고 찾아간 울산시립어린이테마파크, 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "고즈넉", "사색"]'::jsonb, 35.488439, 129.437788, '2026-08-19T10:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001552', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2701356', '달빛한옥 수류화개', '드라이브 겸 나들이로 달빛한옥 수류화개 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "데이트", "방문팁", "온마루"]'::jsonb, 34.739384, 126.717098, '2026-08-02T11:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001553', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2932873', '계와고택', '드라이브 겸 나들이로 계와고택 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 36.505822, 128.852973, '2026-08-08T10:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001554', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2605277', '웰컴투동막골촬영지', '해 질 무렵에 웰컴투동막골촬영지 방문했는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 37.314157, 128.471100, '2026-09-07T08:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001555', '54500700-0000-4000-8000-000000000069', 'p-tourapi-3116447', '웰컴미스테익스', '날씨가 너무 맑아서 웰컴미스테익스 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 37.591682, 126.963502, '2026-09-10T06:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001556', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3438422', '한옥 스테이 미경', '근처 여행 코스로 한옥 스테이 미경 넣길 정말 잘했어요. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행"]'::jsonb, 37.586687, 127.007964, '2026-08-01T07:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001557', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2702475', '고진하 가옥', '근처 여행 코스로 고진하 가옥 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 37.174340, 128.387213, '2026-08-17T23:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001558', '54500700-0000-4000-8000-000000000082', 'p-tourapi-3438586', '휴휴가', 'SNS에서 사진 보고 찾아간 휴휴가, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 34.955178, 127.480940, '2026-07-21T13:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001559', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2996647', '정촌유기농원', '비 오는 날 운치 찾아 정촌유기농원 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "사진맛집", "인생샷", "온마루"]'::jsonb, 36.425752, 126.672079, '2026-09-10T17:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001560', '54500700-0000-4000-8000-000000000078', 'p-tourapi-3454469', '아동청소년친화공간 꿈이랑', '평일 연차 쓰고 혼자 아동청소년친화공간 꿈이랑 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "산책로"]'::jsonb, 38.199953, 128.580299, '2026-08-13T08:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001561', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3438585', '스테이 구도', '해 질 무렵에 스테이 구도 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 34.792113, 126.380243, '2026-07-22T08:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001562', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3072235', '유준당 바이 버틀러리', 'SNS에서 사진 보고 찾아간 유준당 바이 버틀러리, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집", "방문팁", "온마루"]'::jsonb, 37.582195, 126.987016, '2026-08-21T10:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001563', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2707444', '가영당', 'SNS에서 사진 보고 찾아간 가영당, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "사진맛집", "데이트"]'::jsonb, 36.735142, 127.405349, '2026-08-21T07:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001564', '54500700-0000-4000-8000-000000000113', 'p-tourapi-126419', '다산초당', '기대 이상으로 너무 좋았던 다산초당! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 34.580751, 126.744862, '2026-09-05T02:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001565', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2569237', '운정루', '오랜만에 여유 찾으러 운정루 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "힐링", "사색"]'::jsonb, 35.791365, 129.246038, '2026-08-10T16:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001566', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3511656', '하얀민들레마을(주식회사미진)', '주말에 친구들이랑 하얀민들레마을(주식회사미진) 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 36.493865, 127.611101, '2026-09-05T18:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001567', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2782543', '보성 이진래고택', '조용히 사색하고 싶어서 찾은 보성 이진래고택. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "풍경맛집", "사색"]'::jsonb, 34.762722, 127.186639, '2026-09-04T03:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001568', '54500700-0000-4000-8000-000000000113', 'p-tourapi-2701896', '평창지동봉가옥', '비 오는 날 운치 찾아 평창지동봉가옥 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 37.333684, 128.379367, '2026-08-22T17:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001569', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2667868', '마음의 고향', '천천히 골목 걷다가 마주친 마음의 고향. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 35.032716, 126.390824, '2026-07-31T14:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001570', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2850183', '대한옥', 'SNS에서 사진 보고 찾아간 대한옥, 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "방문팁", "주말나들이"]'::jsonb, 37.519674, 126.911229, '2026-09-11T01:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001571', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2751703', '달팽이', '오랜만에 여유 찾으러 달팽이 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "사색"]'::jsonb, 35.413596, 127.616579, '2026-07-17T18:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001572', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '조용히 사색하고 싶어서 찾은 미담 한옥 게스트 하우스. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.580687, 126.986797, '2026-08-18T09:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001573', '54500700-0000-4000-8000-000000000172', 'p-tourapi-250460', '남원몽심재', '근처 여행 코스로 남원몽심재 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.338382, 127.374603, '2026-07-18T05:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001574', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3102131', '여여재', '날씨가 너무 맑아서 여여재 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 37.283806, 127.008871, '2026-09-01T15:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001575', '54500700-0000-4000-8000-000000000112', 'p-tourapi-3544376', '강릉종합사회복지관', '천천히 골목 걷다가 마주친 강릉종합사회복지관. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.764910, 128.915711, '2026-07-31T11:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001576', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2702475', '고진하 가옥', '근처 여행 코스로 고진하 가옥 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "산책로", "사색", "온마루"]'::jsonb, 37.174023, 128.387383, '2026-09-02T02:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001577', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2998479', '삼판서고택', '기대 이상으로 너무 좋았던 삼판서고택! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉", "온마루"]'::jsonb, 36.820892, 128.616011, '2026-09-02T18:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001578', '54500700-0000-4000-8000-000000000062', 'p-tourapi-1437668', '순창장류체험관', '기대 이상으로 너무 좋았던 순창장류체험관! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["데이트", "인생샷", "방문팁"]'::jsonb, 35.366002, 127.108044, '2026-08-26T01:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001579', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2717416', '올드타임', '주말에 친구들이랑 올드타임 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "사진맛집", "방문팁"]'::jsonb, 37.000413, 127.200388, '2026-08-23T04:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001580', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2604371', '노을한옥', '근처 여행 코스로 노을한옥 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행", "데이트"]'::jsonb, 34.851173, 127.523308, '2026-09-03T11:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001581', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2605277', '웰컴투동막골촬영지', '부모님 모시고 웰컴투동막골촬영지 산책 겸 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 37.313928, 128.470837, '2026-07-19T13:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001582', '54500700-0000-4000-8000-000000000144', 'p-tourapi-3102084', '산온 리트릿', '근처 여행 코스로 산온 리트릿 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["주말나들이", "인생샷"]'::jsonb, 36.574019, 128.578559, '2026-08-05T22:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001583', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2358186', '쌍산재', 'SNS에서 사진 보고 찾아간 쌍산재, 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 35.215825, 127.498421, '2026-08-02T00:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001584', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2789519', '황병산사냥민속놀이체험관', '예전부터 가보고 싶었던 황병산사냥민속놀이체험관 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 37.707405, 128.687200, '2026-08-19T01:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001585', '54500700-0000-4000-8000-000000000176', 'p-tourapi-2817792', '밀알영농조합', '평일 연차 쓰고 혼자 밀알영농조합 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 35.081833, 128.186022, '2026-08-15T10:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001586', '54500700-0000-4000-8000-000000000107', 'p-tourapi-3510971', '컬러브릿지협동조합', '주말에 친구들이랑 컬러브릿지협동조합 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 35.141248, 126.917212, '2026-08-10T17:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001587', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2717292', '카페 방림별곡', '은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색", "혼자여행"]'::jsonb, 37.426585, 128.394825, '2026-08-25T23:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001588', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2633890', '통영어드벤처타워', '근처 여행 코스로 통영어드벤처타워 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 34.824948, 128.422388, '2026-08-28T06:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001589', '54500700-0000-4000-8000-000000000200', 'p-tourapi-1623646', '권희문가옥', '근처 여행 코스로 권희문가옥 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "사진맛집", "방문팁", "온마루"]'::jsonb, 35.587593, 127.386137, '2026-07-20T19:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001590', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2717494', '쌍류포도정원협동조합', '부모님 모시고 쌍류포도정원협동조합 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉", "힐링", "온마루"]'::jsonb, 36.603717, 127.216045, '2026-08-04T04:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001591', '54500700-0000-4000-8000-000000000087', 'p-tourapi-1992090', '논산 명재고택', '드라이브 겸 나들이로 논산 명재고택 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "데이트", "사진맛집"]'::jsonb, 36.281929, 127.131070, '2026-08-27T17:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001592', '54500700-0000-4000-8000-000000000177', 'p-tourapi-1605990', '관훈동 민씨 가옥 (구 부마도위박영효가옥)', 'SNS에서 사진 보고 찾아간 관훈동 민씨 가옥 (구 부마도위박영효가옥), 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "가족여행", "주말나들이", "온마루"]'::jsonb, 37.558755, 126.993716, '2026-09-11T08:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001593', '54500700-0000-4000-8000-000000000078', 'p-tourapi-3438431', '사월 한옥', '해 질 무렵에 사월 한옥 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.593730, 127.000248, '2026-07-17T17:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001594', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3007507', '호수양조장', '드라이브 겸 나들이로 호수양조장 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "사진맛집"]'::jsonb, 37.872441, 127.731356, '2026-09-14T06:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001595', '54500700-0000-4000-8000-000000000059', 'p-tourapi-1883536', '산청율수원', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 35.380026, 128.010437, '2026-09-02T20:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001596', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2607706', '곡전재', '천천히 골목 걷다가 마주친 곡전재. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "데이트"]'::jsonb, 35.203901, 127.513866, '2026-08-16T07:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001597', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2736325', '전주 한옥마을 덕수궁', '근처 여행 코스로 전주 한옥마을 덕수궁 넣길 정말 잘했어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.816456, 127.155676, '2026-08-12T21:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001598', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2676000', '응정헌', '날씨가 너무 맑아서 응정헌 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "데이트", "온마루"]'::jsonb, 37.640362, 126.939333, '2026-09-03T14:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001599', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2932894', '주월재', '비 오는 날 운치 찾아 주월재 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 34.778974, 127.167189, '2026-08-15T02:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001600', '54500700-0000-4000-8000-000000000172', 'p-tourapi-231938', '서울 경모궁지', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "가족여행", "주말나들이"]'::jsonb, 37.580232, 126.998904, '2026-07-29T01:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001601', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2695730', '효자스테이', '오랜만에 여유 찾으러 효자스테이 다녀왔습니다. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 37.578962, 126.973518, '2026-09-13T05:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001602', '54500700-0000-4000-8000-000000000118', 'p-tourapi-1883996', '취옹예술관', '드라이브 겸 나들이로 취옹예술관 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "주말나들이", "데이트"]'::jsonb, 37.752493, 127.359858, '2026-08-17T00:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001603', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2531372', '소설재', '조용히 사색하고 싶어서 찾은 소설재. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "혼자여행", "고즈넉", "온마루"]'::jsonb, 35.833956, 129.214574, '2026-08-24T11:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001604', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2708325', '봉황재 한옥 게스트하우스', '오랜만에 여유 찾으러 봉황재 한옥 게스트하우스 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["산책로", "사색", "풍경맛집"]'::jsonb, 36.450822, 127.120381, '2026-08-24T05:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001605', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2770621', '향사례 대구시민단', '오랜만에 여유 찾으러 향사례 대구시민단 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["고즈넉", "사색", "풍경맛집", "온마루"]'::jsonb, 35.897991, 128.601164, '2026-07-17T19:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001606', '54500700-0000-4000-8000-000000000122', 'p-tourapi-3428156', '국가유산 방문 캠페인 인천공항 홍보관', '천천히 골목 걷다가 마주친 국가유산 방문 캠페인 인천공항 홍보관. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "사색", "고즈넉"]'::jsonb, 37.447853, 126.452423, '2026-08-02T16:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001607', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3447048', '사우당 종택', '드라이브 겸 나들이로 사우당 종택 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "힐링", "사색", "온마루"]'::jsonb, 35.828282, 128.214454, '2026-09-05T11:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001608', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2594831', '양참사댁(양동호 가옥 / 한옥152)', '근처 여행 코스로 양참사댁(양동호 가옥 / 한옥152) 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["데이트", "가족여행", "온마루"]'::jsonb, 34.984267, 126.911306, '2026-07-22T22:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001609', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3438450', '평안채', '드라이브 겸 나들이로 평안채 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["사진맛집", "인생샷", "온마루"]'::jsonb, 37.640805, 126.938953, '2026-08-27T06:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001610', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2569552', '셔블', '비 오는 날 운치 찾아 셔블 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["사진맛집", "인생샷", "방문팁", "온마루"]'::jsonb, 35.837049, 129.211214, '2026-07-22T00:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001611', '54500700-0000-4000-8000-000000000191', 'p-tourapi-1971911', '채원당', '조용히 사색하고 싶어서 찾은 채원당. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "산책로", "혼자여행"]'::jsonb, 35.275896, 127.307081, '2026-09-09T20:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001612', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2574250', '라온한옥꿀잠', '오랜만에 여유 찾으러 라온한옥꿀잠 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "힐링", "고즈넉", "온마루"]'::jsonb, 35.815971, 127.154168, '2026-07-17T21:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001613', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2358186', '쌍산재', '날씨가 너무 맑아서 쌍산재 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 35.215753, 127.498249, '2026-08-17T05:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001614', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3102203', '함라한옥체험단지', '함라한옥체험단지 다녀왔어요! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "사진맛집", "방문팁"]'::jsonb, 36.063014, 126.909649, '2026-07-19T18:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001615', '54500700-0000-4000-8000-000000000201', 'p-tourapi-2605443', '사나래한옥', '조용히 사색하고 싶어서 찾은 사나래한옥. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 34.837263, 126.902740, '2026-08-28T12:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001616', '54500700-0000-4000-8000-000000000133', 'p-tourapi-3438583', '여유', '드라이브 겸 나들이로 여유 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "힐링", "산책로"]'::jsonb, 35.812498, 127.158794, '2026-08-07T06:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001617', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2777057', '이두형가옥', '예전부터 가보고 싶었던 이두형가옥 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["사진맛집", "인생샷", "온마루"]'::jsonb, 38.087918, 128.568338, '2026-08-25T02:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001618', '54500700-0000-4000-8000-000000000058', 'p-tourapi-3438622', '스테이 나스러움', '비 오는 날 운치 찾아 스테이 나스러움 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁", "데이트"]'::jsonb, 36.563551, 128.714014, '2026-08-23T14:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001619', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2939003', '영월애살으리랏다', 'SNS에서 사진 보고 찾아간 영월애살으리랏다, 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "사색"]'::jsonb, 37.243793, 128.356111, '2026-09-02T13:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001620', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2782981', '존재고택', '해 질 무렵에 존재고택 방문했는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷", "사진맛집", "온마루"]'::jsonb, 34.549618, 126.949672, '2026-08-28T00:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001621', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2995167', '달달구리(주식회사달달구리)', '천천히 골목 걷다가 마주친 달달구리(주식회사달달구리). 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.938360, 127.167077, '2026-09-11T23:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001622', '54500700-0000-4000-8000-000000000122', 'p-tourapi-1882248', '인우하우스', '천천히 골목 걷다가 마주친 인우하우스. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["가족여행", "방문팁", "데이트", "온마루"]'::jsonb, 37.583027, 126.986754, '2026-07-26T18:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001623', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3532989', '예선재', 'SNS에서 사진 보고 찾아간 예선재, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["인생샷", "데이트", "방문팁", "온마루"]'::jsonb, 36.961989, 127.938060, '2026-07-22T12:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001624', '54500700-0000-4000-8000-000000000205', 'p-tourapi-3351556', '서천문화예술창작공간', '드라이브 겸 나들이로 서천문화예술창작공간 선택했는데 대만족! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 36.008620, 126.696089, '2026-09-03T00:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001625', '54500700-0000-4000-8000-000000000103', 'p-tourapi-3532595', '오브헤리티지', '근처 여행 코스로 오브헤리티지 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 34.546343, 127.136842, '2026-08-11T00:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001626', '54500700-0000-4000-8000-000000000074', 'p-tourapi-2570109', '망와고택', '천천히 골목 걷다가 마주친 망와고택. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 36.982481, 128.738775, '2026-08-24T11:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001627', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2668426', '학림재', '드라이브 겸 나들이로 학림재 선택했는데 대만족! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 36.551081, 127.190103, '2026-08-15T01:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001628', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2633890', '통영어드벤처타워', '예전부터 가보고 싶었던 통영어드벤처타워 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "데이트", "가족여행"]'::jsonb, 34.824942, 128.422127, '2026-08-29T19:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001629', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2409490', '만회고택', '날씨가 너무 맑아서 만회고택 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 36.897078, 128.715190, '2026-08-18T14:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001630', '54500700-0000-4000-8000-000000000186', 'p-tourapi-3532618', '산성동그곳', '드라이브 겸 나들이로 산성동그곳 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["가족여행", "주말나들이"]'::jsonb, 36.458744, 127.126324, '2026-07-27T21:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001631', '54500700-0000-4000-8000-000000000136', 'p-tourapi-128591', '창녕 진양하씨 고택', '날씨가 너무 맑아서 창녕 진양하씨 고택 한 바퀴 돌고 왔네요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 35.540239, 128.495837, '2026-08-04T08:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001632', '54500700-0000-4000-8000-000000000137', 'p-tourapi-1594374', '전주전통한지원', '비 오는 날 운치 찾아 전주전통한지원 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "사색", "힐링", "온마루"]'::jsonb, 35.816040, 127.153564, '2026-08-23T20:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001633', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2668091', '구림전통한옥민박', '평일 연차 쓰고 혼자 구림전통한옥민박 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 34.763702, 126.621721, '2026-07-18T09:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001634', '54500700-0000-4000-8000-000000000138', 'p-tourapi-3533114', '스테이여유담', '기대 이상으로 너무 좋았던 스테이여유담! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "산책로", "혼자여행", "온마루"]'::jsonb, 35.051588, 126.864419, '2026-08-31T00:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001635', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2699607', '모꼬지', '오랜만에 여유 찾으러 모꼬지 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "고즈넉", "사색"]'::jsonb, 35.811632, 127.156119, '2026-08-06T22:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001636', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2588908', '모항갯벌체험장', '날씨가 너무 맑아서 모항갯벌체험장 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 35.587554, 126.514036, '2026-07-23T06:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001637', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2932435', '3S', '근처 여행 코스로 3S 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 34.919094, 126.396559, '2026-07-19T10:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001638', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2572817', '옥산정사 독락당', '기대 이상으로 너무 좋았던 옥산정사 독락당! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["주말나들이", "사진맛집"]'::jsonb, 36.016934, 129.160052, '2026-08-29T21:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001639', '54500700-0000-4000-8000-000000000134', 'p-tourapi-1626784', '영동규당고택', '근처 여행 코스로 영동규당고택 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 36.180700, 127.776628, '2026-08-15T00:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001640', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2696383', '한옥 201(Hanok 201)', '드라이브 겸 나들이로 한옥 201(Hanok 201) 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행", "풍경맛집"]'::jsonb, 37.580620, 126.985793, '2026-09-07T19:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001641', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2572817', '옥산정사 독락당', '부모님 모시고 옥산정사 독락당 산책 겸 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 36.016944, 129.160058, '2026-09-14T04:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001642', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2820794', '별내리마을', '날씨가 너무 맑아서 별내리마을 한 바퀴 돌고 왔네요. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 35.454895, 126.843167, '2026-08-18T09:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001643', '54500700-0000-4000-8000-000000000127', 'p-tourapi-1799268', '회원식당', '부모님 모시고 회원식당 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.078061, 127.768912, '2026-08-19T01:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001644', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2570611', '잊음', '잊음 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 34.846500, 128.418896, '2026-08-21T07:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001645', '54500700-0000-4000-8000-000000000067', 'p-tourapi-3101965', '스테이서문', '드라이브 겸 나들이로 스테이서문 선택했는데 대만족! 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["주말나들이", "사진맛집"]'::jsonb, 35.033792, 126.712120, '2026-08-10T16:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001646', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2606387', '예천군체육회활체험센터', '주말에 친구들이랑 예천군체육회활체험센터 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "방문팁"]'::jsonb, 36.635027, 128.468394, '2026-07-23T07:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001647', '54500700-0000-4000-8000-000000000108', 'p-tourapi-127371', '수내동가옥(이택구가옥)', '조용히 사색하고 싶어서 찾은 수내동가옥(이택구가옥). 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "고즈넉", "사색"]'::jsonb, 37.380351, 127.120723, '2026-07-20T18:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001648', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2995168', '유한회사복합문화공간 서리울', '조용히 사색하고 싶어서 찾은 유한회사복합문화공간 서리울. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "풍경맛집", "산책로", "온마루"]'::jsonb, 36.015235, 127.145411, '2026-08-03T21:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001649', '54500700-0000-4000-8000-000000000095', 'p-tourapi-250369', '퇴계종택', '부모님 모시고 퇴계종택 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.737012, 128.848700, '2026-09-10T22:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001650', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2623573', '한미장', '주말에 친구들이랑 한미장 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 37.671238, 127.007414, '2026-07-22T17:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001651', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438470', '한옥 카키', '천천히 골목 걷다가 마주친 한옥 카키. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["가족여행", "주말나들이"]'::jsonb, 37.642350, 126.939006, '2026-07-22T21:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001652', '54500700-0000-4000-8000-000000000145', 'p-tourapi-3532717', '스테이 안김A', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "데이트", "온마루"]'::jsonb, 35.835615, 129.213195, '2026-08-02T02:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001653', '54500700-0000-4000-8000-000000000146', 'p-tourapi-3438736', '전주한옥마을 독채덕수궁', '부모님 모시고 전주한옥마을 독채덕수궁 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 35.817063, 127.151666, '2026-08-28T17:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001654', '54500700-0000-4000-8000-000000000169', 'p-tourapi-1677831', '괴산 수월정', '오랜만에 여유 찾으러 괴산 수월정 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "사색"]'::jsonb, 36.747323, 127.840743, '2026-09-05T19:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001655', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2717494', '쌍류포도정원협동조합', '천천히 골목 걷다가 마주친 쌍류포도정원협동조합. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 36.603299, 127.216319, '2026-08-02T17:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001656', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3101961', '자미재', '조용히 사색하고 싶어서 찾은 자미재. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "혼자여행", "산책로", "온마루"]'::jsonb, 34.911575, 126.648448, '2026-07-24T00:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001657', '54500700-0000-4000-8000-000000000158', 'p-tourapi-1437668', '순창장류체험관', '부모님 모시고 순창장류체험관 산책 겸 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 35.365604, 127.108009, '2026-07-26T19:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001658', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2696528', '토박이숙박', '드라이브 겸 나들이로 토박이숙박 선택했는데 대만족! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 35.813486, 127.152099, '2026-08-17T13:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001659', '54500700-0000-4000-8000-000000000071', 'p-tourapi-3438573', '자단', '예전부터 가보고 싶었던 자단 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 35.823862, 127.152870, '2026-08-09T21:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001660', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2509933', '울산 큰애기집', '오랜만에 여유 찾으러 울산 큰애기집 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 35.556416, 129.321870, '2026-08-29T15:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001661', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2050339', '장보고한옥펜션', '장보고한옥펜션 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집", "산책로", "온마루"]'::jsonb, 37.762581, 126.446733, '2026-08-03T02:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001662', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2869033', '광릉한옥점', 'SNS에서 사진 보고 찾아간 광릉한옥점, 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "사색", "고즈넉"]'::jsonb, 37.743455, 127.199263, '2026-07-27T20:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001663', '54500700-0000-4000-8000-000000000131', 'p-tourapi-3438166', '뉠스테이', '기대 이상으로 너무 좋았던 뉠스테이! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 37.579620, 126.967814, '2026-09-05T00:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001664', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2660381', '매월당', '날씨가 너무 맑아서 매월당 한 바퀴 돌고 왔네요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 35.349114, 127.272981, '2026-08-30T10:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001665', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2600301', '김진호가옥', '해 질 무렵에 김진호가옥 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["가족여행", "인생샷", "방문팁"]'::jsonb, 36.734022, 128.620372, '2026-08-22T09:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001666', '54500700-0000-4000-8000-000000000144', 'p-tourapi-1971880', '좋은날', '기대 이상으로 너무 좋았던 좋은날! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "방문팁", "온마루"]'::jsonb, 35.817202, 127.149179, '2026-09-15T04:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001667', '54500700-0000-4000-8000-000000000131', 'p-tourapi-1201060', '이천보고가', '이천보고가 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "가족여행", "방문팁", "온마루"]'::jsonb, 37.798787, 127.348207, '2026-08-31T19:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001668', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2717291', '바우파머스몰(대관령마켓)', '비 오는 날 운치 찾아 바우파머스몰(대관령마켓) 다녀왔어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 37.672822, 128.706349, '2026-09-02T11:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001669', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3009051', '도깨비 양조장', '비 오는 날 운치 찾아 도깨비 양조장 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "데이트", "온마루"]'::jsonb, 37.026124, 128.384821, '2026-07-27T18:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001670', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2513410', '삼척해상케이블카', '해 질 무렵에 삼척해상케이블카 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "가족여행", "방문팁"]'::jsonb, 37.289281, 129.308837, '2026-09-05T09:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001671', '54500700-0000-4000-8000-000000000144', 'p-tourapi-2814166', '강현재', '드라이브 겸 나들이로 강현재 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "사진맛집", "데이트", "온마루"]'::jsonb, 34.949522, 127.204482, '2026-08-25T13:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001672', '54500700-0000-4000-8000-000000000134', 'p-tourapi-3532717', '스테이 안김A', '평일 연차 쓰고 혼자 스테이 안김A 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "힐링", "사색"]'::jsonb, 35.835327, 129.212950, '2026-08-24T10:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001673', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2708322', '이화고택', '부모님 모시고 이화고택 산책 겸 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "사색", "혼자여행", "온마루"]'::jsonb, 35.816290, 127.154066, '2026-08-27T19:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001674', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2996818', '반줄', '반줄 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 35.945559, 127.102071, '2026-08-04T21:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001675', '54500700-0000-4000-8000-000000000065', 'p-tourapi-4065913', '청원루', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링"]'::jsonb, 36.579330, 128.548649, '2026-08-16T08:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001676', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2995169', '농업회사법인 주식회사 공동체공간 수작', '평일 연차 쓰고 혼자 농업회사법인 주식회사 공동체공간 수작 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "사색", "힐링"]'::jsonb, 35.942135, 127.262788, '2026-07-31T07:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001677', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2575839', '사랑나무 한옥펜션', '부모님 모시고 사랑나무 한옥펜션 산책 겸 다녀왔습니다. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "가족여행", "주말나들이"]'::jsonb, 35.811426, 127.152402, '2026-08-15T11:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001678', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2621370', '태양아래월출산', '조용히 사색하고 싶어서 찾은 태양아래월출산. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 34.739591, 126.718146, '2026-08-07T20:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001679', '54500700-0000-4000-8000-000000000166', 'p-tourapi-3426935', '구리문화재단', '드라이브 겸 나들이로 구리문화재단 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.595627, 127.130077, '2026-08-11T19:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001680', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2821865', '향온', '비 오는 날 운치 찾아 향온 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 36.403971, 126.846429, '2026-08-19T17:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001681', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2000946', '치암고택', '조용히 사색하고 싶어서 찾은 치암고택. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집", "혼자여행"]'::jsonb, 36.582993, 128.736381, '2026-08-18T09:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001682', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2610549', '예원당(한옥체험 예원당)', '드라이브 겸 나들이로 예원당(한옥체험 예원당) 선택했는데 대만족! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.817392, 127.152655, '2026-09-12T09:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001683', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3533161', '앙니드 공이안', '평일 연차 쓰고 혼자 앙니드 공이안 다녀옴. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.581609, 126.981548, '2026-08-18T12:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001684', '54500700-0000-4000-8000-000000000204', 'p-tourapi-3531662', '최선평 가옥', '오랜만에 여유 찾으러 최선평 가옥 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색", "힐링"]'::jsonb, 37.878705, 128.795902, '2026-07-29T09:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001685', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2996004', '달창재(달창사랑 협동조합)', '예전부터 가보고 싶었던 달창재(달창사랑 협동조합) 드디어 방문! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "주말나들이", "사진맛집"]'::jsonb, 35.634889, 128.487107, '2026-08-10T07:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001686', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2855009', '한옥 생고기', '해 질 무렵에 한옥 생고기 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.949005, 127.189807, '2026-07-21T15:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001687', '54500700-0000-4000-8000-000000000082', 'p-tourapi-4072012', '호텔호자', '천천히 골목 걷다가 마주친 호텔호자. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "주말나들이", "인생샷", "온마루"]'::jsonb, 34.794820, 126.377433, '2026-07-27T03:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001688', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3438435', '사임당 귀한그대', '사임당 귀한그대 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.641461, 126.940410, '2026-08-03T02:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001689', '54500700-0000-4000-8000-000000000203', 'p-tourapi-1372956', '이상화 고택', '비 오는 날 운치 찾아 이상화 고택 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.867121, 128.588291, '2026-08-16T05:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001690', '54500700-0000-4000-8000-000000000087', 'p-tourapi-1055245', '서천 이하복 고택', '비 오는 날 운치 찾아 서천 이하복 고택 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 36.081186, 126.759524, '2026-08-12T10:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001691', '54500700-0000-4000-8000-000000000128', 'p-tourapi-128825', '독도전망대 케이블카', '주말에 친구들이랑 독도전망대 케이블카 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 37.482739, 130.900268, '2026-07-17T15:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001692', '54500700-0000-4000-8000-000000000153', 'p-tourapi-1437090', '괴산 송병일 고택', '조용히 사색하고 싶어서 찾은 괴산 송병일 고택. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 36.661486, 127.738347, '2026-08-08T02:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001693', '54500700-0000-4000-8000-000000000071', 'p-tourapi-1938123', '광천토굴새우젓단지', '광천토굴새우젓단지 다녀왔어요! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["사진맛집", "가족여행", "주말나들이"]'::jsonb, 36.485129, 126.615747, '2026-08-31T12:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001694', '54500700-0000-4000-8000-000000000152', 'p-tourapi-3438215', '무월관', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 37.577335, 126.983677, '2026-08-20T17:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001695', '54500700-0000-4000-8000-000000000186', 'p-tourapi-1972014', '삼락헌', '예전부터 가보고 싶었던 삼락헌 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉", "사색"]'::jsonb, 35.815674, 127.152633, '2026-08-28T09:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001696', '54500700-0000-4000-8000-000000000121', 'p-tourapi-3438736', '전주한옥마을 독채덕수궁', '평일 연차 쓰고 혼자 전주한옥마을 독채덕수궁 다녀옴. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 35.816606, 127.152037, '2026-08-17T04:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001697', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2544573', '광화문한옥집', '해 질 무렵에 광화문한옥집 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "데이트"]'::jsonb, 37.572772, 126.974268, '2026-09-15T06:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001698', '54500700-0000-4000-8000-000000000090', 'p-tourapi-1812994', '조랑말체험공원', '부모님 모시고 조랑말체험공원 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "고즈넉", "힐링"]'::jsonb, 33.383432, 126.735702, '2026-07-27T07:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001699', '54500700-0000-4000-8000-000000000067', 'p-tourapi-231892', '안동 의성김씨 종택', '기대 이상으로 너무 좋았던 안동 의성김씨 종택! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 36.535868, 128.856004, '2026-08-12T06:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001700', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2706608', '경주오릉한옥', '부모님 모시고 경주오릉한옥 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["주말나들이", "데이트", "인생샷"]'::jsonb, 35.826190, 129.207559, '2026-09-08T00:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001701', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2048324', '사랑가득', '부모님 모시고 사랑가득 산책 겸 다녀왔습니다. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["방문팁", "사진맛집", "인생샷", "온마루"]'::jsonb, 35.812724, 127.157785, '2026-06-20T20:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001702', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2603918', '(사)영남선비문화수련원(구암서원)', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "인생샷", "방문팁", "온마루"]'::jsonb, 35.901624, 128.596915, '2026-06-10T23:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001703', '54500700-0000-4000-8000-000000000115', 'p-tourapi-129210', '무안 유교리 고택', '무안 유교리 고택 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 34.847336, 126.438469, '2026-06-23T21:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001704', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3354226', '농업회사법인주식회사 월출산꽃따리농장', '해 질 무렵에 농업회사법인주식회사 월출산꽃따리농장 방문했는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["주말나들이", "사진맛집"]'::jsonb, 34.720698, 126.576733, '2026-06-02T00:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001705', '54500700-0000-4000-8000-000000000127', 'p-tourapi-231938', '서울 경모궁지', '서울 경모궁지 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "주말나들이", "인생샷", "온마루"]'::jsonb, 37.580619, 126.999149, '2026-05-31T06:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001706', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3533114', '스테이여유담', '오랜만에 여유 찾으러 스테이여유담 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "사색"]'::jsonb, 35.051127, 126.863978, '2026-05-19T14:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001707', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2528155', '남원예촌', '조용히 사색하고 싶어서 찾은 남원예촌. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 35.404419, 127.379509, '2026-05-15T04:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001708', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3422587', '더맑음', '날씨가 너무 맑아서 더맑음 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 35.540587, 129.338947, '2026-05-11T01:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001709', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2820370', '버들국수 (농업법인 주식회사 유화 ㈜)', '근처 여행 코스로 버들국수 (농업법인 주식회사 유화 ㈜) 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.576328, 128.439448, '2026-07-12T19:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001710', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3432261', '인천업사이클에코센터', '근처 여행 코스로 인천업사이클에코센터 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 37.443146, 126.655337, '2026-05-01T04:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001711', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2599272', '모지고택', '드라이브 겸 나들이로 모지고택 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 36.540826, 128.518338, '2026-07-12T18:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001712', '54500700-0000-4000-8000-000000000108', 'p-tourapi-1089992', '대전교통문화연수원', '조용히 사색하고 싶어서 찾은 대전교통문화연수원. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 36.377199, 127.386780, '2026-06-24T11:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001713', '54500700-0000-4000-8000-000000000127', 'p-tourapi-1882538', '인심좋은웅기댁', '기대 이상으로 너무 좋았던 인심좋은웅기댁! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 35.667561, 128.229306, '2026-06-08T07:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001714', '54500700-0000-4000-8000-000000000113', 'p-tourapi-126391', '고창신재효고택', '오랜만에 여유 찾으러 고창신재효고택 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "고즈넉", "혼자여행", "온마루"]'::jsonb, 35.432111, 126.703505, '2026-06-04T09:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001715', '54500700-0000-4000-8000-000000000077', 'p-tourapi-3454469', '아동청소년친화공간 꿈이랑', '아동청소년친화공간 꿈이랑 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["인생샷", "데이트", "사진맛집", "온마루"]'::jsonb, 38.199466, 128.580524, '2026-06-24T01:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001716', '54500700-0000-4000-8000-000000000113', 'p-tourapi-128994', '구례 운조루 고택', '근처 여행 코스로 구례 운조루 고택 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색", "고즈넉"]'::jsonb, 35.206259, 127.515004, '2026-04-22T10:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001717', '54500700-0000-4000-8000-000000000147', 'p-tourapi-129539', '동천석실', 'SNS에서 사진 보고 찾아간 동천석실, 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 34.153591, 126.541414, '2026-07-06T08:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001718', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2594865', '성암재', '기대 이상으로 너무 좋았던 성암재! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.940151, 128.913908, '2026-07-10T14:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001719', '54500700-0000-4000-8000-000000000122', 'p-tourapi-1908555', '지리산한옥마을', '지리산한옥마을 다녀왔어요! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "사진맛집"]'::jsonb, 35.418464, 127.626041, '2026-05-16T05:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001720', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3532968', '황남별채', '주말에 친구들이랑 황남별채 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 35.835099, 129.209118, '2026-04-28T09:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001721', '54500700-0000-4000-8000-000000000114', 'p-tourapi-231931', '논산명재고택', '해 질 무렵에 논산명재고택 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 36.281835, 127.131572, '2026-05-04T22:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001722', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2671267', '가락청', '가락청 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷", "사진맛집", "온마루"]'::jsonb, 35.817346, 127.153712, '2026-06-05T13:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001723', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2507433', '삼해소주', '삼해소주 다녀왔어요! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "인생샷", "사진맛집"]'::jsonb, 37.563009, 126.913285, '2026-07-16T22:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001724', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3510987', '주식회사감천아울', '해 질 무렵에 주식회사감천아울 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 35.093381, 129.008649, '2026-04-28T09:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001725', '54500700-0000-4000-8000-000000000107', 'p-tourapi-4074856', '연림스테이', '천천히 골목 걷다가 마주친 연림스테이. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "고즈넉", "온마루"]'::jsonb, 35.972266, 128.698822, '2026-05-08T15:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001726', '54500700-0000-4000-8000-000000000077', 'p-tourapi-1972381', '서로', '기대 이상으로 너무 좋았던 서로! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 35.815803, 127.153781, '2026-05-01T20:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001727', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2714217', '만천하 슬라이드', '부모님 모시고 만천하 슬라이드 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 36.977365, 128.336843, '2026-06-07T12:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001728', '54500700-0000-4000-8000-000000000122', 'p-tourapi-3030491', '선성현문화단지 한옥체험관', '드라이브 겸 나들이로 선성현문화단지 한옥체험관 선택했는데 대만족! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "풍경맛집"]'::jsonb, 36.698223, 128.814871, '2026-04-23T14:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001729', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2647939', '고스락', '기대 이상으로 너무 좋았던 고스락! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "주말나들이", "방문팁"]'::jsonb, 36.046154, 126.960892, '2026-05-23T00:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001730', '54500700-0000-4000-8000-000000000196', 'p-tourapi-1395270', '최순우 옛집', '해 질 무렵에 최순우 옛집 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.592849, 126.999971, '2026-04-19T22:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001731', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3025473', '영광 매간당 고택', '천천히 골목 걷다가 마주친 영광 매간당 고택. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "사진맛집", "가족여행"]'::jsonb, 35.241091, 126.474107, '2026-07-08T23:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001732', '54500700-0000-4000-8000-000000000175', 'p-tourapi-3411229', '천지인 전통사상체험관', '비 오는 날 운치 찾아 천지인 전통사상체험관 다녀왔어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 36.730811, 128.614804, '2026-06-19T03:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001733', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2717604', '어슬티굿밤', '부모님 모시고 어슬티굿밤 산책 겸 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "주말나들이", "방문팁"]'::jsonb, 36.488150, 126.822583, '2026-07-08T18:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001734', '54500700-0000-4000-8000-000000000144', 'p-tourapi-2435103', '중앙탑의상실', '중앙탑의상실 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["데이트", "주말나들이", "온마루"]'::jsonb, 37.018408, 127.866164, '2026-07-10T06:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001735', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438599', '이사빛1968 한옥스테이', '비 오는 날 운치 찾아 이사빛1968 한옥스테이 다녀왔어요. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 36.564895, 128.737415, '2026-04-28T01:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001736', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3072197', '오롯이, 한옥', 'SNS에서 사진 보고 찾아간 오롯이, 한옥, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링", "풍경맛집", "온마루"]'::jsonb, 37.580072, 126.968113, '2026-07-12T05:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001737', '54500700-0000-4000-8000-000000000168', 'p-tourapi-127520', '서귀포 김정희 유배지', '비 오는 날 운치 찾아 서귀포 김정희 유배지 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 33.249926, 126.278053, '2026-06-17T14:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001738', '54500700-0000-4000-8000-000000000108', 'p-tourapi-1610542', '달성 조길방 고택', '오랜만에 여유 찾으러 달성 조길방 고택 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "산책로"]'::jsonb, 35.755932, 128.582000, '2026-07-06T23:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001739', '54500700-0000-4000-8000-000000000137', 'p-tourapi-753850', '키즈오토파크', '근처 여행 코스로 키즈오토파크 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "혼자여행"]'::jsonb, 37.549120, 127.076513, '2026-05-29T02:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001740', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2725128', '오대산힐링빌리지', '해 질 무렵에 오대산힐링빌리지 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행", "사색"]'::jsonb, 37.609906, 128.517171, '2026-06-09T23:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001741', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2621722', '꽃잠', '날씨가 너무 맑아서 꽃잠 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "사색"]'::jsonb, 35.818748, 127.152964, '2026-05-17T05:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001742', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2996127', '기범이네국수', '오랜만에 여유 찾으러 기범이네국수 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "고즈넉", "온마루"]'::jsonb, 36.104519, 127.488002, '2026-06-03T18:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001743', '54500700-0000-4000-8000-000000000147', 'p-tourapi-231940', '안동 소호헌', 'SNS에서 사진 보고 찾아간 안동 소호헌, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["가족여행", "사진맛집", "주말나들이", "온마루"]'::jsonb, 36.463586, 128.663417, '2026-04-29T22:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001744', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2570282', '서문한옥게스트하우스', '천천히 골목 걷다가 마주친 서문한옥게스트하우스. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.866402, 128.579568, '2026-05-03T05:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001745', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2713848', '수상한마법학교', '평일 연차 쓰고 혼자 수상한마법학교 다녀옴. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 37.730566, 128.879226, '2026-07-15T02:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001746', '54500700-0000-4000-8000-000000000067', 'p-tourapi-3080477', '수원전통문화관', '평일 연차 쓰고 혼자 수원전통문화관 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.287455, 127.014566, '2026-06-24T06:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001747', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2788137', '화사별서(조씨고가)', '기대 이상으로 너무 좋았던 화사별서(조씨고가)! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "방문팁", "인생샷", "온마루"]'::jsonb, 35.171095, 127.700844, '2026-04-19T08:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001748', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3337761', '마마스홈퀴진', '평일 연차 쓰고 혼자 마마스홈퀴진 다녀옴. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "혼자여행"]'::jsonb, 35.561496, 129.116329, '2026-06-17T10:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001749', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2605927', '초원사진관', '기대 이상으로 너무 좋았던 초원사진관! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "가족여행", "사진맛집"]'::jsonb, 35.987894, 126.708098, '2026-06-14T11:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001750', '54500700-0000-4000-8000-000000000175', 'p-tourapi-1971917', '청공한옥', '드라이브 겸 나들이로 청공한옥 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.781882, 129.303026, '2026-06-04T07:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001751', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2603550', '무척산관광예술원', '예전부터 가보고 싶었던 무척산관광예술원 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "인생샷"]'::jsonb, 35.383834, 128.839566, '2026-05-02T12:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001752', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2696383', '한옥 201(Hanok 201)', '기대 이상으로 너무 좋았던 한옥 201(Hanok 201)! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 37.580423, 126.985425, '2026-05-02T18:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001753', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2701896', '평창지동봉가옥', '날씨가 너무 맑아서 평창지동봉가옥 한 바퀴 돌고 왔네요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "산책로", "고즈넉"]'::jsonb, 37.333610, 128.379335, '2026-07-17T08:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001754', '54500700-0000-4000-8000-000000000196', 'p-tourapi-3072219', '북촌빈관 by 락고재', 'SNS에서 사진 보고 찾아간 북촌빈관 by 락고재, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "가족여행", "인생샷"]'::jsonb, 37.582420, 126.984438, '2026-06-30T07:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001755', '54500700-0000-4000-8000-000000000087', 'p-tourapi-1626699', '아산 외암마을 참판댁', '조용히 사색하고 싶어서 찾은 아산 외암마을 참판댁. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "사색", "혼자여행", "온마루"]'::jsonb, 36.730131, 127.018573, '2026-04-22T23:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001756', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2717493', '삼버들협동조합', '기대 이상으로 너무 좋았던 삼버들협동조합! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "힐링", "고즈넉", "온마루"]'::jsonb, 36.527802, 127.370237, '2026-07-03T00:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001757', '54500700-0000-4000-8000-000000000074', 'p-tourapi-1871362', '문화공간 양사재', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "산책로", "사색"]'::jsonb, 35.813144, 127.153987, '2026-06-27T04:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001758', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2607481', '향운', '비 오는 날 운치 찾아 향운 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "고즈넉", "힐링", "온마루"]'::jsonb, 37.583100, 126.985692, '2026-06-09T10:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001759', '54500700-0000-4000-8000-000000000075', 'p-tourapi-843726', '한옥집김치찜', '드라이브 겸 나들이로 한옥집김치찜 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.869255, 128.593950, '2026-05-08T01:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001760', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3532750', '해우당', '비 오는 날 운치 찾아 해우당 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 37.355561, 127.065140, '2026-07-02T05:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001761', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2783068', '하이원리조트 알파인코스터', '기대 이상으로 너무 좋았던 하이원리조트 알파인코스터! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "사진맛집", "인생샷"]'::jsonb, 37.210508, 128.826911, '2026-07-07T23:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001762', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2575760', '연우당', '비 오는 날 운치 찾아 연우당 다녀왔어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 35.815708, 127.152772, '2026-05-29T18:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001763', '54500700-0000-4000-8000-000000000174', 'p-tourapi-1114959', '음성잿말고택 (김주태가옥)', '예전부터 가보고 싶었던 음성잿말고택 (김주태가옥) 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "가족여행", "주말나들이"]'::jsonb, 37.080868, 127.657847, '2026-05-19T00:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001764', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2717494', '쌍류포도정원협동조합', '천천히 골목 걷다가 마주친 쌍류포도정원협동조합. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "데이트", "인생샷"]'::jsonb, 36.603304, 127.216439, '2026-07-10T08:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001765', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2660381', '매월당', '매월당 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "산책로"]'::jsonb, 35.348960, 127.273086, '2026-05-19T17:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001766', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3033516', '논산한옥마을', '드라이브 겸 나들이로 논산한옥마을 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행", "풍경맛집"]'::jsonb, 36.211444, 127.181483, '2026-06-09T13:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001767', '54500700-0000-4000-8000-000000000058', 'p-tourapi-4071289', '함평 이재혁 가옥', '천천히 골목 걷다가 마주친 함평 이재혁 가옥. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.066716, 126.512139, '2026-06-21T04:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001768', '54500700-0000-4000-8000-000000000158', 'p-tourapi-126747', '남산골한옥마을', '마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 37.559687, 126.993074, '2026-05-17T19:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001769', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2615342', '비비정예술열차', '조용히 사색하고 싶어서 찾은 비비정예술열차. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.899160, 127.067811, '2026-06-17T06:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001770', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2820838', '평창캠프닉', '근처 여행 코스로 평창캠프닉 넣길 정말 잘했어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로"]'::jsonb, 37.578845, 128.331810, '2026-05-24T05:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001771', '54500700-0000-4000-8000-000000000138', 'p-tourapi-3452165', '경산청년지식놀이터', '천천히 골목 걷다가 마주친 경산청년지식놀이터. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행", "주말나들이", "온마루"]'::jsonb, 35.841623, 128.760077, '2026-05-23T12:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001772', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2681174', '고선재', '근처 여행 코스로 고선재 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["데이트", "인생샷", "온마루"]'::jsonb, 36.566209, 127.517921, '2026-06-25T09:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001773', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3438592', '한옥스테이 다가감', '천천히 골목 걷다가 마주친 한옥스테이 다가감. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "고즈넉"]'::jsonb, 35.835051, 129.213001, '2026-07-04T01:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001774', '54500700-0000-4000-8000-000000000195', 'p-tourapi-126387', '전주 풍패지관 (전주객사)', '부모님 모시고 전주 풍패지관 (전주객사) 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 35.818459, 127.145370, '2026-07-04T01:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001775', '54500700-0000-4000-8000-000000000101', 'p-tourapi-800528', '춘천 강언덕마을 [농촌전통테마]', '예전부터 가보고 싶었던 춘천 강언덕마을 [농촌전통테마] 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 37.678983, 127.613852, '2026-05-28T06:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001776', '54500700-0000-4000-8000-000000000195', 'p-tourapi-2531374', '교동살래', '평일 연차 쓰고 혼자 교동살래 다녀옴. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 35.811463, 127.153384, '2026-05-21T12:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001777', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2595672', '하회 양진당', '오랜만에 여유 찾으러 하회 양진당 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "힐링", "사색"]'::jsonb, 36.539236, 128.516340, '2026-05-29T20:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001778', '54500700-0000-4000-8000-000000000168', 'p-tourapi-1390215', '장흥 죽헌고택', '예전부터 가보고 싶었던 장흥 죽헌고택 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 34.548962, 126.949740, '2026-05-06T12:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001779', '54500700-0000-4000-8000-000000000122', 'p-tourapi-3532712', '스테이화요일', '주말에 친구들이랑 스테이화요일 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로", "힐링"]'::jsonb, 36.847908, 126.904612, '2026-06-19T10:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001780', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2623573', '한미장', '평일 연차 쓰고 혼자 한미장 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "사색", "고즈넉", "온마루"]'::jsonb, 37.671139, 127.007639, '2026-05-06T01:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001781', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2932921', '한울', '조용히 사색하고 싶어서 찾은 한울. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 37.237133, 127.265317, '2026-06-20T20:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001782', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2698680', '4.16희망목공소(4.16희망목공협동조합)', '천천히 골목 걷다가 마주친 4.16희망목공소(4.16희망목공협동조합). 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "데이트", "가족여행"]'::jsonb, 37.343569, 126.834723, '2026-07-15T09:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001783', '54500700-0000-4000-8000-000000000082', 'p-tourapi-3532478', '임당생활문화센터', '예전부터 가보고 싶었던 임당생활문화센터 드디어 방문! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "인생샷", "사진맛집", "온마루"]'::jsonb, 37.754777, 128.895086, '2026-05-08T19:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001784', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2717486', '엘오알오', '날씨가 너무 맑아서 엘오알오 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["가족여행", "사진맛집", "온마루"]'::jsonb, 36.733529, 128.108307, '2026-05-30T17:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001785', '54500700-0000-4000-8000-000000000071', 'p-tourapi-128560', '안동 임청각', '비 오는 날 운치 찾아 안동 임청각 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 36.565209, 128.745359, '2026-05-07T21:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001786', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2605809', '태화강동굴피아', '날씨가 너무 맑아서 태화강동굴피아 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 35.545269, 129.302163, '2026-05-10T14:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001787', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3533157', '미미몽몽', '근처 여행 코스로 미미몽몽 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 35.819128, 127.158248, '2026-06-04T19:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001788', '54500700-0000-4000-8000-000000000090', 'p-tourapi-3438578', '나루 한옥스테이 독채', '주말에 친구들이랑 나루 한옥스테이 독채 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "방문팁", "온마루"]'::jsonb, 35.811472, 127.154425, '2026-05-31T06:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001789', '54500700-0000-4000-8000-000000000102', 'p-tourapi-128694', '안동한지', '해 질 무렵에 안동한지 방문했는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["주말나들이", "사진맛집", "인생샷", "온마루"]'::jsonb, 36.580649, 128.555119, '2026-05-21T11:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001790', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3426935', '구리문화재단', '조용히 사색하고 싶어서 찾은 구리문화재단. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "사색", "힐링"]'::jsonb, 37.595464, 127.130027, '2026-05-12T17:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001791', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3101970', '불국사한옥동오당', '불국사한옥동오당 다녀왔어요! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 35.783126, 129.328061, '2026-06-26T16:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001792', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3572354', '포항전통문화체험관', '근처 여행 코스로 포항전통문화체험관 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.165096, 129.185283, '2026-06-02T14:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001793', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2583187', '전통문화체험장', '부모님 모시고 전통문화체험장 산책 겸 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 35.989134, 127.260989, '2026-05-03T00:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001794', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2572898', '고현당', 'SNS에서 사진 보고 찾아간 고현당, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 35.815204, 127.153387, '2026-06-14T17:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001795', '54500700-0000-4000-8000-000000000194', 'p-tourapi-1623828', '안동권씨유회당종가일원', '부모님 모시고 안동권씨유회당종가일원 산책 겸 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "사진맛집", "방문팁"]'::jsonb, 36.277983, 127.404462, '2026-05-29T20:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001796', '54500700-0000-4000-8000-000000000099', 'p-tourapi-1621155', '제주 성읍마을 고평오 고택', '기대 이상으로 너무 좋았던 제주 성읍마을 고평오 고택! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 33.385931, 126.802278, '2026-05-08T17:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001797', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2610985', '전주 한옥숙박 체험관', '드라이브 겸 나들이로 전주 한옥숙박 체험관 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 35.814724, 127.152244, '2026-06-05T16:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001798', '54500700-0000-4000-8000-000000000159', 'p-tourapi-1923400', '백두대간협곡열차(V-트레인)', '백두대간협곡열차(V-트레인) 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로", "풍경맛집", "온마루"]'::jsonb, 37.112997, 129.036853, '2026-06-19T17:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001799', '54500700-0000-4000-8000-000000000205', 'p-tourapi-1623646', '권희문가옥', '조용히 사색하고 싶어서 찾은 권희문가옥. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.587502, 127.385936, '2026-05-10T09:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001800', '54500700-0000-4000-8000-000000000159', 'p-tourapi-1883104', '연풍고택(문충고가)', '예전부터 가보고 싶었던 연풍고택(문충고가) 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "주말나들이", "가족여행"]'::jsonb, 35.668184, 128.229018, '2026-04-26T14:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001801', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2621722', '꽃잠', '해 질 무렵에 꽃잠 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.818877, 127.153073, '2026-04-30T16:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001802', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2657501', '한옥카페 갤러리 도솔', '주말에 친구들이랑 한옥카페 갤러리 도솔 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "주말나들이", "가족여행"]'::jsonb, 37.641789, 126.506123, '2026-06-24T12:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001803', '54500700-0000-4000-8000-000000000060', 'p-tourapi-3438182', '여느날', '비 오는 날 운치 찾아 여느날 다녀왔어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 37.576542, 126.969718, '2026-05-09T19:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001804', '54500700-0000-4000-8000-000000000174', 'p-tourapi-2638529', '포항 장기유배문화체험촌', '평일 연차 쓰고 혼자 포항 장기유배문화체험촌 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "풍경맛집", "혼자여행"]'::jsonb, 35.903928, 129.486185, '2026-05-11T10:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001805', '54500700-0000-4000-8000-000000000158', 'p-tourapi-3454381', '디즈니스토어 현대프리미엄아울렛 대전점', '조용히 사색하고 싶어서 찾은 디즈니스토어 현대프리미엄아울렛 대전점. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["고즈넉", "혼자여행", "산책로"]'::jsonb, 36.423414, 127.398171, '2026-05-28T05:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001806', '54500700-0000-4000-8000-000000000146', 'p-tourapi-3438041', '유선재', '유선재 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "사색"]'::jsonb, 37.490529, 127.709414, '2026-05-22T01:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001807', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2821565', '룰루낭만협동조합', '날씨가 너무 맑아서 룰루낭만협동조합 한 바퀴 돌고 왔네요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집", "사색", "온마루"]'::jsonb, 35.235618, 128.881462, '2026-07-06T01:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001808', '54500700-0000-4000-8000-000000000081', 'p-tourapi-1882210', '얼음골한옥펜션', '조용히 사색하고 싶어서 찾은 얼음골한옥펜션. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.597888, 128.953205, '2026-05-18T23:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001809', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2007983', '경북전통음식체험관 모심정', '기대 이상으로 너무 좋았던 경북전통음식체험관 모심정! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 36.661818, 128.119197, '2026-04-29T12:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001810', '54500700-0000-4000-8000-000000000073', 'p-tourapi-129688', '보은 우당고택', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "방문팁", "데이트"]'::jsonb, 36.468955, 127.790337, '2026-05-06T08:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001811', '54500700-0000-4000-8000-000000000099', 'p-tourapi-1883996', '취옹예술관', '비 오는 날 운치 찾아 취옹예술관 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "혼자여행", "힐링", "온마루"]'::jsonb, 37.752604, 127.360137, '2026-06-03T00:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001812', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2623572', '그 여자네 집', '해 질 무렵에 그 여자네 집 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "가족여행", "인생샷", "온마루"]'::jsonb, 35.812125, 127.155427, '2026-06-30T01:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001813', '54500700-0000-4000-8000-000000000175', 'p-tourapi-1055245', '서천 이하복 고택', '예전부터 가보고 싶었던 서천 이하복 고택 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 36.081114, 126.759217, '2026-07-16T19:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001814', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2574326', '개울한옥민박', '해 질 무렵에 개울한옥민박 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁", "사진맛집"]'::jsonb, 34.515850, 126.661614, '2026-07-12T19:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001815', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2717492', '비녀랑 한복이랑', '기대 이상으로 너무 좋았던 비녀랑 한복이랑! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "사진맛집", "가족여행", "온마루"]'::jsonb, 36.629629, 127.287326, '2026-05-13T22:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001816', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2705296', '물뫼힐링팜', '조용히 사색하고 싶어서 찾은 물뫼힐링팜. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 33.464284, 126.396789, '2026-06-30T16:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001817', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2698914', '한옥펜션 나비의 꿈', '평일 연차 쓰고 혼자 한옥펜션 나비의 꿈 다녀옴. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 35.608347, 126.585483, '2026-04-30T20:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001818', '54500700-0000-4000-8000-000000000177', 'p-tourapi-3532478', '임당생활문화센터', '예전부터 가보고 싶었던 임당생활문화센터 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 37.754781, 128.895202, '2026-05-07T02:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001819', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3572354', '포항전통문화체험관', '기대 이상으로 너무 좋았던 포항전통문화체험관! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "데이트", "인생샷", "온마루"]'::jsonb, 36.165126, 129.185433, '2026-05-27T23:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001820', '54500700-0000-4000-8000-000000000159', 'p-tourapi-1606001', '해풍부원군윤택영댁재실', '부모님 모시고 해풍부원군윤택영댁재실 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "방문팁", "가족여행"]'::jsonb, 37.558135, 126.994388, '2026-04-30T13:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001821', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3438358', '정연재', '드라이브 겸 나들이로 정연재 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.583540, 126.980521, '2026-05-05T01:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001822', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2753977', '울진과학체험관', '전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["사진맛집", "가족여행", "인생샷", "온마루"]'::jsonb, 36.996579, 129.408011, '2026-07-01T16:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001823', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3438233', '월운', '평일 연차 쓰고 혼자 월운 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행", "산책로", "온마루"]'::jsonb, 37.573821, 126.991510, '2026-07-10T12:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001824', '54500700-0000-4000-8000-000000000059', 'p-tourapi-1622772', '합천 사의정', '날씨가 너무 맑아서 합천 사의정 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 35.544259, 128.000510, '2026-05-05T20:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001825', '54500700-0000-4000-8000-000000000095', 'p-tourapi-129057', '청송 평산신씨 판사공파 종택과 분가 고택', '기대 이상으로 너무 좋았던 청송 평산신씨 판사공파 종택과 분가 고택! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 36.458370, 129.023198, '2026-07-16T21:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001826', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2531409', '더 한옥', '조용히 사색하고 싶어서 찾은 더 한옥. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 35.813697, 127.152310, '2026-04-23T06:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001827', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2531497', '추우재', '추우재 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉", "풍경맛집"]'::jsonb, 35.668404, 128.227624, '2026-07-08T19:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001828', '54500700-0000-4000-8000-000000000056', 'p-tourapi-129688', '보은 우당고택', 'SNS에서 사진 보고 찾아간 보은 우당고택, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "주말나들이", "가족여행"]'::jsonb, 36.468959, 127.790075, '2026-06-16T12:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001829', '54500700-0000-4000-8000-000000000075', 'p-tourapi-1623828', '안동권씨유회당종가일원', '천천히 골목 걷다가 마주친 안동권씨유회당종가일원. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 36.277791, 127.404895, '2026-04-26T06:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001830', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2049307', '녹운재', '주말에 친구들이랑 녹운재 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 35.903108, 127.242845, '2026-07-17T08:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001831', '54500700-0000-4000-8000-000000000069', 'p-tourapi-3510444', '농업회사법인주식회사꿀벌인', '근처 여행 코스로 농업회사법인주식회사꿀벌인 넣길 정말 잘했어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 36.014215, 128.421623, '2026-05-09T13:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001832', '54500700-0000-4000-8000-000000000072', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '예전부터 가보고 싶었던 거창 갈계리 임씨고가 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "인생샷", "가족여행"]'::jsonb, 35.779994, 127.818297, '2026-05-11T03:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001833', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2792794', '밀양교동 손씨고가', '근처 여행 코스로 밀양교동 손씨고가 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 35.504732, 128.755324, '2026-07-06T12:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001834', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2891349', '미술관아래협동조합', '조용히 사색하고 싶어서 찾은 미술관아래협동조합. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집", "힐링", "온마루"]'::jsonb, 34.775034, 126.647211, '2026-07-12T22:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001835', '54500700-0000-4000-8000-000000000086', 'p-tourapi-1883086', '연경당', '천천히 골목 걷다가 마주친 연경당. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 35.015800, 127.586256, '2026-06-05T19:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001836', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2574307', '목양산방', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "가족여행", "온마루"]'::jsonb, 34.889493, 127.507322, '2026-05-31T08:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001837', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2820184', '감성공작소', '천천히 골목 걷다가 마주친 감성공작소. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "데이트", "방문팁"]'::jsonb, 37.442392, 129.162881, '2026-07-10T07:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001838', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2718998', '전북특별자치도 119안전체험관', '근처 여행 코스로 전북특별자치도 119안전체험관 넣길 정말 잘했어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 35.602087, 127.284166, '2026-06-02T06:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001839', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2717492', '비녀랑 한복이랑', '천천히 골목 걷다가 마주친 비녀랑 한복이랑. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 36.629709, 127.287375, '2026-06-12T22:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001840', '54500700-0000-4000-8000-000000000201', 'p-tourapi-3469419', '미지한옥', '바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["데이트", "인생샷", "주말나들이"]'::jsonb, 36.567976, 128.734557, '2026-06-18T01:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001841', '54500700-0000-4000-8000-000000000191', 'p-tourapi-3438412', '중림재', '오랜만에 여유 찾으러 중림재 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "혼자여행", "힐링", "온마루"]'::jsonb, 37.558036, 126.967919, '2026-07-11T06:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001842', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3108226', '사단법인 푸른차문화연구원', '근처 여행 코스로 사단법인 푸른차문화연구원 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.834906, 128.677001, '2026-06-25T07:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001843', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2717605', '청양의 봄, 청춘', '비 오는 날 운치 찾아 청양의 봄, 청춘 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁", "데이트"]'::jsonb, 36.450334, 126.800269, '2026-05-20T19:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001844', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3066467', '우리 놀이터 마루달', '오랜만에 여유 찾으러 우리 놀이터 마루달 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 35.816482, 127.152496, '2026-06-14T18:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001845', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2574415', '별자리', '날씨가 너무 맑아서 별자리 한 바퀴 돌고 왔네요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 35.816610, 127.151260, '2026-07-09T05:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001846', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2595847', '달의 정원', '근처 여행 코스로 달의 정원 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "인생샷", "사진맛집"]'::jsonb, 35.790225, 128.087352, '2026-05-06T12:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001847', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2594513', '단촌서원고택', '툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 36.929430, 128.335566, '2026-04-26T03:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001848', '54500700-0000-4000-8000-000000000090', 'p-tourapi-3438736', '전주한옥마을 독채덕수궁', '오랜만에 여유 찾으러 전주한옥마을 독채덕수궁 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 35.816543, 127.151678, '2026-06-04T07:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001849', '54500700-0000-4000-8000-000000000165', 'p-tourapi-127289', '괴산 홍범식 고가(벽초 홍명희 생가)', '기대 이상으로 너무 좋았던 괴산 홍범식 고가(벽초 홍명희 생가)! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.814004, 127.794391, '2026-05-05T20:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001850', '54500700-0000-4000-8000-000000000150', 'p-tourapi-3510944', '주식회사영리캐롤', '근처 여행 코스로 주식회사영리캐롤 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 36.007978, 128.359802, '2026-05-26T01:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001851', '54500700-0000-4000-8000-000000000141', 'p-tourapi-3438126', '스테이 어플로트', '오랜만에 여유 찾으러 스테이 어플로트 다녀왔습니다. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "혼자여행", "온마루"]'::jsonb, 37.578505, 126.972370, '2026-06-27T04:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001852', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2747760', '그라운드플래닛', '드라이브 겸 나들이로 그라운드플래닛 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "인생샷", "주말나들이", "온마루"]'::jsonb, 37.433921, 127.010920, '2026-06-03T13:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001853', '54500700-0000-4000-8000-000000000101', 'p-tourapi-1579747', '거창 동호리 이씨고가', '근처 여행 코스로 거창 동호리 이씨고가 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.799014, 127.927535, '2026-05-20T13:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001854', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2717494', '쌍류포도정원협동조합', '해 질 무렵에 쌍류포도정원협동조합 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "방문팁", "사진맛집"]'::jsonb, 36.603395, 127.216294, '2026-05-10T00:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001855', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2714563', '서편제 촬영지', '오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 34.172068, 126.862411, '2026-04-19T20:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001856', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2707233', '한옥人(한옥인)', '비 오는 날 운치 찾아 한옥人(한옥인) 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행", "주말나들이", "온마루"]'::jsonb, 35.834553, 129.211296, '2026-06-15T13:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001857', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2706568', '왕의지밀', '왕의지밀 다녀왔어요! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 35.799656, 127.178331, '2026-04-29T02:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001858', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2662467', '만천하 알파인코스터', '주말에 친구들이랑 만천하 알파인코스터 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 36.977614, 128.337256, '2026-07-15T16:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001859', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2608508', '취락당', '해 질 무렵에 취락당 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 35.818456, 127.152933, '2026-07-13T17:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001860', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2820395', '놀러와외갓집(우리동네협동조합)', '주말에 친구들이랑 놀러와외갓집(우리동네협동조합) 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색", "고즈넉"]'::jsonb, 35.387990, 128.478588, '2026-05-09T21:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001861', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2600248', '수춘제(김태길) 고택', '평일 연차 쓰고 혼자 수춘제(김태길) 고택 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "산책로", "힐링"]'::jsonb, 36.734902, 128.618999, '2026-06-17T03:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001862', '54500700-0000-4000-8000-000000000104', 'p-tourapi-3019714', '같이삽시도', '천천히 골목 걷다가 마주친 같이삽시도. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "방문팁", "온마루"]'::jsonb, 36.346475, 126.353426, '2026-04-30T21:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001863', '54500700-0000-4000-8000-000000000099', 'p-tourapi-3438494', '상상헌', '부모님 모시고 상상헌 산책 겸 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "고즈넉", "산책로", "온마루"]'::jsonb, 37.641567, 126.938691, '2026-06-29T02:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001864', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2707439', '스테이 데이 오프', '드라이브 겸 나들이로 스테이 데이 오프 선택했는데 대만족! 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "사진맛집", "온마루"]'::jsonb, 37.577127, 126.971232, '2026-04-25T02:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001865', '54500700-0000-4000-8000-000000000096', 'p-tourapi-3038851', '치헌', '치헌 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 36.534726, 128.860766, '2026-05-31T16:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001866', '54500700-0000-4000-8000-000000000070', 'p-tourapi-4013381', '장흥한옥수영장', '근처 여행 코스로 장흥한옥수영장 넣길 정말 잘했어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "데이트"]'::jsonb, 37.739455, 126.958085, '2026-04-28T20:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001867', '54500700-0000-4000-8000-000000000163', 'p-tourapi-795829', '청송 후송당 고택', '고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "가족여행"]'::jsonb, 36.289744, 129.009733, '2026-05-05T01:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001868', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3438571', '거북이 한옥', '조용히 사색하고 싶어서 찾은 거북이 한옥. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "사색"]'::jsonb, 36.329740, 126.543187, '2026-05-07T00:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001869', '54500700-0000-4000-8000-000000000158', 'p-tourapi-4079534', '한옥스테이 궁붙', '주말에 친구들이랑 한옥스테이 궁붙 들렀는데 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "방문팁", "온마루"]'::jsonb, 36.000862, 129.014598, '2026-07-16T03:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001870', '54500700-0000-4000-8000-000000000078', 'p-tourapi-4072014', '스테이 화녹', '기대 이상으로 너무 좋았던 스테이 화녹! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.801119, 129.196859, '2026-05-03T11:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001871', '54500700-0000-4000-8000-000000000063', 'p-tourapi-1583188', '조해영가옥', '근처 여행 코스로 조해영가옥 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "산책로"]'::jsonb, 36.060866, 126.910730, '2026-05-20T03:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001872', '54500700-0000-4000-8000-000000000115', 'p-tourapi-843726', '한옥집김치찜', '예전부터 가보고 싶었던 한옥집김치찜 드디어 방문! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "인생샷", "데이트", "온마루"]'::jsonb, 35.869350, 128.593945, '2026-05-15T05:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001873', '54500700-0000-4000-8000-000000000091', 'p-tourapi-3511602', '주식회사조아지구', '드라이브 겸 나들이로 주식회사조아지구 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "사색", "산책로", "온마루"]'::jsonb, 35.944130, 127.164458, '2026-07-06T11:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001874', '54500700-0000-4000-8000-000000000196', 'p-tourapi-1951619', '비암사 도깨비도로', '조용히 사색하고 싶어서 찾은 비암사 도깨비도로. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 36.610617, 127.191623, '2026-05-28T02:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001875', '54500700-0000-4000-8000-000000000150', 'p-tourapi-3532956', '경주황리단길숙소 한옥스테이 목화', '근처 여행 코스로 경주황리단길숙소 한옥스테이 목화 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "사진맛집", "인생샷"]'::jsonb, 35.836797, 129.211382, '2026-05-26T10:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001876', '54500700-0000-4000-8000-000000000194', 'p-tourapi-3102210', '선음재', '선음재 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["데이트", "방문팁", "온마루"]'::jsonb, 37.584828, 126.986011, '2026-06-22T02:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001877', '54500700-0000-4000-8000-000000000149', 'p-tourapi-3532694', '어보이', '평일 연차 쓰고 혼자 어보이 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 35.811857, 127.153393, '2026-04-27T12:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001878', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2820629', '부여북포한옥마을', '주말에 친구들이랑 부여북포한옥마을 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 36.292844, 126.924663, '2026-06-09T12:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001879', '54500700-0000-4000-8000-000000000169', 'p-tourapi-1990092', '고성 최필간고택', '해 질 무렵에 고성 최필간고택 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "사진맛집", "가족여행"]'::jsonb, 34.950428, 128.193718, '2026-05-18T20:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001880', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2699326', '월출산 청풍명월', '평일 연차 쓰고 혼자 월출산 청풍명월 다녀옴. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 34.769533, 126.654410, '2026-05-24T04:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001881', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2574186', '김포아트빌리지 전통한옥숙박체험관', '드라이브 겸 나들이로 김포아트빌리지 전통한옥숙박체험관 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "주말나들이", "사진맛집", "온마루"]'::jsonb, 37.646692, 126.696369, '2026-05-19T12:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001882', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2700309', '경주읍성한옥', '평일 연차 쓰고 혼자 경주읍성한옥 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 35.849393, 129.211541, '2026-06-27T14:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001883', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2587036', '백년한옥', '근처 여행 코스로 백년한옥 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.815993, 127.155260, '2026-05-27T05:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001884', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2610985', '전주 한옥숙박 체험관', '드라이브 겸 나들이로 전주 한옥숙박 체험관 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이", "인생샷", "온마루"]'::jsonb, 35.815142, 127.152126, '2026-05-21T22:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001885', '54500700-0000-4000-8000-000000000096', 'p-tourapi-3102031', '소산당', '비 오는 날 운치 찾아 소산당 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 35.206621, 127.511770, '2026-06-24T14:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001886', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2820893', '평창사랑', '기대 이상으로 너무 좋았던 평창사랑! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 37.490310, 128.410478, '2026-06-20T05:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001887', '54500700-0000-4000-8000-000000000190', 'p-tourapi-1872349', '순천만 해룡성고택', '근처 여행 코스로 순천만 해룡성고택 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 34.919877, 127.502550, '2026-06-12T16:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001888', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2657848', '한국트로트가요센터', '드라이브 겸 나들이로 한국트로트가요센터 선택했는데 대만족! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 34.791351, 126.685583, '2026-07-02T14:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001889', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3102087', '한옥더원', '날씨가 너무 맑아서 한옥더원 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 37.471194, 127.505899, '2026-05-19T00:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001890', '54500700-0000-4000-8000-000000000185', 'p-tourapi-128547', '이해룡고가', '주말에 친구들이랑 이해룡고가 들렀는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 36.911938, 127.287128, '2026-05-22T14:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001891', '54500700-0000-4000-8000-000000000152', 'p-tourapi-3438435', '사임당 귀한그대', '주말에 친구들이랑 사임당 귀한그대 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "가족여행", "사진맛집"]'::jsonb, 37.641137, 126.940535, '2026-07-12T18:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001892', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2598985', '초전고택', '근처 여행 코스로 초전고택 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "가족여행", "인생샷"]'::jsonb, 36.441199, 129.024408, '2026-05-25T10:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001893', '54500700-0000-4000-8000-000000000166', 'p-tourapi-3438496', '소우주', '소우주 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "산책로", "사색"]'::jsonb, 37.640907, 126.939000, '2026-05-27T06:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001894', '54500700-0000-4000-8000-000000000170', 'p-tourapi-1882248', '인우하우스', '드라이브 겸 나들이로 인우하우스 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.582459, 126.986987, '2026-05-02T15:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001895', '54500700-0000-4000-8000-000000000203', 'p-tourapi-3532773', '덕용재4.9', '해 질 무렵에 덕용재4.9 방문했는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로"]'::jsonb, 36.691630, 128.409450, '2026-05-14T01:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001896', '54500700-0000-4000-8000-000000000136', 'p-tourapi-126795', '고성 어명기 고택', '드라이브 겸 나들이로 고성 어명기 고택 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 38.314716, 128.517613, '2026-05-23T05:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001897', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2811451', '스테이황룡', '조용히 사색하고 싶어서 찾은 스테이황룡. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.294971, 126.770311, '2026-06-10T20:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001898', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2775304', '아올', '평일 연차 쓰고 혼자 아올 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 35.275999, 126.509441, '2026-05-10T15:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001899', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3532711', '안스테이', '예전부터 가보고 싶었던 안스테이 드디어 방문! 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "주말나들이", "인생샷"]'::jsonb, 37.765119, 127.392632, '2026-07-01T08:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001900', '54500700-0000-4000-8000-000000000179', 'p-tourapi-635593', '갈중이(천연염색체험)', '주말에 친구들이랑 갈중이(천연염색체험) 들렀는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "사진맛집", "데이트"]'::jsonb, 33.235027, 126.313519, '2026-06-21T15:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001901', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2717590', '김성래 가옥', '오랜만에 여유 찾으러 김성래 가옥 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 37.987383, 128.739712, '2026-04-21T00:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001902', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3438576', '테오리아', '비 오는 날 운치 찾아 테오리아 다녀왔어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 35.818216, 127.151272, '2026-05-09T13:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001903', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2574307', '목양산방', '근처 여행 코스로 목양산방 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트", "주말나들이"]'::jsonb, 34.890075, 127.507333, '2026-06-04T23:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001904', '54500700-0000-4000-8000-000000000138', 'p-tourapi-250372', '의성김씨 학봉종택', '드라이브 겸 나들이로 의성김씨 학봉종택 선택했는데 대만족! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉", "힐링", "온마루"]'::jsonb, 36.609640, 128.669259, '2026-05-23T06:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001905', '54500700-0000-4000-8000-000000000170', 'p-tourapi-3438581', '교동94', '기대 이상으로 너무 좋았던 교동94! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "데이트", "주말나들이", "온마루"]'::jsonb, 35.812682, 127.152636, '2026-06-06T11:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001906', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2760074', '지리산태고재 (정일품농원)', '평일 연차 쓰고 혼자 지리산태고재 (정일품농원) 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "고즈넉", "힐링"]'::jsonb, 35.564922, 127.767246, '2026-06-22T08:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001907', '54500700-0000-4000-8000-000000000165', 'p-tourapi-3511230', '김씨네마카롱공장(주식회사필링)', '비 오는 날 운치 찾아 김씨네마카롱공장(주식회사필링) 다녀왔어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 35.490559, 129.435686, '2026-06-16T01:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001908', '54500700-0000-4000-8000-000000000124', 'p-tourapi-3101956', '죽록정사', '근처 여행 코스로 죽록정사 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "사진맛집", "인생샷", "온마루"]'::jsonb, 35.226520, 127.486074, '2026-05-01T05:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001909', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2569552', '셔블', '기대 이상으로 너무 좋았던 셔블! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 35.836851, 129.211712, '2026-06-04T10:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001910', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3541047', '주문진 관광안내센터', '해 질 무렵에 주문진 관광안내센터 방문했는데 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "가족여행", "데이트"]'::jsonb, 37.890376, 128.828619, '2026-05-16T05:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001911', '54500700-0000-4000-8000-000000000138', 'p-tourapi-1594374', '전주전통한지원', '비 오는 날 운치 찾아 전주전통한지원 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["인생샷", "데이트", "온마루"]'::jsonb, 35.816063, 127.153446, '2026-04-30T06:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001912', '54500700-0000-4000-8000-000000000067', 'p-tourapi-3532883', '소풍한옥풀빌라', '평일 연차 쓰고 혼자 소풍한옥풀빌라 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "고즈넉", "혼자여행", "온마루"]'::jsonb, 35.855737, 129.266968, '2026-06-08T10:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001913', '54500700-0000-4000-8000-000000000168', 'p-tourapi-3438368', '해아원', '천천히 골목 걷다가 마주친 해아원. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "풍경맛집"]'::jsonb, 37.582953, 126.983269, '2026-07-02T17:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001914', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2939588', '행주커뮤니티센터', '예전부터 가보고 싶었던 행주커뮤니티센터 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 37.602835, 126.822754, '2026-05-12T01:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001915', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2663296', '경주 한옥(경주한옥펜션)', '기대 이상으로 너무 좋았던 경주 한옥(경주한옥펜션)! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 35.801358, 129.196564, '2026-04-26T02:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001916', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3532598', '월하', '천천히 골목 걷다가 마주친 월하. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 35.847974, 129.207342, '2026-07-17T02:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001917', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2737316', '킹콩놀이터', '평일 연차 쓰고 혼자 킹콩놀이터 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.008451, 126.773457, '2026-06-10T09:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001918', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3025473', '영광 매간당 고택', '오랜만에 여유 찾으러 영광 매간당 고택 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "풍경맛집", "산책로"]'::jsonb, 35.240643, 126.474391, '2026-06-29T07:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001919', '54500700-0000-4000-8000-000000000184', 'p-tourapi-128788', '설악산 케이블카', '설악산 케이블카 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 38.172897, 128.489276, '2026-06-12T16:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001920', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1971917', '청공한옥', '천천히 골목 걷다가 마주친 청공한옥. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.782175, 129.303455, '2026-06-07T04:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001921', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3438589', '윤은재', '주말에 친구들이랑 윤은재 들렀는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "사진맛집", "가족여행"]'::jsonb, 35.033317, 126.712253, '2026-07-09T21:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001922', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2638480', '울산안전체험관', '예전부터 가보고 싶었던 울산안전체험관 드디어 방문! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "인생샷", "사진맛집"]'::jsonb, 35.617846, 129.440537, '2026-07-14T17:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001923', '54500700-0000-4000-8000-000000000158', 'p-tourapi-1610542', '달성 조길방 고택', '부모님 모시고 달성 조길방 고택 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.755716, 128.581699, '2026-05-07T21:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001924', '54500700-0000-4000-8000-000000000194', 'p-tourapi-3438431', '사월 한옥', '조용히 사색하고 싶어서 찾은 사월 한옥. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 37.594221, 126.999938, '2026-05-27T01:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001925', '54500700-0000-4000-8000-000000000065', 'p-tourapi-3072240', '온유헌 바이 버틀러리', '주말에 친구들이랑 온유헌 바이 버틀러리 들렀는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 37.581591, 126.987649, '2026-05-07T18:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001926', '54500700-0000-4000-8000-000000000186', 'p-tourapi-3116447', '웰컴미스테익스', '기대 이상으로 너무 좋았던 웰컴미스테익스! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 37.591525, 126.963377, '2026-05-16T04:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001927', '54500700-0000-4000-8000-000000000188', 'p-tourapi-3438160', '통인 1939', '비 오는 날 운치 찾아 통인 1939 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트", "주말나들이", "온마루"]'::jsonb, 37.579297, 126.970728, '2026-07-05T08:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001928', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2373420', '아띠인력거', '드라이브 겸 나들이로 아띠인력거 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "고즈넉", "사색", "온마루"]'::jsonb, 37.579268, 126.982258, '2026-07-05T22:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001929', '54500700-0000-4000-8000-000000000112', 'p-tourapi-3032740', '대가야기마문화체험장', '해 질 무렵에 대가야기마문화체험장 방문했는데 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "방문팁", "인생샷", "온마루"]'::jsonb, 35.711227, 128.267202, '2026-07-08T05:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001930', '54500700-0000-4000-8000-000000000069', 'p-tourapi-1883996', '취옹예술관', '부모님 모시고 취옹예술관 산책 겸 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링", "혼자여행"]'::jsonb, 37.752336, 127.360151, '2026-05-22T11:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001931', '54500700-0000-4000-8000-000000000192', 'p-tourapi-1606009', '삼청동오위장김춘영가옥', '평일 연차 쓰고 혼자 삼청동오위장김춘영가옥 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행", "고즈넉"]'::jsonb, 37.558932, 126.994329, '2026-06-29T07:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001932', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2775016', '잼토리 JAMTORY', '기대 이상으로 너무 좋았던 잼토리 JAMTORY! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "사색", "고즈넉"]'::jsonb, 36.943903, 127.517183, '2026-06-18T00:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001933', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '기대 이상으로 너무 좋았던 미담 한옥 게스트 하우스! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "힐링", "풍경맛집"]'::jsonb, 37.580409, 126.986357, '2026-06-21T11:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001934', '54500700-0000-4000-8000-000000000171', 'p-tourapi-1799268', '회원식당', '예전부터 가보고 싶었던 회원식당 드디어 방문! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "고즈넉", "혼자여행"]'::jsonb, 35.078116, 127.769190, '2026-06-20T16:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001935', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2706485', '오류헌', 'SNS에서 사진 보고 찾아간 오류헌, 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 36.519234, 128.867199, '2026-07-06T01:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001936', '54500700-0000-4000-8000-000000000196', 'p-tourapi-800528', '춘천 강언덕마을 [농촌전통테마]', 'SNS에서 사진 보고 찾아간 춘천 강언덕마을 [농촌전통테마], 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "사진맛집", "방문팁"]'::jsonb, 37.678483, 127.613733, '2026-06-09T04:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001937', '54500700-0000-4000-8000-000000000121', 'p-tourapi-3438452', '담서제', '예전부터 가보고 싶었던 담서제 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "가족여행", "사진맛집"]'::jsonb, 37.640875, 126.939060, '2026-05-16T05:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001938', '54500700-0000-4000-8000-000000000085', 'p-tourapi-3066280', '전주일몽', '평일 연차 쓰고 혼자 전주일몽 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 35.811930, 127.154484, '2026-07-05T02:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001939', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2707445', '일독일박', '비 오는 날 운치 찾아 일독일박 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집", "가족여행"]'::jsonb, 37.578407, 126.968958, '2026-06-20T16:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001940', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2853622', '양수리한옥집', '근처 여행 코스로 양수리한옥집 넣길 정말 잘했어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 37.547466, 127.321374, '2026-05-23T18:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001941', '54500700-0000-4000-8000-000000000203', 'p-tourapi-3438359', '스테이모일', '조용히 사색하고 싶어서 찾은 스테이모일. 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.576508, 126.991224, '2026-07-01T18:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001942', '54500700-0000-4000-8000-000000000167', 'p-tourapi-1310884', '고성장산리허씨고가', '고성장산리허씨고가 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.060594, 128.324259, '2026-07-13T09:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001943', '54500700-0000-4000-8000-000000000112', 'p-tourapi-1624505', '해남 민정기 가옥', '해 질 무렵에 해남 민정기 가옥 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "데이트"]'::jsonb, 34.542630, 126.568614, '2026-05-08T06:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001944', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2502595', '술샘', '오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.233398, 127.298458, '2026-05-27T11:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001945', '54500700-0000-4000-8000-000000000110', 'p-tourapi-2586166', '황토한옥고마', 'SNS에서 사진 보고 찾아간 황토한옥고마, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "인생샷"]'::jsonb, 36.461451, 127.122669, '2026-05-30T13:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001946', '54500700-0000-4000-8000-000000000088', 'p-tourapi-1972030', '상유재', '날씨가 너무 맑아서 상유재 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행", "사색", "온마루"]'::jsonb, 37.379172, 128.660760, '2026-06-26T18:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001947', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2600371', '선비촌', '오랜만에 여유 찾으러 선비촌 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 36.931302, 128.581019, '2026-06-21T05:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001948', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2598834', '안동 군자마을', '조용히 사색하고 싶어서 찾은 안동 군자마을. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 36.673198, 128.801526, '2026-06-17T07:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001949', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2606387', '예천군체육회활체험센터', '평일 연차 쓰고 혼자 예천군체육회활체험센터 다녀옴. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 36.634424, 128.468361, '2026-06-13T15:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001950', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2786838', '산청 남사리 이씨고가', '드라이브 겸 나들이로 산청 남사리 이씨고가 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "주말나들이", "가족여행", "온마루"]'::jsonb, 35.275094, 127.935158, '2026-05-21T23:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001951', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3056595', '전주한옥마을역사관', '주말에 친구들이랑 전주한옥마을역사관 들렀는데 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "주말나들이"]'::jsonb, 35.816110, 127.153012, '2026-06-16T12:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001952', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3438561', '스테이용궁', '평일 연차 쓰고 혼자 스테이용궁 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "고즈넉", "산책로"]'::jsonb, 37.281614, 127.019846, '2026-05-08T12:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001953', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3469953', '하녹집', '드라이브 겸 나들이로 하녹집 선택했는데 대만족! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 36.564546, 128.736386, '2026-07-17T09:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001954', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2932873', '계와고택', '비 오는 날 운치 찾아 계와고택 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "풍경맛집", "고즈넉"]'::jsonb, 36.506254, 128.852893, '2026-07-11T09:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001955', '54500700-0000-4000-8000-000000000166', 'p-tourapi-3457765', '인천애뜰', '드라이브 겸 나들이로 인천애뜰 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "풍경맛집", "사색"]'::jsonb, 37.455005, 126.706171, '2026-07-05T04:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001956', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2702475', '고진하 가옥', '주말에 친구들이랑 고진하 가옥 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 37.174174, 128.386759, '2026-05-27T00:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001957', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2531675', '진도한옥펜션', '근처 여행 코스로 진도한옥펜션 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "주말나들이", "방문팁", "온마루"]'::jsonb, 34.398380, 126.277145, '2026-06-25T13:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001958', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2603918', '(사)영남선비문화수련원(구암서원)', '주말에 친구들이랑 (사)영남선비문화수련원(구암서원) 들렀는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 35.901553, 128.596744, '2026-06-18T20:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001959', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2628953', '하늘풍경', '조용히 사색하고 싶어서 찾은 하늘풍경. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 35.812379, 127.151997, '2026-06-15T03:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001960', '54500700-0000-4000-8000-000000000141', 'p-tourapi-3532770', '월하고택', '근처 여행 코스로 월하고택 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "데이트", "방문팁"]'::jsonb, 37.719238, 127.313333, '2026-06-25T06:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001961', '54500700-0000-4000-8000-000000000124', 'p-tourapi-1883085', '늘봄스테이', '예전부터 가보고 싶었던 늘봄스테이 드디어 방문! 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "산책로"]'::jsonb, 35.813306, 127.152621, '2026-05-17T17:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001962', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3532465', '동해산타열차', 'SNS에서 사진 보고 찾아간 동해산타열차, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행", "인생샷"]'::jsonb, 37.764156, 128.899495, '2026-05-27T02:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001963', '54500700-0000-4000-8000-000000000124', 'p-tourapi-3438569', '아담', '조용히 사색하고 싶어서 찾은 아담. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 36.450557, 127.122084, '2026-05-25T01:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001964', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2706641', '달빛미소', '비 오는 날 운치 찾아 달빛미소 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "데이트", "주말나들이"]'::jsonb, 34.740415, 126.717856, '2026-04-23T07:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001965', '54500700-0000-4000-8000-000000000160', 'p-tourapi-3438496', '소우주', '드라이브 겸 나들이로 소우주 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "주말나들이", "인생샷", "온마루"]'::jsonb, 37.640872, 126.938653, '2026-06-03T23:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001966', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2531683', '옛마실펜션', '날씨가 너무 맑아서 옛마실펜션 한 바퀴 돌고 왔네요. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 34.850786, 128.724318, '2026-04-24T05:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001967', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2049706', '교동가온', '교동가온 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로"]'::jsonb, 35.813626, 127.152825, '2026-04-27T07:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001968', '54500700-0000-4000-8000-000000000195', 'p-tourapi-2046299', '한옥이야기', '평일 연차 쓰고 혼자 한옥이야기 다녀옴. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 35.812205, 127.153606, '2026-05-27T22:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001969', '54500700-0000-4000-8000-000000000063', 'p-tourapi-3056595', '전주한옥마을역사관', '비 오는 날 운치 찾아 전주한옥마을역사관 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.815795, 127.153073, '2026-07-17T11:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001970', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2604371', '노을한옥', '노을한옥 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "고즈넉", "온마루"]'::jsonb, 34.850917, 127.523027, '2026-07-02T05:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001971', '54500700-0000-4000-8000-000000000132', 'p-tourapi-794941', '안동 진성이씨 종택', '천천히 골목 걷다가 마주친 안동 진성이씨 종택. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로", "풍경맛집", "온마루"]'::jsonb, 36.639739, 128.742061, '2026-04-19T05:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001972', '54500700-0000-4000-8000-000000000104', 'p-tourapi-4074856', '연림스테이', '부모님 모시고 연림스테이 산책 겸 다녀왔습니다. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링", "혼자여행"]'::jsonb, 35.972397, 128.698821, '2026-06-13T21:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001973', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2000946', '치암고택', '예전부터 가보고 싶었던 치암고택 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "주말나들이", "데이트"]'::jsonb, 36.582974, 128.735930, '2026-04-22T14:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001974', '54500700-0000-4000-8000-000000000111', 'p-tourapi-3533160', '와하녹', '비 오는 날 운치 찾아 와하녹 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "가족여행"]'::jsonb, 37.581735, 126.999673, '2026-05-05T14:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001975', '54500700-0000-4000-8000-000000000201', 'p-tourapi-2500218', '광흥당', '해 질 무렵에 광흥당 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 37.548308, 126.928906, '2026-06-13T08:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001976', '54500700-0000-4000-8000-000000000179', 'p-tourapi-128645', '춘천최재근가옥', '날씨가 너무 맑아서 춘천최재근가옥 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "주말나들이", "가족여행", "온마루"]'::jsonb, 37.842967, 127.727348, '2026-07-10T11:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001977', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2668426', '학림재', '해 질 무렵에 학림재 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "사색", "풍경맛집"]'::jsonb, 36.551251, 127.190326, '2026-07-11T05:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001978', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2598650', '주촌종택(주촌(두루)종택)', '근처 여행 코스로 주촌종택(주촌(두루)종택) 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 36.642619, 128.739324, '2026-07-07T19:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001979', '54500700-0000-4000-8000-000000000087', 'p-tourapi-3438402', '사사로이', '해 질 무렵에 사사로이 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 37.577890, 126.981255, '2026-07-08T01:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001980', '54500700-0000-4000-8000-000000000080', 'p-tourapi-231940', '안동 소호헌', '부모님 모시고 안동 소호헌 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 36.463619, 128.663465, '2026-07-04T15:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001981', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3358056', '닥나무한지체험관 콩닥콩닥', '근처 여행 코스로 닥나무한지체험관 콩닥콩닥 넣길 정말 잘했어요. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링", "사색"]'::jsonb, 35.691283, 126.817631, '2026-04-23T14:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001982', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2603996', '매죽헌2(매죽헌한옥민박)', '평일 연차 쓰고 혼자 매죽헌2(매죽헌한옥민박) 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "힐링", "혼자여행"]'::jsonb, 35.068674, 127.401705, '2026-07-07T19:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001983', '54500700-0000-4000-8000-000000000186', 'p-tourapi-3510980', '유한회사더담희', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "사진맛집", "온마루"]'::jsonb, 35.219401, 126.878397, '2026-04-26T23:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001984', '54500700-0000-4000-8000-000000000153', 'p-tourapi-3065503', '전주 대사습청', '오랜만에 여유 찾으러 전주 대사습청 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.817648, 127.153624, '2026-07-07T16:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001985', '54500700-0000-4000-8000-000000000140', 'p-tourapi-3012433', '경기도국민안전체험관', '주말에 친구들이랑 경기도국민안전체험관 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.178443, 127.062865, '2026-06-15T03:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001986', '54500700-0000-4000-8000-000000000183', 'p-tourapi-3469822', '대동고택', '오랜만에 여유 찾으러 대동고택 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 35.821378, 127.136139, '2026-05-18T20:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001987', '54500700-0000-4000-8000-000000000189', 'p-tourapi-3337188', '세종전통문화체험관', 'SNS에서 사진 보고 찾아간 세종전통문화체험관, 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 36.506590, 127.292017, '2026-05-02T17:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001988', '54500700-0000-4000-8000-000000000145', 'p-tourapi-3438616', '한낮', '조용히 사색하고 싶어서 찾은 한낮. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "풍경맛집", "혼자여행"]'::jsonb, 36.556369, 128.755720, '2026-07-06T00:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001989', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2701396', '서남산한옥', 'SNS에서 사진 보고 찾아간 서남산한옥, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 35.781211, 129.204573, '2026-04-25T06:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001990', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2393927', '충청남도 안전체험관', '기대 이상으로 너무 좋았던 충청남도 안전체험관! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "방문팁", "주말나들이"]'::jsonb, 36.821513, 127.191551, '2026-05-26T01:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001991', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2614384', '윤동주 유고보존 정병욱 가옥', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 34.970928, 127.759510, '2026-07-02T02:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001992', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2609894', '경기전 연가', '근처 여행 코스로 경기전 연가 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "가족여행", "인생샷"]'::jsonb, 35.817691, 127.150250, '2026-06-01T19:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001993', '54500700-0000-4000-8000-000000000125', 'p-tourapi-1089992', '대전교통문화연수원', '주말에 친구들이랑 대전교통문화연수원 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 36.376988, 127.386754, '2026-07-03T16:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001994', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2814160', '불국사한옥팜스테이', '드라이브 겸 나들이로 불국사한옥팜스테이 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.782925, 129.328011, '2026-07-17T01:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001995', '54500700-0000-4000-8000-000000000148', 'p-tourapi-3451224', '은계2어울림센터', '전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링", "고즈넉", "온마루"]'::jsonb, 37.435892, 126.797861, '2026-05-09T13:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001996', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2598834', '안동 군자마을', '오랜만에 여유 찾으러 안동 군자마을 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "산책로", "사색"]'::jsonb, 36.673621, 128.801199, '2026-06-30T21:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001997', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3540259', '한옥스테이 파인앤프렌즈', '오랜만에 여유 찾으러 한옥스테이 파인앤프렌즈 다녀왔습니다. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "고즈넉", "온마루"]'::jsonb, 37.776000, 128.932856, '2026-04-25T21:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001998', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2603884', '연당', '조용히 사색하고 싶어서 찾은 연당. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 37.582620, 126.987194, '2026-05-04T11:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000001999', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2607481', '향운', '비 오는 날 운치 찾아 향운 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 37.582866, 126.985826, '2026-06-02T22:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002000', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1685586', '청풍 황석리 고가', '해 질 무렵에 청풍 황석리 고가 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["주말나들이", "사진맛집", "가족여행", "온마루"]'::jsonb, 37.005104, 128.170715, '2026-06-27T22:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002001', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2819158', '매원마을', '평일 연차 쓰고 혼자 매원마을 다녀옴. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "힐링", "산책로"]'::jsonb, 35.994418, 128.431225, '2026-06-13T03:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002002', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2622784', '소양고택 한옥스테이', '근처 여행 코스로 소양고택 한옥스테이 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 35.903698, 127.243204, '2026-05-02T21:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002003', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2668131', '춘화당', '해 질 무렵에 춘화당 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 34.791458, 126.382875, '2026-06-10T06:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002004', '54500700-0000-4000-8000-000000000102', 'p-tourapi-1972012', '산에는 꽃이피네', '산에는 꽃이피네 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 34.998720, 126.823345, '2026-05-13T13:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002005', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3533160', '와하녹', '부모님 모시고 와하녹 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["주말나들이", "사진맛집", "가족여행"]'::jsonb, 37.581471, 126.999683, '2026-06-07T00:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002006', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2046299', '한옥이야기', '예전부터 가보고 싶었던 한옥이야기 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 35.812411, 127.154057, '2026-05-21T13:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002007', '54500700-0000-4000-8000-000000000092', 'p-tourapi-129052', '청송초전댁', '드라이브 겸 나들이로 청송초전댁 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 36.438137, 129.026712, '2026-05-10T10:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002008', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3444479', '성주 예산리 배리댁', '기대 이상으로 너무 좋았던 성주 예산리 배리댁! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 35.923708, 128.285180, '2026-06-26T19:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002009', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2604344', '락희원', '천천히 골목 걷다가 마주친 락희원. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "힐링"]'::jsonb, 35.837447, 129.211899, '2026-05-27T02:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002010', '54500700-0000-4000-8000-000000000057', 'p-tourapi-798830', '영동 김참판댁', '비 오는 날 운치 찾아 영동 김참판댁 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.153027, 127.754820, '2026-05-03T09:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002011', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2820893', '평창사랑', '예전부터 가보고 싶었던 평창사랑 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 37.490266, 128.410719, '2026-06-16T08:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002012', '54500700-0000-4000-8000-000000000180', 'p-tourapi-3424446', '영동군 숲에너지육감 활성화센터', '평일 연차 쓰고 혼자 영동군 숲에너지육감 활성화센터 다녀옴. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "산책로"]'::jsonb, 36.155676, 127.785778, '2026-05-23T11:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002013', '54500700-0000-4000-8000-000000000152', 'p-tourapi-1373030', '서상돈 고택', '해 질 무렵에 서상돈 고택 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["사색", "산책로", "풍경맛집", "온마루"]'::jsonb, 35.867375, 128.588138, '2026-05-20T20:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002014', '54500700-0000-4000-8000-000000000056', 'p-tourapi-1997202', '여수 해상케이블카', 'SNS에서 사진 보고 찾아간 여수 해상케이블카, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "방문팁"]'::jsonb, 34.730756, 127.739520, '2026-05-10T12:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002015', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2699340', '한옥 게스트하우스 동촌재', '천천히 골목 걷다가 마주친 한옥 게스트하우스 동촌재. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "주말나들이", "사진맛집"]'::jsonb, 37.579936, 126.969975, '2026-04-23T00:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002016', '54500700-0000-4000-8000-000000000165', 'p-tourapi-231936', '달성 태고정', '주말에 친구들이랑 달성 태고정 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "인생샷", "방문팁"]'::jsonb, 35.911147, 128.416273, '2026-06-26T21:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002017', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3438574', '풍류가옥', '주말에 친구들이랑 풍류가옥 들렀는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 35.824480, 127.155244, '2026-04-22T11:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002018', '54500700-0000-4000-8000-000000000169', 'p-tourapi-3438420', '성북 은은한가', '조용히 사색하고 싶어서 찾은 성북 은은한가. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "사색", "풍경맛집", "온마루"]'::jsonb, 37.590689, 127.009126, '2026-06-21T17:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002019', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2595489', '동해한옥 동안재', '근처 여행 코스로 동해한옥 동안재 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링", "풍경맛집", "온마루"]'::jsonb, 37.528402, 129.108645, '2026-06-11T10:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002020', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2605351', '광주폴리', '비 오는 날 운치 찾아 광주폴리 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 35.182577, 126.890106, '2026-04-19T09:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002021', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2600221', '박정우가옥', '근처 여행 코스로 박정우가옥 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로", "힐링", "온마루"]'::jsonb, 36.734512, 128.619790, '2026-05-16T20:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002022', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2380834', '마복산 목재문화체험장', '날씨가 너무 맑아서 마복산 목재문화체험장 한 바퀴 돌고 왔네요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "사색"]'::jsonb, 34.550492, 127.375627, '2026-05-11T10:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002023', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2468936', '옛날에금잔디', 'SNS에서 사진 보고 찾아간 옛날에금잔디, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행", "산책로"]'::jsonb, 37.715734, 126.389229, '2026-06-19T03:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002024', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3444338', '완정고택', '드라이브 겸 나들이로 완정고택 선택했는데 대만족! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 36.003976, 128.234600, '2026-06-07T02:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002025', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2651450', '한옥혜윰', '오랜만에 여유 찾으러 한옥혜윰 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "사색", "풍경맛집"]'::jsonb, 35.811363, 127.152384, '2026-07-15T05:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002026', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3438592', '한옥스테이 다가감', '근처 여행 코스로 한옥스테이 다가감 넣길 정말 잘했어요. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "인생샷", "방문팁"]'::jsonb, 35.834873, 129.212935, '2026-06-30T23:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002027', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3454074', '영화의전당 라이브러리 자료실', '드라이브 겸 나들이로 영화의전당 라이브러리 자료실 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.170925, 129.127109, '2026-07-08T10:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002028', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2820733', '생생마을여행사', '생생마을여행사 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["주말나들이", "사진맛집", "가족여행"]'::jsonb, 37.027281, 127.630106, '2026-05-14T15:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002029', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2713277', '산토끼 노래동산', '오랜만에 여유 찾으러 산토끼 노래동산 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 35.577649, 128.383559, '2026-05-11T10:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002030', '54500700-0000-4000-8000-000000000092', 'p-tourapi-1884345', '행복드림한옥', '날씨가 너무 맑아서 행복드림한옥 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "사진맛집", "데이트"]'::jsonb, 35.905392, 127.209533, '2026-05-22T14:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002031', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2587214', '제이한옥(JAY Hanok)', '기대 이상으로 너무 좋았던 제이한옥(JAY Hanok)! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["사진맛집", "방문팁"]'::jsonb, 37.582282, 126.987620, '2026-04-21T22:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002032', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3511602', '주식회사조아지구', '날씨가 너무 맑아서 주식회사조아지구 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "산책로", "혼자여행", "온마루"]'::jsonb, 35.943979, 127.164648, '2026-05-13T08:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002033', '54500700-0000-4000-8000-000000000077', 'p-tourapi-3009051', '도깨비 양조장', '날씨가 너무 맑아서 도깨비 양조장 한 바퀴 돌고 왔네요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색", "혼자여행"]'::jsonb, 37.026220, 128.384969, '2026-05-02T10:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002034', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2638488', '거제 관광모노레일', '주말에 친구들이랑 거제 관광모노레일 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "주말나들이", "인생샷", "온마루"]'::jsonb, 34.876377, 128.625485, '2026-04-25T14:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002035', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2707438', '하은재', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["주말나들이", "방문팁"]'::jsonb, 37.582193, 126.971413, '2026-07-13T05:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002036', '54500700-0000-4000-8000-000000000071', 'p-tourapi-3102211', '자하연', '비 오는 날 운치 찾아 자하연 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 35.812127, 127.154870, '2026-04-26T18:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002037', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3101961', '자미재', '천천히 골목 걷다가 마주친 자미재. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 34.911583, 126.648077, '2026-06-07T02:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002038', '54500700-0000-4000-8000-000000000171', 'p-tourapi-3353949', '㈜ 희품씨', '해 질 무렵에 ㈜ 희품씨 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "사진맛집", "데이트"]'::jsonb, 35.567240, 129.112756, '2026-05-10T16:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002039', '54500700-0000-4000-8000-000000000082', 'p-tourapi-1877312', '양소당', '기대 이상으로 너무 좋았던 양소당! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["주말나들이", "데이트", "사진맛집", "온마루"]'::jsonb, 36.579916, 128.546972, '2026-05-04T22:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002040', '54500700-0000-4000-8000-000000000204', 'p-tourapi-3532465', '동해산타열차', '날씨가 너무 맑아서 동해산타열차 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.764106, 128.899807, '2026-07-14T04:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002041', '54500700-0000-4000-8000-000000000147', 'p-tourapi-3438450', '평안채', '평일 연차 쓰고 혼자 평안채 다녀옴. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "힐링", "사색", "온마루"]'::jsonb, 37.640909, 126.938362, '2026-06-17T07:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002042', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2725010', '휴식 레스토랑', '오랜만에 여유 찾으러 휴식 레스토랑 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 36.451414, 126.813372, '2026-04-18T23:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002043', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2620413', '병암고택', '해 질 무렵에 병암고택 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 36.558093, 129.128019, '2026-05-13T04:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002044', '54500700-0000-4000-8000-000000000101', 'p-tourapi-1594500', '전주목판서화체험관', '아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 35.811486, 127.155725, '2026-05-30T14:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002045', '54500700-0000-4000-8000-000000000188', 'p-tourapi-3105334', '133파티룸 한옥스테이점', 'SNS에서 사진 보고 찾아간 133파티룸 한옥스테이점, 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["주말나들이", "데이트"]'::jsonb, 37.279219, 127.016128, '2026-07-16T20:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002046', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2708657', '초정행궁', '천천히 골목 걷다가 마주친 초정행궁. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "방문팁"]'::jsonb, 36.721152, 127.601675, '2026-07-03T10:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002047', '54500700-0000-4000-8000-000000000137', 'p-tourapi-3532950', '유류헌', '고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 37.881582, 127.741831, '2026-06-29T12:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002048', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2707242', '위연재', '날씨가 너무 맑아서 위연재 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 35.836521, 129.218292, '2026-04-19T17:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002049', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2608140', '하늘누리', '기대 이상으로 너무 좋았던 하늘누리! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "사색", "고즈넉"]'::jsonb, 34.638054, 127.034283, '2026-04-21T02:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002050', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2638480', '울산안전체험관', '울산안전체험관 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "데이트", "가족여행", "온마루"]'::jsonb, 35.617897, 129.440785, '2026-05-19T19:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002051', '54500700-0000-4000-8000-000000000078', 'p-tourapi-3438359', '스테이모일', '평일 연차 쓰고 혼자 스테이모일 다녀옴. 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 37.576791, 126.991160, '2026-06-10T23:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002052', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2049874', '해마루 힐링숲', '드라이브 겸 나들이로 해마루 힐링숲 선택했는데 대만족! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "풍경맛집", "산책로", "온마루"]'::jsonb, 34.438865, 126.632775, '2026-06-28T01:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002053', '54500700-0000-4000-8000-000000000158', 'p-tourapi-128994', '구례 운조루 고택', 'SNS에서 사진 보고 찾아간 구례 운조루 고택, 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 35.205930, 127.515423, '2026-06-21T07:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002054', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2932921', '한울', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "주말나들이", "사진맛집"]'::jsonb, 37.237401, 127.265320, '2026-05-29T06:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002055', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3532948', '하녹명당', '오랜만에 여유 찾으러 하녹명당 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 35.836346, 129.212061, '2026-05-14T16:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002056', '54500700-0000-4000-8000-000000000149', 'p-tourapi-3007507', '호수양조장', '근처 여행 코스로 호수양조장 넣길 정말 잘했어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "데이트"]'::jsonb, 37.872205, 127.730745, '2026-06-10T14:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002057', '54500700-0000-4000-8000-000000000092', 'p-tourapi-128547', '이해룡고가', '조용히 사색하고 싶어서 찾은 이해룡고가. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "사색", "풍경맛집"]'::jsonb, 36.911780, 127.287146, '2026-05-07T04:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002058', '54500700-0000-4000-8000-000000000085', 'p-tourapi-1871270', '맥산댁', '날씨가 너무 맑아서 맥산댁 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "데이트"]'::jsonb, 35.667439, 128.228392, '2026-06-20T02:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002059', '54500700-0000-4000-8000-000000000107', 'p-tourapi-3102212', '한옥마을숙박 가인당', '한옥마을숙박 가인당 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 35.812290, 127.151577, '2026-07-08T21:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002060', '54500700-0000-4000-8000-000000000135', 'p-tourapi-3454325', '꿀잼도시 대전홍보관', '주말에 친구들이랑 꿀잼도시 대전홍보관 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행", "인생샷"]'::jsonb, 36.375351, 127.382125, '2026-07-10T18:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002061', '54500700-0000-4000-8000-000000000112', 'p-tourapi-3438485', '다락재', '천천히 골목 걷다가 마주친 다락재. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "주말나들이", "사진맛집"]'::jsonb, 37.640971, 126.939999, '2026-07-07T10:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002062', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2651484', '생비원', '오랜만에 여유 찾으러 생비원 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "사색", "힐링", "온마루"]'::jsonb, 35.801075, 128.176477, '2026-07-06T13:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002063', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2572792', '매죽헌(매죽헌 한옥 민박)', '기대 이상으로 너무 좋았던 매죽헌(매죽헌 한옥 민박)! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 35.065995, 127.403763, '2026-07-04T21:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002064', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2699354', '은혜당', '기대 이상으로 너무 좋았던 은혜당! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "고즈넉", "산책로"]'::jsonb, 36.507844, 129.400960, '2026-05-16T01:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002065', '54500700-0000-4000-8000-000000000182', 'p-tourapi-4041219', '지후헌', '조용히 사색하고 싶어서 찾은 지후헌. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.589599, 127.003353, '2026-05-10T17:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002066', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2569237', '운정루', '예전부터 가보고 싶었던 운정루 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.791267, 129.245839, '2026-05-12T16:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002067', '54500700-0000-4000-8000-000000000105', 'p-tourapi-561914', '원주변씨 간재종택 및 간재정', '천천히 골목 걷다가 마주친 원주변씨 간재종택 및 간재정. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "고즈넉"]'::jsonb, 36.600908, 128.676934, '2026-05-03T20:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002068', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3532618', '산성동그곳', '드라이브 겸 나들이로 산성동그곳 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "혼자여행", "사색"]'::jsonb, 36.458903, 127.126405, '2026-05-15T02:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002069', '54500700-0000-4000-8000-000000000198', 'p-tourapi-1877312', '양소당', 'SNS에서 사진 보고 찾아간 양소당, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 36.579942, 128.547123, '2026-05-22T10:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002070', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2725124', '반정', '날씨가 너무 맑아서 반정 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색", "고즈넉"]'::jsonb, 37.492864, 128.457510, '2026-05-22T12:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002071', '54500700-0000-4000-8000-000000000190', 'p-tourapi-3438577', '청연', '주말에 친구들이랑 청연 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 35.810970, 127.152168, '2026-06-12T18:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002072', '54500700-0000-4000-8000-000000000170', 'p-tourapi-1627236', '신경섭 전통가옥', '비 오는 날 운치 찾아 신경섭 전통가옥 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 36.420773, 126.668246, '2026-06-28T04:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002073', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2939639', '유현문화관광지', '주말에 친구들이랑 유현문화관광지 들렀는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 37.530424, 127.820182, '2026-06-24T09:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002074', '54500700-0000-4000-8000-000000000109', 'p-tourapi-3438468', '생활서가', '생활서가 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "인생샷", "사진맛집"]'::jsonb, 37.642905, 126.938997, '2026-06-14T08:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002075', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2615342', '비비정예술열차', '천천히 골목 걷다가 마주친 비비정예술열차. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "혼자여행"]'::jsonb, 35.898945, 127.068114, '2026-04-20T11:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002076', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2811451', '스테이황룡', 'SNS에서 사진 보고 찾아간 스테이황룡, 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 35.294967, 126.770446, '2026-05-15T08:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002077', '54500700-0000-4000-8000-000000000151', 'p-tourapi-3105335', '세렌디피아', '해 질 무렵에 세렌디피아 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "혼자여행", "산책로", "온마루"]'::jsonb, 34.786508, 126.382011, '2026-05-13T08:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002078', '54500700-0000-4000-8000-000000000106', 'p-tourapi-128653', '거창 동계종택', '오랜만에 여유 찾으러 거창 동계종택 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "혼자여행"]'::jsonb, 35.755310, 127.828923, '2026-05-24T23:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002079', '54500700-0000-4000-8000-000000000132', 'p-tourapi-128655', '거창 황산리 신씨고가', '드라이브 겸 나들이로 거창 황산리 신씨고가 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "방문팁", "온마루"]'::jsonb, 35.762935, 127.836857, '2026-05-12T19:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002080', '54500700-0000-4000-8000-000000000160', 'p-tourapi-3068424', '가리왕산케이블카', '날씨가 너무 맑아서 가리왕산케이블카 한 바퀴 돌고 왔네요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 37.474106, 128.609990, '2026-04-20T03:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002081', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2606207', '목포 해상케이블카', '주말에 친구들이랑 목포 해상케이블카 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "방문팁", "인생샷"]'::jsonb, 34.799471, 126.370178, '2026-07-16T13:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002082', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2677655', '성주 백세각', '주말에 친구들이랑 성주 백세각 들렀는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "주말나들이", "가족여행", "온마루"]'::jsonb, 35.988461, 128.245766, '2026-06-02T17:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002083', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2790490', '비손농장(포항체험잇다)', '비손농장(포항체험잇다) 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행", "방문팁"]'::jsonb, 36.197657, 129.317420, '2026-04-19T16:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002084', '54500700-0000-4000-8000-000000000061', 'p-tourapi-250460', '남원몽심재', '예전부터 가보고 싶었던 남원몽심재 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 35.337858, 127.374430, '2026-05-02T05:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002085', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2609878', '흥부가(家)', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 35.815262, 127.151839, '2026-06-01T20:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002086', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2814147', '순천만숲', '예전부터 가보고 싶었던 순천만숲 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "가족여행", "사진맛집"]'::jsonb, 34.897313, 127.506658, '2026-05-11T03:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002087', '54500700-0000-4000-8000-000000000145', 'p-tourapi-2602446', '기헌고택', 'SNS에서 사진 보고 찾아간 기헌고택, 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이", "방문팁"]'::jsonb, 36.911981, 128.873265, '2026-06-06T11:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002088', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2738653', '토토아뜰리에', 'SNS에서 사진 보고 찾아간 토토아뜰리에, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 33.469852, 126.413351, '2026-05-09T11:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002089', '54500700-0000-4000-8000-000000000120', 'p-tourapi-3067572', '점핑고', '부모님 모시고 점핑고 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "방문팁"]'::jsonb, 36.787892, 127.121882, '2026-06-26T01:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002090', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2574225', '도원', '해 질 무렵에 도원 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 35.807745, 127.149996, '2026-07-10T01:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002091', '54500700-0000-4000-8000-000000000166', 'p-tourapi-264450', '안동 고성이씨 탑동파 종택', '비 오는 날 운치 찾아 안동 고성이씨 탑동파 종택 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행", "산책로"]'::jsonb, 36.566275, 128.746343, '2026-06-08T04:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002092', '54500700-0000-4000-8000-000000000194', 'p-tourapi-3102129', '연월한옥', '근처 여행 코스로 연월한옥 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 33.317269, 126.269738, '2026-06-17T21:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002093', '54500700-0000-4000-8000-000000000134', 'p-tourapi-1579811', '거창 반구헌', 'SNS에서 사진 보고 찾아간 거창 반구헌, 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링", "고즈넉", "온마루"]'::jsonb, 35.755246, 127.829154, '2026-05-01T07:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002094', '54500700-0000-4000-8000-000000000093', 'p-tourapi-3438422', '한옥 스테이 미경', '예전부터 가보고 싶었던 한옥 스테이 미경 드디어 방문! 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "힐링"]'::jsonb, 37.586485, 127.007754, '2026-05-31T00:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002095', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2713848', '수상한마법학교', '드라이브 겸 나들이로 수상한마법학교 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "사진맛집", "방문팁"]'::jsonb, 37.730543, 128.879499, '2026-06-16T00:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002096', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2576343', '뜰안채', '예전부터 가보고 싶었던 뜰안채 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.817379, 127.149237, '2026-05-26T09:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002097', '54500700-0000-4000-8000-000000000175', 'p-tourapi-3511400', '농업회사법인삼산도가주식회사', '근처 여행 코스로 농업회사법인삼산도가주식회사 넣길 정말 잘했어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 35.984277, 127.308248, '2026-05-13T10:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002098', '54500700-0000-4000-8000-000000000077', 'p-tourapi-3532770', '월하고택', '주말에 친구들이랑 월하고택 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 37.719530, 127.312754, '2026-06-16T02:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002099', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2770591', '오봉오감', '천천히 골목 걷다가 마주친 오봉오감. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "힐링"]'::jsonb, 35.892970, 128.581411, '2026-04-21T00:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002100', '54500700-0000-4000-8000-000000000144', 'p-tourapi-3357398', '송해기념관 선비체험관', '평일 연차 쓰고 혼자 송해기념관 선비체험관 다녀옴. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.771460, 128.489131, '2026-06-25T14:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002101', '54500700-0000-4000-8000-000000000189', 'p-tourapi-1089992', '대전교통문화연수원', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 36.377079, 127.386481, '2026-04-11T09:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002102', '54500700-0000-4000-8000-000000000157', 'p-tourapi-3067572', '점핑고', '비 오는 날 운치 찾아 점핑고 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 36.787863, 127.121559, '2026-02-18T17:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002103', '54500700-0000-4000-8000-000000000093', 'p-tourapi-3457765', '인천애뜰', '기대 이상으로 너무 좋았던 인천애뜰! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.455087, 126.706020, '2026-02-20T09:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002104', '54500700-0000-4000-8000-000000000081', 'p-tourapi-127014', '안동 유일재 종택', '비 오는 날 운치 찾아 안동 유일재 종택 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "방문팁", "사진맛집", "온마루"]'::jsonb, 36.616371, 128.773938, '2026-02-08T17:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002105', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2707242', '위연재', '날씨가 너무 맑아서 위연재 한 바퀴 돌고 왔네요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "고즈넉", "혼자여행", "온마루"]'::jsonb, 35.836065, 129.217751, '2026-04-17T07:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002106', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2598702', '마골댁', '은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.557831, 129.372879, '2026-03-09T18:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002107', '54500700-0000-4000-8000-000000000066', 'p-tourapi-1882550', '토향고택', '토향고택 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 36.896541, 128.714742, '2026-02-19T11:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002108', '54500700-0000-4000-8000-000000000063', 'p-tourapi-3438160', '통인 1939', '드라이브 겸 나들이로 통인 1939 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "방문팁", "주말나들이"]'::jsonb, 37.579189, 126.970891, '2026-01-05T18:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002109', '54500700-0000-4000-8000-000000000163', 'p-tourapi-3532990', '더옐로우', '드라이브 겸 나들이로 더옐로우 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.835137, 129.207330, '2026-03-19T00:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002110', '54500700-0000-4000-8000-000000000184', 'p-tourapi-1992090', '논산 명재고택', '기대 이상으로 너무 좋았던 논산 명재고택! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "인생샷", "데이트"]'::jsonb, 36.281991, 127.131234, '2026-03-01T00:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002111', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2600265', '섬계고택', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "가족여행", "사진맛집", "온마루"]'::jsonb, 36.734568, 128.618534, '2026-04-01T07:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002112', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2804401', '서울한옥스테이(jnpstay)', '조용히 사색하고 싶어서 찾은 서울한옥스테이(jnpstay). 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "힐링", "풍경맛집"]'::jsonb, 37.576894, 126.970726, '2026-01-15T08:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002113', '54500700-0000-4000-8000-000000000074', 'p-tourapi-1610542', '달성 조길방 고택', '천천히 골목 걷다가 마주친 달성 조길방 고택. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "고즈넉", "사색", "온마루"]'::jsonb, 35.756069, 128.581730, '2026-02-12T07:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002114', '54500700-0000-4000-8000-000000000163', 'p-tourapi-1600674', '장철성고택', '날씨가 너무 맑아서 장철성고택 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "가족여행", "방문팁"]'::jsonb, 35.770120, 127.002684, '2026-02-05T02:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002115', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2568571', '1928 쉼마루', '날씨가 너무 맑아서 1928 쉼마루 한 바퀴 돌고 왔네요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 35.811634, 127.152734, '2026-01-20T18:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002116', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2795229', '한지생각이닥', '평일 연차 쓰고 혼자 한지생각이닥 다녀옴. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 37.470344, 126.626518, '2026-01-26T09:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002117', '54500700-0000-4000-8000-000000000113', 'p-tourapi-2679990', '신라불교초전지', '평일 연차 쓰고 혼자 신라불교초전지 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "힐링", "고즈넉", "온마루"]'::jsonb, 36.291026, 128.363532, '2026-02-20T09:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002118', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2607661', '남악종택', '날씨가 너무 맑아서 남악종택 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "사진맛집", "데이트", "온마루"]'::jsonb, 36.687846, 128.384149, '2026-02-19T22:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002119', '54500700-0000-4000-8000-000000000189', 'p-tourapi-1883135', '안동고택 이상루', '해 질 무렵에 안동고택 이상루 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "풍경맛집", "혼자여행"]'::jsonb, 36.635000, 128.678850, '2026-04-11T04:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002120', '54500700-0000-4000-8000-000000000181', 'p-tourapi-3033516', '논산한옥마을', '부모님 모시고 논산한옥마을 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "사진맛집"]'::jsonb, 36.211758, 127.180926, '2026-02-08T17:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002121', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2707438', '하은재', '평일 연차 쓰고 혼자 하은재 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링", "고즈넉"]'::jsonb, 37.582197, 126.971243, '2026-03-24T11:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002122', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2700309', '경주읍성한옥', '천천히 골목 걷다가 마주친 경주읍성한옥. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이", "온마루"]'::jsonb, 35.849193, 129.211505, '2026-02-25T08:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002123', '54500700-0000-4000-8000-000000000078', 'p-tourapi-1600674', '장철성고택', '날씨가 너무 맑아서 장철성고택 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.770391, 127.002682, '2026-03-22T17:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002124', '54500700-0000-4000-8000-000000000182', 'p-tourapi-126973', '이충무공자당기거지', 'SNS에서 사진 보고 찾아간 이충무공자당기거지, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "방문팁", "데이트"]'::jsonb, 34.740221, 127.683773, '2026-01-06T07:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002125', '54500700-0000-4000-8000-000000000140', 'p-tourapi-3021290', '자작자작협동조합', '주말에 친구들이랑 자작자작협동조합 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 36.968890, 127.932733, '2026-02-01T02:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002126', '54500700-0000-4000-8000-000000000141', 'p-tourapi-794941', '안동 진성이씨 종택', '비 오는 날 운치 찾아 안동 진성이씨 종택 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 36.639612, 128.741952, '2026-02-07T11:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002127', '54500700-0000-4000-8000-000000000111', 'p-tourapi-3009051', '도깨비 양조장', '근처 여행 코스로 도깨비 양조장 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "혼자여행", "사색", "온마루"]'::jsonb, 37.026286, 128.384694, '2026-01-31T15:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002128', '54500700-0000-4000-8000-000000000073', 'p-tourapi-3438504', '한옥 포지티브스', '해 질 무렵에 한옥 포지티브스 방문했는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.641444, 126.939643, '2026-02-26T13:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002129', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3432261', '인천업사이클에코센터', '해 질 무렵에 인천업사이클에코센터 방문했는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "인생샷", "사진맛집", "온마루"]'::jsonb, 37.443317, 126.655232, '2026-03-22T13:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002130', '54500700-0000-4000-8000-000000000176', 'p-tourapi-2992824', '락고재 컬쳐 라운지 애가헌', '조용히 사색하고 싶어서 찾은 락고재 컬쳐 라운지 애가헌. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.581924, 126.983726, '2026-01-24T05:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002131', '54500700-0000-4000-8000-000000000174', 'p-tourapi-129448', '두륜산케이블카', '해 질 무렵에 두륜산케이블카 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["방문팁", "사진맛집"]'::jsonb, 34.496836, 126.625002, '2026-01-27T08:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002132', '54500700-0000-4000-8000-000000000079', 'p-tourapi-128594', '창녕 석리 성씨고가', '조용히 사색하고 싶어서 찾은 창녕 석리 성씨고가. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.556971, 128.459774, '2026-02-23T00:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002133', '54500700-0000-4000-8000-000000000178', 'p-tourapi-1310884', '고성장산리허씨고가', '비 오는 날 운치 찾아 고성장산리허씨고가 다녀왔어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 35.060545, 128.323726, '2026-03-15T10:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002134', '54500700-0000-4000-8000-000000000114', 'p-tourapi-3544376', '강릉종합사회복지관', '기대 이상으로 너무 좋았던 강릉종합사회복지관! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 37.764599, 128.915902, '2026-04-17T10:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002135', '54500700-0000-4000-8000-000000000135', 'p-tourapi-2598297', '목재고택', '오랜만에 여유 찾으러 목재고택 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "풍경맛집"]'::jsonb, 36.742798, 128.864207, '2026-03-18T03:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002136', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3532720', '메모리스테이 효자', 'SNS에서 사진 보고 찾아간 메모리스테이 효자, 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "사진맛집", "가족여행"]'::jsonb, 37.582663, 126.971427, '2026-03-14T14:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002137', '54500700-0000-4000-8000-000000000135', 'p-tourapi-2822429', '아산 외암마을 건재고택', '오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 36.730848, 127.016219, '2026-01-27T10:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002138', '54500700-0000-4000-8000-000000000070', 'p-tourapi-128177', '낭추골 현장체험학습원', '예전부터 가보고 싶었던 낭추골 현장체험학습원 드디어 방문! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 36.597783, 127.617840, '2026-03-08T19:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002139', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2679990', '신라불교초전지', '예전부터 가보고 싶었던 신라불교초전지 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "인생샷", "방문팁"]'::jsonb, 36.290904, 128.363157, '2026-03-20T07:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002140', '54500700-0000-4000-8000-000000000079', 'p-tourapi-4065913', '청원루', '평일 연차 쓰고 혼자 청원루 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 36.579646, 128.548440, '2026-03-10T10:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002141', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2613459', '공주 중학동 구 선교사 가옥', '공주 중학동 구 선교사 가옥 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "인생샷", "주말나들이"]'::jsonb, 36.449743, 127.126361, '2026-01-21T22:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002142', '54500700-0000-4000-8000-000000000121', 'p-tourapi-3354154', '삼포 만화북투어', '해 질 무렵에 삼포 만화북투어 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "풍경맛집", "온마루"]'::jsonb, 37.482273, 126.620955, '2026-02-06T09:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002143', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2684765', '강화 원도심 스토리워크', '드라이브 겸 나들이로 강화 원도심 스토리워크 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "가족여행", "온마루"]'::jsonb, 37.748108, 126.486043, '2026-01-10T21:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002144', '54500700-0000-4000-8000-000000000151', 'p-tourapi-3351556', '서천문화예술창작공간', '해 질 무렵에 서천문화예술창작공간 방문했는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 36.008263, 126.696086, '2026-01-31T01:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002145', '54500700-0000-4000-8000-000000000080', 'p-tourapi-4093690', '삼호정', '조용히 사색하고 싶어서 찾은 삼호정. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 35.464606, 126.625206, '2026-04-13T19:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002146', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2572898', '고현당', '천천히 골목 걷다가 마주친 고현당. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "데이트", "주말나들이"]'::jsonb, 35.815047, 127.153809, '2026-02-01T21:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002147', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2706047', '한옥 게스트하우스 동촌재', '부모님 모시고 한옥 게스트하우스 동촌재 산책 겸 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["주말나들이", "사진맛집", "방문팁"]'::jsonb, 37.580184, 126.969870, '2026-01-28T23:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002148', '54500700-0000-4000-8000-000000000111', 'p-tourapi-129125', '서산 경주김씨 고택', '해 질 무렵에 서산 경주김씨 고택 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "풍경맛집", "사색"]'::jsonb, 36.741354, 126.519490, '2026-01-15T04:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002149', '54500700-0000-4000-8000-000000000185', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '거창 갈계리 임씨고가 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "인생샷", "방문팁", "온마루"]'::jsonb, 35.780563, 127.818653, '2026-03-23T03:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002150', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2638521', '영천 목재문화체험장', '드라이브 겸 나들이로 영천 목재문화체험장 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 36.142475, 128.978657, '2026-02-24T16:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002151', '54500700-0000-4000-8000-000000000143', 'p-tourapi-4104618', '함계정사', '오랜만에 여유 찾으러 함계정사 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "산책로", "혼자여행", "온마루"]'::jsonb, 36.047492, 128.978070, '2026-01-18T21:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002152', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2854436', '옥천전통문화체험관', '부모님 모시고 옥천전통문화체험관 산책 겸 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 36.316742, 127.585073, '2026-01-17T23:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002153', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2751703', '달팽이', '평일 연차 쓰고 혼자 달팽이 다녀옴. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 35.413864, 127.616592, '2026-04-11T17:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002154', '54500700-0000-4000-8000-000000000112', 'p-tourapi-128046', '여주 황포돛배', '평일 연차 쓰고 혼자 여주 황포돛배 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 37.292810, 127.666606, '2026-02-01T04:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002155', '54500700-0000-4000-8000-000000000109', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '오랜만에 여유 찾으러 거창 갈계리 임씨고가 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 35.780299, 127.818860, '2026-04-12T08:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002156', '54500700-0000-4000-8000-000000000105', 'p-tourapi-1872077', '석정댁', '기대 이상으로 너무 좋았던 석정댁! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로", "사색"]'::jsonb, 35.666992, 128.228693, '2026-01-08T19:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002157', '54500700-0000-4000-8000-000000000115', 'p-tourapi-1971911', '채원당', '부모님 모시고 채원당 산책 겸 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "데이트", "사진맛집"]'::jsonb, 35.275975, 127.306639, '2026-01-13T13:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002158', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2820068', '누리마루숲', '오랜만에 여유 찾으러 누리마루숲 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "힐링", "풍경맛집"]'::jsonb, 36.814588, 127.170644, '2026-02-28T07:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002159', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3089931', '모영재', '통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "풍경맛집"]'::jsonb, 35.934190, 128.718599, '2026-01-25T07:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002160', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2946527', '리얼 이스케이프 챌린지', 'SNS에서 사진 보고 찾아간 리얼 이스케이프 챌린지, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "인생샷", "데이트", "온마루"]'::jsonb, 37.554191, 126.927299, '2026-02-23T21:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002161', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2481866', '백인제가옥', '백인제가옥 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉", "풍경맛집"]'::jsonb, 37.580438, 126.984231, '2026-03-05T08:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002162', '54500700-0000-4000-8000-000000000176', 'p-tourapi-3508744', '주식회사더정원의뜰', '날씨가 너무 맑아서 주식회사더정원의뜰 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 37.628767, 127.209143, '2026-01-07T01:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002163', '54500700-0000-4000-8000-000000000094', 'p-tourapi-1393351', '연제 안승갑 고가', '오랜만에 여유 찾으러 연제 안승갑 고가 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "혼자여행", "사색", "온마루"]'::jsonb, 36.846430, 127.353198, '2026-03-26T07:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002164', '54500700-0000-4000-8000-000000000166', 'p-tourapi-3532770', '월하고택', '주말에 친구들이랑 월하고택 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "사진맛집", "주말나들이", "온마루"]'::jsonb, 37.719601, 127.313195, '2026-01-14T06:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002165', '54500700-0000-4000-8000-000000000148', 'p-tourapi-4012463', '검무한옥 휴복당', '기대 이상으로 너무 좋았던 검무한옥 휴복당! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "사진맛집", "주말나들이"]'::jsonb, 36.575540, 128.511642, '2026-01-21T04:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002166', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2662467', '만천하 알파인코스터', '기대 이상으로 너무 좋았던 만천하 알파인코스터! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이", "데이트"]'::jsonb, 36.977643, 128.336691, '2026-01-23T14:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002167', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2789519', '황병산사냥민속놀이체험관', '조용히 사색하고 싶어서 찾은 황병산사냥민속놀이체험관. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 37.707083, 128.687438, '2026-03-01T16:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002168', '54500700-0000-4000-8000-000000000151', 'p-tourapi-1600719', '정종수 고택', '정종수 고택 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.773993, 126.858820, '2026-04-17T15:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002169', '54500700-0000-4000-8000-000000000164', 'p-tourapi-3469943', '안동별장', '안동별장 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 36.566172, 128.716946, '2026-03-30T12:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002170', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2777931', '생산소', '조용히 사색하고 싶어서 찾은 생산소. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "힐링", "산책로"]'::jsonb, 36.243388, 126.887801, '2026-04-07T06:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002171', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2000964', '향단', '천천히 골목 걷다가 마주친 향단. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 36.000148, 129.252616, '2026-04-05T13:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002172', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2820893', '평창사랑', '비 오는 날 운치 찾아 평창사랑 다녀왔어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 37.490270, 128.410918, '2026-01-12T16:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002173', '54500700-0000-4000-8000-000000000135', 'p-tourapi-231892', '안동 의성김씨 종택', '오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 36.535751, 128.856277, '2026-01-22T08:42:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002174', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2610294', '문경 가은오픈세트장', '기대 이상으로 너무 좋았던 문경 가은오픈세트장! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 36.653657, 128.062208, '2026-03-02T18:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002175', '54500700-0000-4000-8000-000000000139', 'p-tourapi-662234', '순천전통야생차체험관', '드라이브 겸 나들이로 순천전통야생차체험관 선택했는데 대만족! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "사진맛집", "인생샷"]'::jsonb, 34.994722, 127.334051, '2026-02-07T02:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002176', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2604806', '목임당', '조용히 사색하고 싶어서 찾은 목임당. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 34.951804, 127.201459, '2026-02-08T20:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002177', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2686588', '오성한옥마을', '주말에 친구들이랑 오성한옥마을 들렀는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "가족여행", "방문팁"]'::jsonb, 35.903369, 127.243563, '2026-01-04T09:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002178', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2046122', '정강원 관광농원', '천천히 골목 걷다가 마주친 정강원 관광농원. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 37.570283, 128.408326, '2026-02-12T04:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002179', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3451224', '은계2어울림센터', '평일 연차 쓰고 혼자 은계2어울림센터 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 37.435945, 126.797965, '2026-01-26T03:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002180', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2961964', '하정사색', '드라이브 겸 나들이로 하정사색 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 35.408476, 127.382271, '2026-04-06T16:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002181', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2796968', '진주공예창작지원센터', 'SNS에서 사진 보고 찾아간 진주공예창작지원센터, 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 35.246606, 128.042949, '2026-01-18T01:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002182', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2569150', '서울이야기 한옥(서울이야기한옥게스트하우스)', '예전부터 가보고 싶었던 서울이야기 한옥(서울이야기한옥게스트하우스) 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "풍경맛집", "사색", "온마루"]'::jsonb, 37.577274, 126.984457, '2026-04-11T01:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002183', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2588636', '부안청림천문대', '기대 이상으로 너무 좋았던 부안청림천문대! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "고즈넉", "온마루"]'::jsonb, 35.657914, 126.615646, '2026-01-11T15:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002184', '54500700-0000-4000-8000-000000000120', 'p-tourapi-3454383', '이응노의 집 고암이응노생가기념관', '근처 여행 코스로 이응노의 집 고암이응노생가기념관 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.622768, 126.632163, '2026-03-29T17:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002185', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2603884', '연당', '예전부터 가보고 싶었던 연당 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "사진맛집", "방문팁"]'::jsonb, 37.582929, 126.987321, '2026-02-13T19:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002186', '54500700-0000-4000-8000-000000000056', 'p-tourapi-1626843', '음성 공산정 고택', '음성 공산정 고택 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "힐링", "산책로"]'::jsonb, 37.077283, 127.638934, '2026-02-19T12:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002187', '54500700-0000-4000-8000-000000000067', 'p-tourapi-3438573', '자단', '천천히 골목 걷다가 마주친 자단. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "혼자여행", "힐링", "온마루"]'::jsonb, 35.823977, 127.153662, '2026-03-24T21:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002188', '54500700-0000-4000-8000-000000000145', 'p-tourapi-3438587', '빌라오', '오랜만에 여유 찾으러 빌라오 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 34.953560, 127.479963, '2026-02-11T02:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002189', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1992090', '논산 명재고택', '논산 명재고택 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "데이트", "방문팁"]'::jsonb, 36.282258, 127.131105, '2026-01-06T01:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002190', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2996333', '모단아트(모단공예협동조합)', '모단아트(모단공예협동조합) 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집", "사색", "온마루"]'::jsonb, 35.227599, 128.879821, '2026-04-06T02:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002191', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2531357', '경주한옥1번가', '툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "혼자여행", "힐링", "온마루"]'::jsonb, 35.825858, 129.213305, '2026-02-27T17:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002192', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2050197', '어련당', '어련당 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.573919, 129.350004, '2026-03-13T22:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002193', '54500700-0000-4000-8000-000000000170', 'p-tourapi-3108226', '사단법인 푸른차문화연구원', '사단법인 푸른차문화연구원 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "방문팁", "가족여행"]'::jsonb, 35.834947, 128.677422, '2026-02-06T08:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002194', '54500700-0000-4000-8000-000000000087', 'p-tourapi-1997202', '여수 해상케이블카', '천천히 골목 걷다가 마주친 여수 해상케이블카. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["가족여행", "데이트", "온마루"]'::jsonb, 34.731147, 127.739209, '2026-03-18T20:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002195', '54500700-0000-4000-8000-000000000160', 'p-tourapi-3438527', '한울타리', '날씨가 너무 맑아서 한울타리 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 37.641485, 126.938842, '2026-01-04T21:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002196', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2786845', '함양 일두고택', '기대 이상으로 너무 좋았던 함양 일두고택! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 35.566469, 127.768272, '2026-01-23T17:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002197', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2698914', '한옥펜션 나비의 꿈', '예전부터 가보고 싶었던 한옥펜션 나비의 꿈 드디어 방문! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 35.607918, 126.585088, '2026-03-02T08:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002198', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3102033', '풍경의 아침', '오랜만에 여유 찾으러 풍경의 아침 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 35.387970, 126.885334, '2026-02-26T06:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002199', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2603733', '중제고택', '해 질 무렵에 중제고택 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 35.384813, 128.321531, '2026-03-24T12:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002200', '54500700-0000-4000-8000-000000000140', 'p-tourapi-1972012', '산에는 꽃이피네', '예전부터 가보고 싶었던 산에는 꽃이피네 드디어 방문! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "사진맛집", "주말나들이"]'::jsonb, 34.998960, 126.823273, '2026-03-11T22:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002201', '54500700-0000-4000-8000-000000000096', 'p-tourapi-3013816', '궁집', '천천히 골목 걷다가 마주친 궁집. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 37.643883, 127.230477, '2026-03-17T04:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002202', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2702472', '김종길 가옥', '평일 연차 쓰고 혼자 김종길 가옥 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 37.271208, 128.264223, '2026-02-01T01:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002203', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3444338', '완정고택', '날씨가 너무 맑아서 완정고택 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["인생샷", "사진맛집", "주말나들이"]'::jsonb, 36.004314, 128.234746, '2026-03-07T20:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002204', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2696312', '소담스테이', '근처 여행 코스로 소담스테이 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 37.547996, 126.955933, '2026-03-01T01:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002205', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2668037', '월암종택(김호장군고택)', '기대 이상으로 너무 좋았던 월암종택(김호장군고택)! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "사진맛집"]'::jsonb, 35.819659, 129.218621, '2026-03-24T05:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002206', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2850183', '대한옥', '천천히 골목 걷다가 마주친 대한옥. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉"]'::jsonb, 37.519608, 126.910920, '2026-03-08T06:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002207', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2782688', '와글아이', '근처 여행 코스로 와글아이 넣길 정말 잘했어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 37.654154, 126.775819, '2026-03-31T23:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002208', '54500700-0000-4000-8000-000000000108', 'p-tourapi-129125', '서산 경주김씨 고택', '조용히 사색하고 싶어서 찾은 서산 경주김씨 고택. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 36.740771, 126.519598, '2026-01-17T21:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002209', '54500700-0000-4000-8000-000000000095', 'p-tourapi-3438381', '북촌다락방', 'SNS에서 사진 보고 찾아간 북촌다락방, 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "인생샷", "주말나들이"]'::jsonb, 37.582709, 126.984117, '2026-01-21T23:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002210', '54500700-0000-4000-8000-000000000091', 'p-tourapi-3102203', '함라한옥체험단지', '평일 연차 쓰고 혼자 함라한옥체험단지 다녀옴. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "힐링", "풍경맛집", "온마루"]'::jsonb, 36.062656, 126.909986, '2026-01-25T22:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002211', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2604499', '보금자리', '보금자리 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 34.739813, 126.717712, '2026-02-16T03:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002212', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2775017', '주식회사 하늘', '부모님 모시고 주식회사 하늘 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링"]'::jsonb, 35.304696, 126.546550, '2026-02-23T06:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002213', '54500700-0000-4000-8000-000000000118', 'p-tourapi-736751', '화성 정시영 고택', '드라이브 겸 나들이로 화성 정시영 고택 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "풍경맛집", "사색", "온마루"]'::jsonb, 37.133184, 126.700859, '2026-03-08T19:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002214', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2753977', '울진과학체험관', '오랜만에 여유 찾으러 울진과학체험관 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 36.996404, 129.408090, '2026-01-10T01:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002215', '54500700-0000-4000-8000-000000000142', 'p-tourapi-3438579', '스테이 한울', '기대 이상으로 너무 좋았던 스테이 한울! 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "사색"]'::jsonb, 35.812515, 127.151912, '2026-04-11T23:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002216', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2939003', '영월애살으리랏다', 'SNS에서 사진 보고 찾아간 영월애살으리랏다, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 37.243748, 128.355477, '2026-03-06T18:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002217', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3072218', '오히', '해 질 무렵에 오히 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["방문팁", "주말나들이", "데이트", "온마루"]'::jsonb, 35.823967, 129.212995, '2026-03-04T03:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002218', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2753977', '울진과학체험관', '부모님 모시고 울진과학체험관 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 36.996556, 129.407946, '2026-01-25T03:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002219', '54500700-0000-4000-8000-000000000094', 'p-tourapi-3544074', '대한노인회 강릉시지회', '근처 여행 코스로 대한노인회 강릉시지회 넣길 정말 잘했어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "주말나들이", "가족여행"]'::jsonb, 37.747542, 128.884219, '2026-03-02T22:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002220', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2820629', '부여북포한옥마을', '해 질 무렵에 부여북포한옥마을 방문했는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 36.292693, 126.924205, '2026-01-13T15:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002221', '54500700-0000-4000-8000-000000000169', 'p-tourapi-3102073', '오원 스테이', '오원 스테이 다녀왔어요! 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "사진맛집", "가족여행"]'::jsonb, 35.836386, 129.208647, '2026-02-13T17:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002222', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2569237', '운정루', '오랜만에 여유 찾으러 운정루 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "사색", "고즈넉"]'::jsonb, 35.791301, 129.245677, '2026-03-21T23:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002223', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2713395', '영월 북쌍리 고택', '부모님 모시고 영월 북쌍리 고택 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "산책로"]'::jsonb, 37.205746, 128.377989, '2026-01-29T17:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002224', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2569150', '서울이야기 한옥(서울이야기한옥게스트하우스)', '주말에 친구들이랑 서울이야기 한옥(서울이야기한옥게스트하우스) 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 37.576858, 126.985053, '2026-01-18T19:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002225', '54500700-0000-4000-8000-000000000081', 'p-tourapi-231931', '논산명재고택', '조용히 사색하고 싶어서 찾은 논산명재고택. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 36.282082, 127.131004, '2026-01-22T07:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002226', '54500700-0000-4000-8000-000000000180', 'p-tourapi-3438452', '담서제', 'SNS에서 사진 보고 찾아간 담서제, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "데이트", "방문팁"]'::jsonb, 37.640553, 126.939115, '2026-03-31T21:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002227', '54500700-0000-4000-8000-000000000110', 'p-tourapi-126419', '다산초당', '비 오는 날 운치 찾아 다산초당 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 34.580783, 126.744870, '2026-03-25T13:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002228', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3533114', '스테이여유담', '마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 35.051502, 126.863886, '2026-01-14T20:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002229', '54500700-0000-4000-8000-000000000072', 'p-tourapi-127704', '창원 진해현 관아 및 객사유지', '해 질 무렵에 창원 진해현 관아 및 객사유지 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 35.114987, 128.488154, '2026-01-21T15:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002230', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2614384', '윤동주 유고보존 정병욱 가옥', 'SNS에서 사진 보고 찾아간 윤동주 유고보존 정병욱 가옥, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 34.970908, 127.759024, '2026-03-06T09:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002231', '54500700-0000-4000-8000-000000000176', 'p-tourapi-2647939', '고스락', '해 질 무렵에 고스락 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "주말나들이", "사진맛집", "온마루"]'::jsonb, 36.046017, 126.960219, '2026-04-01T17:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002232', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3066280', '전주일몽', '해 질 무렵에 전주일몽 방문했는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["사진맛집", "방문팁", "데이트"]'::jsonb, 35.812298, 127.154313, '2026-02-07T19:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002233', '54500700-0000-4000-8000-000000000134', 'p-tourapi-3337761', '마마스홈퀴진', '드라이브 겸 나들이로 마마스홈퀴진 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색", "힐링", "온마루"]'::jsonb, 35.561632, 129.116774, '2026-01-21T04:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002234', '54500700-0000-4000-8000-000000000189', 'p-tourapi-3438590', '중정별채', '드라이브 겸 나들이로 중정별채 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "산책로", "고즈넉"]'::jsonb, 35.076794, 126.685516, '2026-03-31T13:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002235', '54500700-0000-4000-8000-000000000194', 'p-tourapi-3072219', '북촌빈관 by 락고재', '날씨가 너무 맑아서 북촌빈관 by 락고재 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 37.582492, 126.984532, '2026-04-08T06:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002236', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3469978', '호연담', '비 오는 날 운치 찾아 호연담 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["사진맛집", "인생샷"]'::jsonb, 37.910371, 127.742035, '2026-02-08T07:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002237', '54500700-0000-4000-8000-000000000186', 'p-tourapi-561914', '원주변씨 간재종택 및 간재정', '고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉"]'::jsonb, 36.600955, 128.677241, '2026-04-17T01:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002238', '54500700-0000-4000-8000-000000000195', 'p-tourapi-2600221', '박정우가옥', '비 오는 날 운치 찾아 박정우가옥 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "데이트", "주말나들이"]'::jsonb, 36.734838, 128.619718, '2026-01-20T12:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002239', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2587036', '백년한옥', '주말에 친구들이랑 백년한옥 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 35.815999, 127.155264, '2026-02-27T20:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002240', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3438581', '교동94', '오랜만에 여유 찾으러 교동94 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "사색", "고즈넉"]'::jsonb, 35.812821, 127.152392, '2026-04-08T02:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002241', '54500700-0000-4000-8000-000000000115', 'p-tourapi-264284', '전북 전주 한옥마을 [슬로시티]', '전북 전주 한옥마을 [슬로시티] 다녀왔어요! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.818185, 127.153438, '2026-03-20T05:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002242', '54500700-0000-4000-8000-000000000085', 'p-tourapi-3351567', '충남안전체험관', '천천히 골목 걷다가 마주친 충남안전체험관. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "방문팁", "사진맛집", "온마루"]'::jsonb, 36.821945, 127.191826, '2026-02-08T10:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002243', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3533114', '스테이여유담', '해 질 무렵에 스테이여유담 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 35.051239, 126.864447, '2026-02-26T15:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002244', '54500700-0000-4000-8000-000000000099', 'p-tourapi-1964622', '스카이로드', '스카이로드 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 36.329179, 127.427772, '2026-01-07T06:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002245', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3532598', '월하', 'SNS에서 사진 보고 찾아간 월하, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 35.848039, 129.207501, '2026-03-19T03:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002246', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2608081', '여락재', '날씨가 너무 맑아서 여락재 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 34.740741, 126.718892, '2026-01-05T12:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002247', '54500700-0000-4000-8000-000000000078', 'p-tourapi-1883996', '취옹예술관', '드라이브 겸 나들이로 취옹예술관 선택했는데 대만족! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 37.752327, 127.359951, '2026-01-31T00:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002248', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2000946', '치암고택', '치암고택 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "사색", "온마루"]'::jsonb, 36.583289, 128.736076, '2026-03-16T16:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002249', '54500700-0000-4000-8000-000000000156', 'p-tourapi-1882853', '풍남헌', '비 오는 날 운치 찾아 풍남헌 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 35.816805, 127.152012, '2026-03-16T10:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002250', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3438452', '담서제', '천천히 골목 걷다가 마주친 담서제. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "인생샷", "방문팁", "온마루"]'::jsonb, 37.640477, 126.938950, '2026-01-24T15:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002251', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3438433', '호우재 한옥', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "데이트", "방문팁", "온마루"]'::jsonb, 37.595805, 126.999632, '2026-01-11T22:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002252', '54500700-0000-4000-8000-000000000143', 'p-tourapi-792208', '괴산 한지체험박물관', '부모님 모시고 괴산 한지체험박물관 산책 겸 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 36.785530, 128.015003, '2026-02-20T14:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002253', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3533132', '시월재', '조용히 사색하고 싶어서 찾은 시월재. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "혼자여행", "고즈넉"]'::jsonb, 37.290226, 127.019850, '2026-01-08T19:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002254', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2665817', '부여안방마님', '기대 이상으로 너무 좋았던 부여안방마님! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "가족여행", "방문팁", "온마루"]'::jsonb, 36.265387, 126.848468, '2026-01-21T15:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002255', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2706608', '경주오릉한옥', '천천히 골목 걷다가 마주친 경주오릉한옥. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 35.825946, 129.207509, '2026-01-21T13:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002256', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2775014', '나무키움(전의양묘영농조합법인)', '조용히 사색하고 싶어서 찾은 나무키움(전의양묘영농조합법인). 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["고즈넉", "혼자여행", "산책로"]'::jsonb, 36.676809, 127.197741, '2026-01-14T19:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002257', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2992824', '락고재 컬쳐 라운지 애가헌', '날씨가 너무 맑아서 락고재 컬쳐 라운지 애가헌 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "산책로", "혼자여행"]'::jsonb, 37.582417, 126.984002, '2026-02-19T00:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002258', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3438629', '아늑', '기대 이상으로 너무 좋았던 아늑! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "데이트", "온마루"]'::jsonb, 36.554246, 128.756699, '2026-01-08T12:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002259', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2047715', '소강고택', '부모님 모시고 소강고택 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.893705, 128.712505, '2026-01-25T09:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002260', '54500700-0000-4000-8000-000000000117', 'p-tourapi-3438589', '윤은재', '근처 여행 코스로 윤은재 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 35.033766, 126.712328, '2026-01-08T01:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002261', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2594864', '남호구택', '해 질 무렵에 남호구택 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "힐링", "산책로", "온마루"]'::jsonb, 36.893566, 128.712164, '2026-02-09T02:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002262', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2820659', '부여 선샤인', '드라이브 겸 나들이로 부여 선샤인 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "방문팁", "주말나들이", "온마루"]'::jsonb, 36.274313, 126.887296, '2026-02-16T04:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002263', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2940719', '예린당 바이 버틀러리', '예린당 바이 버틀러리 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["주말나들이", "사진맛집", "온마루"]'::jsonb, 37.578679, 126.970342, '2026-02-21T00:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002264', '54500700-0000-4000-8000-000000000149', 'p-tourapi-127274', '청주 신전동 고가', '청주 신전동 고가 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "데이트", "사진맛집"]'::jsonb, 36.609069, 127.402197, '2026-04-13T06:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002265', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2000964', '향단', '평일 연차 쓰고 혼자 향단 다녀옴. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 35.999719, 129.252599, '2026-02-24T08:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002266', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2465890', '시은재', '날씨가 너무 맑아서 시은재 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 37.573369, 126.987318, '2026-02-25T09:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002267', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2663065', '휴휴당', '조용히 사색하고 싶어서 찾은 휴휴당. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 35.835561, 129.212278, '2026-02-07T21:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002268', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2820027', '바른스포츠월드', '주말에 친구들이랑 바른스포츠월드 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "사진맛집", "온마루"]'::jsonb, 36.599475, 127.423107, '2026-03-28T14:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002269', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2650230', '문래예술공장', '오랜만에 여유 찾으러 문래예술공장 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 37.513331, 126.900107, '2026-01-23T16:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002270', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2786845', '함양 일두고택', '기대 이상으로 너무 좋았던 함양 일두고택! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 35.566238, 127.768773, '2026-01-20T17:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002271', '54500700-0000-4000-8000-000000000069', 'p-tourapi-3067458', '맘맘스', '조용히 사색하고 싶어서 찾은 맘맘스. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "산책로", "힐링", "온마루"]'::jsonb, 36.868671, 127.283624, '2026-02-04T03:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002272', '54500700-0000-4000-8000-000000000116', 'p-tourapi-125925', '아산 맹씨 행단(맹사성 고택)', '날씨가 너무 맑아서 아산 맹씨 행단(맹사성 고택) 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 36.746990, 127.041882, '2026-02-01T10:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002273', '54500700-0000-4000-8000-000000000124', 'p-tourapi-3532711', '안스테이', '드라이브 겸 나들이로 안스테이 선택했는데 대만족! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "사색", "온마루"]'::jsonb, 37.765567, 127.392683, '2026-04-04T20:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002274', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2775336', '와나스타', '근처 여행 코스로 와나스타 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 35.540465, 129.167494, '2026-03-29T20:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002275', '54500700-0000-4000-8000-000000000114', 'p-tourapi-3543415', '주문진문화교육센터', '근처 여행 코스로 주문진문화교육센터 넣길 정말 잘했어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "인생샷", "데이트"]'::jsonb, 37.881695, 128.822693, '2026-02-13T09:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002276', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2722927', '대전트래블라운지', '부모님 모시고 대전트래블라운지 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "힐링"]'::jsonb, 36.330177, 127.430108, '2026-01-08T00:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002277', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2569165', '수곡고택', '오랜만에 여유 찾으러 수곡고택 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "산책로", "혼자여행", "온마루"]'::jsonb, 36.574168, 128.526274, '2026-04-02T03:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002278', '54500700-0000-4000-8000-000000000116', 'p-tourapi-1971880', '좋은날', '평일 연차 쓰고 혼자 좋은날 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행", "힐링"]'::jsonb, 35.816956, 127.149343, '2026-01-26T00:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002279', '54500700-0000-4000-8000-000000000122', 'p-tourapi-3438041', '유선재', '날씨가 너무 맑아서 유선재 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 37.490334, 127.709326, '2026-03-27T18:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002280', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2714276', '말문화체험관', '조용히 사색하고 싶어서 찾은 말문화체험관. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 36.030520, 128.998195, '2026-04-12T07:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002281', '54500700-0000-4000-8000-000000000131', 'p-tourapi-3454469', '아동청소년친화공간 꿈이랑', '오랜만에 여유 찾으러 아동청소년친화공간 꿈이랑 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 38.199455, 128.580407, '2026-04-16T19:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002282', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2570188', '청풍헌(시랑골한옥스테이)', '침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.979492, 127.233170, '2026-01-20T10:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002283', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2788137', '화사별서(조씨고가)', '기대 이상으로 너무 좋았던 화사별서(조씨고가)! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.171301, 127.701030, '2026-01-28T12:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002284', '54500700-0000-4000-8000-000000000175', 'p-tourapi-895327', '남도한옥민박마을', '비 오는 날 운치 찾아 남도한옥민박마을 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 34.509135, 126.606172, '2026-04-10T06:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002285', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3438225', '자하', '자하 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "가족여행"]'::jsonb, 37.576861, 126.971521, '2026-01-14T06:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002286', '54500700-0000-4000-8000-000000000203', 'p-tourapi-3072227', '아담한옥', '비 오는 날 운치 찾아 아담한옥 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행", "산책로"]'::jsonb, 37.580277, 126.969581, '2026-01-06T12:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002287', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2594218', '정가한옥', '기대 이상으로 너무 좋았던 정가한옥! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 35.816550, 127.155145, '2026-01-16T08:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002288', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2768086', '한양 한옥마을점', '주말에 친구들이랑 한양 한옥마을점 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.390843, 126.638732, '2026-02-19T22:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002289', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2795956', '양평 창대리 고가', '해 질 무렵에 양평 창대리 고가 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "인생샷", "온마루"]'::jsonb, 37.471076, 127.505798, '2026-01-28T23:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002290', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2992823', 'K-컬처 스크린(대한민국역사박물관)', '기대 이상으로 너무 좋았던 K-컬처 스크린(대한민국역사박물관)! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링", "풍경맛집", "온마루"]'::jsonb, 37.574322, 126.977602, '2026-03-19T17:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002291', '54500700-0000-4000-8000-000000000137', 'p-tourapi-3582821', '한복남 프리미엄점', '예전부터 가보고 싶었던 한복남 프리미엄점 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 37.576412, 126.973693, '2026-01-05T22:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002292', '54500700-0000-4000-8000-000000000179', 'p-tourapi-1923400', '백두대간협곡열차(V-트레인)', '해 질 무렵에 백두대간협곡열차(V-트레인) 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 37.113400, 129.036548, '2026-03-27T10:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002293', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3428156', '국가유산 방문 캠페인 인천공항 홍보관', 'SNS에서 사진 보고 찾아간 국가유산 방문 캠페인 인천공항 홍보관, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 37.447742, 126.452073, '2026-04-09T02:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002294', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2595862', '온계종택 삼백당', '부모님 모시고 온계종택 삼백당 산책 겸 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 36.749962, 128.830011, '2026-02-14T12:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002295', '54500700-0000-4000-8000-000000000069', 'p-tourapi-1171915', '조선왕가', '근처 여행 코스로 조선왕가 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "데이트", "방문팁", "온마루"]'::jsonb, 38.063519, 127.101637, '2026-02-01T19:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002296', '54500700-0000-4000-8000-000000000078', 'p-tourapi-1884345', '행복드림한옥', '드라이브 겸 나들이로 행복드림한옥 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 35.905460, 127.209574, '2026-01-15T02:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002297', '54500700-0000-4000-8000-000000000113', 'p-tourapi-2576546', '홍시(전주한옥마을 숙박 홍시)', '오랜만에 여유 찾으러 홍시(전주한옥마을 숙박 홍시) 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.815107, 127.153319, '2026-01-19T22:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002298', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2680818', '산수유사랑채', '기대 이상으로 너무 좋았던 산수유사랑채! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 37.340985, 127.462590, '2026-01-08T01:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002299', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3483083', '간송옛집', 'SNS에서 사진 보고 찾아간 간송옛집, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 37.665033, 127.028250, '2026-04-09T04:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002300', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3072240', '온유헌 바이 버틀러리', '조용히 사색하고 싶어서 찾은 온유헌 바이 버틀러리. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행", "풍경맛집"]'::jsonb, 37.581731, 126.987455, '2026-03-10T07:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002301', '54500700-0000-4000-8000-000000000062', 'p-tourapi-1201060', '이천보고가', '주말에 친구들이랑 이천보고가 들렀는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "데이트"]'::jsonb, 37.798393, 127.348120, '2026-04-11T15:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002302', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3076943', '벽파정', '부모님 모시고 벽파정 산책 겸 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "사진맛집", "데이트"]'::jsonb, 34.538066, 126.344778, '2026-02-05T22:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002303', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2000725', '안동 수애당', 'SNS에서 사진 보고 찾아간 안동 수애당, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["가족여행", "사진맛집"]'::jsonb, 36.553019, 128.923290, '2026-03-01T04:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002304', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2531675', '진도한옥펜션', '조용히 사색하고 싶어서 찾은 진도한옥펜션. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 34.398222, 126.277216, '2026-03-29T13:56:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002305', '54500700-0000-4000-8000-000000000130', 'p-tourapi-2572792', '매죽헌(매죽헌 한옥 민박)', '근처 여행 코스로 매죽헌(매죽헌 한옥 민박) 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "인생샷"]'::jsonb, 35.066018, 127.404101, '2026-01-17T14:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002306', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2568571', '1928 쉼마루', 'SNS에서 사진 보고 찾아간 1928 쉼마루, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "방문팁"]'::jsonb, 35.811996, 127.152574, '2026-03-16T02:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002307', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2604602', '경주 교동한옥집', '기대 이상으로 너무 좋았던 경주 교동한옥집! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "방문팁", "데이트", "온마루"]'::jsonb, 35.829000, 129.211443, '2026-02-22T13:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002308', '54500700-0000-4000-8000-000000000158', 'p-tourapi-800971', '순창 거북장수마을 [농촌전통테마]', '날씨가 너무 맑아서 순창 거북장수마을 [농촌전통테마] 한 바퀴 돌고 왔네요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.443926, 127.211791, '2026-01-25T00:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002309', '54500700-0000-4000-8000-000000000064', 'p-tourapi-3455504', '용인특례시 가상현실스포츠체험센터', '근처 여행 코스로 용인특례시 가상현실스포츠체험센터 넣길 정말 잘했어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "혼자여행"]'::jsonb, 37.238836, 127.180766, '2026-02-16T07:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002310', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3438166', '뉠스테이', '기대 이상으로 너무 좋았던 뉠스테이! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 37.579723, 126.967602, '2026-01-23T13:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002311', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3510160', '주식회사꽃초린두레', '드라이브 겸 나들이로 주식회사꽃초린두레 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 35.348629, 128.322416, '2026-02-01T20:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002312', '54500700-0000-4000-8000-000000000158', 'p-tourapi-3089931', '모영재', '천천히 골목 걷다가 마주친 모영재. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "데이트", "인생샷", "온마루"]'::jsonb, 35.934304, 128.718729, '2026-01-06T05:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002313', '54500700-0000-4000-8000-000000000071', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '거창 갈계리 임씨고가 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "인생샷", "사진맛집"]'::jsonb, 35.780016, 127.818596, '2026-01-17T06:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002314', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2593271', '가은채', '해 질 무렵에 가은채 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "가족여행", "온마루"]'::jsonb, 35.817119, 127.153391, '2026-01-31T02:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002315', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3469822', '대동고택', '조용히 사색하고 싶어서 찾은 대동고택. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 35.821395, 127.136394, '2026-03-13T13:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002316', '54500700-0000-4000-8000-000000000082', 'p-tourapi-1998844', '춘우재고택', '예전부터 가보고 싶었던 춘우재고택 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 36.706613, 128.440976, '2026-01-28T08:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002317', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3438435', '사임당 귀한그대', '드라이브 겸 나들이로 사임당 귀한그대 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.641144, 126.940117, '2026-03-26T08:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002318', '54500700-0000-4000-8000-000000000131', 'p-tourapi-3511071', '주식회사피알아이피', '조용히 사색하고 싶어서 찾은 주식회사피알아이피. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "혼자여행", "산책로"]'::jsonb, 35.143068, 129.108372, '2026-02-07T05:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002319', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2782688', '와글아이', '근처 여행 코스로 와글아이 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 37.654241, 126.775724, '2026-04-09T05:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002320', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2593643', '목향재', '주말에 친구들이랑 목향재 들렀는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "고즈넉"]'::jsonb, 36.501773, 127.239533, '2026-01-08T11:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002321', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2627867', '가람나무', '조용히 사색하고 싶어서 찾은 가람나무. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 37.754827, 126.688889, '2026-04-03T10:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002322', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3532757', '곰곰하우스', '드라이브 겸 나들이로 곰곰하우스 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 37.581509, 126.986532, '2026-02-06T16:53:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002323', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2627867', '가람나무', '해 질 무렵에 가람나무 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 37.754627, 126.688744, '2026-03-10T14:21:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002324', '54500700-0000-4000-8000-000000000115', 'p-tourapi-1872349', '순천만 해룡성고택', '예전부터 가보고 싶었던 순천만 해룡성고택 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 34.919945, 127.502423, '2026-02-13T03:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002325', '54500700-0000-4000-8000-000000000068', 'p-tourapi-1882210', '얼음골한옥펜션', '조용히 사색하고 싶어서 찾은 얼음골한옥펜션. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "힐링", "고즈넉", "온마루"]'::jsonb, 35.598279, 128.952860, '2026-04-05T05:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002326', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2746709', '파주팜랜드', '드라이브 겸 나들이로 파주팜랜드 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "가족여행", "사진맛집"]'::jsonb, 37.810215, 126.692386, '2026-03-15T14:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002327', '54500700-0000-4000-8000-000000000171', 'p-tourapi-3469889', '석주재', '해 질 무렵에 석주재 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로", "힐링", "온마루"]'::jsonb, 35.510796, 128.837683, '2026-04-04T16:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002328', '54500700-0000-4000-8000-000000000129', 'p-tourapi-129517', '예천 예천권씨 초간공파 종택 및 예천권씨 초간종택 별당', '평일 연차 쓰고 혼자 예천 예천권씨 초간공파 종택 및 예천권씨 초간종택 별당 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.692127, 128.398082, '2026-03-28T00:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002329', '54500700-0000-4000-8000-000000000072', 'p-tourapi-3531662', '최선평 가옥', '주말에 친구들이랑 최선평 가옥 들렀는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 37.878167, 128.796075, '2026-01-31T02:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002330', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2782543', '보성 이진래고택', '예전부터 가보고 싶었던 보성 이진래고택 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "방문팁", "가족여행"]'::jsonb, 34.762973, 127.186433, '2026-02-11T02:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002331', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2778518', '주포지구한옥전원마을', '해 질 무렵에 주포지구한옥전원마을 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 35.091956, 126.460935, '2026-04-11T23:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002332', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2613676', '전주한옥숙박 사랑루', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로", "풍경맛집"]'::jsonb, 35.811881, 127.154212, '2026-01-05T07:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002333', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2786859', '읍청정(산청)', '부모님 모시고 읍청정(산청) 산책 겸 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.308916, 127.965486, '2026-04-14T06:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002334', '54500700-0000-4000-8000-000000000124', 'p-tourapi-128559', '농암종택', '오랜만에 여유 찾으러 농암종택 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "사색", "힐링", "온마루"]'::jsonb, 36.763621, 128.884985, '2026-01-22T17:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002335', '54500700-0000-4000-8000-000000000160', 'p-tourapi-250364', '문화역 서울 284', '드라이브 겸 나들이로 문화역 서울 284 선택했는데 대만족! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 37.556144, 126.971626, '2026-01-15T07:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002336', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2774723', '니지모리 스튜디오', '예전부터 가보고 싶었던 니지모리 스튜디오 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "사진맛집", "데이트"]'::jsonb, 37.879704, 127.092904, '2026-02-19T07:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002337', '54500700-0000-4000-8000-000000000201', 'p-tourapi-1583188', '조해영가옥', '오랜만에 여유 찾으러 조해영가옥 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 36.060872, 126.910848, '2026-01-04T20:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002338', '54500700-0000-4000-8000-000000000140', 'p-tourapi-802566', '광주 산두른마을', '비 오는 날 운치 찾아 광주 산두른마을 다녀왔어요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "데이트", "사진맛집", "온마루"]'::jsonb, 37.279324, 127.291066, '2026-04-08T07:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002339', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2994636', '다담한옥', '조용히 사색하고 싶어서 찾은 다담한옥. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.588279, 129.059971, '2026-04-05T22:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002340', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3533131', '안동한옥스테이휴', '부모님 모시고 안동한옥스테이휴 산책 겸 다녀왔습니다. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.560484, 128.711911, '2026-01-04T20:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002341', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2775365', '바다공룡 워케이션', '조용히 사색하고 싶어서 찾은 바다공룡 워케이션. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "풍경맛집", "사색"]'::jsonb, 35.016925, 128.298005, '2026-01-27T18:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002342', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3533113', '금천재', '비 오는 날 운치 찾아 금천재 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "주말나들이"]'::jsonb, 35.032445, 126.755546, '2026-02-26T15:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002343', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438622', '스테이 나스러움', '주말에 친구들이랑 스테이 나스러움 들렀는데 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 36.563494, 128.713230, '2026-01-23T11:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002344', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3102104', '도담헌', '드라이브 겸 나들이로 도담헌 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "주말나들이", "가족여행"]'::jsonb, 34.945699, 127.484062, '2026-01-09T15:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002345', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2932973', '다올재', '다올재 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 34.955057, 127.480623, '2026-02-28T20:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002346', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2900858', '제천비행장', '날씨가 너무 맑아서 제천비행장 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 37.162620, 128.213801, '2026-02-17T18:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002347', '54500700-0000-4000-8000-000000000148', 'p-tourapi-127223', '남성재', '기대 이상으로 너무 좋았던 남성재! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "사진맛집"]'::jsonb, 35.973346, 129.353201, '2026-01-12T12:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002348', '54500700-0000-4000-8000-000000000129', 'p-tourapi-250372', '의성김씨 학봉종택', '부모님 모시고 의성김씨 학봉종택 산책 겸 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 36.609465, 128.669009, '2026-03-16T10:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002349', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2531357', '경주한옥1번가', '날씨가 너무 맑아서 경주한옥1번가 한 바퀴 돌고 왔네요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.825611, 129.213059, '2026-04-17T07:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002350', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2668037', '월암종택(김호장군고택)', '비 오는 날 운치 찾아 월암종택(김호장군고택) 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.819657, 129.219120, '2026-04-05T09:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002351', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2373420', '아띠인력거', '드라이브 겸 나들이로 아띠인력거 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "힐링"]'::jsonb, 37.579237, 126.982535, '2026-02-24T06:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002352', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2804370', '화담재', '기대 이상으로 너무 좋았던 화담재! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 34.739233, 126.716794, '2026-03-21T07:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002353', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2817792', '밀알영농조합', '드라이브 겸 나들이로 밀알영농조합 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "풍경맛집", "고즈넉"]'::jsonb, 35.081605, 128.185804, '2026-02-27T15:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002354', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2681174', '고선재', '주말에 친구들이랑 고선재 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 36.565750, 127.517944, '2026-01-15T06:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002355', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2996825', '애플트리 힐링팜', '예전부터 가보고 싶었던 애플트리 힐링팜 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 35.557425, 127.099052, '2026-02-12T05:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002356', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2660696', '세연재', '천천히 골목 걷다가 마주친 세연재. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "주말나들이", "가족여행"]'::jsonb, 37.640318, 126.939962, '2026-04-09T20:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002357', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2932894', '주월재', '평일 연차 쓰고 혼자 주월재 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 34.779285, 127.167473, '2026-01-17T22:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002358', '54500700-0000-4000-8000-000000000174', 'p-tourapi-231933', '경주 양동 무첨당', '기대 이상으로 너무 좋았던 경주 양동 무첨당! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "인생샷", "주말나들이", "온마루"]'::jsonb, 36.001972, 129.252701, '2026-01-07T14:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002359', '54500700-0000-4000-8000-000000000119', 'p-tourapi-1566740', '양평 맑은숲캠프', '근처 여행 코스로 양평 맑은숲캠프 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "힐링"]'::jsonb, 37.562106, 127.734330, '2026-03-21T08:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002360', '54500700-0000-4000-8000-000000000189', 'p-tourapi-3425093', '서울 인디스페이스', '날씨가 너무 맑아서 서울 인디스페이스 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "방문팁", "주말나들이", "온마루"]'::jsonb, 37.557250, 126.924972, '2026-04-17T23:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002361', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1846830', '남도해양열차 에스트레인(S-train)', '오랜만에 여유 찾으러 남도해양열차 에스트레인(S-train) 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 35.115020, 129.042109, '2026-01-19T00:54:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002362', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2049307', '녹운재', '예전부터 가보고 싶었던 녹운재 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 35.902763, 127.242275, '2026-04-13T22:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002363', '54500700-0000-4000-8000-000000000121', 'p-tourapi-1883590', '옥연정사', '근처 여행 코스로 옥연정사 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 36.543503, 128.518045, '2026-02-20T10:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002364', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2775336', '와나스타', '와나스타 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링", "사색", "온마루"]'::jsonb, 35.540340, 129.167324, '2026-02-19T03:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002365', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2606219', '영천전투메모리얼파크', '근처 여행 코스로 영천전투메모리얼파크 넣길 정말 잘했어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["데이트", "방문팁", "온마루"]'::jsonb, 35.973240, 128.926888, '2026-02-23T01:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002366', '54500700-0000-4000-8000-000000000134', 'p-tourapi-3438225', '자하', '비 오는 날 운치 찾아 자하 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁", "데이트", "온마루"]'::jsonb, 37.576897, 126.971212, '2026-02-27T06:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002367', '54500700-0000-4000-8000-000000000195', 'p-tourapi-2570532', '한옥미담(전주한옥마을 한옥미담)', '오랜만에 여유 찾으러 한옥미담(전주한옥마을 한옥미담) 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 35.819191, 127.150501, '2026-04-05T23:16:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002368', '54500700-0000-4000-8000-000000000161', 'p-tourapi-1590555', '이웅재고가', '예전부터 가보고 싶었던 이웅재고가 드디어 방문! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 35.504282, 127.316921, '2026-04-15T18:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002369', '54500700-0000-4000-8000-000000000202', 'p-tourapi-1620863', '양금석가옥', '기대 이상으로 너무 좋았던 양금석가옥! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 33.291315, 126.628720, '2026-01-18T04:19:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002370', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3072271', '청담', '주말에 친구들이랑 청담 들렀는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 36.456104, 127.120218, '2026-03-14T15:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002371', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2576371', '월출산 달빛정원', '조용히 사색하고 싶어서 찾은 월출산 달빛정원. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 34.770899, 126.653313, '2026-04-05T12:35:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002372', '54500700-0000-4000-8000-000000000139', 'p-tourapi-1623828', '안동권씨유회당종가일원', '드라이브 겸 나들이로 안동권씨유회당종가일원 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "주말나들이", "인생샷"]'::jsonb, 36.277573, 127.404699, '2026-03-21T12:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002373', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2607787', '꿈', '해 질 무렵에 꿈 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 35.812779, 127.153992, '2026-02-08T01:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002374', '54500700-0000-4000-8000-000000000135', 'p-tourapi-2409490', '만회고택', '근처 여행 코스로 만회고택 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "가족여행", "주말나들이"]'::jsonb, 36.897116, 128.715533, '2026-03-26T13:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002375', '54500700-0000-4000-8000-000000000160', 'p-tourapi-3532743', '아늑한가 서울한옥 스테이 풀빌라 스파펜션', '천천히 골목 걷다가 마주친 아늑한가 서울한옥 스테이 풀빌라 스파펜션. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.693748, 127.044001, '2026-02-01T21:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002376', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2786845', '함양 일두고택', '천천히 골목 걷다가 마주친 함양 일두고택. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["방문팁", "사진맛집", "주말나들이"]'::jsonb, 35.566503, 127.768125, '2026-04-17T21:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002377', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2775365', '바다공룡 워케이션', '천천히 골목 걷다가 마주친 바다공룡 워케이션. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.016570, 128.297968, '2026-01-09T08:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002378', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2680818', '산수유사랑채', '산수유사랑채 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "고즈넉", "힐링"]'::jsonb, 37.340605, 127.462100, '2026-01-26T19:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002379', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2713848', '수상한마법학교', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "주말나들이"]'::jsonb, 37.730707, 128.878787, '2026-01-26T23:06:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002380', '54500700-0000-4000-8000-000000000088', 'p-tourapi-231909', '안동 예안이씨 충효당', '천천히 골목 걷다가 마주친 안동 예안이씨 충효당. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 36.574289, 128.579803, '2026-02-14T15:08:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002381', '54500700-0000-4000-8000-000000000093', 'p-tourapi-1992717', '의성 소우당', 'SNS에서 사진 보고 찾아간 의성 소우당, 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "주말나들이", "데이트", "온마루"]'::jsonb, 36.245285, 128.701358, '2026-03-18T12:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002382', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2638521', '영천 목재문화체험장', '오랜만에 여유 찾으러 영천 목재문화체험장 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "풍경맛집", "고즈넉"]'::jsonb, 36.142553, 128.977974, '2026-04-13T00:17:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002383', '54500700-0000-4000-8000-000000000165', 'p-tourapi-3354017', '술작가 양조장', '조용히 사색하고 싶어서 찾은 술작가 양조장. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 37.473539, 126.641244, '2026-02-05T10:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002384', '54500700-0000-4000-8000-000000000122', 'p-tourapi-2606219', '영천전투메모리얼파크', '드라이브 겸 나들이로 영천전투메모리얼파크 선택했는데 대만족! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "산책로", "고즈넉"]'::jsonb, 35.973185, 128.927103, '2026-01-30T15:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002385', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3438724', '소월정', '천천히 골목 걷다가 마주친 소월정. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "고즈넉", "온마루"]'::jsonb, 37.583234, 126.986638, '2026-02-10T04:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002386', '54500700-0000-4000-8000-000000000065', 'p-tourapi-1877312', '양소당', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "고즈넉", "혼자여행"]'::jsonb, 36.579989, 128.546455, '2026-02-28T10:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002387', '54500700-0000-4000-8000-000000000105', 'p-tourapi-1245865', '심산기념문화센터', '드라이브 겸 나들이로 심산기념문화센터 선택했는데 대만족! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "주말나들이", "온마루"]'::jsonb, 37.498404, 126.991072, '2026-03-25T07:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002388', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3453420', '황촌마을활력소', '비 오는 날 운치 찾아 황촌마을활력소 다녀왔어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "산책로", "사색"]'::jsonb, 35.845013, 129.220754, '2026-04-12T15:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002389', '54500700-0000-4000-8000-000000000091', 'p-tourapi-3529694', '서울아리', '조용히 사색하고 싶어서 찾은 서울아리. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 37.576639, 126.991273, '2026-03-12T19:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002390', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2782667', '김대기가옥', '날씨가 너무 맑아서 김대기가옥 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행", "데이트"]'::jsonb, 36.692602, 128.410355, '2026-03-07T13:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002391', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2743315', '의왕도깨비도로', '천천히 골목 걷다가 마주친 의왕도깨비도로. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 37.394167, 127.027493, '2026-02-17T06:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002392', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2657848', '한국트로트가요센터', 'SNS에서 사진 보고 찾아간 한국트로트가요센터, 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 34.791537, 126.685282, '2026-03-17T17:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002393', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2996855', '버금상점', '버금상점 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 34.972400, 128.323475, '2026-03-28T09:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002394', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2594831', '양참사댁(양동호 가옥 / 한옥152)', 'SNS에서 사진 보고 찾아간 양참사댁(양동호 가옥 / 한옥152), 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉", "사색", "온마루"]'::jsonb, 34.984461, 126.911551, '2026-03-08T04:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002395', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2357469', '훈몽재 유지', '드라이브 겸 나들이로 훈몽재 유지 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 35.472525, 126.968486, '2026-03-22T07:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002396', '54500700-0000-4000-8000-000000000105', 'p-tourapi-128177', '낭추골 현장체험학습원', '주말에 친구들이랑 낭추골 현장체험학습원 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 36.598084, 127.617476, '2026-02-28T15:00:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002397', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2819607', '드로잉라이프', '드로잉라이프 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "방문팁", "사진맛집"]'::jsonb, 34.951445, 127.483371, '2026-02-18T19:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002398', '54500700-0000-4000-8000-000000000174', 'p-tourapi-2946242', '내맘대로폰케이스 홍대점', '평일 연차 쓰고 혼자 내맘대로폰케이스 홍대점 다녀옴. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.550991, 126.921988, '2026-03-23T06:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002399', '54500700-0000-4000-8000-000000000177', 'p-tourapi-3432447', '2025 서울 카페&베이커리페어', '예전부터 가보고 싶었던 2025 서울 카페&베이커리페어 드디어 방문! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 37.496279, 127.070459, '2026-01-04T07:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002400', '54500700-0000-4000-8000-000000000074', 'p-tourapi-4065913', '청원루', '예전부터 가보고 싶었던 청원루 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 36.579504, 128.548795, '2026-03-21T14:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002401', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2638488', '거제 관광모노레일', '주말에 친구들이랑 거제 관광모노레일 들렀는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "힐링"]'::jsonb, 34.876439, 128.625263, '2026-02-20T15:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002402', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2990172', '팔봉제빵점', '드라이브 겸 나들이로 팔봉제빵점 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["주말나들이", "인생샷", "온마루"]'::jsonb, 36.647094, 127.494030, '2026-03-25T10:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002403', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3508744', '주식회사더정원의뜰', '예전부터 가보고 싶었던 주식회사더정원의뜰 드디어 방문! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "산책로", "온마루"]'::jsonb, 37.628755, 127.209769, '2026-02-03T04:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002404', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2677655', '성주 백세각', '기대 이상으로 너무 좋았던 성주 백세각! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행", "힐링"]'::jsonb, 35.988102, 128.245964, '2026-03-17T04:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002405', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2629010', '영남알프스 얼음골케이블카', '해 질 무렵에 영남알프스 얼음골케이블카 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집"]'::jsonb, 35.582588, 128.987030, '2026-01-18T19:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002406', '54500700-0000-4000-8000-000000000173', 'p-tourapi-2574164', '금마관', '기대 이상으로 너무 좋았던 금마관! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "주말나들이", "가족여행", "온마루"]'::jsonb, 35.996085, 127.059270, '2026-02-11T12:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002407', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2049307', '녹운재', '평일 연차 쓰고 혼자 녹운재 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 35.903123, 127.242458, '2026-03-23T23:38:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002408', '54500700-0000-4000-8000-000000000064', 'p-tourapi-3038851', '치헌', '조용히 사색하고 싶어서 찾은 치헌. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.534595, 128.860987, '2026-01-26T02:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002409', '54500700-0000-4000-8000-000000000203', 'p-tourapi-3510944', '주식회사영리캐롤', '평일 연차 쓰고 혼자 주식회사영리캐롤 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 36.008347, 128.359962, '2026-03-16T10:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002410', '54500700-0000-4000-8000-000000000151', 'p-tourapi-264402', '화성어차', '해 질 무렵에 화성어차 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.288053, 127.023724, '2026-01-29T20:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002411', '54500700-0000-4000-8000-000000000168', 'p-tourapi-3114431', '모주체험 여', '모주체험 여 다녀왔어요! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "사진맛집", "가족여행", "온마루"]'::jsonb, 35.815887, 127.152037, '2026-02-16T00:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002412', '54500700-0000-4000-8000-000000000176', 'p-tourapi-1606001', '해풍부원군윤택영댁재실', '주말에 친구들이랑 해풍부원군윤택영댁재실 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "산책로"]'::jsonb, 37.558495, 126.994498, '2026-03-29T17:44:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002413', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2603652', '경주한옥', '평일 연차 쓰고 혼자 경주한옥 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 35.804603, 129.194360, '2026-04-04T23:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002414', '54500700-0000-4000-8000-000000000101', 'p-tourapi-3438433', '호우재 한옥', 'SNS에서 사진 보고 찾아간 호우재 한옥, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 37.595538, 126.999977, '2026-01-28T06:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002415', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2531675', '진도한옥펜션', '진도한옥펜션 다녀왔어요! 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "산책로", "혼자여행", "온마루"]'::jsonb, 34.398661, 126.277065, '2026-02-18T16:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002416', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2638566', '주문진읍 BTS 앨범사진 촬영지 (버스정류장)', '비 오는 날 운치 찾아 주문진읍 BTS 앨범사진 촬영지 (버스정류장) 다녀왔어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "가족여행", "주말나들이"]'::jsonb, 37.912466, 128.816843, '2026-03-28T03:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002417', '54500700-0000-4000-8000-000000000122', 'p-tourapi-3438653', '호호재', '예전부터 가보고 싶었던 호호재 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색", "힐링"]'::jsonb, 36.560443, 128.710673, '2026-04-12T16:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002418', '54500700-0000-4000-8000-000000000104', 'p-tourapi-3438358', '정연재', '천천히 골목 걷다가 마주친 정연재. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "풍경맛집", "산책로", "온마루"]'::jsonb, 37.583520, 126.980237, '2026-04-03T14:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002419', '54500700-0000-4000-8000-000000000057', 'p-tourapi-1622772', '합천 사의정', '드라이브 겸 나들이로 합천 사의정 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "고즈넉"]'::jsonb, 35.543880, 128.000386, '2026-02-11T05:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002420', '54500700-0000-4000-8000-000000000076', 'p-tourapi-1883085', '늘봄스테이', '해 질 무렵에 늘봄스테이 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 35.813019, 127.152303, '2026-03-12T15:40:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002421', '54500700-0000-4000-8000-000000000123', 'p-tourapi-1871270', '맥산댁', '맥산댁 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.667529, 128.228957, '2026-03-09T10:14:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002422', '54500700-0000-4000-8000-000000000085', 'p-tourapi-3012678', '사기막골 도예촌', '주말에 친구들이랑 사기막골 도예촌 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "사색"]'::jsonb, 37.293878, 127.411819, '2026-02-22T22:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002423', '54500700-0000-4000-8000-000000000138', 'p-tourapi-126417', '해남윤씨 녹우당 일원', '비 오는 날 운치 찾아 해남윤씨 녹우당 일원 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "혼자여행", "고즈넉"]'::jsonb, 34.551006, 126.621599, '2026-03-23T12:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002424', '54500700-0000-4000-8000-000000000106', 'p-tourapi-1624517', '해남윤씨 추원당', '해 질 무렵에 해남윤씨 추원당 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 34.588438, 126.679476, '2026-02-24T06:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002425', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2481866', '백인제가옥', '근처 여행 코스로 백인제가옥 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 37.580406, 126.984077, '2026-02-15T20:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002426', '54500700-0000-4000-8000-000000000072', 'p-tourapi-3438570', '렛스테이', '오랜만에 여유 찾으러 렛스테이 다녀왔습니다. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "사색", "풍경맛집", "온마루"]'::jsonb, 36.454746, 127.123316, '2026-03-26T20:27:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002427', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3532666', '산다', '해 질 무렵에 산다 방문했는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.819175, 127.157313, '2026-02-09T12:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002428', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2610850', '강원숲체험장', '기대 이상으로 너무 좋았던 강원숲체험장! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "혼자여행"]'::jsonb, 37.963048, 127.639929, '2026-03-07T05:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002429', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2607653', '오람정', '평일 연차 쓰고 혼자 오람정 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 35.779667, 129.183224, '2026-03-22T00:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002430', '54500700-0000-4000-8000-000000000167', 'p-tourapi-231938', '서울 경모궁지', '천천히 골목 걷다가 마주친 서울 경모궁지. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "혼자여행"]'::jsonb, 37.580448, 126.998919, '2026-02-10T19:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002431', '54500700-0000-4000-8000-000000000191', 'p-tourapi-1436162', '괴산 이창훈 고가', '오랜만에 여유 찾으러 괴산 이창훈 고가 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "산책로"]'::jsonb, 36.840787, 127.858996, '2026-02-24T20:51:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002432', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2820640', '가림상회', '천천히 골목 걷다가 마주친 가림상회. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 36.189840, 126.892783, '2026-04-14T09:57:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002433', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2611669', '양천나눔누리타운', '비 오는 날 운치 찾아 양천나눔누리타운 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 37.518924, 126.853889, '2026-02-24T18:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002434', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2603652', '경주한옥', '날씨가 너무 맑아서 경주한옥 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 35.804308, 129.194020, '2026-03-25T20:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002435', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2660381', '매월당', '조용히 사색하고 싶어서 찾은 매월당. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "산책로", "풍경맛집"]'::jsonb, 35.348812, 127.272657, '2026-03-01T07:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002436', '54500700-0000-4000-8000-000000000131', 'p-tourapi-3438574', '풍류가옥', '평일 연차 쓰고 혼자 풍류가옥 다녀옴. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.824469, 127.155572, '2026-03-27T17:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002437', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2621417', '장락원(장락원전통한옥펜션)', '주말에 친구들이랑 장락원(장락원전통한옥펜션) 들렀는데 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "주말나들이", "가족여행", "온마루"]'::jsonb, 37.727721, 127.553206, '2026-02-13T08:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002438', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2574186', '김포아트빌리지 전통한옥숙박체험관', '주말에 친구들이랑 김포아트빌리지 전통한옥숙박체험관 들렀는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 37.646999, 126.696482, '2026-02-07T20:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002439', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2708658', '최참판댁 한옥숙박시설', '예전부터 가보고 싶었던 최참판댁 한옥숙박시설 드디어 방문! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "산책로", "풍경맛집"]'::jsonb, 35.155687, 127.686494, '2026-04-01T23:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002440', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2811451', '스테이황룡', '근처 여행 코스로 스테이황룡 넣길 정말 잘했어요. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "데이트", "방문팁"]'::jsonb, 35.295153, 126.770408, '2026-01-14T02:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002441', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3358056', '닥나무한지체험관 콩닥콩닥', '마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 35.691640, 126.818113, '2026-01-22T21:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002442', '54500700-0000-4000-8000-000000000144', 'p-tourapi-662234', '순천전통야생차체험관', 'SNS에서 사진 보고 찾아간 순천전통야생차체험관, 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "풍경맛집", "산책로"]'::jsonb, 34.995190, 127.334160, '2026-02-19T23:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002443', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2572908', '별바라기집', '날씨가 너무 맑아서 별바라기집 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 34.741068, 126.717987, '2026-03-20T15:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002444', '54500700-0000-4000-8000-000000000196', 'p-tourapi-1883758', '창실고택', 'SNS에서 사진 보고 찾아간 창실고택, 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "힐링"]'::jsonb, 36.438189, 129.027213, '2026-04-12T15:33:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002445', '54500700-0000-4000-8000-000000000161', 'p-tourapi-1992543', '송정고택', '비 오는 날 운치 찾아 송정고택 다녀왔어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "고즈넉", "사색", "온마루"]'::jsonb, 36.436159, 129.026161, '2026-02-23T23:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002446', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2607653', '오람정', '기대 이상으로 너무 좋았던 오람정! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로", "혼자여행"]'::jsonb, 35.779850, 129.183642, '2026-03-06T02:04:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002447', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3337799', '레이홉', '해 질 무렵에 레이홉 방문했는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 35.542291, 129.307298, '2026-04-08T16:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002448', '54500700-0000-4000-8000-000000000146', 'p-tourapi-3101964', '고기리 다온스테이', '천천히 골목 걷다가 마주친 고기리 다온스테이. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "방문팁", "가족여행"]'::jsonb, 37.352679, 127.067318, '2026-02-02T19:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002449', '54500700-0000-4000-8000-000000000163', 'p-tourapi-3438724', '소월정', '주말에 친구들이랑 소월정 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "고즈넉", "산책로", "온마루"]'::jsonb, 37.583289, 126.986939, '2026-01-17T13:28:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002450', '54500700-0000-4000-8000-000000000186', 'p-tourapi-129052', '청송초전댁', '부모님 모시고 청송초전댁 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "주말나들이", "방문팁", "온마루"]'::jsonb, 36.438010, 129.026596, '2026-02-22T21:03:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002451', '54500700-0000-4000-8000-000000000196', 'p-tourapi-1870849', '덕동댁', '주말에 친구들이랑 덕동댁 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 35.667025, 128.227979, '2026-01-05T08:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002452', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2509920', '울산중구생활문화센터', '드라이브 겸 나들이로 울산중구생활문화센터 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "산책로", "사색"]'::jsonb, 35.556677, 129.322118, '2026-02-02T16:45:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002453', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2607765', '다락', '드라이브 겸 나들이로 다락 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.816738, 127.150865, '2026-03-18T16:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002454', '54500700-0000-4000-8000-000000000077', 'p-tourapi-3532712', '스테이화요일', '천천히 골목 걷다가 마주친 스테이화요일. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["사진맛집", "주말나들이", "인생샷"]'::jsonb, 36.847667, 126.904540, '2026-03-28T16:22:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002455', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2679044', '청향재', '주말에 친구들이랑 청향재 들렀는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 37.641957, 126.940406, '2026-04-09T19:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002456', '54500700-0000-4000-8000-000000000151', 'p-tourapi-3544376', '강릉종합사회복지관', '오랜만에 여유 찾으러 강릉종합사회복지관 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 37.764768, 128.915805, '2026-01-23T10:12:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002457', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3532720', '메모리스테이 효자', '천천히 골목 걷다가 마주친 메모리스테이 효자. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 37.582902, 126.971411, '2026-01-15T02:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002458', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2602196', '의양리 권진사댁', '오랜만에 여유 찾으러 의양리 권진사댁 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "힐링"]'::jsonb, 36.944871, 128.911898, '2026-02-22T07:24:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002459', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '해 질 무렵에 미담 한옥 게스트 하우스 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "인생샷", "온마루"]'::jsonb, 37.580598, 126.986049, '2026-02-04T04:05:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002460', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3438249', '아보헌', '해 질 무렵에 아보헌 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "데이트", "사진맛집", "온마루"]'::jsonb, 37.582149, 126.989433, '2026-02-01T11:52:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002461', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2993194', '위라이드 서울전차', 'SNS에서 사진 보고 찾아간 위라이드 서울전차, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷", "데이트"]'::jsonb, 37.570842, 126.980210, '2026-02-24T12:31:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002462', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2594218', '정가한옥', '부모님 모시고 정가한옥 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.816383, 127.154970, '2026-03-21T13:37:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002463', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2574250', '라온한옥꿀잠', '예전부터 가보고 싶었던 라온한옥꿀잠 드디어 방문! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 35.815887, 127.154190, '2026-03-11T03:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002464', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2602196', '의양리 권진사댁', '주말에 친구들이랑 의양리 권진사댁 들렀는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 36.945041, 128.912438, '2026-02-05T14:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002465', '54500700-0000-4000-8000-000000000094', 'p-tourapi-1624514', '해남윤씨 영모당', '비 오는 날 운치 찾아 해남윤씨 영모당 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "사진맛집", "데이트", "온마루"]'::jsonb, 34.577344, 126.705507, '2026-01-25T07:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002466', '54500700-0000-4000-8000-000000000085', 'p-tourapi-3433029', '어깨동무스토리움', '바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "방문팁"]'::jsonb, 37.575002, 126.886795, '2026-04-16T07:25:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002467', '54500700-0000-4000-8000-000000000150', 'p-tourapi-3428156', '국가유산 방문 캠페인 인천공항 홍보관', '국가유산 방문 캠페인 인천공항 홍보관 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["데이트", "가족여행", "사진맛집"]'::jsonb, 37.447883, 126.452502, '2026-02-14T00:20:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002468', '54500700-0000-4000-8000-000000000173', 'p-tourapi-2610850', '강원숲체험장', '근처 여행 코스로 강원숲체험장 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 37.962666, 127.639710, '2026-03-23T17:11:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002469', '54500700-0000-4000-8000-000000000075', 'p-tourapi-264311', '명동', '주말에 친구들이랑 명동 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.562287, 126.984733, '2026-01-10T08:39:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002470', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3351556', '서천문화예술창작공간', 'SNS에서 사진 보고 찾아간 서천문화예술창작공간, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로", "힐링"]'::jsonb, 36.008608, 126.696038, '2026-04-01T07:29:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002471', '54500700-0000-4000-8000-000000000182', 'p-tourapi-1626773', '영동 소석고택', '부모님 모시고 영동 소석고택 산책 겸 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["주말나들이", "데이트"]'::jsonb, 36.218115, 127.712718, '2026-04-10T06:01:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002472', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2583699', '소소하우스', '날씨가 너무 맑아서 소소하우스 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "혼자여행", "온마루"]'::jsonb, 37.580416, 126.968440, '2026-01-18T20:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002473', '54500700-0000-4000-8000-000000000099', 'p-tourapi-3085314', '북촌전통발효공방 빚담', '비 오는 날 운치 찾아 북촌전통발효공방 빚담 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "방문팁", "가족여행"]'::jsonb, 37.582519, 126.985425, '2026-01-20T09:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002474', '54500700-0000-4000-8000-000000000126', 'p-tourapi-3032740', '대가야기마문화체험장', 'SNS에서 사진 보고 찾아간 대가야기마문화체험장, 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 35.711445, 128.266751, '2026-03-22T05:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002475', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3025473', '영광 매간당 고택', '기대 이상으로 너무 좋았던 영광 매간당 고택! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.240829, 126.474244, '2026-03-18T21:41:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002476', '54500700-0000-4000-8000-000000000161', 'p-tourapi-1877477', '노송정종택(퇴계생가)', '해 질 무렵에 노송정종택(퇴계생가) 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 36.749535, 128.828363, '2026-01-17T06:36:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002477', '54500700-0000-4000-8000-000000000078', 'p-tourapi-1870767', '다향소축', '주말에 친구들이랑 다향소축 들렀는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "힐링", "혼자여행"]'::jsonb, 34.578844, 126.749115, '2026-04-14T11:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002478', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2570229', '결성향교', '부모님 모시고 결성향교 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "인생샷", "사진맛집"]'::jsonb, 36.528960, 126.543344, '2026-01-17T07:58:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002479', '54500700-0000-4000-8000-000000000162', 'p-tourapi-1579811', '거창 반구헌', '조용히 사색하고 싶어서 찾은 거창 반구헌. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 35.755098, 127.828867, '2026-02-10T19:32:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002480', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2607515', '화랑도체험장', '드라이브 겸 나들이로 화랑도체험장 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링", "혼자여행"]'::jsonb, 38.218329, 128.570099, '2026-03-18T02:10:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002481', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3091065', '홍성 노은리 고택', '대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색"]'::jsonb, 36.644478, 126.735190, '2026-01-22T06:02:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002482', '54500700-0000-4000-8000-000000000142', 'p-tourapi-3438589', '윤은재', 'SNS에서 사진 보고 찾아간 윤은재, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 35.033486, 126.712144, '2026-02-24T18:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002483', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2891338', '동강리버버깅', '조용히 사색하고 싶어서 찾은 동강리버버깅. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "고즈넉"]'::jsonb, 37.116507, 128.539028, '2026-01-14T23:55:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002484', '54500700-0000-4000-8000-000000000191', 'p-tourapi-3511071', '주식회사피알아이피', 'SNS에서 사진 보고 찾아간 주식회사피알아이피, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 35.142902, 129.108288, '2026-02-03T08:26:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002485', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2820706', '폴링 인 진주', '기대 이상으로 너무 좋았던 폴링 인 진주! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "데이트"]'::jsonb, 35.183242, 128.085074, '2026-01-07T05:48:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002486', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2613097', '월암재', '해 질 무렵에 월암재 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "사진맛집", "주말나들이"]'::jsonb, 35.815613, 129.215906, '2026-03-26T22:43:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002487', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2607675', '학은재', '부모님 모시고 학은재 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집", "혼자여행"]'::jsonb, 34.786745, 126.380186, '2026-03-07T05:34:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002488', '54500700-0000-4000-8000-000000000177', 'p-tourapi-231938', '서울 경모궁지', 'SNS에서 사진 보고 찾아간 서울 경모궁지, 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 37.580471, 126.999005, '2026-01-12T15:47:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002489', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3452786', '시흥시청소년수련관', '오랜만에 여유 찾으러 시흥시청소년수련관 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 37.446532, 126.797624, '2026-01-22T10:50:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002490', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2702472', '김종길 가옥', '예전부터 가보고 싶었던 김종길 가옥 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.271057, 128.264097, '2026-02-21T14:13:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002491', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2613318', '이가한옥', '오랜만에 여유 찾으러 이가한옥 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 35.816856, 127.155760, '2026-01-08T20:23:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002492', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2708320', '이랑한옥스테이', '예전부터 가보고 싶었던 이랑한옥스테이 드디어 방문! 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["가족여행", "방문팁"]'::jsonb, 35.520093, 127.151196, '2026-01-07T21:30:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002493', '54500700-0000-4000-8000-000000000192', 'p-tourapi-1624846', '창원정씨종가', 'SNS에서 사진 보고 찾아간 창원정씨종가, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 35.565375, 127.395463, '2026-04-01T00:46:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002494', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2593643', '목향재', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 36.502020, 127.239441, '2026-02-18T12:59:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002495', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3113740', '고결', '고결 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "풍경맛집", "사색"]'::jsonb, 36.643028, 128.064824, '2026-03-17T06:18:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002496', '54500700-0000-4000-8000-000000000082', 'p-tourapi-3532720', '메모리스테이 효자', '비 오는 날 운치 찾아 메모리스테이 효자 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "가족여행", "데이트", "온마루"]'::jsonb, 37.582971, 126.970647, '2026-01-14T17:09:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002497', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2961964', '하정사색', '예전부터 가보고 싶었던 하정사색 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 35.408578, 127.382451, '2026-04-10T23:07:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002498', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2638521', '영천 목재문화체험장', '드라이브 겸 나들이로 영천 목재문화체험장 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.142487, 128.978238, '2026-01-14T20:49:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002499', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3033516', '논산한옥마을', '조용히 사색하고 싶어서 찾은 논산한옥마을. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "혼자여행", "산책로"]'::jsonb, 36.211411, 127.181028, '2026-03-30T21:15:38Z'::timestamptz),
('54500700-0000-4000-9000-000000002500', '54500700-0000-4000-8000-000000000108', 'p-tourapi-4039810', '스테이꼬리', '날씨가 너무 맑아서 스테이꼬리 한 바퀴 돌고 왔네요. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "데이트", "인생샷"]'::jsonb, 35.813275, 129.212933, '2026-01-09T16:42:38Z'::timestamptz);
INSERT INTO onmaru.community_visit_reviews (
